\label{lemma-closed-is-limit-closed-and-finite-presentation}
\begin{slogan}
Closed immersions of qcqs algebraic spaces can be approximated
by finitely presented closed immersions.
\end{slogan}
Let $S$ be a scheme. Let $f : X \to Y$ be a closed immersion of algebraic
spaces over $S$. Assume $Y$ quasi-compact and quasi-separated.
Then $X$ can be written as a directed limit $X = \lim X_i$
where the transition maps are closed immersions and the morphisms
$X_i \to Y$ are closed immersions of finite presentation.

\label{lemma-countable-finite-type}
Let $R$ be a countable Noetherian ring. Then the category of schemes of finite
type over $R$ is countable.

\label{lemma-base-change-separated}
All of the separation axioms listed in
Definition \ref{definition-separated-morphism}
are stable under base change.

\label{lemma-projective-space-separated}
Let $S$ be a scheme.
The structure morphism $\mathbf{P}^n_S \to S$ is
\begin{enumerate}
\item separated,
\item quasi-compact,
\item satisfies the existence and uniqueness parts of the valuative criterion,
and
\item universally closed.
\end{enumerate}

\label{lemma-symbol-compare-modules}
Let $A$ be a Noetherian local ring.
Let $\alpha : M \to M'$ be a homomorphism of
finite $A$-modules of dimension $1$.
Let $a, b \in A$. Assume
\begin{enumerate}
\item $a$, $b$ are nonzerodivisors on both $M$ and $M'$, and
\item $\dim(\Ker(\alpha)), \dim(\Coker(\alpha)) \leq 0$.
\end{enumerate}
Then $d_M(a, b) = d_{M'}(a, b)$.

\label{lemma-deform-property-fp-over-ft}
Consider a commutative diagram
$$
\xymatrix{
(\mathcal{X} \subset \mathcal{X}') \ar[rr]_{(f, f')} \ar[rd] & &
(\mathcal{Y} \subset \mathcal{Y}') \ar[ld] \\
& (\mathcal{B} \subset \mathcal{B}')
}
$$
of thickenings of algebraic stacks.
Assume $\mathcal{Y}' \to \mathcal{B}'$ locally of finite type,
$\mathcal{X}' \to \mathcal{B}'$ flat and locally of finite presentation,
$\mathcal{X} = \mathcal{B} \times_{\mathcal{B}'} \mathcal{X}'$, and
$\mathcal{Y} = \mathcal{B} \times_{\mathcal{B}'} \mathcal{Y}'$. Then
\begin{enumerate}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat-fp-over-ft}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism-fp-over-ft}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion-fp-over-ft}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism-fp-over-ft}
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite-fp-over-ft}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic-fp-over-ft}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth-fp-over-ft}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified-fp-over-ft}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale-fp-over-ft}
\item $f$ is finite if and only if $f'$ is finite, and
\label{item-finite-fp-over-ft}
\item add more here.
\end{enumerate}

\label{proposition-when-gerbe}
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is a gerbe, and
\item $\mathcal{I}_\mathcal{X} \to \mathcal{X}$ is flat and locally of
finite presentation.
\end{enumerate}

\label{lemma-lift-points-H-to-G}
Let $R$ be an $A$-algebra which is absolutely integrally closed. Then
$G(R) \to H(R)$ is surjective.

\label{lemma-stable-curves}
There exist an open substack $\Curvesstack^{stable} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{stable}$,
\item $X \to S$ is a stable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{stable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, the genus of $X$ is $\geq 2$, and
$X$ has no rational tails or bridges,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and $\omega_{X_s}$ is ample.
\end{enumerate}
\end{enumerate}

\label{lemma-no-dense-separated-quasi-compact-open-in-qcqs}
There exists a quasi-compact and quasi-separated scheme $X$ which does
not contain a separated quasi-compact dense open.

\label{lemma-base-change-unramified}
The base change of a morphism which is unramified is unramified.
The same holds for G-unramified morphisms.

\label{lemma-support}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. For an $A$-module $M$ the following are equivalent
\begin{enumerate}
\item $H^0_T(M) = M$, and
\item $\text{Supp}(M) \subset T$.
\end{enumerate}
The category of such $A$-modules is a Serre subcategory
of the category $A$-modules closed under direct sums.

\label{lemma-normal-dimension-2-Cohen-Macaulay}
Let $X$ be a locally Noetherian scheme which is normal and
has dimension $\leq 2$. Then $X$ is Cohen-Macaulay.

\label{lemma-gorenstein-local-ring-fibre}
The property of morphisms of germs of schemes
\begin{align*}
& \mathcal{P}((X, x) \to (S, s)) = \\
& \text{the local ring }
\mathcal{O}_{X_s, x}
\text{ of the fibre is Noetherian and Gorenstein}
\end{align*}
is \'etale local on the source-and-target (Descent, Definition
\ref{descent-definition-local-source-target-at-point}).

\label{lemma-normal-integral-sections}
\begin{slogan}
The ring of functions on a normal scheme is normal.
\end{slogan}
Let $X$ be an integral normal scheme.
Then $\Gamma(X, \mathcal{O}_X)$ is a normal domain.

\label{lemma-hilb-s-lfp}
The morphism $\Hilbfunctor_{X/B} \to B$ is separated
and locally of finite presentation.

\label{lemma-composition-finite-type}
The composition of finite type morphisms is of finite type.
The same holds for locally of finite type.

\label{lemma-w-local-algebraic-residue-field-extensions}
Let $A$ be a ring such that $X = \Spec(A)$ is w-local. Let $I \subset A$
be the radical ideal cutting out the set $X_0$ of closed points in $X$.
Let $A \to B$ be a ring map inducing algebraic extensions on residue
fields at primes. Then
\begin{enumerate}
\item every point of $Z = V(IB)$ is a closed point of $\Spec(B)$,
\item there exists an ind-Zariski ring map $B \to C$ such that
\begin{enumerate}
\item $B/IB \to C/IC$ is an isomorphism,
\item the space $Y = \Spec(C)$ is w-local,
\item the induced map $p : Y \to X$ is w-local, and
\item $p^{-1}(X_0)$ is the set of closed points of $Y$.
\end{enumerate}
\end{enumerate}

\label{lemma-composition-thickening}
Let $S$ be a scheme. If $X \subset X'$ and $X' \subset X''$ are
thickenings of algebraic spaces over $S$, then so is $X \subset X''$.

\label{lemma-decent-Jacobson}
Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
Then $X$ is Jacobson if and only if $|X|$ is Jacobson.

\label{lemma-NL-etale}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is \'etale, and
\item $f$ is locally of finite presentation and
$H^{-1}(\NL_{X/Y}) = H^0(\NL_{X/Y}) = 0$.
\end{enumerate}

\label{lemma-qf-and-qc-finite-fibre}
In diagram (\ref{equation-points-fibres}) the set (\ref{equation-fibre})
is finite if $f$ is of finite type and $f$ is quasi-finite at $x$.

\label{lemma-RQ-zero}
With notation as in
Lemma \ref{lemma-enough-injectives}
we have $R^pQ(F) = 0$ for all $p > 0$ and any adequate functor $F$.

\label{lemma-characterize-representable-quasi-compact}
Let $S$ be a scheme.
Let $f : X \to Y$ be a representable morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item $f$ is quasi-compact
(in the sense of Section \ref{section-representable}), and
\item for every quasi-compact algebraic space $Z$ and any morphism
$Z \to Y$ the algebraic space $Z \times_Y X$ is quasi-compact.
\end{enumerate}

\label{lemma-locally-noetherian-fibre}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Let $y \in |Y|$. The following are equivalent
\begin{enumerate}
\item for some scheme $V$, point $v \in V$, and \'etale morphism $V \to Y$
mapping $v$ to $y$, the algebraic space $X_v$ is locally Noetherian,
\item for every scheme $V$, point $v \in V$, and \'etale morphism $V \to Y$
mapping $v$ to $y$, the algebraic space $X_v$ is locally Noetherian, and
\item there exists a field $k$ and a morphism $\Spec(k) \to Y$ representing
$y$ such that $X_k$ is locally Noetherian.
\end{enumerate}
If there exists a field $k_0$ and a monomorphism $\Spec(k_0) \to Y$
representing $y$, then these are also equivalent to
\begin{enumerate}
\item[(4)] the algebraic space $X_{k_0}$ is locally Noetherian.
\end{enumerate}

\label{lemma-syntomic-relative-dimension}
Let $f : X \to S$ be a syntomic morphism. The function
$x \mapsto \dim_x(X_{f(x)})$ is locally constant on $X$.

\label{lemma-locally-finite-type-dim-zero}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Assume $X$ satisfies at least one of the following conditions
\begin{enumerate}
\item $X$ is quasi-separated and $\dim(X) = 0$,
\item $X$ is locally of finite type over a field $k$ and $\dim(X) = 0$,
\item $X$ is Noetherian and $\dim(X) = 0$, or
\item add more here.
\end{enumerate}
Then $X$ is a separated scheme and any quasi-compact open of $X$ is affine.

\label{lemma-characterize-dbcoh-proper-regular}
Let $X$ be a proper scheme over a field $k$ which is regular. Let
$K \in \Ob(D_\QCoh(\mathcal{O}_X))$. The following are equivalent
\begin{enumerate}
\item $K \in D^b_{\textit{Coh}}(\mathcal{O}_X) = D_{perf}(\mathcal{O}_X)$, and
\item $\sum_{i \in \mathbf{Z}} \dim_k \Ext^i_X(E, K) < \infty$
for all perfect $E$ in $D(\mathcal{O}_X)$.
\end{enumerate}

\label{lemma-groupoid-on-field-locally-finite-type-dimension}
In
Situation \ref{situation-groupoid-on-field}
assume $s, t$ are locally of finite type.
For all $r \in |R|$
\begin{enumerate}
\item $\dim(R) = \dim_r(R)$,
\item the transcendence degree of $r$ over $\Spec(k)$
via $s$ equals the transcendence degree of $r$ over $\Spec(k)$
via $t$, and
\item if the transcendence degree mentioned in (2) is $0$, then
$\dim(R) = \dim(\mathcal{O}_{R, \overline{r}})$.
\end{enumerate}

\label{lemma-differential-product}
Let $f : X \to S$ and $g : Y \to S$ be morphisms of schemes with the same
target. Let $p : X \times_S Y \to X$ and $q : X \times_S Y \to Y$ be the
projection morphisms. The maps from
Lemma \ref{lemma-functoriality-differentials}
$$
p^*\Omega_{X/S} \oplus q^*\Omega_{Y/S}
\longrightarrow
\Omega_{X \times_S Y/S}
$$
give an isomorphism.

\label{lemma-bounded-on-fibres}
Let $f : X \to S$ be a morphism of schemes which is flat and
locally of finite presentation. Let $E$ be a pseudo-coherent
object of $D(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item $E$ is $S$-perfect, and
\item $E$ is locally bounded below and for every point $s \in S$
the object $L(X_s \to X)^*E$ of $D(\mathcal{O}_{X_s})$
is locally bounded below.
\end{enumerate}

\label{theorem-finiteness}
\begin{reference}
This is a special case of \cite[Satz 2]{Faltings-finiteness}.
\end{reference}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal.
Set $Z = V(I) \subset \Spec(A)$. Let $M$ be a finite $A$-module.
Set $s = s_{A, I}(M)$ as in (\ref{equation-cutoff}).
Assume that
\begin{enumerate}
\item $A$ is universally catenary,
\item the formal fibres of the local rings of $A$ are Cohen-Macaulay.
\end{enumerate}
Then $H^i_Z(M)$ is finite for $0 \leq i < s$ and
$H^s_Z(M)$ is not finite.

\label{lemma-eventually-affine}
Let $S$ be a scheme. Let $Y$ be an algebraic space over $S$.
Let $X = \lim X_i$ be a directed limit of algebraic spaces over $Y$
with affine transition morphisms. Assume
\begin{enumerate}
\item $Y$ quasi-compact and quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item $X \to Y$ affine.
\end{enumerate}
Then $X_i \to Y$ is affine for $i$ large enough.

\label{lemma-rig-smooth}
Let $A$ be a Noetherian ring and let $I$ be an ideal.
Let $B$ be a finite type $A$-algebra.
\begin{enumerate}
\item If $\Spec(B) \to \Spec(A)$ is smooth over $\Spec(A) \setminus V(I)$,
then $B^\wedge$ is rig-smooth over $(A, I)$.
\item If $B^\wedge$ is rig-smooth over $(A, I)$,
then there exists $g \in 1 + IB$ such that $\Spec(B_g)$ is smooth
over $\Spec(A) \setminus V(I)$.
\end{enumerate}

\label{lemma-essential-extension}
Let $R$ be a ring. Let $M \subset N$ be $R$-modules. The following
are equivalent
\begin{enumerate}
\item $M \subset N$ is an essential extension,
\item for all $x \in N$ nonzero there exists an $f \in R$ such that $fx \in M$
and $fx \not = 0$.
\end{enumerate}

\label{lemma-points-DM-locus}
Let $\mathcal{X}$ be an algebraic stack. Let $x \in |\mathcal{X}|$
correspond to $x : \Spec(k) \to \mathcal{X}$. Let $G_x/k$
be the automorphism group algebraic space of $x$. Then
\begin{enumerate}
\item  $x$ is in the DM locus of $\mathcal{X}$
if and only if $G_x \to \Spec(k)$ is unramified, and
\item $x$ is in the quasi-DM locus of $\mathcal{X}$
if and only if $G_x \to \Spec(k)$ is locally quasi-finite.
\end{enumerate}

\label{lemma-locally-quasi-finite-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally quasi-finite''
is \'etale local on the source.

\label{lemma-image-universally-closed-separated}
Let $S$ be a scheme. Let $B$ be an algebraic space over $S$.
Let $f : X \to Y$ be a surjective universally closed
morphism of algebraic spaces over $B$.
\begin{enumerate}
\item If $X$ is quasi-separated, then $Y$ is quasi-separated.
\item If $X$ is separated, then $Y$ is separated.
\item If $X$ is quasi-separated over $B$, then $Y$ is quasi-separated over $B$.
\item If $X$ is separated over $B$, then $Y$ is separated over $B$.
\end{enumerate}

\label{lemma-algebraic-stack-RS-star}
Let $\mathcal{X}$ be an algebraic stack over a base $S$.
Then $\mathcal{X}$ satisfies (RS*).

\label{lemma-vanishing-injective}
In Situation \ref{situation-vanishing} the morphism $p : X \to \Spec(A)$ is
universally injective.

\label{lemma-diagram-pull}
Let $B \to S$ be as in Section \ref{section-notation}.
Let $(U, R, s, t, c, e, i)$ be a groupoid in algebraic spaces over $B$.
The diagram
\begin{equation}
\label{equation-pull}
\xymatrix{
R \times_{t, U, t} R
\ar@<1ex>[r]^-{\text{pr}_1} \ar@<-1ex>[r]_-{\text{pr}_0}
\ar[d]_{\text{pr}_0 \times c \circ (i, 1)} &
R \ar[r]^t \ar[d]^{\text{id}_R} &
U \ar[d]^{\text{id}_U} \\
R \times_{s, U, t} R
\ar@<1ex>[r]^-c \ar@<-1ex>[r]_-{\text{pr}_0} \ar[d]_{\text{pr}_1} &
R \ar[r]^t \ar[d]^s &
U \\
R \ar@<1ex>[r]^s \ar@<-1ex>[r]_t &
U
}
\end{equation}
is commutative. The two top rows are isomorphic via the vertical maps given.
The two lower left squares are cartesian.

\label{lemma-when-quotient-scheme-at-point}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$ and
let $G$ be a finite group acting freely on $X$. Set $Y = X/G$ as
in Properties of Spaces, Lemma \ref{spaces-properties-lemma-quotient}.
For $y \in |Y|$ the following are equivalent
\begin{enumerate}
\item $y$ is in the schematic locus of $Y$, and
\item there exists an affine open $U \subset X$
containing the preimage of $y$.
\end{enumerate}

\label{lemma-c1-center}
Let $(S, \delta)$ be as in Situation \ref{situation-setup}.
Let $X$ be locally of finite type over $S$.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Then
\begin{enumerate}
\item $c_1(\mathcal{L}) \in A^1(X)$ is in the center of $A^*(X)$ and
\item if $f : X' \to X$ is locally of finite type and $c \in A^*(X' \to X)$,
then $c \circ c_1(\mathcal{L}) = c_1(f^*\mathcal{L}) \circ c$.
\end{enumerate}

\label{lemma-weird-sheaf}
There exists a sheaf of abelian groups $G$ on
$\Sch_\etale$ with the following properties
\begin{enumerate}
\item $G(\Spec(k)) = 0$ whenever $k$ is a field,
\item $G$ is limit preserving,
\item if $X \subset X'$ is a thickening, then $G(X) = G(X')$, and
\item $G$ is not zero.
\end{enumerate}

\label{lemma-flat-eq}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $\mathcal{F}$ be an
$\mathcal{O}$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a flat $\mathcal{O}$-module.
\item Let $U$ be an object of $\mathcal{C}$ and let
$$
\mathcal{O}_U \xrightarrow{(f_1, \ldots, f_n)}
\mathcal{O}_U^{\oplus n} \xrightarrow{(s_1, \ldots, s_n)}
\mathcal{F}|_U
$$
be a complex of $\mathcal{O}_U$-modules. Then there exists a covering
$\{U_i \to U\}$ and for each $i$ a factorization
$$
\mathcal{O}_{U_i}^{\oplus n}
\xrightarrow{B_i}
\mathcal{O}_{U_i}^{\oplus l_i} \xrightarrow{(t_{i1}, \ldots, t_{il_i})}
\mathcal{F}|_{U_i}
$$
of $(s_1, \ldots, s_n)|_{U_i}$ such that
$B_i \circ (f_1, \ldots, f_n)|_{U_i} = 0$.
\item Let $U$ be an object of $\mathcal{C}$ and let
$$
\mathcal{O}_U^{\oplus m} \xrightarrow{A}
\mathcal{O}_U^{\oplus n} \xrightarrow{(s_1, \ldots, s_n)}
\mathcal{F}|_U
$$
be a complex of $\mathcal{O}_U$-modules. Then there exists a covering
$\{U_i \to U\}$ and for each $i$ a factorization
$$
\mathcal{O}_{U_i}^{\oplus n}
\xrightarrow{B_i}
\mathcal{O}_{U_i}^{\oplus l_i} \xrightarrow{(t_{i1}, \ldots, t_{il_i})}
\mathcal{F}|_{U_i}
$$
of $(s_1, \ldots, s_n)|_{U_i}$ such that
$B_i \circ A|_{U_i} = 0$.
\end{enumerate}

\label{lemma-limits-colimits-abelian-presheaves}
Let $\mathcal{C}$ be a category.
\begin{enumerate}
\item All limits and colimits exist in $\textit{PAb}(\mathcal{C})$.
\item All limits and colimits commute with taking sections over objects of
$\mathcal{C}$.
\end{enumerate}

\label{lemma-descending-property-syntomic}
The property $\mathcal{P}(f) =$``$f$ is syntomic''
is fpqc local on the base.

\label{lemma-finite-projective-modules-RS}
Example \ref{example-finite-projective-modules}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_V$ is a deformation category
for any finite dimensional vector space $V$ over $k$.

\label{lemma-quasi-coherent-affine-cohomology-zero}
\begin{slogan}
Serre vanishing: Higher cohomology vanishes on affine schemes
for quasi-coherent modules.
\end{slogan}
Let $X$ be a scheme.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
For any affine open $U \subset X$ we have
$H^p(U, \mathcal{F}) = 0$ for all $p > 0$.

\label{lemma-intersection-scheme-theoretically-dense}
Let $X$ be a scheme. If $U$, $V$ are scheme theoretically dense
open subschemes of $X$, then so is $U \cap V$.

\label{lemma-universally-injective}
\begin{reference}
\cite[Proposition 3.7.1]{EGA1-second}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item For every field $K$ the induced map
$\Mor(\Spec(K), X) \to \Mor(\Spec(K), S)$
is injective.
\item The morphism $f$ is universally injective.
\item The morphism $f$ is radicial.
\item The diagonal morphism $\Delta_{X/S} : X \longrightarrow X \times_S X$
is surjective.
\end{enumerate}

\label{lemma-characterize-G-scheme}
Let $X$ be a scheme. The following are equivalent:
\begin{enumerate}
\item $X$ is a G-scheme,
\item $X$ is locally Noetherian and for all $x \in X$ the ring
map $\mathcal{O}_{X, x} \to \mathcal{O}_{X, x}^\wedge$ is regular, and
\item $X$ is locally Noetherian and for any closed point $x \in X$
the ring map $\mathcal{O}_{X, x} \to \mathcal{O}_{X, x}^\wedge$ is regular.
\end{enumerate}

\label{lemma-w-local-morphism-equal-stalks-is-ind-zariski}
Let $A \to B$ be ring map such that
\begin{enumerate}
\item $A \to B$ identifies local rings,
\item the topological spaces $\Spec(B)$, $\Spec(A)$ are w-local, and
\item $\Spec(B) \to \Spec(A)$ is w-local.
\end{enumerate}
Then $A \to B$ is ind-Zariski.

\label{lemma-genus-nonnegative}
If $n, m_i, a_{ij}, w_i, g_i$ is a minimal numerical type
with $n > 1$, then $g \geq g_{top}$.

\label{lemma-implications-between-types}
Let $X$ be an affine formal algebraic space over a scheme $S$.
\begin{enumerate}
\item If $X$ is Noetherian, then $X$ is adic*.
\item If $X$ is adic*, then $X$ is adic.
\item If $X$ is adic, then $X$ is weakly adic.
\item If $X$ is weakly adic, then $X$ is classical.
\item If $X$ is weakly adic, then $X$ is countably indexed.
\item If $X$ is countably indexed, then $X$ is McQuillan.
\end{enumerate}

\label{lemma-pro-V-V}
Let $Y$ be an affine scheme. Let $X = \lim X_i$ be a directed limit
of affine schemes over $Y$. The following are equivalent
\begin{enumerate}
\item $\{X \to Y\}$ is a standard V covering
(Topologies, Definition \ref{topologies-definition-standard-V-covering}), and
\item $\{X_i \to Y\}$ is a standard V covering for all $i$.
\end{enumerate}

\label{lemma-stalk-push-finite}
Let $S$ be a scheme. Let $f : X \to Y$ be a finite morphism of algebraic
spaces over $S$. Let $\overline{y}$ be a geometric point of $Y$ with
lifts $\overline{x}_1, \ldots, \overline{x}_n$ in $X$. Then
$$
(f_*\mathcal{F})_{\overline{y}} =
\prod\nolimits_{i = 1, \ldots, n}
\mathcal{F}_{\overline{x}_i}
$$
for any sheaf $\mathcal{F}$ on $X_\etale$.

\label{lemma-equivalent-definitions}
Let $S$ be a scheme. Let $X$ be a locally Noetherian algebraic space over $S$.
Let $K$ be an object of $D_\QCoh(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item For every \'etale morphism $U \to X$ where $U$ is a scheme
the restriction $K|_U$ is a dualizing complex for $U$ (as discussed above).
\item There exists a surjective \'etale morphism $U \to X$ where $U$ is a
scheme such that $K|_U$ is a dualizing complex for $U$.
\end{enumerate}

\label{lemma-hierarchy}
A morphism $f : \mathcal{X} \to \mathcal{Y}$ of algebraic stacks is
\begin{enumerate}
\item a monomorphism if and only if $\Delta_{f, 1}$ is an isomorphism, and
\item representable by algebraic spaces if and only if $\Delta_{f, 1}$
is a monomorphism.
\end{enumerate}
Moreover, the second diagonal $\Delta_{f, 2}$ is always a monomorphism.

\label{lemma-torsors-stack-in-groupoids}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p : G\textit{-Torsors} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{lemma-hilb-diagonal-closed}
The diagonal of $\Hilbfunctor_{X/B} \to B$ is a closed immersion
of finite presentation.

\label{lemma-miniversal-object-existence-1}
Let $\mathcal{F}$ be a predeformation category.
Let $\xi$ be a versal formal object of $\mathcal{F}$ such that
(\ref{equation-bijective}) holds. Then
\begin{enumerate}
\item $\mathcal{F}$ satisfies (S1).
\item $\mathcal{F}$ satisfies (S2).
\item $\dim_k T\mathcal{F}$ is finite.
\end{enumerate}

\label{lemma-hom-into-point-sheaf}
Let $X$ be a Noetherian scheme. Let $x \in X$ be a closed point and
denote $\mathcal{O}_x$ the skyscraper sheaf at $x$ with value $\kappa(x)$.
Let $K$ in $D^b_{\textit{Coh}}(\mathcal{O}_X)$. Let $b \in \mathbf{Z}$.
The following are equivalent
\begin{enumerate}
\item $H^i(K)_x = 0$ for all $i > b$ and
\item $\Hom_X(K, \mathcal{O}_x[-i]) = 0$ for all $i > b$.
\end{enumerate}

\label{lemma-descent-squares-helper}
With $\epsilon : (\mathcal{C}_\tau, \mathcal{O}_\tau) \to
(\mathcal{C}_{\tau'}, \mathcal{O}_{\tau'})$ as above. Let
$$
\xymatrix{
E \ar[d] \ar[r] & Y \ar[d] \\
Z \ar[r] & X
}
$$
be a commutative diagram in the category $\mathcal{C}$ such that
\begin{enumerate}
\item $h_X^\# = h_Y^\# \amalg_{h_E^\#} h_Z^\#$, and
\item $h_E^\# \to h_Y^\#$ is injective
\end{enumerate}
where ${}^\#$ denotes $\tau$-sheafification. Then for
$K' \in D(\mathcal{O}_{\tau'})$ in the essential image of
$R\epsilon_*$ the map $c^{K'}_{X, Z, Y, E}$ of Lemma \ref{lemma-c-square}
(using the $\tau'$-topology) is an isomorphism.

\label{lemma-tensor}
The total complex associated to the tensor product of two
strictly perfect complexes is strictly perfect.

\label{lemma-comparison-general}
With notation as in More on Morphisms, Lemma \ref{more-morphisms-lemma-blowup}
for $a \geq 0$ we have
\begin{enumerate}
\item the map
$\Omega^a_{X/S} \to b_*\Omega^a_{X'/S}$ is an isomorphism,
\item the map $\Omega^a_{Z/S} \to p_*\Omega^a_{E/S}$ is an isomorphism,
\item the map $Rb_*\Omega^a_{X'/S} \to i_*Rp_*\Omega^a_{E/S}$ is an isomorphism
on cohomology sheaves in degree $\geq 1$.
\end{enumerate}

\label{lemma-flat-at-point}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Let $x \in |\mathcal{X}|$. Consider commutative diagrams
$$
\vcenter{
\xymatrix{
U \ar[d]_a \ar[r]_h & V \ar[d]^b \\
\mathcal{X} \ar[r]^f & \mathcal{Y}
}
}
\quad\text{with points}
\vcenter{
\xymatrix{
u \in |U| \ar[d] \\
x \in |\mathcal{X}|
}
}
$$
where $U$ and $V$ are algebraic spaces, $b$ is flat, and
$(a, h) : U \to \mathcal{X} \times_\mathcal{Y} V$
is flat. The following are equivalent
\begin{enumerate}
\item $h$ is flat at $u$ for one diagram as above,
\item $h$ is flat at $u$ for every diagram as above.
\end{enumerate}

\label{lemma-deform-property}
Consider a commutative diagram
$$
\xymatrix{
(X \subset X') \ar[rr]_{(f, f')} \ar[rd] & & (Y \subset Y') \ar[ld] \\
& (S \subset S')
}
$$
of thickenings. Assume $S \subset S'$ is a finite order thickening,
$X'$ flat over $S'$, $X = S \times_{S'} X'$, and
$Y = S \times_{S'} Y'$. Then
\begin{enumerate}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion}
\item $f$ is quasi-compact if and only if $f'$ is quasi-compact,
\label{item-quasi-compact}
\item $f$ is universally closed if and only if $f'$ is universally closed,
\label{item-universally-closed}
\item $f$ is (quasi-)separated if and only if $f'$ is (quasi-)separated,
\label{item-separated}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism}
\item $f$ is surjective if and only if $f'$ is surjective,
\label{item-surjective}
\item $f$ is universally injective if and only if $f'$ is universally injective,
\label{item-universally-injective}
\item $f$ is affine if and only if $f'$ is affine,
\label{item-affine}
\item
\label{item-finite-type}
$f$ is locally of finite type if and only if $f'$ is locally of finite type,
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite}
\item
\label{item-finite-presentation}
$f$ is locally of finite presentation if and only if $f'$ is locally of
finite presentation,
\item
\label{item-relative-dimension-d}
$f$ is locally of finite type of relative dimension $d$ if and only if
$f'$ is locally of finite type of relative dimension $d$,
\item $f$ is universally open if and only if $f'$ is universally open,
\label{item-universally-open}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale}
\item $f$ is proper if and only if $f'$ is proper,
\label{item-proper}
\item $f$ is integral if and only if $f'$ is integral,
\label{item-integral}
\item $f$ is finite if and only if $f'$ is finite,
\label{item-finite}
\item
\label{item-finite-locally-free}
$f$ is finite locally free (of rank $d$) if and only if $f'$
is finite locally free (of rank $d$), and
\item add more here.
\end{enumerate}

\label{lemma-descend-finite}
Notation and assumptions as in Situation \ref{situation-descent-property}. If
\begin{enumerate}
\item $f$ is finite,
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is finite for some $i \geq 0$.

\label{lemma-polarized-limits}
The stack in groupoids $\Polarizedstack$ is limit preserving
(Artin's Axioms, Definition \ref{artin-definition-limit-preserving}).

\label{lemma-non-descending-property-projective}
The properties
\begin{enumerate}
\item[] $\mathcal{P}(f) =$``$f$ is projective'', and
\item[] $\mathcal{P}(f) =$``$f$ is quasi-projective''
\end{enumerate}
are not Zariski local on the base. A fortiori, they are not fpqc local
on the base.

\label{lemma-open-generizing}
\begin{reference}
Follows from the implication (a) $\Rightarrow$ (b) in
\cite[IV, Corollary 1.10.4]{EGA}
\end{reference}
Let $\varphi : X \to Y$ be a morphism of schemes.
If $\varphi$ is open, then $\varphi$ is generizing
(i.e., generalizations lift along $\varphi$).
If $\varphi$ is universally open, then $\varphi$ is
universally generizing.

\label{lemma-counter-Grothendieck-existence}
Counter examples to algebraization of coherent sheaves.
\begin{enumerate}
\item Grothendieck's existence theorem as stated in
Cohomology of Schemes, Theorem \ref{coherent-theorem-grothendieck-existence}
is false if we drop the assumption that $X \to \Spec(A)$ is separated.
\item The stack of coherent sheaves $\Cohstack_{X/B}$
of Quot, Theorems \ref{quot-theorem-coherent-algebraic-general} and
\ref{quot-theorem-coherent-algebraic} is in general
not algebraic if we drop the assumption that $X \to S$ is separated
\item The functor $\Quotfunctor_{\mathcal{F}/X/B}$ of
Quot, Proposition \ref{quot-proposition-quot}
is not an algebraic space in general if we drop the assumption
that $X \to B$ is separated.
\end{enumerate}

\label{lemma-monomorphism-iso-over-red}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of formal algebraic
spaces. Assume
\begin{enumerate}
\item $f$ is representable by algebraic spaces,
\item $f$ is a monomorphism,
\item the inclusion $Y_{red} \to Y$ factors through $f$, and
\item $f$ is locally of finite type or $Y$ is locally Noetherian.
\end{enumerate}
Then $f$ is a closed immersion.

\label{lemma-frobenius-flat-regular}
\begin{reference}
\cite{Kunz-flat}
\end{reference}
Let $p$ be a prime number.
Let $A$ be a Noetherian ring with $p = 0$.
The following are equivalent
\begin{enumerate}
\item $A$ is regular, and
\item $F : A \to A$, $a \mapsto a^p$ is flat.
\end{enumerate}

\label{lemma-not-ind-etale}
There is a ring map $A \to B$ which identifies local rings but
which is not ind-\'etale. A fortiori it is not ind-Zariski.

\label{lemma-lqf-base-change-upper-shriek}
Consider a cartesian square
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
$$
of schemes with $f$ locally quasi-finite. For any abelian sheaf $\mathcal{F}$
on $Y'_\etale$ we have $(g')_*(f')^!\mathcal{F} = f^!g_*\mathcal{F}$.

\label{lemma-NL-formally-smooth}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is formally smooth,
\item $H^{-1}(\NL_{X/Y}) = 0$ and $H^0(\NL_{X/Y}) = \Omega_{X/Y}$
is locally projective.
\end{enumerate}

\label{lemma-integral-universally-closed}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent
\begin{enumerate}
\item $f$ is integral, and
\item $f$ is affine and universally closed.
\end{enumerate}

\label{lemma-locally-algebraic-space}
\begin{slogan}
The definition of an algebraic space is fppf local.
\end{slogan}
Let $S$ be a scheme.
Let $F : (\Sch/S)_{fppf}^{opp} \to \textit{Sets}$ be a functor.
Let $\{S_i \to S\}_{i \in I}$ be a covering of $(\Sch/S)_{fppf}$.
Assume that
\begin{enumerate}
\item $F$ is a sheaf,
\item each $F_i = h_{S_i} \times F$ is an algebraic space, and
\item $\coprod_{i \in I} F_i$ is an algebraic space (see
Spaces, Lemma \ref{spaces-lemma-coproduct-algebraic-spaces}).
\end{enumerate}
Then $F$ is an algebraic space.

\label{proposition-Grauert-Riemenschneider}
In Situation \ref{situation-vanishing} assume
\begin{enumerate}
\item $X$ is a normal scheme,
\item $A$ is Nagata and has a dualizing complex $\omega_A^\bullet$.
\end{enumerate}
Let $\omega_X$ be the dualizing module of $X$
(Remark \ref{remark-dualizing-setup}). Then $R^1f_*\omega_X = 0$.

\label{lemma-triangle-ses}
With notation as in (\ref{equation-three-maps}) set
$$
\begin{matrix}
\Omega_1 = \Omega_{\mathcal{O}/A} \otimes_\mathcal{O} \underline{B}
\text{ on }\mathcal{C}_{B/A} \\
\Omega_2 = \Omega_{\mathcal{O}/A} \otimes_\mathcal{O} \underline{C}
\text{ on }\mathcal{C}_{C/A} \\
\Omega_3 = \Omega_{\mathcal{O}/B} \otimes_\mathcal{O} \underline{C}
\text{ on }\mathcal{C}_{C/B}
\end{matrix}
$$
Then we have a canonical short exact sequence of sheaves
of $\underline{C}$-modules
$$
0 \to g_1^{-1}\Omega_1 \otimes_{\underline{B}} \underline{C} \to
g_2^{-1}\Omega_2 \to
g_3^{-1}\Omega_3 \to 0
$$
on $\mathcal{C}_{C/B/A}$.

\label{lemma-cup-product-hodge-graded-commutative}
Let $p : X \to S$ be a morphism of schemes.
The cup product on $H^*_{Hodge}(X/S)$ is associative and graded commutative.

\label{lemma-curves-existence}
Consider the stack $\Curvesstack$ over the base
scheme $\Spec(\mathbf{Z})$. Then every formal object is effective.

\label{lemma-silly-compose}
In Lemma \ref{lemma-silly} assume $E_2|_{X_1 \cap X_2}$ is zero. Then
\begin{align*}
P'_1(E_2) & = c'_1(E_2), \\
P'_2(E_2) & = c'_1(E_2)^2 - 2c'_2(E_2), \\
P'_3(E_2) & = c'_1(E_2)^3 - 3c'_1(E_2)c'_2(E_2) + 3c'_3(E_2), \\
P'_4(E_2) & = c'_1(E_2)^4 - 4c'_1(E_2)^2c'_2(E_2) +
4c'_1(E_2)c'_3(E_2) + 2c'_2(E_2)^2 - 4c'_4(E_2),
\end{align*}
and so on with multiplication as in Remark \ref{remark-ring-loc-classes}.

\label{lemma-uniqueness-representable}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
which is representable by algebraic spaces. Then the following are equivalent
\begin{enumerate}
\item $f$ satisfies the uniqueness part of the valuative criterion,
\item for every scheme $T$ and morphism $T \to \mathcal{Y}$
the morphism $\mathcal{X} \times_\mathcal{Y} T \to T$ satisfies
the uniqueness part of the valuative criterion as a morphism
of algebraic spaces.
\end{enumerate}

\label{lemma-Ext-0-regular}
Let $X$ be a regular Noetherian scheme of dimension $d < \infty$. Then
\begin{enumerate}
\item for $\mathcal{F}$, $\mathcal{G}$ coherent $\mathcal{O}_X$-modules
we have $\Ext^n_X(\mathcal{F}, \mathcal{G}) = 0$ for $n > d$, and
\item for $K, L \in D^b_{\textit{Coh}}(\mathcal{O}_X)$ and $a \in \mathbf{Z}$
if $H^i(K) = 0$ for $i < a + d$ and $H^i(L) = 0$ for $i \geq a$ then
$\Hom_X(K, L) = 0$.
\end{enumerate}

\label{lemma-maximal-subfield}
\begin{slogan}
The dimension of a finite central skew field is the square of the dimension
of any maximal subfield.
\end{slogan}
Let $A$ be a finite central skew field over $k$.
Then every maximal subfield $K \subset A$ satisfies
$[A : k] = [K : k]^2$.

\label{lemma-lqf-f-upper-shriek-stalk}
Let $f : X \to Y$ be a morphism of schemes which is locally quasi-finite.
For an abelian group $A$ and a geometric point
$\overline{y} : \Spec(k) \to Y$ we have
$f^!(\overline{y}_*A) = \prod\nolimits_{f(\overline{x}) = \overline{y}}
\overline{x}_*A$.

\label{lemma-tor-qc-qs}
Let $X$ be a quasi-separated scheme. Let $E$ be an object
of $D_\QCoh(\mathcal{O}_X)$. Let $a \leq b$. The
following are equivalent
\begin{enumerate}
\item $E$ has tor amplitude in $[a, b]$, and
\item for all $\mathcal{F}$ in $\QCoh(\mathcal{O}_X)$
we have $H^i(E \otimes_{\mathcal{O}_X}^\mathbf{L} \mathcal{F}) = 0$
for $i \not \in [a, b]$.
\end{enumerate}

\label{lemma-ample-separated}
Let $X$ be a scheme. If there exists an ample invertible sheaf on $X$
then $X$ is separated.

\label{lemma-retrocompact-dense-open-connected-at-infinity-closed}
Let $X$ be a scheme. Let $U \subset X$ be a dense open. Assume
\begin{enumerate}
\item $U \to X$ is quasi-compact,
\item every point of $X \setminus U$ is closed, and
\item for every $x \in X \setminus U$ the punctured spectrum of the
strict henselization of $\mathcal{O}_{X, x}$ is connected.
\end{enumerate}
Then $\textit{F\'Et}_X \to \textit{F\'et}_U$ is fully faithful.

\label{lemma-relative-dualizing-algebraic}
Let $\varphi : R \to A$ be a finite type map of Noetherian rings.
\begin{enumerate}
\item If $\varphi$ is perfect, then
\begin{enumerate}
\item $\omega_{A/R}^\bullet$ is in $D^b_{\textit{Coh}}(A)$,
\item $\omega_{A/R}^\bullet$ has finite tor dimension over $R$, and
\item $A \to R\Hom_A(\omega_{A/R}^\bullet, \omega_{A/R}^\bullet)$
is an isomorphism.
\end{enumerate}
\item If $\varphi$ is flat, then (1)(a), (1)(b), and (1)(c) hold and
\begin{enumerate}
\item $\omega_{A/R}^\bullet$ is $R$-perfect
(More on Algebra,
Definition \ref{more-algebra-definition-relatively-perfect}), and
\item for every map $R \to k$ to a field the base change
$\omega_{A/R}^\bullet \otimes_A^\mathbf{L} (A \otimes_R k)$
is a dualizing complex for $A \otimes_R k$.
\end{enumerate}
\end{enumerate}

\label{lemma-base-change-finite-presentation}
A base change of a finitely presented morphism is of finite presentation.
The same holds for morphisms which are locally of finite presentation.

\label{lemma-loc-chern-disjoint}
In Situation \ref{situation-loc-chern}
if $\alpha \in \CH_k(X)$ has support disjoint from $Z$, then
$P_p(Z \to X, E) \cap \alpha = 0$, resp.\ $c_p(Z \to X, E) \cap \alpha = 0$.

\label{lemma-category-vector-bundles}
The category of vector bundles over a scheme $S$ is
anti-equivalent to the category of quasi-coherent $\mathcal{O}_S$-modules.

\label{lemma-extend-spaces-to-spaces}
Let $T$ be an algebraic space over $\mathbf{Z}$. Let $\mathcal{S}_T$
denote the corresponding algebraic stack (Algebraic Stacks, Sections
\ref{algebraic-section-split},
\ref{algebraic-section-representable-by-algebraic-spaces}, and
\ref{algebraic-section-stacks-spaces}).
We have an equivalence of categories
$$
\left\{
\begin{matrix}
\text{morphisms of algebraic spaces }\\
X \to T\text{ of finite type}
\end{matrix}
\right\}
\longrightarrow
\Mor_{\textit{Cat}/\Sch_{fppf}}(\mathcal{S}_T, \Spacesstack'_{ft})
$$
and an equivalence of categories
$$
\left\{
\begin{matrix}
\text{morphisms of algebraic spaces }X \to T\\
\text{of finite presentation, flat, and proper}
\end{matrix}
\right\}
\longrightarrow
\Mor_{\textit{Cat}/\Sch_{fppf}}(\mathcal{S}_T,
\Spacesstack'_{fp, flat, proper})
$$

\label{lemma-scheme-theoretic-image}
\begin{slogan}
The scheme-theoretic image of a morphism of algebraic spaces exists.
\end{slogan}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. There exists a closed subspace $Z \subset Y$ such that $f$ factors
through $Z$ and such that for any other closed subspace $Z' \subset Y$
such that $f$ factors through $Z'$ we have $Z \subset Z'$.

\label{lemma-topology-limit}
With same notation and assumptions as in Lemma \ref{lemma-inverse-limit-sets}
we have $|X| = \lim_i |X_i|$ as topological spaces.

\label{lemma-affine-equivalence-algebras}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
There is an anti-equivalence of categories
$$
\begin{matrix}
\text{algebraic spaces} \\
\text{affine over }X
\end{matrix}
\longleftrightarrow
\begin{matrix}
\text{quasi-coherent sheaves} \\
\text{of }\mathcal{O}_X\text{-algebras}
\end{matrix}
$$
which associates to $f : Y \to X$ the sheaf $f_*\mathcal{O}_Y$.
Moreover, this equivalence is compatible with arbitrary base change.

\label{lemma-quasi-compact-quasi-separated-spectral}
Let $X$ be a quasi-compact and quasi-separated scheme.
Then the underlying topological space of $X$ is a spectral space.

\label{lemma-module-filtered-colimit-constructibles}
In Situation \ref{situation-quasi-compact-objects} assume
(\ref{item-enough}) and (\ref{item-enough-qc}) hold.
\begin{enumerate}
\item Every sheaf of sets is a filtered colimit of sheaves of the form
\begin{equation}
\label{equation-towards-constructible-sets}
\text{Coequalizer}\left(
\xymatrix{
\coprod\nolimits_{j = 1, \ldots, m} h_{V_j}^\#
\ar@<1ex>[r] \ar@<-1ex>[r] &
\coprod\nolimits_{i = 1, \ldots, n} h_{U_i}^\#
}
\right)
\end{equation}
with $U_i$ and $V_j$ in $\mathcal{B}$.
\item If $\mathcal{O}$ is a sheaf of rings, then every $\mathcal{O}$-module
is a filtered colimit of sheaves of the form
\begin{equation}
\label{equation-towards-constructible}
\Coker\left(
\bigoplus\nolimits_{j = 1, \ldots, m} j_{V_j!}\mathcal{O}_{V_j}
\longrightarrow
\bigoplus\nolimits_{i = 1, \ldots, n} j_{U_i!}\mathcal{O}_{U_i}
\right)
\end{equation}
with $U_i$ and $V_j$ in $\mathcal{B}$.
\end{enumerate}

\label{lemma-composition-finite-presentation}
The composition of finitely presented morphisms is of finite presentation.
The same holds for morphisms which are locally of finite presentation.

\label{lemma-bounded-flat-K-flat}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. A bounded above complex
of flat $\mathcal{O}$-modules is K-flat.

\label{lemma-verify-site-ph}
Let $S$ be a scheme. Let $\Sch_{ph}$ be a big ph
site containing $S$. Then $(\textit{Aff}/S)_{ph}$ is a site.

\label{lemma-diagonal}
Let $B \to S$ be as in Section \ref{section-notation}.
Let $(U, R, s, t, c)$ be a groupoid in algebraic spaces over $B$.
Let $G \to U$ be the stabilizer group algebraic space.
\begin{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_B U$ is separated,
\item $G \to U$ is separated, and
\item $e : U \to G$ is a closed immersion.
\end{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_B U$ is locally separated,
\item $G \to U$ is locally separated, and
\item $e : U \to G$ is an immersion.
\end{enumerate}
\item The following are equivalent
\begin{enumerate}
\item $j : R \to U \times_B U$ is quasi-separated,
\item $G \to U$ is quasi-separated, and
\item $e : U \to G$ is quasi-compact.
\end{enumerate}
\end{enumerate}

\label{lemma-sum-effective-Cartier-divisors}
The sum of two effective Cartier divisors is an effective
Cartier divisor.

\label{lemma-w-contractible-proetale-cover}
Let $T = \Spec(A)$ be an affine scheme. The following are equivalent
\begin{enumerate}
\item $A$ is w-contractible, and
\item every pro-\'etale covering of $T$ can be refined by
a Zariski covering of the form $T = \coprod_{i = 1, \ldots, n} U_i$.
\end{enumerate}

\label{lemma-surjective-generated-degree-1-map-relative-proj}
With hypotheses and notation as in Lemma \ref{lemma-morphism-relative-proj}
above. Assume $\mathcal{A}_d \to \mathcal{B}_d$ is surjective for $d \gg 0$
and that $\mathcal{A}$ is generated by $\mathcal{A}_1$ over $\mathcal{A}_0$.
Then
\begin{enumerate}
\item $U(\psi) = Q$,
\item $r_\psi : Q \to P$ is a closed immersion, and
\item the maps $\theta : r_\psi^*\mathcal{O}_P(n) \to \mathcal{O}_Q(n)$
are isomorphisms.
\end{enumerate}

\label{lemma-DQCoh-alternative-small}
In the situation above there are canonical exact equivalences between
the following triangulated categories
\begin{enumerate}
\item $D_\QCoh(\mathcal{O}_X)$,
\item $D_\QCoh(X_{Zar}, \mathcal{O})$,
\item $D_\QCoh(X_{affine, Zar}, \mathcal{O})$,
\item $D_\QCoh(X_{affine}, \mathcal{O}_X)$, and
\item $\mathit{QC}(X_{affine}, \mathcal{O})$.
\end{enumerate}

\label{lemma-Mor-s-lfp}
The morphism $\mathit{Mor}_B(Y, X) \to B$ is separated
and locally of finite presentation.

\label{lemma-out-of-finite}
Suppose that, in (\ref{equation-compare}), $\mathcal{C}$ is the category
of sets and $A$ is a {\it finite set}, then the map is a bijection.

\label{lemma-Noetherian-approximation-geometrically-reduced}
Let $f : X \to S$ be a morphism of affine schemes, which is
of finite presentation with geometrically reduced fibres.
Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ has geometrically reduced fibres.

\label{lemma-right-resolution}
Let $(A, \text{d})$ be a differential graded algebra.
Let $M$ be a differential graded $A$-module. There exists a homomorphism
$M \to I$ of differential graded $A$-modules such that
\begin{enumerate}
\item $M \to I$ is a quasi-isomorphism, and
\item $I$ has property (I).
\end{enumerate}

\label{lemma-descending-property-universally-submersive}
The property $\mathcal{P}(f) =$``$f$ is universally submersive''
is fpqc local on the base.

\label{lemma-composition-universally-closed}
The composition of a pair of (universally) closed morphisms of
algebraic stacks is (universally) closed.

\label{lemma-conormal-algebra-functorial}
Let $S$ be a scheme. Let
$$
\xymatrix{
Z \ar[r]_i \ar[d]_f & X \ar[d]^g \\
Z' \ar[r]^{i'} & X'
}
$$
be a commutative diagram of algebraic spaces over $S$.
Assume $i$, $i'$ immersions. There is a canonical map
of graded $\mathcal{O}_Z$-algebras
$$
f^*\mathcal{C}_{Z'/X', *}
\longrightarrow
\mathcal{C}_{Z/X, *}
$$

\label{proposition-weil-cohomology-theory}
Let $k$ be a field. Let $F$ be a field of characteristic $0$. There is a
$1$-to-$1$ correspondence between the following
\begin{enumerate}
\item data (D0), (D1), (D2), and (D3) satisfying (A), (B), and(C), and
\item $\mathbf{Q}$-linear symmetric monoidal functors
$$
G : M_k \longrightarrow \text{graded }F\text{-vector spaces}
$$
such that $G(\mathbf{1}(1))$ is nonzero only in degree $-2$.
\end{enumerate}

\label{lemma-regular-sequence}
Let $(A, \mathfrak m)$ be a Noetherian local ring. Let
$I \subset J \subset A$ be proper ideals. Assume
\begin{enumerate}
\item $A/J$ has finite tor dimension over $A/I$, and
\item $J$ is generated by a regular sequence.
\end{enumerate}
Then $I$ is generated by a regular sequence and $J/I$
is generated by a regular sequence.

\label{lemma-quotient-stack-cocycle}
Assumptions and notation as in
Lemmas \ref{lemma-quotient-stack-arrows} and
\ref{lemma-quotient-stack-2-arrow}.
The vertical composition of
$$
\xymatrix@C=15pc{
\mathcal{S}_{R \times_{s, U, t} R}
\ruppertwocell^{\pi \circ s \circ \text{pr}_1 = \pi \circ s \circ c}{\ \ \ \ \ \ \alpha \star \text{id}_{\text{pr}_1}}
\ar[r]_(.3){\pi \circ t \circ \text{pr}_1 = \pi \circ s \circ \text{pr}_0}
\rlowertwocell_{\pi \circ t \circ \text{pr}_0 = \pi \circ t \circ c}{\ \ \ \ \ \ \alpha \star \text{id}_{\text{pr}_0}}
&
[U/R]
}
$$
is the $2$-morphism $\alpha \star \text{id}_c$. In a formula
$\alpha \star \text{id}_c =
(\alpha \star \text{id}_{\text{pr}_0})
\circ
(\alpha \star \text{id}_{\text{pr}_1})
$.

\label{lemma-surjective-generated-degree-1-map-relative-proj}
With hypotheses and notation as in Lemma \ref{lemma-morphism-relative-proj}
above. Assume $\mathcal{A}_d \to \mathcal{B}_d$ is surjective for $d \gg 0$
and that $\mathcal{A}$ is generated by $\mathcal{A}_1$ over $\mathcal{A}_0$.
Then
\begin{enumerate}
\item $U(\psi) = Y$,
\item $r_\psi : Y \to X$ is a closed immersion, and
\item the maps $\theta : r_\psi^*\mathcal{O}_X(n) \to \mathcal{O}_Y(n)$
are isomorphisms.
\end{enumerate}

\label{proposition-hilb-d}
Let $X$ be a geometrically irreducible smooth proper curve over a field $k$.
\begin{enumerate}
\item The functors $\Hilbfunctor^d_{X/k}$ are representable by smooth
proper varieties $\underline{\Hilbfunctor}^d_{X/k}$ of dimension
$d$ over $k$.
\item For a field extension $k'/k$ the $k'$-rational points
of $\underline{\Hilbfunctor}^d_{X/k}$ are in $1$-to-$1$ bijection
with effective Cartier divisors of degree $d$ on $X_{k'}$.
\item For $d_1, d_2 \geq 0$ there is a morphism
$$
\underline{\Hilbfunctor}^{d_1}_{X/k}
\times_k
\underline{\Hilbfunctor}^{d_2}_{X/k}
\longrightarrow
\underline{\Hilbfunctor}^{d_1 + d_2}_{X/k}
$$
which is finite locally free of degree ${d_1 + d_2 \choose d_1}$.
\end{enumerate}

\label{lemma-composition-formal-smoothness}
The composition of formally smooth morphisms of algebraic stacks
is formally smooth.

\label{lemma-perfect-direct-image}
Let $S$ be a Noetherian scheme. Let $f : X \to S$ be a morphism of schemes
which is locally of finite type. Let $E \in D(\mathcal{O}_X)$ such that
\begin{enumerate}
\item $E \in D^b_{\textit{Coh}}(\mathcal{O}_X)$,
\item the support of $H^i(E)$ is proper over $S$ for all $i$, and
\item $E$ has finite tor dimension as an object of $D(f^{-1}\mathcal{O}_S)$.
\end{enumerate}
Then $Rf_*E$ is a perfect object of $D(\mathcal{O}_S)$.

\label{lemma-sheaf-property-V}
Let $F$ be a contravariant functor on the category
of schemes with values in sets. Then $F$ satisfies
the sheaf property for the V topology if and only
if it satisfies
\begin{enumerate}
\item the sheaf property for every Zariski covering, and
\item the sheaf property for any standard V covering.
\end{enumerate}
Moreover, in the presence of (1) property (2) is equivalent to
property
\begin{enumerate}
\item[(2')] the sheaf property for a standard V covering
of the form $\{V \to U\}$, i.e., consisting of a single arrow.
\end{enumerate}

\label{lemma-regular-rational}
Let $A$ be a Nagata regular local ring of dimension $2$. Then $A$ defines
a rational singularity.

\label{lemma-torsors-sheaf-stack-in-groupoids}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p : \mathcal{G}\textit{-Torsors} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{lemma-what-equivalence-gives}
Let $f : X \to Y$ be a morphism of quasi-compact and quasi-separated schemes
such that the base change functor $\textit{F\'Et}_Y \to \textit{F\'Et}_X$
is an equivalence of categories. In this case
\begin{enumerate}
\item $f$ induces a homeomorphism $\pi_0(X) \to \pi_0(Y)$,
\item if $X$ or equivalently $Y$ is connected, then
$\pi_1(X, \overline{x}) = \pi_1(Y, \overline{y})$.
\end{enumerate}

\label{lemma-lci-syntomic-local-source}
The property $\mathcal{P}(f) =$``$f$ is a local complete intersection
morphism'' is syntomic local on the source.

\label{lemma-refine-by-ph}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family
of morphisms such that $f_i$ is locally of finite type for all $i$.
The following are equivalent
\begin{enumerate}
\item $\{T_i \to T\}_{i \in I}$ is a ph covering,
\item there is a ph covering which refines $\{T_i \to T\}_{i \in I}$, and
\item $\{\coprod_{i \in I} T_i \to T\}$ is a ph covering.
\end{enumerate}

\label{proposition-group-space-scheme-over-field}
Let $k$ be a field. Let $G$ be a group algebraic space over $k$.
If $G$ is separated, then $G$ is a scheme.

\label{lemma-catenary-dimension-function}
Let $S$ be a locally Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $S$ is catenary, and
\item locally in the Zariski topology there exists a dimension function
on $S$ (see Topology, Definition \ref{topology-definition-dimension-function}).
\end{enumerate}

\label{lemma-universally-injective-local}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent:
\begin{enumerate}
\item $f$ is universally injective,
\item for every affine scheme $Z$ and any morphism
$Z \to \mathcal{Y}$ the morphism $Z \times_\mathcal{Y} \mathcal{X} \to Z$
is universally injective, and
\item add more here.
\end{enumerate}

\label{lemma-is-limit-dimension}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $E \in D(\mathcal{O})$.
Assume there exists an integer $d \geq 0$
and a subset $\mathcal{B} \subset \Ob(\mathcal{C})$ such that
\begin{enumerate}
\item every object of $\mathcal{C}$ has a covering whose members are
elements of $\mathcal{B}$,
\item $H^p(V, H^q(E)) = 0$ for $p > d$, $q < 0$, and $V \in \mathcal{B}$.
\end{enumerate}
Then the map $E \to R\lim \tau_{\geq -n} E$ of
Derived Categories, Remark
\ref{derived-remark-map-into-derived-limit-truncations}
is an isomorphism in $D(\mathcal{O})$.

\label{lemma-vanishing-surjective}
In Cohomology of Spaces, Situation \ref{spaces-cohomology-situation-vanishing}
the morphism $p : X \to \Spec(A)$ is surjective.

\label{lemma-topology-points}
There exists a unique topology on the sets of points
of algebraic stacks with the following properties:
\begin{enumerate}
\item for every morphism of algebraic stacks $\mathcal{X} \to \mathcal{Y}$
the map $|\mathcal{X}| \to |\mathcal{Y}|$ is continuous, and
\item for every morphism $U \to \mathcal{X}$ which is flat and locally
of finite presentation with $U$ an algebraic space
the map of topological spaces $|U| \to |\mathcal{X}|$ is continuous and open.
\end{enumerate}

\label{lemma-ring-affine-open-injective-local-ring}
Let $X$ be a scheme and $x \in X$ a point. There exists an affine open
neighbourhood $U \subset X$ of $x$ such that the canonical map
$\mathcal{O}_X(U) \to \mathcal{O}_{X, x}$ is injective in each of
the following cases:
\begin{enumerate}
\item $X$ is integral,
\item $X$ is locally Noetherian,
\item $X$ is reduced and has a finite number of irreducible components.
\end{enumerate}

\label{lemma-picard-T-and-A}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type $T$.
Then $\Pic(T) \subset \Coker(A)$ where $A = (a_{ij})$.

\label{lemma-sheaf}
Let $S$ be a scheme.
Let $X \subset X'$ and $Y \subset Y'$ be first order thickenings
over $S$. Assume given a morphism $a : X \to Y$ and a map
$A : a^*\mathcal{C}_{Y/Y'} \to \mathcal{C}_{X/X'}$ of
$\mathcal{O}_X$-modules. For an open subscheme $U' \subset X'$
consider morphisms $a' : U' \to Y'$ such that
\begin{enumerate}
\item $a'$ is a morphism over $S$,
\item $a'|_U = a|_U$, and
\item the induced map
$a^*\mathcal{C}_{Y/Y'}|_U \to \mathcal{C}_{X/X'}|_U$
is the restriction of $A$ to $U$.
\end{enumerate}
Here $U = X \cap U'$. Then the rule
\begin{equation}
\label{equation-sheaf}
U' \mapsto
\{a' : U' \to Y'\text{ such that (1), (2), (3) hold.}\}
\end{equation}
defines a sheaf of sets on $X'$.

\label{lemma-gorenstein-local-syntomic}
The property $\mathcal{P}(S) =$``$S$ is Gorenstein''
is local in the syntomic topology.

\label{lemma-describe-sheaves-simplicial-site}
Let $X$ be a simplicial space. There is an equivalence of
categories between
\begin{enumerate}
\item $\Sh(X_{Zar})$, and
\item category of systems $(\mathcal{F}_n, \mathcal{F}(\varphi))$
described above.
\end{enumerate}

\label{lemma-zariski}
Let $f : X \to S$ be a morphism of schemes and $U \subset S$ an open. If
\begin{enumerate}
\item $f$ is separated, locally of finite type, and flat,
\item $f^{-1}(U) \to U$ is an isomorphism, and
\item $U \subset S$ is retrocompact and scheme theoretically dense,
\end{enumerate}
then $f$ is an open immersion.

\label{lemma-composition-ind-etale}
Let $A \to B$ and $B \to C$ be ring maps. If $A \to B$ and $B \to C$
are ind-\'etale, then $A \to C$ is ind-\'etale.

\label{lemma-gorenstein-1-curves}
There exist an open substack
$\Curvesstack^{Gorenstein, 1} \subset \Curvesstack$ such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein, 1}$,
\item the morphism $X \to S$ is Gorenstein and has
relative dimension $1$ (Morphisms of Spaces, Definition
\ref{spaces-morphisms-definition-relative-dimension}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein, 1}$,
\item $X$ is Gorenstein and $X$ is equidimensional of
dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-push-constant-sheaf-from-open}
Let $X$ be an integral normal scheme with function field $K$.
Let $E$ be a set.
\begin{enumerate}
\item Let $g : \Spec(K) \to X$ be the inclusion of the generic point.
Then $g_*\underline{E} = \underline{E}$.
\item Let $j : U \to X$ be the inclusion of a nonempty open. Then
$j_*\underline{E} = \underline{E}$.
\end{enumerate}

\label{lemma-finite-over-henselian}
If $R$ is henselian and $A$ is a finite $R$-algebra, then $A$ is a finite
product of henselian local rings.

\label{lemma-characterize-injective}
Let $R$ be a ring. Let $E$ be an $R$-module. The following are equivalent
\begin{enumerate}
\item $E$ is an injective $R$-module, and
\item given an ideal $I \subset R$ and a module map $\varphi : I \to E$
there exists an extension of $\varphi$ to an $R$-module map $R \to E$.
\end{enumerate}

\label{lemma-base-change-relative-conditions}
Having property $(\beta)$, being decent, or being reasonable
is preserved under arbitrary base change.

\label{lemma-functor-fp-modules-exact}
With $A$, $B$, $F$, and $F'$ as in Lemma \ref{lemma-functor-fp-modules}.
\begin{enumerate}
\item If $F$ is additive, then $F'$ is additive and
commutes with arbitrary direct sums, and
\item if $F$ is right exact, then $F'$ is right exact.
\end{enumerate}

\label{lemma-surjective-graded-rings-map-proj}
With hypotheses and notation as in Lemma \ref{lemma-morphism-proj} above.
Assume $A_d \to B_d$ is surjective for all $d \gg 0$. Then
\begin{enumerate}
\item $U(\psi) = Y$,
\item $r_\psi : Y \to X$ is a closed immersion, and
\item the maps $\theta : r_\psi^*\mathcal{O}_X(n) \to \mathcal{O}_Y(n)$
are surjective but not isomorphisms in general (even if $A \to B$ is
surjective).
\end{enumerate}

\label{lemma-flat-dimension-n}
In Situation \ref{situation-flat-dimension-n}.
\begin{enumerate}
\item The functor $F_n$ satisfies the sheaf property for the fpqc topology.
\item If $f$ is quasi-compact and locally of finite presentation
and $\mathcal{F}$ is of finite presentation, then the functor $F_n$ is
limit preserving.
\end{enumerate}

\label{lemma-bound-wm}
Fix $g \geq 2$. For every minimal numerical type $n, m_i, a_{ij}, w_i, g_i$
of genus $g$ we have $m_i|a_{ij}| \leq 768g$.

\label{lemma-locally-constant-finite-type}
Let $\mathcal{C}$ be a site. Let $\Lambda$ be a ring and let $M$ be a
$\Lambda$-module. Assume $\Sh(\mathcal{C})$ is not the empty topos. Then
\begin{enumerate}
\item $\underline{M}$ is a finite type sheaf of $\underline{\Lambda}$-modules
if and only if $M$ is a finite $\Lambda$-module, and
\item $\underline{M}$ is a finitely presented sheaf of
$\underline{\Lambda}$-modules if and only if $M$ is a 
finitely presented $\Lambda$-module.
\end{enumerate}

\label{lemma-local-cohomology-noetherian}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal.
\begin{enumerate}
\item the adjunction $R\Gamma_I(K) \to K$ is an isomorphism
for $K \in D_{I^\infty\text{-torsion}}(A)$,
\item the functor
(\ref{equation-compare-torsion})
$D(I^\infty\text{-torsion}) \to D_{I^\infty\text{-torsion}}(A)$
is an equivalence,
\item the transformation of functors
(\ref{equation-compare-torsion-functors}) is an isomorphism,
in other words $R\Gamma_I(K) = R\Gamma_Z(K)$ for $K \in D(A)$.
\end{enumerate}

\label{lemma-locally-closed-in-Noetherian}
Any locally closed subscheme of a (locally) Noetherian
scheme is (locally) Noetherian.

\label{lemma-gysin-differential}
The Gysin map (\ref{equation-gysin}) is compatible with the de Rham
differentials on $\Omega^\bullet_{X/S}$ and $\Omega^\bullet_{Z/S}$.

\label{lemma-perfect-weankly-normal}
Let $p$ be a prime number. An $\mathbf{F}_p$-algebra $A$ is
absolutely weakly normal if and only if it is perfect.

\label{lemma-RHom-is-tensor}
In Situation \ref{situation-resolution} assume that
\begin{enumerate}
\item $E$ viewed as an object of $D(R)$ is compact, and
\item $N = \Hom^\bullet_R(E^\bullet, R)$ computes $R\Hom(E, R)$.
\end{enumerate}
Then $R\Hom(E, -) : D(R) \to D(E)$ is isomorphic to
$K \mapsto K \otimes_R^\mathbf{L} N$.

\label{lemma-cotangent-finite}
Let $A$ be a Noetherian ring. Let $A \to B$ be a finite type ring map.
Then $H^n(L_{B/A})$ is a finite $B$-module for all $n \in \mathbf{Z}$.

\label{lemma-descend-tor-amplitude}
Let $X$ be a scheme. Let $E$ be an object of $D(\mathcal{O}_X)$.
Then
\begin{enumerate}
\item $E$ has tor amplitude in $[a, b]$ if and only if
$\epsilon^*E$ has tor amplitude in $[a, b]$.
\item $E$ has finite tor dimension if and only if $\epsilon^*E$ has finite
tor dimension.
\end{enumerate}
Here $\epsilon$ is as in (\ref{equation-epsilon}).

\label{lemma-composition-local-isomorphism}
Let $A \to B$ and $B \to C$ be ring maps.
\begin{enumerate}
\item If $A \to B$ and $B \to C$ are local isomorphisms, then $A \to C$
is a local isomorphism.
\item If $A \to B$ and $B \to C$ identify local rings, then $A \to C$
identifies local rings.
\end{enumerate}

\label{lemma-sheaf-differentials-etale-localization}
Let
$$
\xymatrix{
X_1 \ar[d] & X_2 \ar[l]^f \ar[d] \\
S_1 & S_2 \ar[l]
}
$$
be a commutative diagram of schemes with $X_2 \to X_1$ and $S_2 \to S_1$
\'etale. Then the map $c_f : f^*\Omega_{X_1/S_1} \to \Omega_{X_2/S_2}$ of
Morphisms, Lemma \ref{morphisms-lemma-functoriality-differentials}
is an isomorphism.

\label{lemma-closed-immersion-valuative-criteria}
A closed immersion of algebraic stacks satisfies both
the existence and uniqueness part of the valuative criterion.

\label{lemma-rig-etale-rig-smooth-morphism}
A rig-\'etale morphism of locally Noetherian formal algebraic spaces
is rig-smooth.

\label{lemma-regular}
Let $S$ be a scheme.
Let $X$ be a locally Noetherian algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item $X$ is regular, and
\item every \'etale local ring $\mathcal{O}_{X, \overline{x}}$ is
regular.
\end{enumerate}

\label{lemma-ample-power-ample}
\begin{reference}
\cite[II Proposition 4.5.6(i)]{EGA}
\end{reference}
Let $X$ be a scheme. Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Let $n \geq 1$. Then $\mathcal{L}$ is ample if and only if
$\mathcal{L}^{\otimes n}$ is ample.

\label{lemma-characterize-affine}
Let $X$ be a scheme. Suppose that there exist finitely many elements
$f_1, \ldots, f_n \in \Gamma(X, \mathcal{O}_X)$ such that
\begin{enumerate}
\item each $X_{f_i}$ is an affine open of $X$, and
\item the ideal generated by $f_1, \ldots, f_n$ in
$\Gamma(X, \mathcal{O}_X)$ is equal to the unit ideal.
\end{enumerate}
Then $X$ is affine.

\label{lemma-check-K-flat-stalks}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $\mathcal{K}^\bullet$ be a complex of $\mathcal{O}$-modules.
\begin{enumerate}
\item If $\mathcal{K}^\bullet$ is K-flat, then for every point $p$
of the site $\mathcal{C}$ the complex of $\mathcal{O}_p$-modules
$\mathcal{K}_p^\bullet$ is K-flat in the sense of
More on Algebra, Definition \ref{more-algebra-definition-K-flat}
\item If $\mathcal{C}$ has enough points, then the converse is true.
\end{enumerate}

\label{lemma-recurring}
\begin{reference}
\cite[Theorem I]{Taussky}
\end{reference}
Let $A = (a_{ij})$ be a complex $n \times n$ matrix.
\begin{enumerate}
\item If $|a_{ii}| > \sum_{j \not = i} |a_{ij}|$ for each $i$, then
$\det(A)$ is nonzero.
\item If there exists a real vector $m = (m_1, \ldots, m_n)$
with $m_i > 0$ such that $|a_{ii} m_i| > \sum_{j \not = i} |a_{ij}m_j|$
for each $i$, then $\det(A)$ is nonzero.
\end{enumerate}

\label{lemma-descending-property-universally-injective}
The property $\mathcal{P}(f) =$``$f$ is universally injective''
is fpqc local on the base.

\label{lemma-lci-properties}
Let $S$ be a scheme. Let $f : X \to Y$ be a local complete intersection
morphism of algebraic spaces over $S$. Then
\begin{enumerate}
\item $f$ is locally of finite presentation,
\item $f$ is pseudo-coherent, and
\item $f$ is perfect.
\end{enumerate}

\label{lemma-closed-immersion-finite-presentation}
\begin{slogan}
Closed immersions of finite presentation correspond
to quasi-coherent sheaves of ideals of finite type.
\end{slogan}
A closed immersion $i : Z \to X$ is of finite presentation if and only if
the associated quasi-coherent sheaf of ideals
$\mathcal{I} = \Ker(\mathcal{O}_X \to i_*\mathcal{O}_Z)$
is of finite type (as an $\mathcal{O}_X$-module).

\label{lemma-regular-immersion-lci}
Let $S$ be a scheme. A Koszul-regular immersion of algebraic spaces
over $S$ is a local complete intersection morphism.

\label{lemma-composition-open}
The composition of a pair of (universally) open morphisms of algebraic spaces
is (universally) open.

\label{proposition-lift}
\begin{slogan}
Ind-smoothness of an algebra is stable under infinitesimal deformations
\end{slogan}
Let $R \to \Lambda$ be a ring map. Let $I \subset R$ be an ideal.
Assume that
\begin{enumerate}
\item $I$ is nilpotent,
\item $\Lambda/I\Lambda$ is a filtered colimit of smooth $R/I$-algebras, and
\item $R \to \Lambda$ is flat.
\end{enumerate}
Then $\Lambda$ is a filtered colimit of smooth $R$-algebras.

\label{lemma-base-change-gerbe}
Let $\mathcal{C}$ be a site. Let
$$
\xymatrix{
\mathcal{X}' \ar[r]_{G'} \ar[d]_{F'} & \mathcal{X} \ar[d]^F \\
\mathcal{Y}' \ar[r]^G & \mathcal{Y}
}
$$
be a $2$-fibre product of stacks in groupoids over $\mathcal{C}$.
If $\mathcal{X}$ is a gerbe over $\mathcal{Y}$, then
$\mathcal{X}'$ is a gerbe over $\mathcal{Y}'$.

\label{lemma-rings-RS}
Example \ref{example-rings}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_P$ is a deformation category
for any $k$-algebra $P$.

\label{lemma-all-modules-quasi-coherent}
Let $R$ be a local ring of dimension $0$. Let $S = \Spec(R)$.
Then every $\mathcal{O}_S$-module on $S_\etale$ is quasi-coherent.

\label{lemma-countable-abelian}
Let $\mathcal{A}$ be a countable abelian category.
Then $D^b(\mathcal{A})$ is countable.

\label{lemma-descending-property-monomorphism}
The property $\mathcal{P}(f) =$``$f$ is a monomorphism''
is fpqc local on the base.

\label{lemma-generically-finite}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Assume that $f$ is quasi-separated of finite type.
Let $y \in |Y|$ be a point of codimension $0$ on $Y$.
The following are equivalent:
\begin{enumerate}
\item the space $|X_k|$ is finite where $\Spec(k) \to Y$ represents $y$,
\item $X \to Y$ is quasi-finite at all points of $|X|$ over $y$,
\item there exists an open subspace $Y' \subset Y$ with $y \in |Y'|$
such that $Y' \times_Y X \to Y'$ is finite.
\end{enumerate}
If $Y$ is decent these are also equivalent to
\begin{enumerate}
\item[(4)] the set $f^{-1}(\{y\})$ is finite.
\end{enumerate}

\label{lemma-fibred-category-pushforward}
In the situation above, if $\mathcal{S}$ is a fibred category over
$\mathcal{D}$ then $u^p\mathcal{S}$ is a fibred category over $\mathcal{C}$.

\label{lemma-reduced-scheme-theoretically-dense}
Let $X$ be a reduced scheme and let $U \subset X$ be an open subscheme.
Then the following are equivalent
\begin{enumerate}
\item $U$ is topologically dense in $X$,
\item the scheme theoretic closure of $U$ in $X$ is $X$, and
\item $U$ is scheme theoretically dense in $X$.
\end{enumerate}

\label{lemma-invert-s-sections}
\begin{reference}
\cite[Section 6.8]{EGA1-second}
\end{reference}
Let $X$ be a scheme. Let $\mathcal{L}$ be an invertible sheaf on $X$.
Let $s \in \Gamma(X, \mathcal{L})$. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module.
\begin{enumerate}
\item If $X$ is quasi-compact, then (\ref{equation-module-invert-s})
is injective, and
\item if $X$ is quasi-compact and quasi-separated, then
(\ref{equation-module-invert-s}) is an isomorphism.
\end{enumerate}
In particular, the canonical map
$$
\Gamma_*(X, \mathcal{L})_{(s)}
\longrightarrow
\Gamma(X_s, \mathcal{O}_X),\quad
a/s^n \longmapsto a \otimes s^{-n}
$$
is an isomorphism if $X$ is quasi-compact and quasi-separated.

\label{lemma-perfect-direct-image}
Let $S$ be a scheme. Let $Y$ be a Noetherian algebraic space over $S$.
Let $f : X \to Y$ be a morphism of algebraic spaces which is locally of
finite type and quasi-separated. Let $E \in D(\mathcal{O}_X)$ such that
\begin{enumerate}
\item $E \in D^b_{\textit{Coh}}(\mathcal{O}_X)$,
\item the support of $H^i(E)$ is proper over $Y$ for all $i$,
\item $E$ has finite tor dimension as an object of $D(f^{-1}\mathcal{O}_Y)$.
\end{enumerate}
Then $Rf_*E$ is a perfect object of $D(\mathcal{O}_Y)$.

\label{lemma-conormal-sheaf-section-projective-bundle}
Let $S$ be a scheme and let $X$ be an algebraic space over $S$.
Let $\mathcal{E}$ be a quasi-coherent $\mathcal{O}_X$-module.
There is a bijection
$$
\left\{
\begin{matrix}
\text{sections }\sigma\text{ of the } \\
\text{morphism } \mathbf{P}(\mathcal{E}) \to X
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{surjections }\mathcal{E} \to \mathcal{L}\text{ where} \\
\mathcal{L}\text{ is an invertible }\mathcal{O}_X\text{-module}
\end{matrix}
\right\}
$$
In this case $\sigma$ is a closed immersion and there is a canonical
isomorphism
$$
\Ker(\mathcal{E} \to \mathcal{L})
\otimes_{\mathcal{O}_X} \mathcal{L}^{\otimes -1}
\longrightarrow
\mathcal{C}_{\sigma(X)/\mathbf{P}(\mathcal{E})}
$$
Both the bijection and isomorphism are compatible with base change.

\label{lemma-resolution-property-ample-relative}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$. Assume
\begin{enumerate}
\item $Y$ is quasi-compact and quasi-separated and has the resolution property,
\item there exists an $f$-ample invertible module on $X$
(Divisors on Spaces, Definition
\ref{spaces-divisors-definition-relatively-ample}).
\end{enumerate}
Then $X$ has the resolution property.

\label{proposition-avramov-map}
Let $A \to B$ be a local homomorphism of Noetherian local rings.
Then the following are equivalent
\begin{enumerate}
\item $B$ is a complete intersection and
$\text{Tor}^A_p(B, A/\mathfrak m_A)$ is nonzero for only finitely many $p$,
\item $A$ is a complete intersection and
$A^\wedge \to B^\wedge$ is a complete intersection homomorphism
in the sense defined above.
\end{enumerate}

\label{lemma-resolution-property-affine-diagonal}
\begin{reference}
Special case of \cite[Proposition 1.3]{totaro_resolution}.
\end{reference}
Let $X$ be a quasi-compact and quasi-separated scheme with
the resolution property. Then $X$ has affine diagonal.

\label{lemma-complement-of-affine-does-not-contain-qc-dense-open}
Nonexistence quasi-compact opens of affines:
\begin{enumerate}
\item There exist an affine scheme $S$ and affine open $U \subset S$
such that there is no quasi-compact open $V \subset S$ with
$U \cap V = \emptyset$ and $U \cup V$ dense in $S$.
\item There exists an affine scheme $S$ and a closed point $s \in S$ such that
$S \setminus \{s\}$ does not contain a quasi-compact dense open.
\end{enumerate}

\label{lemma-category-constructible-abelian}
Let $X$ be a quasi-compact and quasi-separated scheme. The category of
constructible abelian sheaves is exactly the category of abelian
sheaves of the form
$$
\Coker\left(
\bigoplus\nolimits_{j = 1, \ldots, m}
j_{V_j!}\underline{\mathbf{Z}/m_j\mathbf{Z}}_{V_j}
\longrightarrow
\bigoplus\nolimits_{i = 1, \ldots, n}
j_{U_i!}\underline{\mathbf{Z}/n_i\mathbf{Z}}_{U_i}
\right)
$$
with $V_j$ and $U_i$ quasi-compact and quasi-separated objects of
$X_\etale$ and $m_j$, $n_i$ positive integers.
In fact, we can even assume $U_i$ and $V_j$ affine.

\label{lemma-jump-loci}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $E \in D(\mathcal{O}_X)$ be pseudo-coherent (for example perfect).
For any $i \in \mathbf{Z}$ consider the function
$$
\beta_i : |X| \longrightarrow \{0, 1, 2, \ldots\}
$$
defined above. Then we have
\begin{enumerate}
\item formation of $\beta_i$ commutes with arbitrary base change,
\item the functions $\beta_i$ are upper semi-continuous, and
\item the level sets of $\beta_i$ are \'etale locally constructible.
\end{enumerate}

\label{lemma-pullback-meromorphic-sections-defined}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Pullbacks of meromorphic sections are defined
in each of the following cases
\begin{enumerate}
\item weakly associated points of $X$ are mapped
to points of codimension $0$ on $Y$,
\item $f$ is flat,
\item add more here as needed.
\end{enumerate}

\label{lemma-etale-nbhd-dominates-smooth}
\begin{slogan}
Smooth morphisms admit \'etale local sections.
\end{slogan}
\begin{reference}
See \cite[Corollaire 17.16.3 (ii)]{EGA4}.
\end{reference}
Let $f : X \to S$ be a smooth morphism of schemes.
Let $s \in S$ be a point in the image of $f$.
Then there exists an \'etale neighbourhood $(S', s') \to (S, s)$
and a $S$-morphism $S' \to X$.

\label{lemma-sections-upstairs}
Let $S$ be a scheme. Let $f : T \to S$ be a morphism such that
\begin{enumerate}
\item $f$ is flat and quasi-compact, and
\item the geometric fibres of $f$ are connected.
\end{enumerate}
Let $\mathcal{F}$ be a sheaf on $S_\etale$.
Then $\Gamma(S, \mathcal{F}) = \Gamma(T, f^{-1}_{small}\mathcal{F})$.

\label{lemma-etale-not-dominated-zariski-finite-etale}
The \'etale cover $U \to X$ cannot be refined by any finite composition
of open immersions and finite \'etale morphisms.

\label{lemma-combine-one}
In Algebraic and Formal Geometry, Situation
\ref{algebraization-situation-bootstrap}
we have $H^s_\mathfrak a(M) = \lim H^s_\mathfrak a(M/I^nM)$.

\label{lemma-versal-object-existence}
Let $\mathcal{F}$ be a category cofibred in groupoids over
$\mathcal{C}_\Lambda$. Assume the following conditions hold:
\begin{enumerate}
\item $\mathcal{F}$ is a predeformation category.
\item $\mathcal{F}$ satisfies (S1).
\item $\mathcal{F}$ satisfies (S2).
\item $\dim_k T\mathcal{F}$ is finite.
\end{enumerate}
Then $\mathcal{F}$ has a versal formal object.

\label{lemma-presentation-inertia}
Let $\mathcal{X}$ be an algebraic stack. Let $[U/R] \to \mathcal{X}$
be a presentation. Let $G/U$ be the stabilizer group algebraic space
associated to the groupoid $(U, R, s, t, c)$. Then
$$
\xymatrix{
G \ar[d] \ar[r] & U \ar[d] \\
\mathcal{I}_\mathcal{X} \ar[r] & \mathcal{X}
}
$$
is a fibre product diagram.

\label{lemma-finite-presentation-permanence}
Let $f : X \to Y$ be a morphism of schemes over $S$.
\begin{enumerate}
\item If $X$ is locally of finite presentation over $S$ and
$Y$ is locally of finite type over $S$, then $f$ is locally
of finite presentation.
\item If $X$ is of finite presentation over $S$ and $Y$ is quasi-separated
and locally of finite type over $S$, then $f$ is of finite presentation.
\end{enumerate}

\label{lemma-tame}
\begin{reference}
Compare with \cite[Definition 7.2.4]{BS}.
\end{reference}
Let $(\mathcal{C}, F)$ be a Galois category. Let $G = \text{Aut}(F)$
be as in Example \ref{example-from-C-F-to-G-sets}. For any connected
$X$ in $\mathcal{C}$ the action of $G$ on $F(X)$ is transitive.

\label{lemma-composition-formally-smooth-etale-unramified}
Composition.
\begin{enumerate}
\item A composition of formally smooth transformations of functors is formally
smooth.
\item A composition of formally \'etale transformations of functors is formally
\'etale.
\item A composition of formally unramified transformations of functors is
formally unramified.
\end{enumerate}

\label{lemma-quasi-coherence-direct-sums}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Then $D_\QCoh(\mathcal{O}_X)$ has direct sums.

\label{lemma-unramified-in-L}
In the situation above the following are equivalent
\begin{enumerate}
\item $X$ is unramified in $L$,
\item $Y \to X$ is \'etale, and
\item $Y \to X$ is finite \'etale.
\end{enumerate}

\label{lemma-rig-flat-local-etale}
Consider a commutative diagram
$$
\xymatrix{
B \ar[r] & B' \\
A \ar[r] \ar[u]^\varphi & A' \ar[u]_{\varphi'}
}
$$
in $\textit{WAdm}^{Noeth}$ with all arrows adic and topologically
of finite type. Assume $A \to A'$ and $B \to B'$ are flat.
Let $I \subset A$ be an ideal of definition.
If $\varphi$ is rig-flat and $A/I \to A'/IA'$
is \'etale, then $\varphi'$ is rig-flat.

\label{lemma-flat-base-change-regular-immersion}
\begin{slogan}
Regular immersions are stable under flat base change.
\end{slogan}
Let $S$ be a scheme. Let $i : Z \to X$ be a Koszul-regular,
$H_1$-regular, or quasi-regular immersion of algebraic spaces over $S$.
Let $X' \to X$ be a flat morphism of algebraic spaces over $S$.
Then the base change $i' : Z \times_X X' \to X'$ is a Koszul-regular,
$H_1$-regular, or quasi-regular immersion.

\label{lemma-locally-constant-on-connected}
Let $X$ be a connected scheme. Let $\overline{x}$ be a geometric point of $X$.
\begin{enumerate}
\item There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite locally constant}\\
\text{sheaves of sets on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\pi_1(X, \overline{x})\text{-sets}
\end{matrix}
\right\}
$$
\item There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite locally constant}\\
\text{sheaves of abelian groups on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\pi_1(X, \overline{x})\text{-modules}
\end{matrix}
\right\}
$$
\item Let $\Lambda$ be a finite ring. There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite type, locally constant}\\
\text{sheaves of }\Lambda\text{-modules on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\pi_1(X, \overline{x})\text{-modules endowed}\\
\text{with commuting }\Lambda\text{-module structure}
\end{matrix}
\right\}
$$
\end{enumerate}

\label{lemma-descend-reduced}
\begin{slogan}
A flat and surjective morphism of algebraic spaces with a reduced source
has a reduced target.
\end{slogan}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
If $f$ is flat and surjective and $X$ is reduced, then $Y$ is reduced.

\label{lemma-limit-preserving-algebraic-space}
Let $S$ be a scheme. Let $\mathcal{X}$ be an algebraic stack over $S$.
Then the following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is a stack in setoids and
$\mathcal{X} \to (\Sch/S)_{fppf}$ is limit preserving on objects,
\item $\mathcal{X}$ is a stack in setoids and limit preserving,
\item $\mathcal{X}$ is representable by an algebraic space
locally of finite presentation.
\end{enumerate}

\label{lemma-characterize-quasi-separated}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item $X$ is a quasi-separated algebraic space,
\item for $U \to X$, $V \to X$ with $U$, $V$ quasi-compact schemes
the fibre product $U \times_X V$ is quasi-compact,
\item for $U \to X$, $V \to X$ with $U$, $V$ affine
the fibre product $U \times_X V$ is quasi-compact.
\end{enumerate}

\label{lemma-proper-finite-fibre-finite-in-neighbourhood}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Let $y \in |Y|$. Assume
\begin{enumerate}
\item $f$ is proper, and
\item $f$ is quasi-finite at all $x \in |X|$ lying over $y$
(Decent Spaces, Lemma \ref{decent-spaces-lemma-conditions-on-fibre-and-qf}).
\end{enumerate}
Then there exists an open neighbourhood $V \subset Y$ of $y$
such that $f|_{f^{-1}(V)} : f^{-1}(V) \to V$ is finite.

\label{lemma-normal-locally-Noetherian}
Let $X$ be a locally Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $X$ is normal, and
\item $X$ is a disjoint union of integral normal schemes.
\end{enumerate}

\label{lemma-local-isomorphism-permanence}
Let $A$ be a ring. Let $B \to C$ be an $A$-algebra homomorphism.
\begin{enumerate}
\item If $A \to B$ and $A \to C$ are local isomorphisms, then $B \to C$
is a local isomorphism.
\item If $A \to B$ and $A \to C$ identify local rings, then $B \to C$
identifies local rings.
\end{enumerate}

\label{lemma-formally-smooth-sheaf-differentials}
Let $f : X \to Y$ be a formally smooth morphism of schemes.
Then $\Omega_{X/Y}$ is locally projective on $X$.

\label{lemma-descending-property-finite}
The property $\mathcal{P}(f) =$``$f$ is finite''
is fpqc local on the base.

\label{lemma-characterize-formally-etale}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is formally \'etale,
\item $f$ is formally unramified and the universal first order thickening
of $X$ over $S$ is equal to $X$,
\item $f$ is formally unramified and $\mathcal{C}_{X/S} = 0$, and
\item $\Omega_{X/S} = 0$ and $\mathcal{C}_{X/S} = 0$.
\end{enumerate}

\label{lemma-fully-faithful-general}
In Situation \ref{situation-local-lefschetz} assume
\begin{enumerate}
\item $A$ is $f$-adically complete,
\item $f$ is a nonzerodivisor.
\item $H^1_\mathfrak m(A/fA)$ is a finite $A$-module.
\end{enumerate}
Then the restriction functor
$$
\colim_{U_0 \subset U' \subset U\text{ open}} \textit{F\'Et}_{U'}
\longrightarrow
\textit{F\'Et}_{U_0}
$$
is fully faithful.

\label{lemma-check-immersion-covering}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Let $W$ be an algebraic space and let $W \to \mathcal{Y}$ be a surjective,
flat morphism which is locally of finite presentation. The following
are equivalent:
\begin{enumerate}
\item $f$ is an (open, resp.\ closed) immersion, and
\item $V = W \times_\mathcal{Y} \mathcal{X}$ is an algebraic space, and
$V \to W$ is an (open, resp.\ closed) immersion.
\end{enumerate}

\label{lemma-purity-ramification}
\begin{reference}
This result for complex spaces can be found on page 170 of \cite{Fischer}.
In general this is \cite[Theorem 2.4]{Zong} attributed to Gabber.
\end{reference}
Let $f : X \to Y$ be a morphism of locally Noetherian schemes.
Let $x \in X$ and set $y = f(x)$. Assume
\begin{enumerate}
\item $\mathcal{O}_{X, x}$ is normal of dimension $\geq 1$,
\item $\mathcal{O}_{Y, y}$ is regular,
\item $f$ is locally of finite type, and
\item for specializations $x' \leadsto x$ with
$\dim(\mathcal{O}_{X, x'}) = 1$ our $f$ is \'etale at $x'$.
\end{enumerate}
Then $f$ is \'etale at $x$.

\label{lemma-weakly-admissible-henselian}
Let $A$ be a weakly admissible topological ring. Let $I \subset A$
be a weak ideal of definition. Then $(A, I)$ is a henselian pair.

\label{lemma-i-upper-shriek}
Let $i : Z \to X$ be a closed immersion of schemes.
There is a functor\footnote{This is likely nonstandard notation.}
$i^! : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Z)$
which is a right adjoint to $i_*$. (Compare
Modules, Lemma \ref{modules-lemma-i-star-right-adjoint}.)

\label{lemma-algebra-descent}
If $A \to B$ is faithfully flat, then the complex $(B/A)_\bullet$ is exact in
positive degrees, and $H^0((B/A)_\bullet) = A$.

\label{lemma-injective-abelian-sheaf-injective-presheaf}
Let $\mathcal{C}$ be a site. An injective abelian sheaf is also injective as an
object in the category $\textit{PAb}(\mathcal{C})$.

\label{lemma-conormal-functorial}
Let $S$ be a scheme. Let
$$
\xymatrix{
Z \ar[r]_i \ar[d]_f & X \ar[d]^g \\
Z' \ar[r]^{i'} & X'
}
$$
be a commutative diagram of algebraic spaces over $S$.
Assume $i$, $i'$ immersions. There is a canonical map
of $\mathcal{O}_Z$-modules
$$
f^*\mathcal{C}_{Z'/X'}
\longrightarrow
\mathcal{C}_{Z/X}
$$

\label{lemma-3}
\begin{reference}
See \cite{Lech-inequalities} and \cite[Lemma 3 page 300]{MatCA}.
\end{reference}
Let $(A, \mathfrak m)$ be a local ring. If $\mathfrak m = (x_1, \ldots, x_r)$
and $x_1^{e_1}, \ldots, x_r^{e_r}$ are independent for some $e_i > 0$,
then $\text{length}_A(A/(x_1^{e_1}, \ldots, x_r^{e_r})) = e_1\ldots e_r$.

\label{lemma-pullback-flat}
\begin{reference}
\cite[Expos\'e V, Corollary 1.7.1]{SGA4}
\end{reference}
Let
$(f, f^\sharp) :
(\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C})
\to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$
be a morphism of ringed topoi or ringed sites.
Then $f^*\mathcal{F}$ is a flat $\mathcal{O}_\mathcal{C}$-module
whenever $\mathcal{F}$ is a flat $\mathcal{O}_\mathcal{D}$-module.

\label{lemma-spaces-RS}
Example \ref{example-spaces}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_X$ is a deformation category
for any algebraic space $X$ over $k$.

\label{lemma-approximation-affine}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$ which is
representable by an affine scheme. Then approximation holds for every
triple $(T, E, m)$ as in Definition \ref{definition-approximation-holds}
such that there exists an integer $r \geq 0$ with
\begin{enumerate}
\item $E$ is $m$-pseudo-coherent,
\item $H^i(E)$ is supported on $T$ for $i \geq m - r + 1$,
\item $X \setminus T$ is the union of $r$ affine opens.
\end{enumerate}
In particular, approximation by perfect complexes holds for affine schemes.

\label{lemma-locally-finite-presentation-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally of finite presentation''
is fppf local on the source.

\label{lemma-example-schematically-dense-missing-weakly-associated-point}
There exists a reduced scheme $X$ and a schematically dense open
$U \subset X$ such that some weakly associated point $x \in X$ is not in $U$.

\label{lemma-smooth-curves-h0}
There exist an open substack
$\Curvesstack^{smooth, h0} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{smooth}$,
\item $f_*\mathcal{O}_X = \mathcal{O}_S$, this holds after any base change,
and $f$ is smooth of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{smooth, h0}$,
\item $X$ is smooth, $\dim(X) = 1$, and $k = H^0(X, \mathcal{O}_X)$,
\item $X$ is smooth, $\dim(X) = 1$, and $X$ is geometrically connected,
\item $X$ is smooth, $\dim(X) = 1$, and $X$ is geometrically integral, and
\item $X_{\overline{k}}$ is a smooth curve.
\end{enumerate}
\end{enumerate}

\label{theorem-presentation-deformation-groupoid}
Let $\mathcal{F}$ be a category cofibered in groupoids over
$\mathcal{C}_\Lambda$. Then $\mathcal{F}$ admits a presentation by a
smooth prorepresentable groupoid in functors on $\mathcal{C}_\Lambda$
if and only if the following conditions hold:
\begin{enumerate}
\item $\mathcal{F}$ is a deformation category.
\item $\dim_k T\mathcal{F}$ is finite.
\item $\dim_k \text{Inf}(\mathcal{F})$ is finite.
\end{enumerate}

\label{lemma-base-change-flat-continuous}
Denote $P$ the property of arrows of $\textit{WAdm}^{Noeth}$
defined in Lemma \ref{lemma-flat-axioms}.
Denote $Q$ the property defined in Lemma \ref{lemma-finite-type-red}
viewed as a property of arrows of $\textit{WAdm}^{Noeth}$.
Denote $R$ the property defined in Lemma \ref{lemma-finite-type}
viewed as a property of arrows of $\textit{WAdm}^{Noeth}$. Then
\begin{enumerate}
\item $P$ is stable under base change by $Q$
(Formal Spaces, Remark
\ref{formal-spaces-remark-base-change-variant-variant-Noetherian}), and
\item $P + R$ is stable under base change
(Formal Spaces, Remark
\ref{formal-spaces-remark-base-change-variant-Noetherian}).
\end{enumerate}

\label{lemma-universally-closed-quasi-compact}
Let $S$ be a scheme.
A universally closed morphism of algebraic spaces over $S$ is quasi-compact.

\label{lemma-base-change-separated}
All of the separation axioms listed in Definition \ref{definition-separated}
are stable under base change.

\label{lemma-when-quotient-scheme-at-point}
Let $S$ be a scheme. Let $X \to Y$ be a surjective finite locally free
morphism of algebraic spaces over $S$. For $y \in |Y|$ the following are
equivalent
\begin{enumerate}
\item $y$ is in the schematic locus of $Y$, and
\item there exists an affine open $U \subset X$
containing the preimage of $y$.
\end{enumerate}

\label{lemma-formal-fibres-gorenstein}
Properties (A), (B), (C), (D), and (E) of
More on Algebra, Section \ref{more-algebra-section-properties-formal-fibres}
hold for $P(k \to R) =$``$R$ is a Gorenstein ring''.

\label{lemma-descending-fppf-property-locally-separated}
The property $\mathcal{P}(f) =$``$f$ is locally separated''
is fppf local on the base.

\label{lemma-surjective-graded-rings-generated-degree-1-map-proj}
With hypotheses and notation as in Lemma \ref{lemma-morphism-proj} above.
Assume $A_d \to B_d$ is surjective for $d \gg 0$ and that $A$ is generated
by $A_1$ over $A_0$. Then
\begin{enumerate}
\item $U(\psi) = Y$,
\item $r_\psi : Y \to X$ is a closed immersion, and
\item the maps $\theta : r_\psi^*\mathcal{O}_X(n) \to \mathcal{O}_Y(n)$
are isomorphisms.
\end{enumerate}

\label{lemma-closed-immersion}
In Situation \ref{situation-contractions} assume given a closed
subset $Z \subset S$ such that
\begin{enumerate}
\item the inverse image of $Z$ in $X'$ is $T'$,
\item $U' \to S \setminus Z$ is a closed immersion,
\item $W \to S_{/Z}$ is a closed immersion.
\end{enumerate}
Then there exists a solution $(f : X' \to X, T, a)$
and moreover $X \to S$ is a closed immersion.

\label{lemma-relation-normal-cones}
With notation as above we have
$$
o^*[C_ZX]_n = [C_Z Y]_{n - 1}
$$
in $\CH_{n - 1}(Y \times_{o, C_Y X} C_ZX)$.

\label{lemma-universally-open-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is universally open''
is fppf local on the source.

\label{lemma-output-quasi-compact}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is quasi-compact if and only if $g$ is quasi-compact.

\label{lemma-finite-type}
Let $(X, \mathcal{O}_X)$ be a ringed space.
\begin{enumerate}
\item The category of finite type $\mathcal{O}_X$-modules has a
set of isomorphism classes.
\item The category of finite type quasi-coherent
$\mathcal{O}_X$-modules has a set of isomorphism classes.
\end{enumerate}

\label{lemma-locally-quasi-finite-fibres}
\begin{slogan}
Finite type morphisms with discrete fibers are quasi-finite.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Assume $f$ is locally of finite type.
Then the following are equivalent
\begin{enumerate}
\item $f$ is locally quasi-finite,
\item for every $s \in S$ the fibre $X_s$ is a discrete topological space, and
\item for every morphism $\Spec(k) \to S$ where $k$ is a field
the base change $X_k$ has an underlying discrete topological space.
\end{enumerate}

\label{proposition-proper-pushforward-coherent}
\begin{reference}
\cite[III Theorem 3.2.1]{EGA}
\end{reference}
Let $S$ be a locally Noetherian scheme.
Let $f : X \to S$ be a proper morphism.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
Then $R^if_*\mathcal{F}$ is a coherent $\mathcal{O}_S$-module
for all $i \geq 0$.

\label{lemma-derivations-finite}
Let $S$ be an object of $\widehat{\mathcal{C}}_\Lambda$.
Then $\dim_k \text{Der}_\Lambda(S, k) < \infty$.

\label{lemma-flat-morphism-from-gorenstein-scheme}
\begin{slogan}
Gorensteinnes of the total space of a flat fibration implies
same for base and fibres
\end{slogan}
Let $f : X \to Y$ be a flat morphism of locally Noetherian schemes.
If $X$ is Gorenstein, then $f$ is Gorenstein and $\mathcal{O}_{Y, f(x)}$
is Gorenstein for all $x \in X$.

\label{lemma-pullback-by-regular-immersion}
Let $f : X \to Y$ be a morphism of varieties.
\begin{enumerate}
\item If $Z \subset Y$ is a subvariety of dimension $d$ and $f$ is a regular
immersion of codimension $c$, then every irreducible component
of $f^{-1}(Z)$ has dimension $\geq d - c$.
\item If $Z \subset Y$ is a subvariety of dimension $d$ and
$f$ is a local complete intersection morphism of relative dimension $r$,
then every irreducible component of $f^{-1}(Z)$ has dimension $\geq d + r$.
\end{enumerate}

\label{lemma-constructions-invertible}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
\begin{enumerate}
\item If $\mathcal{L}$, $\mathcal{N}$ are invertible
$\mathcal{O}$-modules, then so is
$\mathcal{L} \otimes_\mathcal{O} \mathcal{N}$.
\item If $\mathcal{L}$ is an invertible
$\mathcal{O}$-module, then so is
$\SheafHom_\mathcal{O}(\mathcal{L}, \mathcal{O})$ and the evaluation map
$\mathcal{L} \otimes_\mathcal{O}
\SheafHom_\mathcal{O}(\mathcal{L}, \mathcal{O}) \to \mathcal{O}$
is an isomorphism.
\end{enumerate}

\label{lemma-topologically-finite-type-finite-type}
Let $S$ be a scheme. Let $\varphi : A \to B$ be a continuous map of
weakly admissible topological rings over $S$. The following
are equivalent
\begin{enumerate}
\item $\text{Spf}(\varphi) : Y = \text{Spf}(B) \to \text{Spf}(A) = X$
is of finite type,
\item $\varphi$ is taut and $B$ is topologically of finite type over $A$.
\end{enumerate}

\label{lemma-kill-colimit-support}
If in Lemma \ref{lemma-kill-colimit-weak} we additionally assume
\begin{enumerate}
\item[(6)] if $\mathfrak p \not \in V(I)$ and
$V(\mathfrak p) \cap V(I) = \{\mathfrak m\}$, then
$\text{depth}_{A_\mathfrak p}(M_\mathfrak p) > s$,
\end{enumerate}
then $H^i_{J_0}(M) = H^i_J(M) = H^i_\mathfrak m(M)$ for $i \leq s$
and these modules are annihilated by a power of $I$.

\label{lemma-affine-permanence}
Let
$$
\xymatrix{
\mathcal{X} \ar[rr]_f \ar[rd]_a & & \mathcal{Y} \ar[dl]^b \\
& \mathcal{Z}
}
$$
be a commutative diagram of morphisms of algebraic stacks.
If $a$ is affine and $\Delta_b$ is affine, then
$f$ is affine.

\label{lemma-base-change-map-proj}
\begin{reference}
\cite[II, Proposition 2.8.10]{EGA}
\end{reference}
With hypotheses and notation as in Lemma \ref{lemma-morphism-proj} above.
Assume there exists a ring map $R \to A_0$ and a ring map
$R \to R'$ such that $B = R' \otimes_R A$. Then
\begin{enumerate}
\item $U(\psi) = Y$,
\item the diagram
$$
\xymatrix{
Y = \text{Proj}(B) \ar[r]_{r_\psi} \ar[d] &
\text{Proj}(A) = X \ar[d] \\
\Spec(R') \ar[r] &
\Spec(R)
}
$$
is a fibre product square, and
\item the maps $\theta : r_\psi^*\mathcal{O}_X(n) \to \mathcal{O}_Y(n)$
are isomorphisms.
\end{enumerate}

\label{lemma-characterize-representable-quasi-compact}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
which is representable by algebraic spaces. The following are equivalent:
\begin{enumerate}
\item $f$ is quasi-compact (as in Properties of Stacks,
Section \ref{stacks-properties-section-properties-morphisms}), and
\item for every quasi-compact algebraic stack $\mathcal{Z}$
and any morphism $\mathcal{Z} \to \mathcal{Y}$ the algebraic stack
$\mathcal{Z} \times_\mathcal{Y} \mathcal{X}$ is quasi-compact.
\end{enumerate}

\label{lemma-torsion-cohomology}
Let $X$ be a quasi-compact and quasi-separated scheme.
\begin{enumerate}
\item If $\mathcal{F}$ is a torsion abelian sheaf on $X_\etale$, then
$H^n_\etale(X, \mathcal{F})$ is a torsion abelian group for all $n$.
\item If $K$ in $D^+(X_\etale)$ has torsion cohomology sheaves, then
$H^n_\etale(X, K)$ is a torsion abelian group for all $n$.
\end{enumerate}

\label{lemma-pushout}
\begin{slogan}
Algebraic stacks satisfy the (strong) Rim-Schlessinger condition
\end{slogan}
Let $S$ be a scheme. Let
$$
\xymatrix{
X \ar[r] \ar[d] & X' \ar[d] \\
Y \ar[r] & Y'
}
$$
be a pushout in the category of schemes over $S$ where $X \to X'$
is a thickening and $X \to Y$ is affine, see
More on Morphisms, Lemma \ref{more-morphisms-lemma-pushout-along-thickening}.
Let $\mathcal{Z}$ be an algebraic stack over $S$.
Then the functor of fibre categories
$$
\mathcal{Z}_{Y'}
\longrightarrow
\mathcal{Z}_Y \times_{\mathcal{Z}_X} \mathcal{Z}_{X'}
$$
is an equivalence of categories.

\label{lemma-glueable}
Let $(R \to R', f)$ be a glueing pair, see above. Let $Y$ be an algebraic
space over $X$. The following are equivalent
\begin{enumerate}
\item there exists an \'etale covering $\{Y_i \to Y\}_{i \in I}$
with $Y_i$ affine and $\Gamma(Y_i, \mathcal{O}_{Y_i})$
glueable as an $R$-module,
\item for every \'etale morphism $W \to Y$ with $W$ affine
$\Gamma(W, \mathcal{O}_W)$ is a glueable $R$-module.
\end{enumerate}

\label{lemma-composition-integral}
Compositions of integral, resp.\ finite morphisms of algebraic stacks
are integral, resp.\ finite.

\label{lemma-persistence-exactness}
Let $R$, $X$, $Y$, and $\mathcal{K}$ be as in
Lemma \ref{lemma-functor-quasi-coherent-from-affine-diagonal} part (2).
Then for any scheme $T$ over $R$ we have
$$
R^q\text{pr}_{13, *}(\text{pr}_{12}^*\mathcal{F}
\otimes_{\mathcal{O}_{T \times_R X \times_R Y}}
\text{pr}_{23}^*\mathcal{K}) = 0
$$
for $\mathcal{F}$ quasi-coherent on $T \times_R X$ and $q > 0$.

\label{lemma-taut-descent-admissible}
In the situation above, if $B$ is pre-admissible, then $A$
is pre-admissible.

\label{lemma-U-universally-bounded}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
The following are equivalent:
\begin{enumerate}
\item there exist schemes $U_i$ and \'etale morphisms
$U_i \to X$ such that $\coprod U_i \to X$ is surjective and
each $U_i \to X$ has universally bounded fibres, and
\item for every affine scheme $U$ and \'etale morphism $\varphi : U \to X$
the fibres of $U \to X$ are universally bounded.
\end{enumerate}

\label{lemma-affine-identify-affine-etale}
Let $S$ be a scheme. Let $X$ be an affine formal algebraic space over $S$.
Then $X_{affine, \etale}$ is equivalent to the category whose objects
are morphisms $\varphi : U \to X$ of formal algebraic spaces such that
\begin{enumerate}
\item $U$ is an affine formal algebraic space,
\item $\varphi$ is representable by algebraic spaces and \'etale.
\end{enumerate}

\label{lemma-immersion-permanence}
Let $Z \to Y \to X$ be morphisms of schemes.
\begin{enumerate}
\item If $Z \to X$ is an immersion, then $Z \to Y$ is an immersion.
\item If $Z \to X$ is a quasi-compact immersion and $Y \to X$ is
quasi-separated, then $Z \to Y$ is a quasi-compact immersion.
\item If $Z \to X$ is a closed immersion and $Y \to X$ is separated,
then $Z \to Y$ is a closed immersion.
\end{enumerate}

\label{lemma-lift-etale-neighbourhood-fibre}
\begin{slogan}
Lift \'etale neighbourhood of point on fibre to total space.
\end{slogan}
Let $X \to S$ be a morphism of schemes. Let $x \in X$ with image $s \in S$.
Let $(V, v) \to (X_s, x)$ be an \'etale neighbourhood.
Then there exists an \'etale neighbourhood $(U, u) \to (X, x)$
such that there exists a morphism $(U_s, u) \to (V, v)$
of \'etale neighbourhoods of $(X_s, x)$ which is an open immersion.

\label{lemma-sheaf-zero-on-low-dimension}
There exists a sheaf of abelian groups $G$ on
$\Sch_\etale$ with the following properties
\begin{enumerate}
\item $G(X) = 0$ whenever $\dim(X) < n$,
\item $G(X)$ is not zero if $\dim(X) \geq n$, and
\item if $X \subset X'$ is a thickening, then $G(X) = G(X')$.
\end{enumerate}

\label{lemma-quasi-compact-dense-open-connected-at-infinity-Noetherian}
Let $X$ be a scheme. Let $U \subset X$ be a dense open. Assume
\begin{enumerate}
\item the underlying topological space of $X$ is Noetherian, and
\item for every $x \in X \setminus U$ the punctured spectrum of the
strict henselization of $\mathcal{O}_{X, x}$ is connected.
\end{enumerate}
Then $\textit{F\'Et}_X \to \textit{F\'et}_U$ is fully faithful.

\label{lemma-descending-property-open-immersion}
The property $\mathcal{P}(f) =$``$f$ is an open immersion''
is fpqc local on the base.

\label{lemma-weird-permanence-etale}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of schemes.
Let $x \in X$ with image $y \in Y$. Assume
\begin{enumerate}
\item $Y$ is integral and geometrically unibranch at $y$,
\item $g \circ f$ is \'etale at $x$,
\item there is a specialization $x' \leadsto x$ such that $f(x')$
is the generic point of $Y$.
\end{enumerate}
Then $f$ is \'etale at $x$ and $g$ is \'etale at $y$.

\label{lemma-identify-pseudo-coherent-noetherian}
Let $X$ be a Noetherian scheme. Let $E$ be an object of
$D_\QCoh(\mathcal{O}_X)$. For $m \in \mathbf{Z}$ the
following are equivalent
\begin{enumerate}
\item $H^i(E)$ is coherent for $i \geq m$ and zero for $i \gg 0$, and
\item $E$ is $m$-pseudo-coherent.
\end{enumerate}
In particular, $E$ is pseudo-coherent if and only if $E$ is an object
of $D^-_{\textit{Coh}}(\mathcal{O}_X)$.

\label{lemma-morphism-Noetherian-schemes-quasi-compact}
Any morphism of schemes $f : X \to Y$ with $X$ Noetherian
is quasi-compact.

\label{lemma-descend-universally-injective}
Notation and assumptions as in Situation \ref{situation-descent-property}. If
\begin{enumerate}
\item $f$ is universally injective,
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is universally injective for some $i \geq 0$.

\label{proposition-cd-1}
\begin{reference}
The local case of this result is \cite[IV Corollaire 2.9]{MRaynaud-book}.
\end{reference}
In Situation \ref{situation-algebraize} let $(\mathcal{F}_n)$
be an object of $\textit{Coh}(U, I\mathcal{O}_U)$. Assume
\begin{enumerate}
\item $A$ has a dualizing complex and $\text{cd}(A, I) = 1$,
\item $(\mathcal{F}_n)$ satisfies the $(2, 3)$-inequalities, see
Definition \ref{definition-s-d-inequalities}.
\end{enumerate}
Then $(\mathcal{F}_n)$ extends to $X$. In particular, if $A$ is
$I$-adically complete, then $(\mathcal{F}_n)$ is the completion
of a coherent $\mathcal{O}_U$-module.

\label{lemma-check-finiteness-local-cohomology-locally}
\begin{reference}
This is a special case of \cite[Satz 1]{Faltings-finiteness}.
\end{reference}
Let $A$ be a Noetherian ring, $I \subset A$ an ideal, $M$ a finite
$A$-module, and $n \geq 0$ an integer. Let $Z = V(I)$.
The following are equivalent
\begin{enumerate}
\item the modules $H^i_Z(M)$ are finite for $i \leq n$, and
\item for all $\mathfrak p \in \Spec(A)$ the modules
$H^i_Z(M)_\mathfrak p$, $i \leq n$ are finite $A_\mathfrak p$-modules.
\end{enumerate}

\label{lemma-gerbe-of-lifts-fibred}
The category $p : \mathcal{C} \to W_{spaces, \etale}$ constructed
in Remark \ref{remark-gerbe-of-lifts} is fibred in groupoids.

\label{lemma-gerbe-of-lifts}
The category $p : \mathcal{C} \to W_{spaces, \etale}$ constructed
in Remark \ref{remark-gerbe-of-lifts} is a gerbe.

\label{lemma-affine-equivalence-modules}
Let $f : X \to S$ be an affine morphism of schemes.
Let $\mathcal{A} = f_*\mathcal{O}_X$.
The functor $\mathcal{F} \mapsto f_*\mathcal{F}$ induces
an equivalence of categories
$$
\left\{
\begin{matrix}
\text{category of quasi-coherent}\\
\mathcal{O}_X\text{-modules}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{category of quasi-coherent}\\
\mathcal{A}\text{-modules}
\end{matrix}
\right\}
$$
Moreover, an $\mathcal{A}$-module is
quasi-coherent as an $\mathcal{O}_S$-module if and only if
it is quasi-coherent as an $\mathcal{A}$-module.

\label{lemma-quasi-finite-separated-pass-through-finite}
\begin{reference}
\cite[IV Corollary 18.12.13]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
Assume $f$ is quasi-finite and separated and assume that
$S$ is quasi-compact and quasi-separated. Then there exists
a factorization
$$
\xymatrix{
X \ar[rd]_f \ar[rr]_j & & T \ar[ld]^\pi \\
& S &
}
$$
where $j$ is a quasi-compact open immersion and $\pi$ is finite.

\label{lemma-integral-algebra-directed-colimit-finite}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$. Let $\mathcal{A}$ be an integral quasi-coherent
$\mathcal{O}_X$-algebra. Then
\begin{enumerate}
\item $\mathcal{A}$ is the directed colimit of its finite
quasi-coherent $\mathcal{O}_X$-subalgebras, and
\item $\mathcal{A}$ is a directed colimit of finite and finitely presented
$\mathcal{O}_X$-algebras.
\end{enumerate}

\label{lemma-regular-resolution-property}
Let $X$ be a quasi-compact, regular scheme with affine diagonal.
Then $X$ has the resolution property.

\label{lemma-compute-ext-into-field}
Let $A \to k$ be a ring map with $k$ a field. Let $E \in D^-(A)$.
Then $\Ext^i_A(E, k) = \Hom_k(H^{-i}(E \otimes^\mathbf{L} k), k)$.

\label{lemma-connected-flat-over-dvr}
\begin{slogan}
A flat degeneration of a disconnected scheme is either disconnected
or nonreduced.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Assume that
\begin{enumerate}
\item $S$ is the spectrum of a discrete valuation ring,
\item $f$ is flat,
\item $X$ is connected,
\item the closed fibre $X_s$ is reduced.
\end{enumerate}
Then the generic fibre $X_\eta$ is connected.

\label{lemma-F-surj-open}
In Situation \ref{situation-iso}. Assume
\begin{enumerate}
\item $f$ is locally of finite presentation,
\item $\mathcal{G}$ is of finite type,
\item the support of $\mathcal{G}$ is proper over $B$.
\end{enumerate}
Then $F_{surj}$ is an algebraic space and $F_{surj} \to B$
is an open immersion.

\label{lemma-localize-stacks}
Assume that $\mathcal{C}$ is a site,
and $U$ is an object of $\mathcal{C}$ whose associated representable
presheaf is a sheaf. Constructions A and B above define
mutually inverse (!) functors of $2$-categories
$$
\left\{
\begin{matrix}
2\text{-category of}\\
\text{stacks over }\mathcal{C}/U
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
2\text{-category of pairs }(\mathcal{T}, p)
\text{ consisting} \\
\text{of a stack }\mathcal{T}\text{ over }\mathcal{C}\text{ and a morphism} \\
p : \mathcal{T} \to \mathcal{C}/U\text{ of stacks over }\mathcal{C}
\end{matrix}
\right\}
$$

\label{lemma-limit-is-affine}
Notation and assumptions as in Situation \ref{situation-descent}.
If $X$ is affine, then there exists an $i$ such that $X_i$ is affine.

\label{lemma-smooth-localization}
In Example \ref{example-rings} let $P$ be a $k$-algebra.
Let $S \subset P$ be a multiplicative subset. If
\begin{enumerate}
\item $k \to P$ is of finite type, and
\item $\Spec(P) \to \Spec(k)$ is smooth at all points of
$V(g)$ for all $g \in S$.
\end{enumerate}
then the functor between deformation categories of
Lemma \ref{lemma-localization}
$$
\Deformationcategory_P \longrightarrow \Deformationcategory_{S^{-1}P}
$$
is smooth and induces an isomorphism on tangent spaces.

\label{lemma-vasconcelos}
\begin{reference}
Local version of \cite[Theorem 1.1]{Vasconcelos}
\end{reference}
Let $R$ be a Noetherian local ring. Let $I \subset R$ be an ideal
of finite projective dimension over $R$. If $F \subset I/I^2$
is a direct summand free of rank $r$, then there exists a regular sequence
$x_1, \ldots, x_r \in I$ such that $x_1 \bmod I^2, \ldots, x_r \bmod I^2$
generate $F$.

\label{lemma-identify-affine-etale}
Let $S$ be a scheme. Let $X$ be a formal algebraic space over $S$.
Then $X_{affine, \etale}$ is equivalent to the category whose objects
are morphisms $\varphi : U \to X$ of formal algebraic spaces such that
\begin{enumerate}
\item $U$ is an affine formal algebraic space,
\item $\varphi$ is representable by algebraic spaces and \'etale.
\end{enumerate}

\label{lemma-purity}
\begin{reference}
\cite{Nagata-Purity} and \cite[Exp. X, Thm. 3.1]{SGA1}
\end{reference}
\begin{history}
This result was first stated and proved by Zariski in
geometric form in \cite{Zariski-Purity}.
The generalization to nonperfect ground fields by Nagata
was published as the next article in the same volume of the
Proceedings of the National Academy of Sciences of the United States of America
in \cite{Nagata-Remarks-Purity}. In the following year Nagata
proved the result for Noetherian local rings in \cite{Nagata-Purity}.
His proof uses a result of Chow which is a Bertini theorem for
complete local domains, see \cite{Chow-Bertini};
the history of Bertini's theorems is discussed in
Kleiman's historical article \cite{Kleiman-Bertini}.
A few years later a completely different proof was found by
Auslander, see \cite{Auslander-Purity}.
\end{history}
Let $f : X \to Y$ be a morphism of locally Noetherian schemes.
Let $x \in X$ and set $y = f(x)$. Assume
\begin{enumerate}
\item $\mathcal{O}_{X, x}$ is normal,
\item $\mathcal{O}_{Y, y}$ is regular,
\item $f$ is quasi-finite at $x$,
\item $\dim(\mathcal{O}_{X, x}) = \dim(\mathcal{O}_{Y, y}) \geq 1$
\item for specializations $x' \leadsto x$ with
$\dim(\mathcal{O}_{X, x'}) = 1$ our $f$ is unramified at $x'$.
\end{enumerate}
Then $f$ is \'etale at $x$.

\label{proposition-blowup-split}
With notation as in More on Morphisms, Lemma \ref{more-morphisms-lemma-blowup}
the map $\Omega^\bullet_{X/S} \to Rb_*\Omega^\bullet_{X'/S}$
has a splitting in $D(X, (X \to S)^{-1}\mathcal{O}_S)$.

\label{lemma-gorenstein}
Let $X$ be a regular model of a smooth curve $C$ over $K$. Then
\begin{enumerate}
\item $X \to \Spec(R)$ is a Gorenstein morphism of relative dimension $1$,
\item each of the irreducible components $C_i$ of $X_k$ is Gorenstein.
\end{enumerate}

\label{lemma-completion-not-exact}
\begin{slogan}
Completion is neither left nor right exact in general.
\end{slogan}
Completion is not an exact functor in general; it is not even
right exact in general. This holds even when $I$ is finitely
generated on the category of finitely presented modules.

\label{lemma-shrink}
With assumption and notation as in
Definition \ref{definition-shrink}
we have:
\begin{enumerate}
\item
\label{item-shrink-base}
If $S' \subset S$ is a standard open neighbourhood of $s$, then
setting $X' = X_{S'}$, $Z' = Z_{S'}$ and $Y' = Y_{S'}$ we obtain a
standard shrinking.
\item
\label{item-shrink-on-Y}
Let $W \subset Y$ be a standard open neighbourhood of $y$.
Then there exists a standard shrinking with $Y' = W \times_S S'$.
\item
\label{item-shrink-on-X}
Let $U \subset X$ be an open neighbourhood of $x$.
Then there exists a standard shrinking with $X' \subset U$.
\end{enumerate}

\label{lemma-sheaf-finite-presentation}
Let $S$ be a scheme.
Let $F : (\Sch/S)_{fppf}^{opp} \to \textit{Sets}$ be a functor.
Assume that
\begin{enumerate}
\item $F$ is a sheaf, and
\item there exists an fppf covering $\{U_j \to S\}_{j \in J}$ such that
$F|_{(\Sch/U_j)_{fppf}}$ is limit preserving.
\end{enumerate}
Then $F$ is limit preserving.

\label{lemma-integral-sections}
Let $S$ be a scheme. Let $X$ be an integral algebraic space over $S$.
Then $\Gamma(X, \mathcal{O}_X)$ is a domain.

\label{lemma-composition-quasi-finite}
The composition of quasi-finite morphisms is quasi-finite.
The same holds for locally quasi-finite.

\label{lemma-the-complex-for-L-star-gives-chern-class}
The ``boundary'' map
$\delta : \Omega^\bullet_{X/S} \to \Omega^\bullet_{X/S}[2]$
in $D(X, f^{-1}\mathcal{O}_S)$ coming from
the short exact sequence in Lemma \ref{lemma-the-complex-for-L-star}
is the map of Remark \ref{remark-cup-product-as-a-map}
for $\xi = c_1^{dR}(\mathcal{L})$.

\label{lemma-check-along-closed-fibre}
Let $S$ be a local scheme with closed point $s$.
Let $f : X \to S$ be locally of finite type.
Let $\mathcal{F}$ be a finite type quasi-coherent $\mathcal{O}_X$-module.
Assume that
\begin{enumerate}
\item every point of $\text{Ass}_{X/S}(\mathcal{F})$ specializes
to a point of the closed fibre $X_s$\footnote{For example this holds if
$f$ is finite type and $\mathcal{F}$ is pure along $X_s$, or
if $f$ is proper.},
\item $\mathcal{F}$ is flat over $S$ at every point of $X_s$.
\end{enumerate}
Then $\mathcal{F}$ is flat over $S$.

\label{lemma-inertia-base-change}
Let $G$ be a finite group acting on a ring $R$. Let $R^G \to A$ be a ring
map. Let $\mathfrak q' \subset A \otimes_{R^G} R$ be a prime lying
over the prime $\mathfrak q \subset R$. Then
$$
I_\mathfrak q = \{\sigma \in G \mid
\sigma(\mathfrak q) = \mathfrak q\text{ and }
\sigma \bmod \mathfrak q = \text{id}_{\kappa(\mathfrak q)}\}
$$
is equal to
$$
I_{\mathfrak q'} = \{\sigma \in G \mid
\sigma(\mathfrak q') = \mathfrak q'\text{ and }
\sigma \bmod \mathfrak q' = \text{id}_{\kappa(\mathfrak q')}\}
$$

\label{lemma-localize-dualizing}
Let $A \to B$ be a quasi-finite map of Noetherian rings.
\begin{enumerate}
\item If $A \to B$ factors as $A \to A_f \to B$ for some $f \in A$,
then $\omega_{B/A} = \omega_{B/A_f}$.
\item If $g \in B$, then $(\omega_{B/A})_g = \omega_{B_g/A}$.
\item If $f \in A$, then $\omega_{B_f/A_f} = (\omega_{B/A})_f$.
\end{enumerate}

\label{theorem-existence-derived}
In Situation \ref{situation-existence-derived}
there exists a pseudo-coherent $K$ in $D(\mathcal{O}_X)$
such that $K_n = K \otimes_{\mathcal{O}_X}^\mathbf{L} \mathcal{O}_{X_n}$
for all $n$ compatibly with the maps $\varphi_n$.

\label{lemma-NL-formally-smooth}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent
\begin{enumerate}
\item $f$ is formally smooth,
\item $H^{-1}(\NL_{X/Y}) = 0$ and $H^0(\NL_{X/Y}) = \Omega_{X/Y}$
is locally projective.
\end{enumerate}

\label{theorem-approximation}
Let $X$ be a quasi-compact and quasi-separated scheme.
Then approximation by perfect complexes holds on $X$.

\label{lemma-scheme-over-field-universally-open}
Let $k$ be a field. Let $X$ be a scheme over $k$.
The structure morphism $X \to \Spec(k)$ is universally open.

\label{lemma-equivalence-h-v-locally-finite-presentation}
Let $\{f_i : X_i \to X\}_{i \in I}$ be a family of morphisms
of schemes with fixed target with $f_i$ locally of finite
presentation for all $i$. The following are equivalent
\begin{enumerate}
\item $\{X_i \to X\}$ is a ph covering, and
\item $\{X_i \to X\}$ is a V covering.
\end{enumerate}

\label{lemma-fibre-products}
Let $S$ be a scheme. The category of formal algebraic spaces over $S$
has fibre products.

\label{lemma-schemes-RS}
Example \ref{example-schemes}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_X$ is a deformation category
for any scheme $X$ over $k$.

\label{lemma-Noetherian-adic-finite-type-red}
Let $\varphi : A \to B$ be an arrow of $\textit{WAdm}^{Noeth}$.
If $\varphi$ is adic the following are equivalent
\begin{enumerate}
\item $\varphi$ satisfies the condition defined in
Lemma \ref{lemma-finite-type-red} and
\item $\varphi$ satisfies the condition defined in
Lemma \ref{lemma-finite-type}.
\end{enumerate}

\label{lemma-action-by-derivations-etale-localization}
Consider a commutative diagram of first order thickenings
$$
\vcenter{
\xymatrix{
(T_2 \subset T_2') \ar[d]_{(h, h')} \ar[rr]_{(a_2, a_2')} & &
(X_2 \subset X_2') \ar[d]^{(f, f')} \\
(T_1 \subset T_1') \ar[rr]^{(a_1, a_1')} & &
(X_1 \subset X_1')
}
}
\quad
\begin{matrix}
\text{and a commutative} \\
\text{diagram of schemes}
\end{matrix}
\quad
\vcenter{
\xymatrix{
X_2' \ar[r] \ar[d] & S_2 \ar[d] \\
X_1' \ar[r] & S_1
}
}
$$
with $X_2 \to X_1$ and $S_2 \to S_1$ \'etale.
For any $\mathcal{O}_{T_1}$-linear map
$\theta_1 : a_1^*\Omega_{X_1/S_1} \to \mathcal{C}_{T_1/T'_1}$ let
$\theta_2$ be the composition
$$
\xymatrix{
a_2^*\Omega_{X_2/S_2} \ar@{=}[r] &
h^*a_1^*\Omega_{X_1/S_1} \ar[r]^-{h^*\theta_1} &
h^*\mathcal{C}_{T_1/T'_1} \ar[r] &
\mathcal{C}_{T_2/T'_2}
}
$$
(equality sign is explained in the proof). Then the diagram
$$
\xymatrix{
T_2' \ar[rr]_{\theta_2 \cdot a_2'} \ar[d] & & X'_2 \ar[d] \\
T_1' \ar[rr]^{\theta_1 \cdot a_1'} & & X'_1
}
$$
commutes where the actions $\theta_2 \cdot a_2'$ and $\theta_1 \cdot a_1'$
are as in Remark \ref{remark-action-by-derivations}.

\label{lemma-CM-1-curves}
There exist an open substack $\Curvesstack^{CM, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{CM, 1}$,
\item the morphism $X \to S$ is Cohen-Macaulay and has
relative dimension $1$ (Morphisms of Spaces, Definition
\ref{spaces-morphisms-definition-relative-dimension}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{CM, 1}$,
\item $X$ is Cohen-Macaulay and $X$ is equidimensional of
dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-characterize-universally-closed-quasi-separated}
Let $S$ be a scheme. Let $f : X \to Y$ be a
morphism of algebraic spaces over $S$.
\begin{enumerate}
\item If $f$ is quasi-separated and universally closed, then
$f$ satisfies the existence part of the valuative criterion.
\item If $f$ is quasi-compact and quasi-separated, then
$f$ is universally closed if and only if the existence part of the
valuative criterion holds.
\end{enumerate}

\label{lemma-picard-stack}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
\Picardstack_{X/B} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{lemma-completion-proper-surjective-rig-surjective}
In the situation above. If $X$ is locally Noetherian,
$f$ is proper, and $U' \to U$ is surjective, then $f_{/T}$ is rig-surjective.

\label{lemma-center-csa}
Let $A$ be a finite simple $k$-algebra. Then the center $k'$ of $A$
is a finite field extension of $k$.

\label{lemma-w-local-extremally-disconnected}
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item every faithfully flat ring map $A \to B$ identifying local rings
has a retraction,
\item every faithfully flat ind-Zariski ring map $A \to B$ has a retraction, and
\item $A$ satisfies
\begin{enumerate}
\item $\Spec(A)$ is w-local, and
\item $\pi_0(\Spec(A))$ is extremally disconnected.
\end{enumerate}
\end{enumerate}

\label{lemma-descend-affine}
Notation and assumptions as in Situation \ref{situation-descent-property}. If
$f$ is affine, then $f_i$ is affine for some $i \geq 0$.

\label{lemma-cup-product-associative}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}) \to (\Sh(\mathcal{C}'), \mathcal{O}')$
be a morphism of ringed topoi. The relative cup product of
Remark \ref{remark-cup-product} is associative in the sense that
the diagram
$$
\xymatrix{
Rf_*K \otimes_{\mathcal{O}'}^\mathbf{L}
Rf_*L \otimes_{\mathcal{O}'}^\mathbf{L}
Rf_*M \ar[r] \ar[d] &
Rf_*(K \otimes_\mathcal{O}^\mathbf{L} L)
\otimes_{\mathcal{O}'}^\mathbf{L} Rf_*M \ar[d] \\
Rf_*K \otimes_{\mathcal{O}'}^\mathbf{L}
Rf_*(L \otimes_\mathcal{O}^\mathbf{L} M) \ar[r] &
Rf_*(K \otimes_\mathcal{O}^\mathbf{L} 
L \otimes_\mathcal{O}^\mathbf{L} M)
}
$$
is commutative in $D(\mathcal{O}')$ for all $K, L, M$ in $D(\mathcal{O})$.

\label{lemma-formal-fibres-lci}
Properties (A), (B), (C), (D), and (E) of
More on Algebra, Section \ref{more-algebra-section-properties-formal-fibres}
hold for $P(k \to R) =$``$R$ is a local complete intersection''.
See Divided Power Algebra, Definition \ref{dpa-definition-lci}.

\label{lemma-glueing}
In Situation \ref{situation-glueing}
there is an equivalence
$$
\Deformationcategory_X =
\Deformationcategory_{P_1}
\times_{\Deformationcategory_{P_{12}}}
\Deformationcategory_{P_2}
$$
of deformation categories, see Examples \ref{example-schemes} and
\ref{example-rings}.

\label{lemma-representable-property-formally-property}
Let $S$ be a scheme.
Let $F, G : (\Sch/S)_{fppf}^{opp} \to \textit{Sets}$.
Let $a : F \to G$ be a representable transformation of functors.
\begin{enumerate}
\item If $a$ is smooth then $a$ is formally smooth.
\item If $a$ is \'etale, then $a$ is formally \'etale.
\item If $a$ is unramified, then $a$ is formally unramified.
\end{enumerate}

\label{lemma-push-pull-LC}
Let $f : X \to Y$ be a morphism of $\textit{LC}_{qc}$.
Then there are commutative diagrams of topoi
$$
\vcenter{
\xymatrix{
\Sh(\textit{LC}_{qc}/X) \ar[r]_{f_{qc}} \ar[d]_{\epsilon_X} &
\Sh(\textit{LC}_{qc}/Y) \ar[d]^{\epsilon_Y} \\
\Sh(\textit{LC}_{Zar}/X) \ar[r]^{f_{Zar}} &
\Sh(\textit{LC}_{Zar}/Y)
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\Sh(\textit{LC}_{qc}/X) \ar[r]_{f_{qc}} \ar[d]_{a_X} &
\Sh(\textit{LC}_{qc}/Y) \ar[d]^{a_Y} \\
\Sh(X) \ar[r]^f &
\Sh(Y)
}
}
$$
with $a_X = \pi_X \circ \epsilon_X$, $a_Y = \pi_X \circ \epsilon_X$.
If $f$ is proper, then $a_Y^{-1} \circ f_* = f_{qc, *} \circ a_X^{-1}$.

\label{lemma-f-shriek-separated-direct-sums}
Let $f : X \to Y$ be a morphism of schemes which is separated and
locally of finite type. Then functor $f_!$ commutes with direct sums.

\label{lemma-composition-ind-zariski}
Let $A \to B$ and $B \to C$ be ring maps. If $A \to B$ and $B \to C$
are ind-Zariski, then $A \to C$ is ind-Zariski.

\label{lemma-polarized-qs-lfp}
The morphism $\Polarizedstack \to \Spec(\mathbf{Z})$ is quasi-separated and
locally of finite presentation.

\label{lemma-homotopy}
Being formally homotopic is an equivalence relation on
sets of morphisms in $\widehat{\mathcal{C}}_\Lambda$.

\label{lemma-composition-universally-injective}
A composition of radicial morphisms is radicial, and so the same holds
for the equivalent condition of being universally injective.

\label{lemma-zariski-etale-smooth-syntomic-fppf}
Any syntomic covering is an fppf covering, and a fortiori,
any smooth, \'etale, or Zariski covering is an fppf covering.

\label{lemma-functor-on-modules-fp}
Let $A$ be a ring. Let $\mathcal{B}$ be an additive category
with cokernels. There is an equivalence of categories between
\begin{enumerate}
\item the category of functors $F : \text{Mod}^{fp}_A \to \mathcal{B}$
which are right exact, and
\item the category of pairs $(K, \kappa)$ where $K \in \Ob(\mathcal{B})$
and $\kappa : A \to \text{End}_\mathcal{B}(K)$ is a ring homomorphism
\end{enumerate}
given by the rule sending $F$ to $F(A)$ with its natural $A$-action.

\label{lemma-enough-compact-proetale}
Let $S$ be a scheme. Let $\Lambda$ be a ring.
\begin{enumerate}
\item $D(S_\proetale)$ is compactly generated,
\item $D(S_\proetale, \Lambda)$ is compactly generated,
\item $D(S_\proetale, \mathcal{A})$ is compactly generated
for any sheaf of rings $\mathcal{A}$ on $S_\proetale$,
\item $D((\Sch/S)_\proetale)$ is compactly generated,
\item $D((\Sch/S)_\proetale, \Lambda)$ is compactly generated, and
\item $D((\Sch/S)_\proetale, \mathcal{A})$ is compactly generated
for any sheaf of rings $\mathcal{A}$ on $(\Sch/S)_\proetale$,
\end{enumerate}

\label{lemma-flat-closed-immersions-finite-presentation}
A flat closed immersion of finite presentation
is the open immersion of an open and closed subscheme.

\label{lemma-normal}
Let $f : X \to Y$ be a morphism of schemes.
Assume all fibres of $f$ are locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is normal, and
\item $f$ is flat and its fibres are geometrically normal schemes.
\end{enumerate}

\label{lemma-algebraic-stack-RS}
Let $\mathcal{X}$ be an algebraic stack over a locally Noetherian base
$S$. Then $\mathcal{X}$ satisfies (RS).

\label{lemma-composition-quasi-compact}
The composition of a pair of quasi-compact morphisms of algebraic stacks
is quasi-compact.

\label{lemma-approximation-affine}
Let $X$ be an affine scheme. Then approximation holds for every
triple $(T, E, m)$ as in Definition \ref{definition-approximation-holds}
such that there exists an integer $r \geq 0$ with
\begin{enumerate}
\item $E$ is $m$-pseudo-coherent,
\item $H^i(E)$ is supported on $T$ for $i \geq m - r + 1$,
\item $X \setminus T$ is the union of $r$ affine opens.
\end{enumerate}
In particular, approximation by perfect complexes holds for affine schemes.

\label{lemma-irreducible-implies-equidimensional}
If $\mathcal{X}$ is
a Jacobson, pseudo-catenary, and locally Noetherian  algebraic stack
for which $|\mathcal{X}|$ is irreducible,
then $\dim_x(\mathcal{X})$ is a constant function on $|\mathcal{X}|$.

\label{lemma-van-den-bergh}
\begin{reference}
\cite[Lemma 2.14]{CKN}
\end{reference}
Let $k$ be a field. Let $\mathcal{D}$ be a $k$-linear triangulated category
which has direct sums and is compactly generated.
Denote $\mathcal{D}_c$ the full
subcategory of compact objects. Let $H : \mathcal{D}_c^{opp} \to \text{Vect}_k$
be a $k$-linear cohomological functor such that
$\dim_k H(X) < \infty$ for all $X \in \Ob(\mathcal{D}_c)$.
Then $H$ is isomorphic to the functor $X \mapsto \Hom(X, Y)$
for some $Y \in \Ob(\mathcal{D})$.

\label{lemma-flat}
In Situation \ref{situation-flat}.
\begin{enumerate}
\item The functor $F_{flat}$ satisfies the sheaf property for the fpqc topology.
\item If $f$ is quasi-compact and locally of finite presentation
and $\mathcal{F}$ is of finite presentation, then the functor
$F_{flat}$ is limit preserving.
\end{enumerate}

\label{lemma-pi-lower-shriek-constant-sheaf}
If $A \to B$ is a ring map, then $L\pi_!(\pi^{-1}M) = M$
with $\pi$ as in (\ref{equation-pi}).

\label{lemma-smooth-curves}
There exist an open substacks
$$
\Curvesstack^{smooth, 1} \subset \Curvesstack^{smooth} \subset \Curvesstack
$$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{smooth}$, resp.\ $\Curvesstack^{smooth, 1}$,
\item $f$ is smooth, resp.\ smooth of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{smooth}$, resp.\ $\Curvesstack^{smooth, 1}$,
\item $X$ is smooth over $k$, resp.\ $X$ is smooth over $k$ and
$X$ is equidimensional of dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-zariski-open-cover-stack-is-scheme}
Let $\mathcal X$ be an algebraic stack.
Let $\mathcal{X}_i$, $i \in I$ be a set of open substacks of $\mathcal{X}$.
Assume
\begin{enumerate}
\item $\mathcal{X} = \bigcup_{i \in I} \mathcal{X}_i$, and
\item each $\mathcal{X}_i$ is a scheme
\end{enumerate}
Then $\mathcal{X}$ is a scheme.

\label{lemma-dimension}
Let $X$ be a scheme. The following are equal
\begin{enumerate}
\item The dimension of $X$.
\item The supremum of the dimensions of the local rings of $X$.
\item The supremum of $\dim_x(X)$ for $x \in X$.
\end{enumerate}

\label{lemma-functor}
Let $A$ and $B$ be rings. Let $F : \text{Mod}_A \to \text{Mod}_B$
be a functor. The following are equivalent
\begin{enumerate}
\item $F$ is isomorphic to the functor $M \mapsto M \otimes_A K$
for some $A \otimes_\mathbf{Z} B$-module $K$,
\item $F$ is right exact and commutes with all direct sums,
\item $F$ commutes with all colimits,
\item $F$ has a right adjoint $G$.
\end{enumerate}

\label{lemma-unramified-permanence}
Let $f : X \to Y$ be a morphism of schemes over $S$.
\begin{enumerate}
\item If $X$ is unramified over $S$, then $f$ is unramified.
\item If $X$ is G-unramified over $S$ and $Y$ is locally of finite type
over $S$, then $f$ is G-unramified.
\end{enumerate}

\label{lemma-minimal-versal}
Let $\mathcal{F}$ be a predeformation category which
has a versal formal object. Then
\begin{enumerate}
\item $\mathcal{F}$ has a minimal versal formal object,
\item minimal versal objects are unique up to isomorphism, and
\item any versal object is the pushforward of a minimal versal
object along a power series ring extension.
\end{enumerate}

\label{lemma-sibling-faithful}
Let $F$ and $F'$ be siblings as in Definition \ref{definition-siblings}.
Then
\begin{enumerate}
\item if $F$ is essentially surjective, then $F'$ is essentially
surjective,
\item if $F$ is fully faithful, then $F'$ is fully faithful.
\end{enumerate}

\label{lemma-locally-closed-where-H0-locally-free}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $E \in D(\mathcal{O}_X)$ be perfect
of tor-amplitude in $[a, b]$ for some $a, b \in \mathbf{Z}$.
Let $r \geq 0$.
Then there exists a locally closed subspace $j : Z \to X$
characterized by the following
\begin{enumerate}
\item $H^a(Lj^*E)$ is a locally free $\mathcal{O}_Z$-module of rank $r$, and
\item a morphism $f : Y \to X$ factors through $Z$ if and only if
for all morphisms $g : Y' \to Y$ the $\mathcal{O}_{Y'}$-module
$H^a(L(f \circ g)^*E)$ is locally free of rank $r$.
\end{enumerate}
Moreover, $j : Z \to X$ is of finite presentation and we have
\begin{enumerate}
\item[(3)] if $f : Y \to X$ factors as $Y \xrightarrow{g} Z \to X$, then
$H^a(Lf^*E) = g^*H^a(Lj^*E)$,
\item[(4)] if $\beta_a(x) \leq r$ for all $x \in |X|$, then $j$ is
a closed immersion and given $f : Y \to X$ the following are equivalent
\begin{enumerate}
\item $f : Y \to X$ factors through $Z$,
\item $H^0(Lf^*E)$ is a locally free $\mathcal{O}_Y$-module of rank $r$,
\end{enumerate}
and if $r = 1$ these are also equivalent to
\begin{enumerate}
\item[(c)] $\mathcal{O}_Y \to \SheafHom_{\mathcal{O}_Y}(H^0(Lf^*E), H^0(Lf^*E))$
is injective.
\end{enumerate}
\end{enumerate}

\label{lemma-comparison}
For $a \geq 0$ we have
\begin{enumerate}
\item the map
$\Omega^a_{X/S} \to b_*\Omega^a_{L/S}$ is an isomorphism,
\item the map $\Omega^a_{Z/S} \to p_*\Omega^a_{P/S}$ is an isomorphism,
and
\item the map $Rb_*\Omega^a_{L/S} \to i_*Rp_*\Omega^a_{P/S}$ is an isomorphism
on cohomology sheaves in degree $\geq 1$.
\end{enumerate}

\label{lemma-smooth-henselization}
In Example \ref{example-rings} let $P$ be a $k$-algebra.
Let $J \subset P$ be an ideal.
Denote $(P^h, J^h)$ the henselization of the pair $(P, J)$. If
\begin{enumerate}
\item $k \to P$ is of finite type, and
\item $\Spec(P) \to \Spec(k)$ is smooth on the complement of $V(J)$,
\end{enumerate}
then the functor between deformation categories of
Lemma \ref{lemma-henselization}
$$
\Deformationcategory_P \longrightarrow \Deformationcategory_{P^h}
$$
is smooth and induces an isomorphism on tangent spaces.

\label{lemma-syntomic-permanence}
Let $S$ be a scheme. Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& B
}
$$
be a commutative diagram of morphisms of algebraic spaces over $S$. Assume that
\begin{enumerate}
\item $f$ is surjective, flat, and locally of finite presentation,
\item $p$ is syntomic.
\end{enumerate}
Then both $q$ and $f$ are syntomic.

\label{lemma-F-zero-module-map}
Let $A$ be a ring. Let $u : M \to N$ be a map of $A$-modules.
If $N$ is projective as an $A$-module, then there exists an ideal
$I \subset A$ such that for any ring map $\varphi : A \to B$
the following are equivalent
\begin{enumerate}
\item $u \otimes 1 : M \otimes_A B \to N \otimes_A B$ is zero, and
\item $\varphi(I) = 0$.
\end{enumerate}

\label{lemma-quasi-coherent-sheaf}
In Situation \ref{situation-simplicial-site}
let $\mathcal{O}$ be a sheaf of rings on $\mathcal{C}_{total}$.
Let $\mathcal{F}$ be a sheaf of $\mathcal{O}$-modules.
Then $\mathcal{F}$ is quasi-coherent in the sense of
Modules on Sites, Definition \ref{sites-modules-definition-site-local}
if and only if $\mathcal{F}$ is cartesian
and $\mathcal{F}_n$ is a quasi-coherent $\mathcal{O}_n$-module for all $n$.

\label{lemma-retrocompact}
Let $X$ be a scheme. A subset $E$ of $X$ is retrocompact in $X$ if and only if
$E \cap U$ is quasi-compact for every affine open $U$ of $X$.

\label{lemma-composition-universally-submersive}
The composition of a pair of (universally) submersive morphisms of
schemes is (universally) submersive.

\label{lemma-zariski-etale-smooth-syntomic-fppf-fpqc}
Any fppf covering is an fpqc covering, and a fortiori,
any syntomic, smooth, \'etale or Zariski covering is an fpqc covering.

\label{lemma-quasi-separated-gives-quasi-separated}
In the situation above. If $f$ is (quasi-)separated, then
$f_{/T}$ is too.

\label{lemma-tensor-product}
The tensor product of correspondences defined above turns the category of
correspondences into a symmetric monoidal category with unit $\Spec(k)$.

\label{lemma-bounded-truncation}
Let $S$ be a scheme.
Let $X$ be a quasi-compact and quasi-separated algebraic space over $S$.
Let $P \in D_{perf}(\mathcal{O}_X)$ and $E \in D_{\QCoh}(\mathcal{O}_X)$.
Let $a \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], E) = 0$ for $i \gg 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], \tau_{\geq a} E) = 0$ for $i \gg 0$.
\end{enumerate}

\label{lemma-lqf-separated-shriek-composition}
Let $f' : X \to Y'$ and $g : Y' \to Y$ be composable morphisms of schemes
with $f'$ and $f = g \circ f'$ locally quasi-finite and $g$ separated and
locally of finite type. Then there is a canonical isomorphism of functors
$g_! \circ f'_! = f_!$. This isomorphism is compatible with
\begin{enumerate}
\item[(a)] covariance with respect to open embeddings as in
Remarks \ref{remark-covariance-f-shriek-separated} and
\ref{remark-covariance-lqf-f-shriek},
\item[(b)] the base change isomorphisms of
Lemmas \ref{lemma-lqf-base-change-f-shriek}
and \ref{lemma-base-change-f-shriek-separated}, and
\item[(c)] equal to the isomorphism of Lemma \ref{lemma-f-shriek-composition}
via the identifications of Lemma \ref{lemma-finite-support-f-shriek-separated}
in case $f'$ is separated.
\end{enumerate}

\label{lemma-dominate-by-scheme-modification}
In Situation \ref{situation-vanishing} there exists a $U$-admissible
blowup $X' \to S$ which dominates $X$.

\label{lemma-quasi-compact-dense-open-connected-at-infinity}
Let $X$ be a scheme. Let $U \subset X$ be a dense open. Assume
\begin{enumerate}
\item every quasi-compact open of $X$ has finitely many
irreducible components,
\item for every $x \in X \setminus U$ the punctured spectrum of the
strict henselization of $\mathcal{O}_{X, x}$ is connected.
\end{enumerate}
Then $\textit{F\'Et}_X \to \textit{F\'et}_U$ is fully faithful.

\label{lemma-cup-compatible-with-naive}
In the situation above the following diagram commutes
$$
\xymatrix{
f_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}^\mathbf{L}
f_*\mathcal{M}^\bullet \ar[r] \ar[d]
&
Rf_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}^\mathbf{L}
Rf_*\mathcal{M}^\bullet \ar[d]^{\text{Remark \ref{remark-cup-product}}} \\
\text{Tot}(
f_*\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}
f_*\mathcal{M}^\bullet) \ar[d]_{\text{naive cup product}} &
Rf_*(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{C}}^\mathbf{L}
\mathcal{M}^\bullet) \ar[d] \\
f_*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{C}}
\mathcal{M}^\bullet) \ar[r] &
Rf_*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{C}}
\mathcal{M}^\bullet)
}
$$

\label{lemma-topologically-finite-type-Noetherian}
\begin{reference}
\cite[Proposition 7.5.5]{EGA1}
\end{reference}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal. Then
\begin{enumerate}
\item every object of the category $\mathcal{C}'$
(\ref{equation-C-prime}) is Noetherian,
\item if $B \in \Ob(\mathcal{C}')$ and $J \subset B$ is an ideal,
then $B/J$ is an object of $\mathcal{C}'$,
\item for a finite type $A$-algebra $C$ the $I$-adic completion
$C^\wedge$ is in $\mathcal{C}'$,
\item in particular the completion $A[x_1, \ldots, x_r]^\wedge$
is in $\mathcal{C}'$.
\end{enumerate}

\label{lemma-perfect-reduced}
Let $X$ be an algebraic space over a perfect field $k$ (for example
$k$ has characteristic zero).
\begin{enumerate}
\item For $x \in |X|$, if $\mathcal{O}_{X, \overline{x}}$ is
reduced, then $X$ is geometrically reduced at $x$.
\item If $X$ is reduced, then $X$ is geometrically reduced over $k$.
\end{enumerate}

\label{lemma-descending-property-formally-smooth}
The property $\mathcal{P}(f) =$``$f$ is formally smooth''
is fpqc local on the base.

\label{lemma-eventual-iso-graded-rings-map-proj}
With hypotheses and notation as in Lemma \ref{lemma-morphism-proj} above.
Assume $A_d \to B_d$ is an isomorphism for all $d \gg 0$. Then
\begin{enumerate}
\item $U(\psi) = Y$,
\item $r_\psi : Y \to X$ is an isomorphism, and
\item the maps $\theta : r_\psi^*\mathcal{O}_X(n) \to \mathcal{O}_Y(n)$
are isomorphisms.
\end{enumerate}

\label{lemma-valuative-criterion-separatedness}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
Assume
\begin{enumerate}
\item the morphism $f$ is quasi-separated, and
\item the morphism $f$ satisfies the uniqueness
part of the valuative criterion.
\end{enumerate}
Then $f$ is separated.

\label{lemma-quasi-coherent}
Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item With $g$ as in Lemma \ref{lemma-lisse-etale}
for the lisse-\'etale site we have
\begin{enumerate}
\item the functors $g^{-1}$ and $g_!$ define mutually inverse functors
$$
\xymatrix{
\QCoh(\mathcal{O}_\mathcal{X}) \ar@<1ex>[r]^-{g^{-1}} &
\QCoh(\mathcal{X}_{lisse,\etale},
\mathcal{O}_{\mathcal{X}_{lisse,\etale}}) \ar@<1ex>[l]^-{g_!}
}
$$
\item if $\mathcal{F}$ is in $\textit{LQCoh}^{fbc}(\mathcal{O}_\mathcal{X})$
then $g^{-1}\mathcal{F}$ is in
$\QCoh(\mathcal{O}_{\mathcal{X}_{lisse,\etale}})$ and
\item $Q(\mathcal{F}) = g_!g^{-1}\mathcal{F}$ where $Q$ is as in
Lemma \ref{lemma-adjoint}.
\end{enumerate}
\item With $g$ as in Lemma \ref{lemma-lisse-etale}
for the flat-fppf site we have
\begin{enumerate}
\item the functors $g^{-1}$ and $g_!$ define mutually inverse functors
$$
\xymatrix{
\QCoh(\mathcal{O}_\mathcal{X}) \ar@<1ex>[r]^-{g^{-1}} &
\QCoh(\mathcal{X}_{flat,fppf},
\mathcal{O}_{\mathcal{X}_{flat,fppf}}) \ar@<1ex>[l]^-{g_!}
}
$$
\item if $\mathcal{F}$ is in $\textit{LQCoh}^{fbc}(\mathcal{O}_\mathcal{X})$
then $g^{-1}\mathcal{F}$ is in
$\QCoh(\mathcal{O}_{\mathcal{X}_{flat,fppf}})$
and
\item $Q(\mathcal{F}) = g_!g^{-1}\mathcal{F}$ where $Q$ is as in
Lemma \ref{lemma-adjoint}.
\end{enumerate}
\end{enumerate}

\label{lemma-when-universally-injective-radicial}
Let $S$ be a scheme. Let $f : X \to Y$ be a universally injective
morphism of algebraic spaces over $S$.
\begin{enumerate}
\item If $f$ is decent then $f$ is radicial.
\item If $f$ is quasi-separated then $f$ is radicial.
\item If $f$ is locally separated then $f$ is radicial.
\end{enumerate}

\label{lemma-proper-pure}
Let $f : X \to S$ be a morphism of schemes which is of finite type.
Let $\mathcal{F}$ be a finite type quasi-coherent $\mathcal{O}_X$-module.
\begin{enumerate}
\item If the support of $\mathcal{F}$ is proper over $S$, then
$\mathcal{F}$ is universally pure relative to $S$.
\item If $f$ is proper, then
$\mathcal{F}$ is universally pure relative to $S$.
\item If $f$ is proper, then $X$ is universally pure relative to $S$.
\end{enumerate}

\label{lemma-characterize-representable-universally-submersive}
Let $S$ be a scheme. Let $f : X \to Y$ be a representable morphism of
algebraic spaces over $S$. The following are equivalent
\begin{enumerate}
\item $f$ is universally submersive
(in the sense of Section \ref{section-representable}), and
\item for every morphism of algebraic spaces $Z \to Y$ the morphism of
topological spaces $|Z \times_Y X| \to |Z|$ is submersive.
\end{enumerate}

\label{lemma-complexes-RS-star}
In Situation \ref{situation-complexes}. Let
$$
\xymatrix{
Z \ar[r] \ar[d] & Z' \ar[d] \\
Y \ar[r] & Y'
}
$$
be a pushout in the category of schemes over $S$ where
$Z \to Z'$ is a finite order thickening and $Z \to Y$ is affine, see
More on Morphisms, Lemma \ref{more-morphisms-lemma-pushout-along-thickening}.
Then the functor on fibre categories
$$
\Complexesstack_{X/B, Y'}
\longrightarrow
\Complexesstack_{X/B, Y}
\times_{\Complexesstack_{X/B, Z}}
\Complexesstack_{X/B, Z'}
$$
is an equivalence.

\label{lemma-SGE-implies-openness-versality}
Let $S$ be a locally Noetherian scheme. Let $\mathcal{X}$ be a category fibred
in groupoids over $(\Sch/S)_{fppf}$. Assume
\begin{enumerate}
\item $\Delta : \mathcal{X} \to \mathcal{X} \times \mathcal{X}$ is
representable by algebraic spaces,
\item $\mathcal{X}$ has (RS*),
\item $\mathcal{X}$ is limit preserving,
\item systems $(\xi_n)$ as in Remark \ref{remark-strong-effectiveness}
where $\Ker(R_m \to R_n)$ is an ideal of square zero for all $m \geq n$
are effective.
\end{enumerate}
Then $\mathcal{X}$ satisfies openness of versality.

\label{lemma-gorenstein-lci}
If $A \to B$ is a local complete intersection homomorphism of rings and
$A$ is a Noetherian Gorenstein ring, then $B$ is a Gorenstein ring.

\label{lemma-determinant-two-term-complexes}
Let $X$ be a scheme. There is a functor
$$
\det :
\left\{
\begin{matrix}
\text{category of perfect complexes} \\
\text{with tor amplitude in }[-1, 0] \\
\text{morphisms are isomorphisms}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{category of invertible modules} \\
\text{morphisms are isomorphisms}
\end{matrix}
\right\}
$$
In addition, given a rank $0$ perfect object $L$ of $D(\mathcal{O}_X)$ with
tor-amplitude in $[-1, 0]$ there is a canonical element
$\delta(L) \in \Gamma(X, \det(L))$ such that for any isomorphism
$a : L \to K$ in $D(\mathcal{O}_X)$ we have $\det(a)(\delta(L)) = \delta(K)$.
Moreover, the construction is affine locally given by the construction
of More on Algebra, Section \ref{more-algebra-section-determinants-complexes}.

\label{lemma-upper-shriek-restriction-etale}
Let $j : U \to X$ and $j' : V \to U$ be \'etale morphisms.
The isomorphism $(j \circ j')^{-1} = (j')^{-1} \circ j^{-1}$
and the isomorphism $(j \circ j')^! = (j')^! \circ j^!$ of
Lemma \ref{lemma-upper-shriek-restriction}
agree via the isomorphism of Lemma \ref{lemma-etale-upper-shriek}.

\label{lemma-semi-diagonal}
\begin{slogan}
Properties of the graph of a morphism of algebraic spaces
as a consequence of separation properties of the target.
\end{slogan}
Let $S$ be a scheme. Let $T$ be an algebraic space over $S$.
Let $g : X \to Y$ be a morphism of algebraic spaces over $T$.
Consider the graph $i : X \to X \times_T Y$ of $g$. Then
\begin{enumerate}
\item $i$ is representable, locally of finite type, locally quasi-finite,
separated and a monomorphism,
\item if $Y \to T$ is locally separated, then $i$ is an immersion,
\item if $Y \to T$ is separated, then $i$ is a closed immersion, and
\item if $Y \to T$ is quasi-separated, then $i$ is quasi-compact.
\end{enumerate}

\label{lemma-compare-constructible}
Let $X$ be a scheme. Let $\Lambda$ be a Noetherian ring.
The functor $\epsilon^{-1}$ defines an equivalence of categories
$$
\left\{
\begin{matrix}
\text{constructible sheaves of}\\
\Lambda\text{-modules on }X_\etale\\
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{constructible sheaves of}\\
\Lambda\text{-modules on }X_\proetale\\
\end{matrix}
\right\}
$$
between constructible sheaves of $\Lambda$-modules on $X_\etale$
and constructible sheaves of $\Lambda$-modules on $X_\proetale$.

\label{lemma-quot-sheaf}
In Situation \ref{situation-quot}. The functor $\Quotfunctor_{\mathcal{F}/X/B}$
satisfies the sheaf property for the fpqc topology.

\label{lemma-points-monomorphism}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
The map $\{\Spec(k) \to X \text{ monomorphism}\} \to |X|$ is injective.

\label{lemma-unramified-flat-lfp-etale}
A locally finitely presented, flat, unramified morphism of algebraic
spaces is \'etale.

\label{lemma-dualizing-tau}
Let $A \to B$ be a flat quasi-finite map of Noetherian rings.
There exists a trace element $\tau \in \omega_{B/A}$.

\label{lemma-noether-pairing-compatibilities}
Let $A \to B$ be a quasi-finite homomorphism of Noetherian rings.
\begin{enumerate}
\item If $A \to A'$ is a flat map of Noetherian rings, then
$$
\xymatrix{
\omega_{B/A} \times J \ar[r] \ar[d] & B \ar[d]  \\
\omega_{B'/A'} \times J' \ar[r] & B'
}
$$
is commutative where notation as in
Lemma \ref{lemma-noether-different-base-change}
and horizontal arrows are given by
(\ref{equation-pairing-noether}).
\item If $B = B_1 \times B_2$, then
$$
\xymatrix{
\omega_{B/A} \times J \ar[r] \ar[d] & B \ar[d]  \\
\omega_{B_i/A} \times J_i \ar[r] & B_i
}
$$
is commutative for $i = 1, 2$ where notation as in
Lemma \ref{lemma-noether-different-product}
and horizontal arrows are given by
(\ref{equation-pairing-noether}).
\end{enumerate}

\label{lemma-blow-up-normal-rational}
In Situation \ref{situation-rational}
the blowup of $\Spec(A)$ in $\mathfrak m$ is normal.

\label{lemma-flat-proper-family-cannot-collapse-fibre}
\begin{slogan}
Collapsing a fibre of a proper family forces nearby ones to collapse too.
\end{slogan}
Let $S$ be a scheme. Let
$$
\xymatrix{
X \ar[rr]_h \ar[rd]_f & & Y \ar[ld]^g \\
& B
}
$$
be a commutative diagram of morphism of algebraic spaces over $S$.
Let $b \in B$ and let $\Spec(k) \to B$ be a morphism in the equivalence
class of $b$. Assume
\begin{enumerate}
\item $X \to B$ is a proper morphism,
\item $Y \to B$ is separated and locally of finite type,
\item one of the following is true
\begin{enumerate}
\item the image of $|X_k| \to |Y_k|$ is finite,
\item the image of $|f|^{-1}(\{b\})$ in $|Y|$ is finite
and $B$ is decent.
\end{enumerate}
\end{enumerate}
Then there is an open
subspace $B' \subset B$ containing $b$ such that $X_{B'} \to Y_{B'}$
factors through a closed subspace $Z \subset Y_{B'}$ finite over $B'$.

\label{lemma-describe-functoriality}
Let $f : Y \to X$ be a morphism of simplicial spaces. In terms of the
description of sheaves in
Lemma \ref{lemma-describe-sheaves-simplicial-site} the
morphism $f_{Zar}$ of Lemma \ref{lemma-simplicial-space-site-functorial}
can be described as follows.
\begin{enumerate}
\item If $\mathcal{G}$ is a sheaf on $Y$, then
$(f_{Zar, *}\mathcal{G})_n = f_{n, *}\mathcal{G}_n$.
\item If $\mathcal{F}$ is a sheaf on $X$, then
$(f_{Zar}^{-1}\mathcal{F})_n = f_n^{-1}\mathcal{F}_n$.
\end{enumerate}

\label{lemma-geometrically-reduced-connected-1-curves}
There exist an open substack $\Curvesstack^{grc, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{grc, 1}$,
\item the geometric fibres of the morphism $X \to S$ are
reduced, connected, and have dimension $1$,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{grc, 1}$,
\item $X$ is geometrically reduced, geometrically connected,
and has dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-universal-finite-syntomic-etale}
With notation as in Example \ref{example-universal-finite-syntomic}
consider the open subscheme $U'_d \subset X_d$ over which
$\pi_d$ is \'etale. Then $U'_d$ is a dense subset of the
open $U_d$ of Lemma \ref{lemma-universal-finite-syntomic}.

\label{lemma-descending-property-smooth}
The property $\mathcal{P}(f) =$``$f$ is smooth''
is fpqc local on the base.

\label{lemma-recurring-real}
Let $A = (a_{ij})$ be a real $n \times n$ matrix with
$a_{ij} \geq 0$ for $i \not = j$. Let $m = (m_1, \ldots, m_n)$ be a real
vector with $m_i > 0$. For $I \subset \{1, \ldots, n\}$ let
$x_I \in \mathbf{R}^n$
be the vector whose $i$th coordinate is $m_i$ if $i \in I$
and $0$ otherwise. If
\begin{equation}
\label{equation-ineq}
-a_{ii}m_i \geq \sum\nolimits_{j \not = i} a_{ij}m_j
\end{equation}
for each $i$, then $\Ker(A)$ is the vector space
spanned by the vectors $x_I$ such that
\begin{enumerate}
\item $a_{ij} = 0$ for $i \in I$, $j \not \in I$, and
\item equality holds in (\ref{equation-ineq}) for $i \in I$.
\end{enumerate}

\label{lemma-characterize-dbcoh-projective}
\begin{reference}
In the projective case this is \cite[Lemma 7.46]{Rouquier-dimensions}
and implicit in \cite[Theorem A.1]{BvdB}
\end{reference}
Let $X$ be a proper scheme over a field $k$. Let
$K \in \Ob(D_\QCoh(\mathcal{O}_X))$. The following are equivalent
\begin{enumerate}
\item $K \in D^b_{\textit{Coh}}(\mathcal{O}_X)$, and
\item $\sum_{i \in \mathbf{Z}} \dim_k \Ext^i_X(E, K) < \infty$
for all perfect $E$ in $D(\mathcal{O}_X)$.
\end{enumerate}

\label{lemma-flat-base-change-lci}
A flat base change of a local complete intersection morphism is a
local complete intersection morphism.

\label{lemma-lci-shriek}
In Situation \ref{situation-shriek} let $f : X \to Y$ be a morphism of
$\textit{FTS}_S$. Assume $f : X \to Y$ is a local complete
intersection morphism. Then
\begin{enumerate}
\item $f^!\mathcal{O}_Y$ is an invertible object of $D(\mathcal{O}_X)$, and
\item $f^!$ maps perfect complexes to perfect complexes.
\end{enumerate}

\label{lemma-regular-at-x}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $x \in |X|$ be a point. The following are equivalent
\begin{enumerate}
\item $X$ is regular at $x$, and
\item the \'etale local ring $\mathcal{O}_{X, \overline{x}}$ is
regular for any (equivalently some) geometric point $\overline{x}$
lying over $x$.
\end{enumerate}

\label{lemma-dimension-square}
Let $A$ be a finite central simple algebra over a field $k$.
Then $[A : k]$ is a square.

\label{lemma-output-quasi-separated}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is quasi-separated if and only if $g$ is so.

\label{lemma-linear-functor}
Let $L: \text{Mod}^{fg}_R \to \textit{Sets}$,
resp.\ $L: \text{Mod}_R \to \textit{Sets}$ be a
functor.  Suppose $L(0)$ is a one element set and $L$ preserves finite
products.  Then there exists a unique $R$-linear functor
$\widetilde{L} : \text{Mod}^{fg}_R \to \text{Mod}_R$,
resp.\  $\widetilde{L} : \text{Mod}_R \to \text{Mod}_R$,
such that
$$
\vcenter{
\xymatrix{
& \text{Mod}_R \ar[dr]^{\text{forget}} &   \\
\text{Mod}^{fg}_R  \ar[ur]^{\widetilde{L}} \ar[rr]^{L} &  &
\textit{Sets}
}
}
\quad\text{resp.}\quad
\vcenter{
\xymatrix{
& \text{Mod}_R \ar[dr]^{\text{forget}} &   \\
\text{Mod}_R  \ar[ur]^{\widetilde{L}} \ar[rr]^{L} &  &
\textit{Sets}
}
}
$$
commutes.

\label{lemma-smooth-quotient-morphism}
Let $(U, R, s, t, c)$ be a groupoid in functors on $\mathcal{C}_\Lambda$.
The following are equivalent:
\begin{enumerate}
\item The groupoid in functors $(U, R, s, t, c)$ is smooth.
\item The morphism $s : R \to U$ is smooth.
\item The morphism $t : R \to U$ is smooth.
\item The quotient morphism $U \to [U/R]$ is smooth.
\end{enumerate}

\label{lemma-family-associated-closed}
The construction in Example \ref{example-family-associated-closed}
is compatible with base change, restriction, and flat pullback.

\label{lemma-characterize-sheaf-h}
Let $\mathcal{F}$ be a presheaf on $(\Sch/S)_h$.
Then $\mathcal{F}$ is a sheaf if and only if
\begin{enumerate}
\item $\mathcal{F}$ satisfies the sheaf condition for
Zariski coverings, and
\item if $f : V \to U$ is proper, surjective, and of finite presentation, then
$\mathcal{F}(U)$ maps bijectively to the equalizer
of the two maps $\mathcal{F}(V) \to \mathcal{F}(V \times_U V)$.
\end{enumerate}
Moreover, in the presence of (1) property (2) is equivalent to
property
\begin{enumerate}
\item[(2')] the sheaf property for $\{V \to U\}$ as in (2) with $U$ affine.
\end{enumerate}

\label{lemma-criterion-normal}
Let $X$ be a locally Noetherian scheme.
Then $X$ is normal if and only if $X$ has properties $(S_2)$ and $(R_1)$.

\label{lemma-descending-property-finite-type}
The property $\mathcal{P}(f) =$``$f$ is of finite type''
is fpqc local on the base.

\label{lemma-tensor-pull-compatibility}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C}) \to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$ be a morphism of ringed topoi.
Let $\mathcal{K}^\bullet$ and $\mathcal{M}^\bullet$
be complexes of $\mathcal{O}_\mathcal{D}$-modules.
The diagram
$$
\xymatrix{
Lf^*(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}^\mathbf{L}
\mathcal{M}^\bullet) \ar[r] \ar[d] &
Lf^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}
\mathcal{M}^\bullet) \ar[d] \\
Lf^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_\mathcal{C}}^\mathbf{L}
Lf^*\mathcal{M}^\bullet \ar[d] &
f^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_\mathcal{D}}
\mathcal{M}^\bullet) \ar[d] \\
f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_\mathcal{C}}^\mathbf{L}
f^*\mathcal{M}^\bullet \ar[r] &
\text{Tot}(f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_\mathcal{C}}
f^*\mathcal{M}^\bullet)
}
$$
commutes.

\label{lemma-locally-Noetherian-fibres-fppf-local-source-and-target}
The property $\mathcal{P}(f)=$``the fibres of $f$ are locally Noetherian''
is local in the fppf topology on the source and the target.

\label{lemma-locally-constant-on-connected-geom-unibranch}
Let $X$ be an irreducible, geometrically unibranch scheme.
Let $\overline{x}$ be a geometric point of $X$.
Let $\Lambda$ be a ring. There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite type, locally constant}\\
\text{sheaves of }\Lambda\text{-modules on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\Lambda\text{-modules }M\text{ endowed}\\
\text{with a continuous }\pi_1(X, \overline{x})\text{-action}
\end{matrix}
\right\}
$$

\label{proposition-injective-pic}
\begin{reference}
\cite[Theorem 1.9]{Kollar-map-pic}
\end{reference}
Let $(A, \mathfrak m)$ be a Noetherian local ring. Let $f \in \mathfrak m$.
Assume
\begin{enumerate}
\item $A$ has a dualizing complex,
\item $f$ is a nonzerodivisor,
\item $\text{depth}(A/fA) \geq 2$, or equivalently $\text{depth}(A) \geq 3$,
\item if $f \in \mathfrak p \subset A$ is a prime ideal with
$\dim(A/\mathfrak p) = 2$, then $\text{depth}(A_\mathfrak p) \geq 2$.
\end{enumerate}
Let $U$, resp.\ $U_0$ be the punctured spectrum of $A$, resp.\ $A/fA$. The map
$$
\Pic(U) \to \Pic(U_0)
$$
is injective. Finally, if (1), (2), (3), $A$ is $(S_2)$, and
$\dim(A) \geq 4$, then (4) holds.

\label{lemma-descending-property-locally-finite-presentation}
The property $\mathcal{P}(f) =$``$f$ is locally of finite presentation''
is fpqc local on the base.

\label{lemma-normal-dimension-1-regular}
Let $X$ be a locally Noetherian scheme which is normal and
has dimension $\leq 1$. Then $X$ is regular.

\label{lemma-pure-injective}
Let $A$ be a ring. For any $A$-module $M$ set
$M^\vee = \Hom_\mathbf{Z}(M, \mathbf{Q}/\mathbf{Z})$.
\begin{enumerate}
\item For any $A$-module $M$ the $A$-module $M^\vee$ is pure injective.
\item An $A$-module $I$ is pure injective if and only if the map
$I \to (I^\vee)^\vee$ splits.
\item For any module $M$ there exists a universally exact sequence
$0 \to M \to I \to N \to 0$ with $I$ pure injective.
\end{enumerate}

\label{lemma-glueing-gives-functor-proj}
In Situation \ref{situation-relative-proj}.
The scheme $\pi : \underline{\text{Proj}}_S(\mathcal{A}) \to S$
constructed in Lemma \ref{lemma-glue-relative-proj}
and the scheme representing the functor $F$
are canonically isomorphic as schemes over $S$.

\label{lemma-base-change-formal-smoothness}
The base change of a formally smooth morphism of algebraic stacks
by any morphism of algebraic stacks is formally smooth.

\label{lemma-representable-locally-separated-diagonal-immersion}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
representable by algebraic spaces. Then the following are equivalent
\begin{enumerate}
\item $f$ is locally separated, and
\item $\Delta_f$ is an immersion.
\end{enumerate}

\label{lemma-slice-CM}
\begin{reference}
\cite[IV Proposition 17.16.1]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$ be a point with image $s \in S$.
Assume
\begin{enumerate}
\item $f$ is locally of finite presentation,
\item $f$ is Cohen-Macaulay at $x$, and
\item $x$ is a closed point of $X_s$.
\end{enumerate}
Then there exists a regular immersion $Z \to X$ containing $x$ such that
\begin{enumerate}
\item[(a)] $Z \to S$ is flat and locally of finite presentation,
\item[(b)] $Z \to S$ is locally quasi-finite, and
\item[(c)] $Z_s = \{x\}$ set theoretically.
\end{enumerate}

\label{lemma-localize-at-bottom}
Let $A \to A' \to B$ be ring maps such that $B = B \otimes_A^\mathbf{L} A'$.
Then $L_{B/A} = L_{B/A'}$ in $D(B)$.

\label{lemma-smooth-power-series-classical}
Let $\mathcal{F}$ be a predeformation category.
Let $\xi$ be a versal formal object of $\mathcal{F}$ lying over
$R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$. The following are
equivalent
\begin{enumerate}
\item $\mathcal{F}$ is unobstructed, and
\item $\Lambda \to R$ is formally smooth in the $\mathfrak m_R$-adic topology.
\end{enumerate}
In the classical case these are also equivalent to
\begin{enumerate}
\item[(3)] $R \cong \Lambda[[x_1, \ldots, x_n]]$ for some $n$.\
\end{enumerate}

\label{lemma-complexes-strong-effectiveness}
In Situation \ref{situation-complexes} assume $B = S$ is locally Noetherian.
Then strong formal effectiveness in the sense of
Artin's Axioms, Remark \ref{artin-remark-strong-effectiveness}
holds for $p : \Complexesstack_{X/S} \to (\Sch/S)_{fppf}$.

\label{lemma-tor-amplitude-stalk}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $E$ be an object of $D(\mathcal{O})$.
Let $a, b \in \mathbf{Z}$.
\begin{enumerate}
\item If $E$ has tor amplitude in $[a, b]$, then for every point $p$
of the site $\mathcal{C}$ the object $E_p$ of $D(\mathcal{O}_p)$
has tor amplitude in $[a, b]$.
\item If $\mathcal{C}$ has enough points, then the converse is true.
\end{enumerate}

\label{lemma-essentially-surjective-general-better}
In Situation \ref{situation-local-lefschetz} assume
\begin{enumerate}
\item $A$ has a dualizing complex and is $f$-adically complete,
\item one of the following is true
\begin{enumerate}
\item $A_f$ is $(S_2)$ and every irreducible component of $X$
not contained in $X_0$ has dimension $\geq 4$, or
\item if $\mathfrak p \not \in V(f)$ and
$V(\mathfrak p) \cap V(f) \not = \{\mathfrak m\}$, then
$\text{depth}(A_\mathfrak p) + \dim(A/\mathfrak p) > 3$.
\end{enumerate}
\end{enumerate}
Then the restriction functor
$$
\colim_{U_0 \subset U' \subset U\text{ open}} \textit{F\'Et}_{U'}
\longrightarrow
\textit{F\'Et}_{U_0}
$$
is an equivalence.

\label{theorem-tsen}
The function field of a variety of dimension $r$ over an algebraically closed
field $k$ is $C_r$.

\label{lemma-qf-f-shriek-constructible}
Let $f : X \to Y$ be a morphism of schemes which is
locally quasi-finite and of finite presentation.
The functor $f_! : D(X_\etale, \Lambda) \to D(Y_\etale, \Lambda)$
of Lemma \ref{lemma-lqf-shriek-derived}
sends $D_c(X_\etale, \Lambda)$ into $D_c(Y_\etale, \Lambda)$.

\label{lemma-keel-mori-proper}
Let $p : \mathcal{X} \to Y$ be a morphism from an algebraic stack
to an algebraic space. Assume
\begin{enumerate}
\item $\mathcal{I}_\mathcal{X} \to \mathcal{X}$ is finite,
\item $p$ is proper, and
\item $Y$ is locally Noetherian.
\end{enumerate}
Let $f : \mathcal{X} \to M$ be the moduli space constructed in
Theorem \ref{theorem-keel-mori}. Then $M \to Y$ is proper.

\label{proposition-exists-minimal-model}
Let $C$ be a smooth projective curve over $K$ with
$H^0(C, \mathcal{O}_C) = K$. A minimal model exists.

\label{lemma-crystals-on-affine}
In the situation above there is a functor
$$
\begin{matrix}
\text{crystals in quasi-coherent} \\
\mathcal{O}_{X/S}\text{-modules on }\text{Cris}(X/S)
\end{matrix}
\longrightarrow
\begin{matrix}
\text{pairs }(M, \nabla)\text{ satisfying} \\
\text{(\ref{item-complete}), (\ref{item-connection}),
(\ref{item-integrable}), and (\ref{item-topologically-quasi-nilpotent})}
\end{matrix}
$$

\label{lemma-descending-property-surjective}
The property $\mathcal{P}(f) =$``$f$ is surjective''
is fpqc local on the base.

\label{lemma-descend-etale}
With notation and assumptions as in
Situation \ref{situation-descent-property}. If
\begin{enumerate}
\item $f$ is \'etale,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is \'etale for some $i \geq 0$.

\label{lemma-deform-property}
Let $S$ be a scheme. Consider a commutative diagram
$$
\xymatrix{
(X \subset X') \ar[rr]_{(f, f')} \ar[rd] & & (Y \subset Y') \ar[ld] \\
& (B \subset B')
}
$$
of thickenings of algebraic spaces over $S$. Assume $B \subset B'$
is a finite order thickening, $X'$ flat over $B'$, $X = B \times_{B'} X'$,
and $Y = B \times_{B'} Y'$. Then
\begin{enumerate}
\item $f$ is representable if and only if $f'$ is representable,
\label{item-representable}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion}
\item $f$ is quasi-compact if and only if $f'$ is quasi-compact,
\label{item-quasi-compact}
\item $f$ is universally closed if and only if $f'$ is universally closed,
\label{item-universally-closed}
\item $f$ is (quasi-)separated if and only if $f'$ is (quasi-)separated,
\label{item-separated}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism}
\item $f$ is surjective if and only if $f'$ is surjective,
\label{item-surjective}
\item $f$ is universally injective if and only if $f'$ is universally injective,
\label{item-universally-injective}
\item $f$ is affine if and only if $f'$ is affine,
\label{item-affine}
\item
\label{item-finite-type}
$f$ is locally of finite type if and only if $f'$ is locally of finite type,
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite}
\item
\label{item-finite-presentation}
$f$ is locally of finite presentation if and only if $f'$ is locally of
finite presentation,
\item
\label{item-relative-dimension-d}
$f$ is locally of finite type of relative dimension $d$ if and only if
$f'$ is locally of finite type of relative dimension $d$,
\item $f$ is universally open if and only if $f'$ is universally open,
\label{item-universally-open}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale}
\item $f$ is proper if and only if $f'$ is proper,
\label{item-proper}
\item $f$ is integral if and only if $f'$ is integral,
\label{item-integral}
\item $f$ is finite if and only if $f'$ is finite,
\label{item-finite}
\item
\label{item-finite-locally-free}
$f$ is finite locally free (of rank $d$) if and only if $f'$
is finite locally free (of rank $d$), and
\item add more here.
\end{enumerate}

\label{lemma-characterize-sheaf}
Let $\mathcal{F}$ be a presheaf on $(\Sch/S)_{ph}$.
Then $\mathcal{F}$ is a sheaf if and only if
\begin{enumerate}
\item $\mathcal{F}$ satisfies the sheaf condition for
Zariski coverings, and
\item if $f : V \to U$ is proper surjective, then
$\mathcal{F}(U)$ maps bijectively to the equalizer
of the two maps $\mathcal{F}(V) \to \mathcal{F}(V \times_U V)$.
\end{enumerate}
Moreover, in the presence of (1) property (2) is equivalent to property
\begin{enumerate}
\item[(2')] the sheaf property for $\{V \to U\}$ as in (2) with $U$ affine.
\end{enumerate}

\label{lemma-equivalence-coherent-over-field}
\begin{reference}
Weak version of the result in \cite{Gabriel}
stating that the category of quasi-coherent modules
determines the isomorphism class of a scheme.
\end{reference}
Let $k$ be a field. Let $X$, $Y$ be finite type schemes over $k$ with
$X$ separated and $Y$ reduced. If there is a $k$-linear equivalence
$F : \textit{Coh}(\mathcal{O}_X) \to \textit{Coh}(\mathcal{O}_Y)$
of categories, then there is an isomorphism $f : Y \to X$
over $k$ and an invertible $\mathcal{O}_Y$-module $\mathcal{L}$
such that $F(\mathcal{F}) = f^*\mathcal{F} \otimes \mathcal{L}$.

\label{lemma-normal-local-domain-separablly-closed-fraction-field}
A normal local ring with separably closed fraction field is
strictly henselian.

\label{lemma-representable-morphism-equivalent}
Let $S$ be an object of $\Sch_{fppf}$.
Consider a $2$-commutative diagram
$$
\xymatrix{
\mathcal{X}' \ar[r] \ar[d]_{f'} & \mathcal{X} \ar[d]^f \\
\mathcal{Y}' \ar[r] & \mathcal{Y}
}
$$
of $1$-morphisms of categories fibred in groupoids over
$(\Sch/S)_{fppf}$.
Assume the horizontal arrows are equivalences.
Then $f$ is representable if and only if $f'$ is representable.

\label{lemma-quasi-coherence-tensor-product}
Let $X$ be a scheme.
\begin{enumerate}
\item For objects $K, L$ of $D_\QCoh(\mathcal{O}_X)$
the derived tensor product $K \otimes^\mathbf{L}_{\mathcal{O}_X} L$ is in
$D_\QCoh(\mathcal{O}_X)$.
\item If $X = \Spec(A)$ is affine then
$$
\widetilde{M^\bullet} \otimes_{\mathcal{O}_X}^\mathbf{L} \widetilde{K^\bullet}
=
\widetilde{M^\bullet \otimes_A^\mathbf{L} K^\bullet}
$$
for any pair of complexes of $A$-modules $K^\bullet$, $M^\bullet$.
\end{enumerate}

\label{lemma-fibres-irreducible-flat-projective-nonnoetherian}
Let $R$ be a ring. Let $R \to S$ be a ring map.
Assume
\begin{enumerate}
\item $R \to S$ is of finite presentation and flat, and
\item every fibre ring $S \otimes_R \kappa(\mathfrak p)$ is
geometrically integral over $\kappa(\mathfrak p)$.
\end{enumerate}
Then $S$ is projective as an $R$-module.

\label{lemma-galois}
Let $(\mathcal{C}, F)$ be a Galois category. For any connected object $X$
of $\mathcal{C}$ there exists a Galois object $Y$ and a morphism $Y \to X$.

\label{lemma-limit-is-scheme}
Notation and assumptions as in Situation \ref{situation-descent}.
If $X$ is a scheme, then there exists an $i$ such that $X_i$ is a scheme.

\label{lemma-flat-finite-presentation-CM-pieces}
Let $f : X \to S$ be a morphism of schemes which is flat and locally
of finite presentation. For $d \geq 0$ there exist opens $U_d \subset X$
with the following properties
\begin{enumerate}
\item $W = \bigcup_{d \geq 0} U_d$ is dense in every fibre of $f$, and
\item $U_d \to S$ is of relative dimension $d$ (see
Morphisms, Definition \ref{morphisms-definition-relative-dimension-d}).
\end{enumerate}

\label{lemma-gorenstein-lci}
If $f : Y \to X$ is a local complete intersection morphism
with $X$ a Gorenstein scheme, then $Y$ is Gorenstein.

\label{lemma-connected-along-section-open-neighbourhood}
Let $f : X \to Y$, $s : Y \to X$ be as in
Situation \ref{situation-connected-along-section}.
Let $y \in Y$ be a point.
Assume
\begin{enumerate}
\item $f$ is of finite presentation and flat, and
\item the fibre $X_y$ is geometrically reduced.
\end{enumerate}
Then $X^0$ is a neighbourhood of $X^0_y$ in $X$.

\label{lemma-surjective-proper-finite-presentation-h}
Let $f : Y \to X$ be a surjective proper morphism of schemes
which is of finite presentation. Then $\{Y \to X\}$ is an h covering.

\label{lemma-Noetherian-sober}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
If $X$ is Noetherian, then $|X|$ is a sober Noetherian topological space.

\label{lemma-quasi-finite}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is quasi-finite, and
\item $f$ is locally of finite type, quasi-compact, and has finite fibres.
\end{enumerate}

\label{lemma-existence-representable}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
which is representable by algebraic spaces. Then the following are equivalent
\begin{enumerate}
\item $f$ satisfies the existence part of the valuative criterion,
\item for every scheme $T$ and morphism $T \to \mathcal{Y}$
the morphism $\mathcal{X} \times_\mathcal{Y} T \to T$ satisfies
the existence part of the valuative criterion as a morphism
of algebraic spaces.
\end{enumerate}

\label{lemma-cartesian-diagram-quasi-affine}
Let $U \to V$ be an open immersion of quasi-affine schemes. Then
$$
\xymatrix{
U \ar[d] \ar[rr]_-j & & \Spec(\Gamma(U, \mathcal{O}_U)) \ar[d] \\
U \ar[r] & V \ar[r]^-{j'} & \Spec(\Gamma(V, \mathcal{O}_V))
}
$$
is cartesian.

\label{lemma-non-separated-group-scheme}
There exists a flat group scheme of finite type over the affine line
which is not separated.

\label{lemma-get-fully-faithful}
\begin{reference}
Variant of \cite[Lemma 2.15]{Orlov-K3}
\end{reference}
Let $F : \mathcal{D} \to \mathcal{D}'$ be an exact functor of
triangulated categories. Let $S \subset \Ob(\mathcal{D})$ be
a set of objects. Assume
\begin{enumerate}
\item $F$ has both right and left adjoints,
\item for $K \in \mathcal{D}$ if $\Hom(E, K[i]) = 0$ for all
$E \in S$ and $i \in \mathbf{Z}$ then $K = 0$,
\item for $K \in \mathcal{D}$ if $\Hom(K, E[i]) = 0$ for all
$E \in S$ and $i \in \mathbf{Z}$ then $K = 0$,
\item the map $\Hom(E, E'[i]) \to \Hom(F(E), F(E')[i])$ induced by $F$
is bijective for all $E, E' \in S$ and $i \in \mathbf{Z}$.
\end{enumerate}
Then $F$ is fully faithful.

\label{theorem-chevalley}
\begin{reference}
\cite[IV, Theorem 1.8.4]{EGA}
\end{reference}
Let $f : X \to Y$ be a morphism of schemes.
Assume $f$ is quasi-compact and locally of finite presentation.
Then the image of every locally constructible subset is locally constructible.

\label{lemma-depth-2-connected-punctured-spectrum}
\begin{reference}
\cite[Proposition 2.1]{Hartshorne-connectedness}
\end{reference}
\begin{slogan}
Hartshorne's connectedness
\end{slogan}
Let $A$ be a Noetherian local ring of depth $\geq 2$.
Then the punctured spectra of $A$, $A^h$, and $A^{sh}$ are connected.

\label{lemma-adams-and-chern}
In the situation above let $X \in \Ob(\mathcal{C})$.
If $\psi^2$ is as in
Chow Homology, Lemma \ref{chow-lemma-second-adams-operator}
and $c^A$ and $ch^A$ are as in
Propositions \ref{proposition-chern-class} and
\ref{proposition-chern-character}
then we have $c^A_i(\psi^2(\alpha)) = 2^i c^A_i(\alpha)$ and
$ch^A_i(\psi^2(\alpha)) = 2^i ch^A_i(\alpha)$
for all $\alpha \in K_0(\textit{Vect}(X))$.

\label{lemma-cone-pseudo-coherent}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site and $m \in \mathbf{Z}$.
Let $(K, L, M, f, g, h)$ be a distinguished triangle in $D(\mathcal{O})$.
\begin{enumerate}
\item If $K$ is $(m + 1)$-pseudo-coherent and $L$ is $m$-pseudo-coherent
then $M$ is $m$-pseudo-coherent.
\item If $K$ and $M$ are $m$-pseudo-coherent, then $L$ is $m$-pseudo-coherent.
\item If $L$ is $(m + 1)$-pseudo-coherent and $M$
is $m$-pseudo-coherent, then $K$ is $(m + 1)$-pseudo-coherent.
\end{enumerate}

\label{lemma-scheme-regular-iff-all-Rk}
Let $X$ be a locally Noetherian scheme.
Then $X$ is regular if and only if $X$ has $(R_k)$ for all $k \geq 0$.

\label{lemma-semistable-curves}
There exist an open substack $\Curvesstack^{semistable} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{semistable}$,
\item $X \to S$ is a semistable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{semistable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, the genus of $X$ is $\geq 1$, and
$X$ has no rational tails,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and $\omega_{X_s}^{\otimes m}$ is
globally generated for $m \geq 2$.
\end{enumerate}
\end{enumerate}

\label{proposition-QC-compare}
Let $\mathcal{X}$ be an algebraic stack. Then $\mathit{QC}(\mathcal{X})$
is canonically equivalent to $D_\QCoh(\mathcal{O}_\mathcal{X})$.

\label{lemma-Zariski-usual}
The category of sheaves on $S_{Zar}$ is equivalent to the
category of sheaves on the underlying topological space of $S$.

\label{lemma-quasi-coherent-weak-serre}
Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item $\QCoh(\mathcal{O}_{\mathcal{X}_{lisse,\etale}})$
is a weak Serre subcategory of
$\textit{Mod}(\mathcal{O}_{\mathcal{X}_{lisse,\etale}})$.
\item $\QCoh(\mathcal{O}_{\mathcal{X}_{flat,fppf}})$
is a weak Serre subcategory of
$\textit{Mod}(\mathcal{O}_{\mathcal{X}_{flat,fppf}})$.
\end{enumerate}

\label{lemma-reduced-group-scheme-perfect-field-characteristic-p-smooth}
Let $S$ be a scheme. Let $(U, R, s, t, c)$ be a groupoid scheme
over $S$. Assume
\begin{enumerate}
\item $U = \Spec(k)$ with $k$ a field,
\item $s, t$ are locally of finite type,
\item $R$ is reduced, and
\item $k$ is perfect.
\end{enumerate}
Then $s, t : R \to U$ are smooth.

\label{proposition-algebraic-stack-no-automorphisms}
Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $\mathcal{X}$ be an algebraic stack over $S$.
The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is a stack in setoids,
\item the canonical $1$-morphism $\mathcal{I}_\mathcal{X} \to \mathcal{X}$
is an equivalence, and
\item $\mathcal{X}$ is representable by an algebraic space.
\end{enumerate}

\label{lemma-compare-structure-sheaves}
Let $X$ be a scheme. Let
$\tau \in \{Zariski, \etale, smooth, syntomic, fppf\}$.
Let $\mathcal{C}_1 \subset \mathcal{C}_2 \subset (\Sch/X)_\tau$ be full
subcategories with the following properties:
\begin{enumerate}
\item For an object $U/X$ of $\mathcal{C}_t$,
\begin{enumerate}
\item if $\{U_i \to U\}$ is a covering of $(\Sch/X)_\tau$, then
$U_i/X$ is an object of $\mathcal{C}_t$,
\item $U \times \mathbf{A}^1/X$ is an object of $\mathcal{C}_t$.
\end{enumerate}
\item $X/X$ is an object of $\mathcal{C}_t$.
\end{enumerate}
We endow $\mathcal{C}_t$ with the structure of a site whose coverings are
exactly those coverings $\{U_i \to U\}$ of $(\Sch/X)_\tau$ with
$U \in \Ob(\mathcal{C}_t)$. Then
\begin{enumerate}
\item[(a)] The functor $\mathcal{C}_1 \to \mathcal{C}_2$
is fully faithful, continuous, and cocontinuous.
\end{enumerate}
Denote $g : \Sh(\mathcal{C}_1) \to \Sh(\mathcal{C}_2)$ the corresponding
morphism of topoi. Denote $\mathcal{O}_t$ the restriction of $\mathcal{O}$
to $\mathcal{C}_t$. Denote $g_!$ the functor of
Modules on Sites, Definition \ref{sites-modules-definition-g-shriek}.
\begin{enumerate}
\item[(b)] The canonical map $g_!\mathcal{O}_1 \to \mathcal{O}_2$
is an isomorphism.
\end{enumerate}

\label{lemma-conclude}
In the situation of Lemma \ref{lemma-structure-cohomology}
assume that $H^i(V, \mathcal{O}_V) = 0$ for $i \geq \dim(A) - 1$.
Then $V$ is affine.

\label{lemma-composition-universally-closed}
The composition of a pair of (universally) closed morphisms of algebraic spaces
is (universally) closed.

\label{lemma-constructible-quasi-compact-quasi-separated}
Let $X$ be a quasi-compact and quasi-separated scheme.
Any locally constructible subset of $X$ is constructible.

\label{lemma-flat-dimension-n}
In Situation \ref{situation-flat-dimension-n}.
\begin{enumerate}
\item The functor $F_n$ satisfies the sheaf property for the fpqc topology.
\item If $f$ is quasi-compact and locally of finite presentation
and $\mathcal{F}$ is of finite presentation, then the functor $F_n$ is
limit preserving.
\end{enumerate}

\label{lemma-compare-cohomology-general}
In Situation \ref{situation-compare}. Let $X$ be in $\mathcal{C}$.
\begin{enumerate}
\item for $\mathcal{F}'$ in $\mathcal{A}'_X$ we have
$H^n_{\tau'}(X, \mathcal{F}') = H^n_\tau(X, \epsilon_X^{-1}\mathcal{F}')$,
\item for $K' \in D^+_{\mathcal{A}'_X}(\mathcal{C}_{\tau'}/X)$
we have $H^n_{\tau'}(X, K') = H^n_\tau(X, \epsilon_X^{-1}K')$.
\end{enumerate}

\label{lemma-Z-not-quasi-compact}
The scheme $\Spec(\mathbf{Z})$ is not quasi-compact
in the canonical topology on the category of schemes.

\label{lemma-descend-separated-morphism}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If $f$ is separated, then $f_i$ is separated for some $i \geq 0$.

\label{lemma-verify-site-fppf}
Let $S$ be a scheme. Let $\Sch_{fppf}$ be a big fppf
site containing $S$. Then $(\textit{Aff}/S)_{fppf}$ is a site.

\label{lemma-homomorphism-pre}
In Lemma \ref{lemma-gysin-at-infty} we have
$C \circ (W_\infty \to X)_* \circ i_\infty^* = i_\infty^*$.

\label{lemma-quasi-compact-open-immersion-finite-presentation}
Any open immersion is of finite presentation if and only if
it is quasi-compact.

\label{lemma-DQCoh-alternative-small}
In the situation above there are canonical exact equivalences between
the following triangulated categories
\begin{enumerate}
\item $D_\QCoh(\mathcal{O}_X)$,
\item $D_\QCoh(X_{affine, \etale}, \mathcal{O}_X)$,
\item $D_\QCoh(X_{affine}, \mathcal{O}_X)$, and
\item $\mathit{QC}(X_{affine}, \mathcal{O}_X)$.
\end{enumerate}

\label{lemma-smooth-locally-standard-smooth}
\begin{slogan}
Smooth morphisms are locally standard smooth.
\end{slogan}
Let $f : X  \to S$ be a morphism of schemes.
Let $x \in X$ be a point.
Let $V \subset S$ be an affine open neighbourhood of $f(x)$.
The following are equivalent
\begin{enumerate}
\item The morphism $f$ is smooth at $x$.
\item There exists an affine open $U \subset X$,
with $x \in U$ and $f(U) \subset V$ such that the
induced morphism $f|_U : U \to V$ is standard smooth.
\end{enumerate}

\label{lemma-equivalence}
Notation and assumptions as above. Let $p : X_A \to X$ denote the projection.
Given $A'$ denote $p' : X_{A'} \to X$ the projection. The functor $p'_*$
induces an equivalence of categories between
\begin{enumerate}
\item the category $\textit{Lift}(\mathcal{F}, A')$, and
\item the category $\textit{Lift}(p_*\mathcal{F}, A')$.
\end{enumerate}

\label{lemma-ev-injective-sheaves}
For any $\mathcal{O}$-module $\mathcal{F}$ the evaluation map
$ev : \mathcal{F} \to (\mathcal{F}^\vee)^\vee$ is injective.

\label{lemma-Kprime-K}
Let $X$ be a Noetherian regular scheme. Then
the map $K_0(X) \to K'_0(X)$ is an isomorphism.

\label{lemma-characterize-noetherian-affine}
Let $S$ be a scheme. Let $X$ be an affine formal algebraic space.
The following are equivalent
\begin{enumerate}
\item $X$ is Noetherian,
\item $X$ is adic* and for every closed immersion $T \to X$ with $T$ a scheme,
$T$ is Noetherian,
\item $X$ is adic* and for some choice of $X = \colim X_\lambda$ as in
Definition \ref{definition-affine-formal-algebraic-space}
the schemes $X_\lambda$ are Noetherian, and
\item $X$ is weakly adic and for some choice $X = \colim X_\lambda$
as in Definition \ref{definition-affine-formal-algebraic-space}
the schemes $X_\lambda$ are Noetherian.
\end{enumerate}

\label{theorem-centralizer}
Let $A$ be a finite central simple algebra over $k$, and let
$B$ be a simple subalgebra of $A$. Then
\begin{enumerate}
\item the centralizer $C$ of $B$ in $A$ is simple,
\item $[A : k] = [B : k][C : k]$, and
\item the centralizer of $C$ in $A$ is $B$.
\end{enumerate}

\label{lemma-make-family}
With notation as above. Let $X, Y$ be closed subvarieties of $\mathbf{P}(V)$
which intersect properly such that $X \not = \mathbf{P}(V)$ and
$X \cap Y \not = \emptyset$. For a general line $\ell \subset \mathbf{P}$
with $[\text{id}_V] \in \ell$ we have
\begin{enumerate}
\item $X \subset U_g$ for all $[g] \in \ell$,
\item $g(X)$ intersects $Y$ properly for all $[g] \in \ell$.
\end{enumerate}

\label{lemma-equivalence}
The notion above does indeed define an equivalence relation on
morphisms from spectra of fields into the algebraic stack $\mathcal{X}$.

\label{proposition-avramov}
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
Then the following are equivalent
\begin{enumerate}
\item $B^\wedge$ is a complete intersection,
\item $A^\wedge$ and $(B/\mathfrak m_A B)^\wedge$ are complete intersections.
\end{enumerate}

\label{lemma-cat-dotted-arrows}
In the situation of Definition \ref{definition-fill-in-diagram}
the category of dotted arrows is a groupoid. If $\Delta_f$
is separated, then it is a setoid.

\label{lemma-make-commute-map}
Let $(A, \text{d})$ be a differential graded algebra. Let
$$
\xymatrix{
K \ar[r]_f \ar[d]_a & L \ar[d]^b \\
M \ar[r]^g & N
}
$$
be a diagram of homomorphisms of differential graded $A$-modules
commuting up to homotopy.
\begin{enumerate}
\item If $f$ is an admissible monomorphism, then $b$ is homotopic to a
homomorphism which makes the diagram commute.
\item If $g$ is an admissible epimorphism, then $a$ is homotopic to a
morphism which makes the diagram commute.
\end{enumerate}

\label{lemma-noetherian-finite-type-finite-presentation}
\begin{slogan}
Over a locally Noetherian base, finite type is finite presentation.
\end{slogan}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item If $S$ is locally Noetherian and $f$ locally of finite type
then $f$ is locally of finite presentation.
\item If $S$ is locally Noetherian and $f$ of finite type
then $f$ is of finite presentation.
\end{enumerate}

\label{lemma-stabilizer-preserving-unramified}
\begin{reference}
\cite[Proposition 3.5]{rydh_quotients} and
\cite[Proposition 2.5]{alper_quotient}
\end{reference}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Assume
\begin{enumerate}
\item $f$ is representable by algebraic spaces and unramified, and
\item $\mathcal{I}_\mathcal{Y} \to \mathcal{Y}$ is proper.
\end{enumerate}
Then the set of $x \in |\mathcal{X}|$ such that $f$ induces an
isomorphism between automorphism groups at $x$ and $f(x)$
(Remark \ref{remark-identify-automorphism-groups}) is open.
Letting $\mathcal{U} \subset \mathcal{X}$ be the corresponding open substack,
the morphism
$\mathcal{I}_\mathcal{U} \to
\mathcal{U} \times_\mathcal{Y} \mathcal{I}_\mathcal{Y}$
is an isomorphism.

\label{lemma-approximate-by-etale-over-complement}
Let $A$ be a Noetherian ring. Let $I \subset A$ be an ideal.
Let $B$ be an $I$-adically complete $A$-algebra with $A/I \to B/IB$
of finite type. The equivalent conditions of
Lemma \ref{lemma-equivalent-with-artin} are also equivalent to
\begin{enumerate}
\item[(8)]
\label{item-algebraize}
there exists a finite type $A$-algebra $C$ such that
$\Spec(C) \to \Spec(A)$ is \'etale over $\Spec(A) \setminus V(I)$
and such that $B \cong C^\wedge$.
\end{enumerate}

\label{lemma-flat-finite-presentation-CM-fibres-relative-dimension}
\begin{slogan}
Cohen-Macaulay morphisms decompose into clopens of pure relative dimension
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Assume that
\begin{enumerate}
\item $f$ is flat,
\item $f$ is locally of finite presentation, and
\item for all $s \in S$ the fibre $X_s$ is Cohen-Macaulay
(Properties, Definition \ref{properties-definition-Cohen-Macaulay})
\end{enumerate}
Then there exist open and closed subschemes $X_d \subset X$
such that $X = \coprod_{d \geq 0} X_d$ and $f|_{X_d} : X_d \to S$
has relative dimension $d$.

\label{lemma-finite-finitely-presented-over-w-contractible}
Let $A \to B$ be a finite and finitely presented ring map.
If $A$ is w-contractible, so is $B$.

\label{lemma-etale-makes-quasi-finite-finite-multiple-points}
Let $f : X \to S$ be a morphism of schemes.
Let $x_1, \ldots, x_n \in X$ be points having the same image $s$ in $S$.
Assume that
\begin{enumerate}
\item $f$ is locally of finite type, and
\item $x_i \in X_s$ is isolated for $i = 1, \ldots, n$.
\end{enumerate}
Then there exist
\begin{enumerate}
\item[(a)] an elementary \'etale neighbourhood $(U, u) \to (S, s)$,
\item[(b)] for each $i$ an open subscheme $V_i \subset X_U$,
\end{enumerate}
such that for each $i$ we have
\begin{enumerate}
\item[(\romannumeral1)] $V_i \to U$ is a finite morphism,
\item[(\romannumeral2)] there is a unique point $v_i$ of $V_i$
mapping to $u$ in $U$, and
\item[(\romannumeral3)] the point $v_i$ maps to $x_i$ in $X$ and
$\kappa(x_i) = \kappa(v_i)$.
\end{enumerate}

\label{lemma-trivial-implications}
Let $S$ be a scheme.
Let $X$ be an algebraic space over $S$.
We have the following implications among the separation axioms
of Definition \ref{definition-separated}:
\begin{enumerate}
\item separated implies all the others,
\item quasi-separated implies Zariski locally quasi-separated.
\end{enumerate}

\label{lemma-characterize-minimal-groupoid-in-functors}
Let $(U, R, s, t, c)$ be a smooth prorepresentable groupoid in
functors on $\mathcal{C}_\Lambda$.
\begin{enumerate}
\item $(U, R, s, t, c)$ is normalized if and only if the morphism
$U \to [U/R]$ induces an isomorphism on tangent spaces, and
\item $(U, R, s, t, c)$ is minimal if and only if the kernel of
$TU \to T[U/R]$ is contained in the image of
$\text{Der}_\Lambda(k, k) \to TU$.
\end{enumerate}

\label{lemma-dual}
Let $X$ be a smooth projective scheme over $k$ which is equidimensional
of dimension $d$. Then $h(X)(d)$ is a left dual to $h(X)$ in $M_k$.

\label{lemma-rickard}
Let $R$ be a ring. Let $(A, \text{d})$ and $(B, \text{d})$ be
differential graded $R$-algebras. Assume that $A = H^0(A)$.
The following are equivalent
\begin{enumerate}
\item $D(A, \text{d})$ and $D(B, \text{d})$ are equivalent as $R$-linear
triangulated categories, and
\item there exists an object $P$ of $D(B, \text{d})$ such that
\begin{enumerate}
\item $P$ is a compact object of $D(B, \text{d})$,
\item if $N \in D(B, \text{d})$ with $\Hom_{D(B, \text{d})}(P, N[i]) = 0$
for $i \in \mathbf{Z}$, then $N = 0$,
\item $\Hom_{D(B, \text{d})}(P, P[i]) = 0$ for $i \not = 0$ and
equal to $A$ for $i = 0$.
\end{enumerate}
\end{enumerate}
The equivalence $D(A, \text{d}) \to D(B, \text{d})$
constructed in (2) sends $A$ to $P$.

\label{lemma-Jacobson-universally-Jacobson}
Let $S$ be a scheme. Let $X$ be a Jacobson algebraic space over $S$.
Any algebraic space locally of finite type over $X$ is Jacobson.

\label{lemma-flat-descend-pure}
In Situation \ref{situation-pre-pure}.
Let $(Y_1, y_1) \to (Y, y)$ be a morphism of pointed algebraic spaces.
Assume $Y_1 \to Y$ is flat at $y_1$.
\begin{enumerate}
\item If $\mathcal{F}_{Y_1}$ is pure above $y_1$,
then $\mathcal{F}$ is pure above $y$.
\item If $\mathcal{F}_{Y_1}$ is universally pure above $y_1$,
then $\mathcal{F}$ is universally pure above $y$.
\end{enumerate}

\label{lemma-relative-pseudo-coherent-is-moot}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of
algebraic spaces over $S$. Let $E$ in $D_\QCoh(\mathcal{O}_X)$.
If $f$ is flat and locally of finite presentation, then
the following are equivalent
\begin{enumerate}
\item $E$ is pseudo-coherent relative to $Y$, and
\item $E$ is pseudo-coherent on $X$.
\end{enumerate}

\label{lemma-derived-restriction}
In the situation above, the right derived functor of $F$ exists.
We denote it $R\Hom(N, -) : D(B, \text{d}) \to D(A, \text{d})$.

\label{lemma-composition-regular-immersion}
Let $S$ be a scheme. Let $i : Z \to Y$ and $j : Y \to X$ be immersions of
algebraic spaces over $S$.
\begin{enumerate}
\item If $i$ and $j$ are Koszul-regular immersions, so is $j \circ i$.
\item If $i$ and $j$ are $H_1$-regular immersions, so is $j \circ i$.
\item If $i$ is an $H_1$-regular immersion and $j$ is a quasi-regular
immersion, then $j \circ i$ is a quasi-regular immersion.
\end{enumerate}

\label{lemma-cokernel-adequate}
\begin{slogan}
The cokernel of a map of adequate functors on the category of algebras
over a ring is adequate.
\end{slogan}
Let $A$ be a ring.
Let $\varphi : F \to G$ be a map of adequate functors on $\textit{Alg}_A$.
Then $\Coker(\varphi)$ is adequate.

\label{lemma-extend-quot-to-spaces}
In Situation \ref{situation-quot}. Let $T$ be an algebraic space over $S$.
We have
$$
\Mor_{\Sh((\Sch/S)_{fppf})}(T,  \Quotfunctor_{\mathcal{F}/X/B}) =
\left\{
\begin{matrix}
(h, \mathcal{F}_T \to \mathcal{Q}) \text{ where }
h : T \to B \text{ and}\\
\mathcal{Q}\text{ is of finite presentation and}\\
\text{flat over }T\text{ with support proper over }T
\end{matrix}
\right\}
$$
where $\mathcal{F}_T$ denotes the pullback of $\mathcal{F}$
to the algebraic space $X \times_{B, h} T$.

\label{lemma-bounded-in-image-downstairs}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C}) \to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$ be a morphism of ringed topoi.
Let $K$ be an object of $D(\mathcal{O}_\mathcal{D})$. Assume
\begin{enumerate}
\item $f$ is flat,
\item $K$ is bounded below,
\item $H^q(K) \to Rf_*f^*H^q(K)$ is an isomorphism.
\end{enumerate}
Then $K \to Rf_*f^*K$ is an isomorphism.

\label{lemma-cartesian-map-hilbert}
In the situation of
Lemma \ref{lemma-map-hilbert}
assume that the given square is $2$-cartesian. Then the diagram
$$
\xymatrix{
\mathcal{H}_d(\mathcal{X}'/\mathcal{Y}') \ar[r] \ar[d] &
\mathcal{H}_d(\mathcal{X}/\mathcal{Y}) \ar[d] \\
\mathcal{Y}' \ar[r] &
\mathcal{Y}
}
$$
is $2$-cartesian.

\label{lemma-degeneracy-maps-coverings}
Let $\mathcal{C}$ be a site with fibre products. Let $X$ be an object of
$\mathcal{C}$. Let $K$ be a hypercovering of $X$. Then
\begin{enumerate}
\item $K_n$ is a covering of $X$ for each $n \geq 0$,
\item $d^n_i : K_n \to K_{n - 1}$ is a covering for all $n \geq 1$
and $0 \leq i \leq n$.
\end{enumerate}

\label{lemma-composition-unramified}
The composition of two morphisms which are unramified is unramified.
The same holds for G-unramified morphisms.

\label{lemma-decent-locally-noetherian-sober}
Let $\mathcal{X}$ be a decent, locally Noetherian algebraic stack.
Then $|\mathcal{X}|$ is a sober locally Noetherian topological space.

\label{lemma-base-change-fibres-geometrically-irreducible}
Let $f : X \to Y$ be a morphism of schemes.
Let $g : Y' \to Y$ be any morphism, and denote
$f' : X' \to Y'$ the base change of $f$.
Then
\begin{align*}
\{y' \in Y' \mid X'_{y'}\text{ is geometrically irreducible}\} \\
= g^{-1}(\{y \in Y \mid X_y\text{ is geometrically irreducible}\}).
\end{align*}

\label{lemma-derived-limit-suitable-system}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $(K_n)$
be an inverse system of objects of $D(\mathcal{O})$.
Let $\mathcal{B} \subset \Ob(\mathcal{C})$ be a subset. Assume
\begin{enumerate}
\item every object of $\mathcal{C}$ has a covering whose members are
elements of $\mathcal{B}$,
\item for all $U \in \mathcal{B}$ and all $q \in \mathbf{Z}$ we have
\begin{enumerate}
\item $H^p(U, H^q(K_n)) = 0$ for $p > 0$,
\item the inverse system $H^0(U, H^q(K_n))$ has vanishing $R^1\lim$.
\end{enumerate}
\end{enumerate}
Then $H^q(R\lim K_n) = \lim H^q(K_n)$ for $q \in \mathbf{Z}$.

\label{lemma-exact}
Notation and assumptions as in Definition \ref{definition-cech-complex}.
The complex of abelian presheaves
\begin{align*}
\mathbf{Z}_\mathcal{U}^\bullet \quad : \quad
\bigoplus_{i_0 \in I} \mathbf{Z}_{U_{i_0}} \leftarrow
\bigoplus_{i_0, i_1 \in I} \mathbf{Z}_{U_{i_0} \times_U U_{i_1}} \leftarrow
\bigoplus_{i_0, i_1, i_2 \in I}
\mathbf{Z}_{U_{i_0} \times_U U_{i_1} \times_U U_{i_2}} \leftarrow
\ldots
\end{align*}
is exact in all degrees except $0$ in $\textit{PAb}(\mathcal{C})$.

\label{lemma-formally-unramified-differentials}
Let $f : X \to S$ be a morphism of schemes.
Then $f$ is formally unramified if and only if $\Omega_{X/S} = 0$.

\label{proposition-siblings-isomorphic}
\begin{reference}
\cite[Proposition 2.16]{Orlov-K3}; the fact that we do not need
to assume vanishing of $\Ext^q(N, X)$ for $q > 0$ in the definition
of negative objects above is due to \cite{Canonaco-Stellari}.
\end{reference}
Let $F$ and $F'$ be siblings as in Definition \ref{definition-siblings}.
Assume that $F$ is fully faithful and that $\mathcal{A}$ has enough
negative objects (see above). Then $F$ and $F'$ are isomorphic functors.

\label{lemma-good}
Let $R$ be a discrete valuation ring with fraction field $K$.
Let $C$ be a smooth projective curve over $K$ with $H^0(C, \mathcal{O}_C) = K$.
The following are equivalent
\begin{enumerate}
\item there exists a proper smooth model for $C$,
\item there exists a minimal model for $C$ which is smooth over $R$,
\item any minimal model is smooth over $R$.
\end{enumerate}

\label{lemma-delocalize-weak}
\begin{reference}
\cite[Lemma 12.2]{swan} or
\cite[Lemma 2]{popescu-GND}
\end{reference}
Let $R \to A \to \Lambda \supset \mathfrak q$ be as in
Situation \ref{situation-local}. Let $\mathfrak p = R \cap \mathfrak q$.
Assume that $\mathfrak q$ is minimal over $\mathfrak h_A$ and that
$R_\mathfrak p \to A_\mathfrak p \to \Lambda_\mathfrak q
\supset \mathfrak q\Lambda_\mathfrak q$ can be resolved.
Then there exists a factorization $A \to C \to \Lambda$ with $C$ of
finite presentation such that $H_{C/R} \Lambda \not \subset \mathfrak q$.

\label{lemma-characterize-regular}
Let $X$ be a scheme. The following are equivalent:
\begin{enumerate}
\item $X$ is regular,
\item $X$ is locally Noetherian and all of its local rings are regular,
and
\item $X$ is locally Noetherian and for any closed point $x \in X$
the local ring $\mathcal{O}_{X, x}$ is regular.
\end{enumerate}

\label{lemma-zero-dimensional-flat-ideal}
\begin{slogan}
Zero dimensional ring with flat ideal.
\end{slogan}
There exists a local ring $R$ with a unique prime ideal
and a nonzero ideal $I \subset R$ which is a flat $R$-module

\label{lemma-localize-on-top}
Let $A \to B \to C$ be ring maps such that $L_{C/B} = 0$.
Then $L_{C/A} = L_{B/A} \otimes_B^\mathbf{L} C$.

\label{proposition-positivity}
\begin{reference}
This is one of the main results of \cite{Serre_algebre_locale}.
\end{reference}
Let $X$ be a nonsingular variety. Let $V \subset X$ and
$W \subset Y$ be closed subvarieties which intersect properly.
Let $Z \subset V \cap W$ be an irreducible component.
Then $e(X, V \cdot W, Z) > 0$.

\label{lemma-differential-product}
Let $S$ be a scheme.
Let $f : X \to B$ and $g : Y \to B$ be morphisms of algebraic spaces
over $S$ with the same target.
Let $p : X \times_B Y \to X$ and $q : X \times_B Y \to Y$ be the
projection morphisms. The maps from
Lemma \ref{lemma-functoriality-differentials}
$$
p^*\Omega_{X/B} \oplus q^*\Omega_{Y/B}
\longrightarrow
\Omega_{X \times_B Y/B}
$$
give an isomorphism.

\label{lemma-formal-scheme-sheaf-fppf}
\begin{slogan}
Formal schemes are fpqc sheaves
\end{slogan}
Let $\mathfrak X$ be a formal scheme. The functor of points
$h_\mathfrak X$ (see Lemma \ref{lemma-fully-faithful})
satisfies the sheaf condition for fpqc coverings.

\label{lemma-affine-equivalence-algebras}
Let $S$ be a scheme. There is an anti-equivalence of categories
$$
\begin{matrix}
\text{Schemes affine} \\
\text{over }S
\end{matrix}
\longleftrightarrow
\begin{matrix}
\text{quasi-coherent sheaves} \\
\text{of }\mathcal{O}_S\text{-algebras}
\end{matrix}
$$
which associates to $f : X \to S$ the sheaf $f_*\mathcal{O}_X$.
Moreover, this equivalence is compatible with arbitrary base change.

\label{lemma-not-essentially-surjective}
The canonical map $\mathcal{X}(S) \to \lim \mathcal{X}(S_n)$
is not essentially surjective.

\label{lemma-structure-integral-stack}
Let $\mathcal{X}$ be an integral algebraic stack. Then
\begin{enumerate}
\item $|\mathcal{X}|$ is sober, irreducible, and has a unique generic point,
\item there exists an open substack $\mathcal{U} \subset \mathcal{X}$ 
which is a gerbe over an integral scheme $U$.
\end{enumerate}

\label{lemma-check-smoothness-on-infinitesimal-nbhds}
Let $f : X \to S$ be a finite type morphism of locally Noetherian schemes.
Let $Z \subset S$ be a closed subscheme with $n$th infinitesimal
neighbourhood $Z_n \subset S$. Set $X_n = Z_n \times_S X$.
\begin{enumerate}
\item If $X_n \to Z_n$ is smooth for all $n$, then $f$
is smooth at every point of $f^{-1}(Z)$.
\item If $X_n \to Z_n$ is \'etale for all $n$, then $f$
is \'etale at every point of $f^{-1}(Z)$.
\end{enumerate}

\label{lemma-gorenstein-curves}
There exist an open substack $\Curvesstack^{Gorenstein} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein}$,
\item the morphism $X \to S$ is Gorenstein,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein}$,
\item $X$ is Gorenstein.
\end{enumerate}
\end{enumerate}

\label{lemma-faithfully-flat-injective}
If $R \to S$ is a faithfully flat ring map then for every $R$-module
$M$ the map $M \to S \otimes_R M$, $x \mapsto 1 \otimes x$ is injective.

\label{lemma-rig-closed-point-after-localization}
Let $\varphi : A \to B$ be an arrow of $\textit{WAdm}^{Noeth}$
which is adic and topologically of finite type.
Let $\mathfrak q \subset B$ be rig-closed.
There exists an $f \in A$ which maps to a unit in
$B/\mathfrak q$ such that we obtain a diagram
$$
\vcenter{
\xymatrix{
B \ar[r] &
B_{\{f\}} \\
A \ar[r] \ar[u]_\varphi &
A_{\{f\}} \ar[u]_{\varphi_{\{f\}}}
}
}
\quad\text{with primes}\quad
\vcenter{
\xymatrix{
\mathfrak q \ar@{-}[r] \ar@{-}[d] &
\mathfrak q' \ar@{-}[d] \ar@{=}[r] &
\mathfrak q B_{\{f\}} \\
\mathfrak p \ar@{-}[r] &
\mathfrak p'
}
}
$$
such that $\mathfrak p'$ is rig-closed, i.e.,
the map $A_{\{f\}} \to B_{\{f\}}$ and the prime ideals
$\mathfrak q'$ and $\mathfrak p'$ satisfy
the equivalent conditions of Lemma \ref{lemma-rig-closed-point-relative}.

\label{lemma-base-change-universally-submersive}
The base change of a universally submersive morphism of schemes
by any morphism of schemes is universally submersive.

\label{lemma-intersection-number-in-terms-of-components}
In the situation of Definition \ref{definition-intersection-number}
let $Z_i \subset Z$ be the irreducible components of dimension $d$. Let
$m_i = \text{length}_{\mathcal{O}_{X, \overline{x}_i}}
(\mathcal{O}_{Z, \overline{x}_i})$
where $\overline{x}_i$ is a geometric generic point of $Z_i$. Then
$$
(\mathcal{L}_1 \cdots \mathcal{L}_d \cdot Z) =
\sum m_i(\mathcal{L}_1 \cdots \mathcal{L}_d \cdot Z_i)
$$

\label{lemma-cohomology-of-open}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $U$ be an object of $\mathcal{C}$.
\begin{enumerate}
\item If $\mathcal{I}$ is an injective $\mathcal{O}$-module
then $\mathcal{I}|_U$ is an injective $\mathcal{O}_U$-module.
\item For any sheaf of $\mathcal{O}$-modules $\mathcal{F}$ we have
$H^p(U, \mathcal{F}) = H^p(\mathcal{C}/U, \mathcal{F}|_U)$.
\end{enumerate}

\label{lemma-connected-along-section-open}
Let $f : X \to Y$, $s : Y \to X$ be as in
Situation \ref{situation-connected-along-section}.
Assume
\begin{enumerate}
\item $f$ is of finite presentation and flat, and
\item all fibres of $f$ are geometrically reduced.
\end{enumerate}
Then $X^0$ is open in $X$.

\label{lemma-flat-over-gorenstein-gorenstein-fibre}
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
If $A$ and $B/\mathfrak m_A B$ are Gorenstein, then $B$ is Gorenstein.

\label{lemma-hilb-is-quot}
In Situation \ref{situation-hilb} we have
$\Hilbfunctor_{X/B} = \Quotfunctor_{\mathcal{O}_X/X/B}$.

\label{lemma-finite-de-Rham}
Let $A$ be a Noetherian ring. Let $X$ be a proper scheme over $S = \Spec(A)$.
Then $H^i_{dR}(X/S)$ is a finite $A$-module for all $i$.

\label{lemma-flat-finite-presentation-perfect}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces over
$S$. The following are equivalent
\begin{enumerate}
\item $f$ is flat and perfect, and
\item $f$ is flat and locally of finite presentation.
\end{enumerate}

\label{lemma-geometrically-reduced-at-point}
Let $k$ be a field. Let $X$ be an algebraic space over $k$.
Let $x \in |X|$. The following are equivalent
\begin{enumerate}
\item $X$ is geometrically reduced at $x$,
\item for some \'etale neighbourhood $(U, u) \to (X, x)$
where $U$ is a scheme, $U$ is geometrically reduced at $u$,
\item for any \'etale neighbourhood $(U, u) \to (X, x)$
where $U$ is a scheme, $U$ is geometrically reduced at $u$.
\end{enumerate}

\label{lemma-done}
Assume given data (D0), (D1), and (D2') satisfying axioms (A1) -- (A8).
Then the cycle class map $\gamma$ commutes with pushforward.

\label{proposition-galois}
\begin{reference}
This is a weak version of \cite[Expos\'e V]{SGA1}.
The proof is borrowed from \cite[Theorem 7.2.5]{BS}.
\end{reference}
Let $(\mathcal{C}, F)$ be a Galois category. Let $G = \text{Aut}(F)$
be as in Example \ref{example-from-C-F-to-G-sets}. The functor
$F : \mathcal{C} \to \textit{Finite-}G\textit{-Sets}$
(\ref{equation-remember}) an equivalence.

\label{lemma-compose-pushforward}
Let $f : X \to Y$ and $g : Y \to Z$ be proper morphisms of
varieties. Then $g_* \circ f_* = (g \circ f)_*$ as maps $Z_k(X) \to Z_k(Z)$.

\label{lemma-blowup-nonsingular-curves-meeting-at-point}
In the situation above let $X' \to X$ be the blowing up of $X$ in $p$.
Let $Y', Z' \subset X'$ be the strict transforms of $Y, Z$.
If $\mathcal{O}_{Y, p}$ is regular, then
\begin{enumerate}
\item $Y' \to Y$ is an isomorphism,
\item $Y'$ meets the exceptional fibre $E \subset X'$ in one point
$q$ and $m_q(Y \cap E) = 1$,
\item if $q \in Z'$ too, then $m_q(Y \cap Z') < m_p(Y \cap Z)$.
\end{enumerate}

\label{lemma-geometrically-reduced-generic-fibre}
Let $f : X \to Y$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $Y$ is irreducible with generic point $\eta$,
\item $X_\eta$ is geometrically reduced, and
\item $f$ is of finite type.
\end{enumerate}
Then there exists a nonempty open subscheme $V \subset Y$
such that $X_V \to V$ has geometrically reduced fibres.

\label{lemma-dimension-function-scheme}
Let $X$ be a locally Noetherian scheme. Let $\omega_X^\bullet$
be a dualizing complex on $X$. Then $X$ is universally catenary
and the function
$X \to \mathbf{Z}$ defined by
$$
x \longmapsto \delta(x)\text{ such that }
\omega_{X, x}^\bullet[-\delta(x)]
\text{ is a normalized dualizing complex over }
\mathcal{O}_{X, x}
$$
is a dimension function.

\label{lemma-unique-point-better}
Let $S$ be a scheme. Let $Z$ be an algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item $Z$ is reduced, locally Noetherian, and $|Z|$
is a singleton, and
\item there exists a locally finitely presented, surjective, flat morphism
$\Spec(k) \to Z$ where $k$ is a field.
\end{enumerate}

\label{lemma-semistable}
Let $f : X \to S$ be a prestable family of curves of genus $g \geq 1$.
Let $s \in S$ be a point of the base scheme. Let $m \geq 2$.
The following are equivalent
\begin{enumerate}
\item $X_s$ does not have a rational tail
(Algebraic Curves, Example \ref{curves-example-rational-tail}), and
\item $f^*f_*\omega_{X/S}^{\otimes m} \to \omega_{X/S}^{\otimes m}$,
is surjective over $f^{-1}(U)$ for some $s \in U \subset S$ open.
\end{enumerate}

\label{lemma-dualizing-components}
In Semistable Reduction, Situation \ref{models-situation-regular-model}
the dualizing module of $C_i$ over $k$ is
$$
\omega_{C_i} = \omega_X(C_i)|_{C_i}
$$
where $\omega_X$ is as above.

\label{lemma-finite-flat-is-finite-locally-free}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item every finite flat quasi-coherent $\mathcal{O}_X$-module is
finite locally free, and
\item every closed subset $Z \subset X$ which is closed under generalizations
is open.
\end{enumerate}

\label{lemma-vanishing-universally-closed}
In Cohomology of Spaces, Situation \ref{spaces-cohomology-situation-vanishing}
the morphism $p : X \to \Spec(A)$ is universally closed.

\label{lemma-locally-quasi-finite-A}
Let $f : X \to Y$ be a separated locally quasi-finite morphism of schemes.
Then property (A) above holds.

\label{lemma-restrict-and-shriek-from-etale-c}
Let $\Lambda$ be a Noetherian ring.
If $j : U \to X$ is an \'etale morphism of schemes, then
\begin{enumerate}
\item $K|_U \in D_c(U_\etale, \Lambda)$ if $K \in D_c(X_\etale, \Lambda)$, and
\item $j_!M \in D_c(X_\etale, \Lambda)$ if $M \in D_c(U_\etale, \Lambda)$ and
the morphism $j$ is quasi-compact and quasi-separated.
\end{enumerate}

\label{lemma-self-centralizing-subfield}
Let $A$ be a finite central simple algebra over $k$.
If $K \subset A$ is a subfield, then the following are equivalent
\begin{enumerate}
\item $[A : k] = [K : k]^2$,
\item $K$ is its own centralizer, and
\item $K$ is a maximal commutative subring.
\end{enumerate}

\label{lemma-brauer-inverse}
Let $A$ be a finite central simple algebra over $K$. Then
$$
\begin{matrix}
A \otimes_K A^{opp} & \longrightarrow & \text{End}_K(A) \\
\ a \otimes a' & \longmapsto & (x \mapsto a x a')
\end{matrix}
$$
is an isomorphism of algebras over $K$.

\label{lemma-UR-quasi-compact-above-x}
Let $\mathcal{X}$ be an algebraic stack. Let $x \in |\mathcal{X}|$
be a point. The following are equivalent
\begin{enumerate}
\item some morphism $\Spec(k) \to \mathcal{X}$ in the equivalence
class of $x$ is quasi-compact, and
\item any morphism $\Spec(k) \to \mathcal{X}$ in the equivalence
class of $x$ is quasi-compact.
\end{enumerate}

\label{lemma-zariski-etale-smooth-syntomic}
Any smooth covering is a syntomic covering, and a fortiori,
any \'etale or Zariski covering is a syntomic covering.

\label{lemma-w-local-strictly-henselian-extremally-disconnected}
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item $A$ is w-contractible,
\item every faithfully flat, ind-\'etale ring map $A \to B$ has
a retraction, and
\item $A$ satisfies
\begin{enumerate}
\item $\Spec(A)$ is w-local,
\item $\pi_0(\Spec(A))$ is extremally disconnected, and
\item for every maximal ideal $\mathfrak m \subset A$ the
local ring $A_\mathfrak m$ is strictly henselian.
\end{enumerate}
\end{enumerate}

\label{proposition-cotangent-complex-local-complete-intersection}
Let $A \to B$ be a local complete intersection map.
Then $L_{B/A}$ is a perfect complex with tor amplitude in $[-1, 0]$.

\label{lemma-set-iso-classes-bounded-size}
Let $\mathcal{A}$ be a Grothendieck abelian category with generator $U$.
\begin{enumerate}
\item If $|M| \leq \kappa$, then $M$ is the quotient of a direct
sum of at most $\kappa$ copies of $U$.
\item For every cardinal $\kappa$ the isomorphism classes
of objects $M$ with $|M| \leq \kappa$ form a set.
\end{enumerate}

\label{lemma-tensor-coherent}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item If $\mathcal{F}$ and $\mathcal{G}$ are coherent $\mathcal{O}_X$-modules,
then $\text{Tor}_p^{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})$ is too.
\item If $L$ and $K$ are in $D^-_{\textit{Coh}}(\mathcal{O}_X)$, then
so is $L \otimes_{\mathcal{O}_X}^\mathbf{L} K$.
\end{enumerate}

\label{lemma-ses}
\begin{reference}
\cite[Theorem 8.1]{Ma}
\end{reference}
Let $R$ be a topological ring. Let $M$ be a linearly topologized
$R$-module. Let $N \subset M$ be a submodule. Assume $M$ has a
countable fundamental system of neighbourhoods of $0$. Then
\begin{enumerate}
\item $0 \to N^\wedge \to M^\wedge \to (M/N)^\wedge \to 0$ is exact,
\item $N^\wedge$ is the closure of the image of $N \to M^\wedge$,
\item $M^\wedge \to (M/N)^\wedge$ is open.
\end{enumerate}

\label{lemma-set-theoretic-pre-equivalence-geometric}
In the situation of Definition \ref{definition-set-theoretic-equivalence}.
The following are equivalent:
\begin{enumerate}
\item The morphism $j$ is a set-theoretic pre-equivalence relation.
\item The subset $j(|R|) \subset |U \times_B U|$ contains the image of
$|j'|$ for any of the morphisms $j'$ as in Equation (\ref{equation-list}).
\item For every algebraically closed field $k$ over $B$ of sufficiently large
cardinality the subset $j(R(k)) \subset U(k) \times U(k)$ is an equivalence
relation.
\end{enumerate}
If $s, t$ are locally of finite type these are also equivalent to
\begin{enumerate}
\item[(4)] For every algebraically closed field $k$ over $B$
the subset $j(R(k)) \subset U(k) \times U(k)$ is an equivalence relation.
\end{enumerate}

\label{lemma-flat-bc-surjection}
Let $R \to A$ and $R \to R'$ be ring maps and $A' = A \otimes_R R'$.
Assume
\begin{enumerate}
\item $A$ is pseudo-coherent as an $R$-module,
\item $R'$ has finite tor dimension as an $R$-module (for example
$R \to R'$ is flat),
\item $A$ and $R'$ are tor independent over $R$.
\end{enumerate}
Then (\ref{equation-base-change}) is an isomorphism for $K \in D^+(R)$.

\label{theorem-bondal-van-den-Bergh}
Let $X$ be a quasi-compact and quasi-separated scheme. The category
$D_\QCoh(\mathcal{O}_X)$ can be generated by a single
perfect object. More precisely, there exists a perfect object
$P$ of $D(\mathcal{O}_X)$ such that for 
$E \in D_\QCoh(\mathcal{O}_X)$ the following are equivalent
\begin{enumerate}
\item $E = 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[n], E) = 0$ for all $n \in \mathbf{Z}$.
\end{enumerate}

\label{lemma-base-change-etale}
The base change of an \'etale morphism of algebraic spaces
by any morphism of algebraic spaces is \'etale.

\label{lemma-projective-cover-unique}
Let $R$ be a ring and let $M$ be an $R$-module. If a projective cover
of $M$ exists, then it is unique up to isomorphism.

\label{lemma-bounded-below-truncation}
Let $X$ be a quasi-compact and quasi-separated scheme. Let
$P \in D_{perf}(\mathcal{O}_X)$ and $E \in D_{\QCoh}(\mathcal{O}_X)$.
Let $a \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], E) = 0$ for $i \ll 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], \tau_{\leq a} E) = 0$ for $i \ll 0$.
\end{enumerate}

\label{lemma-etale-covering-hom-functor}
Let $S$ be a scheme. Let $Z \to B$ and $X' \to X \to B$ be morphisms of
algebraic spaces over $S$. Assume
\begin{enumerate}
\item $X' \to X$ is \'etale, and
\item $Z \to B$ is finite locally free.
\end{enumerate}
Then $\mathit{Mor}_B(Z, X') \to \mathit{Mor}_B(Z, X)$ is representable
by algebraic spaces and \'etale. If $X' \to X$ is also surjective,
then $\mathit{Mor}_B(Z, X') \to \mathit{Mor}_B(Z, X)$ is surjective.

\label{lemma-monomorphism-cartesian-square-inertia}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a monomorphism of algebraic stacks.
Then the diagram
$$
\xymatrix{
\mathcal{I}_\mathcal{X} \ar[r] \ar[d] &
\mathcal{X} \ar[d] \\
\mathcal{I}_\mathcal{Y} \ar[r] &
\mathcal{Y}
}
$$
is a fibre product square.

\label{lemma-closure}
Let $R$ be a topological ring. Let $M$ be a linearly topologized
$R$-module. Let $N \subset M$ be a submodule. Then
\begin{enumerate}
\item $0 \to N^\wedge \to M^\wedge \to (M/N)^\wedge$ is exact, and
\item $N^\wedge$ is the closure of the image of $N \to M^\wedge$.
\end{enumerate}

\label{lemma-flat-base-change-NL}
Consider a cartesian diagram of schemes
$$
\xymatrix{
X' \ar[d] \ar[r]_{g'} & X \ar[d] \\
Y' \ar[r] & Y
}
$$
If $Y' \to Y$ is flat, then the canonical map
$(g')^*\NL_{X/Y} \to \NL_{X'/Y'}$ is a quasi-isomorphism.

\label{lemma-noether-different-product}
Let $A \to B_i$, $i = 1, 2$ be ring maps. Set $B = B_1 \times B_2$.
\begin{enumerate}
\item The annihilator $J$ of $\Ker(B \otimes_A B \to B)$ is $J_1 \times J_2$
where $J_i$ is the annihilator of $\Ker(B_i \otimes_A B_i \to B_i)$.
\item The Noether different $\mathfrak{D}$ of $B$ over $A$ is
$\mathfrak{D}_1 \times \mathfrak{D}_2$, where $\mathfrak{D}_i$ is
the Noether different of $B_i$ over $A$.
\end{enumerate}

\label{lemma-closed-subspace-w-local}
Let $X$ be a w-local spectral space. If $Y \subset X$ is closed,
then $Y$ is w-local.

\label{lemma-composition-thickening}
\begin{slogan}
Compositions of thickenings are thickenings
\end{slogan}
If $S \subset S'$ and $S' \subset S''$ are thickenings, then so is
$S \subset S''$.

\label{lemma-modifications}
Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
Let $x \in |X|$ be a closed point such that $U = X \setminus \{x\} \to X$
is quasi-compact. With
$V = \Spec(\mathcal{O}_{X, x}^h) \setminus \{\mathfrak m_x^h\}$
the base change functor
$$
\left\{
\begin{matrix}
f : Y \to X\text{ of finite presentation} \\
f^{-1}(U) \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
g : Y \to \Spec(\mathcal{O}_{X, x}^h)\text{ of finite presentation} \\
g^{-1}(V) \to V\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

\label{lemma-lci-gorenstein}
A syntomic morphism is Gorenstein. Equivalently a flat
local complete intersection morphism is Gorenstein.

\label{lemma-vanishing-cohomology-mu-smooth-curve}
Let $X$ be an affine smooth curve over an algebraically closed field $k$ and
$n \in k^*$. Let $X \subset \overline{X}$ be a smooth projective
compactification
(Varieties, Remark \ref{varieties-remark-smooth-projective-compactification}).
Let $g$ be the genus of $\overline{X}$ and let $r$ be the number of
points of $\overline{X} \setminus X$. Then
\begin{enumerate}
\item $H_\etale^0(X, \mu_n) = \mu_n(k)$;
\item $H_\etale^1(X, \mu_n) \cong (\mathbf{Z}/n\mathbf{Z})^{2g+r-1}$, and
\item $H_\etale^q(X, \mu_n) = 0$ for all $q \geq 2$.
\end{enumerate}

\label{lemma-complex-tensored-still-exact}
\begin{slogan}
The integral presheaf {\v C}ech complex is a flat resolution of the
constant presheaf of integers.
\end{slogan}
Let $\mathcal{C}$ be a category. Let
$\mathcal{U} = \{f_i : U_i \to U\}_{i \in I}$ be a family of morphisms
with fixed target such that all fibre products
$U_{i_0} \times_U \ldots \times_U U_{i_p}$ exist in $\mathcal{C}$.
Let $\mathcal{O}$ be a presheaf of rings on $\mathcal{C}$.
The chain complex
$$
\mathbf{Z}_{\mathcal{U}, \bullet}
\otimes_{p, \mathbf{Z}}
\mathcal{O}
$$
is exact in positive degrees. Here $\mathbf{Z}_{\mathcal{U}, \bullet}$
is the chain complex of Lemma \ref{lemma-cech-map-into}, and
the tensor product is over the constant presheaf of rings
with value $\mathbf{Z}$.

\label{lemma-finite-presentation-finite-type}
A morphism which is locally of finite presentation is locally of finite type.
A morphism of finite presentation is of finite type.

\label{lemma-base-change-almost-blow-up}
Consider an almost blow up square (\ref{equation-almost-blow-up-square}).
Let $Y \to X$ be any morphism. Then the base change
$$
\xymatrix{
Y \times_X E \ar[d] \ar[r] & Y \times_X X' \ar[d] \\
Y \times_X Z \ar[r] & Y
}
$$
is an almost blow up square too.

\label{lemma-descent-sheaf-fppf-etale}
In Lemma \ref{lemma-push-pull-fppf-etale} assume
$f$ is flat, locally of finite presentation, and surjective.
Then the functor
$$
\Sh(Y_\etale) \longrightarrow
\left\{
(\mathcal{G}, \mathcal{H}, \alpha)
\middle|
\begin{matrix}
\mathcal{G} \in \Sh(X_\etale),\ \mathcal{H} \in \Sh((\Sch/Y)_{fppf}), \\
\alpha : a_X^{-1}\mathcal{G} \to f_{big, fppf}^{-1}\mathcal{H}
\text{ an isomorphism}
\end{matrix}
\right\}
$$
sending $\mathcal{F}$ to
$(f_{small}^{-1}\mathcal{F}, a_Y^{-1}\mathcal{F}, can)$ is an equivalence.

\label{lemma-descent-ascent}
Let $f : X \to Y$ be a morphism of locally Noetherian schemes. Assume
\begin{enumerate}
\item $f$ is syntomic and surjective, or
\item $f$ is a surjective flat local complete intersection morphism, or
\item $f$ is a surjective Gorenstein morphism of finite type.
\end{enumerate}
Then $K \in D_\QCoh(\mathcal{O}_Y)$ is a dualizing complex on $Y$ if and only
if $Lf^*K$ is a dualizing complex on $X$.

\label{lemma-base-change-flat}
Let $S$ be a scheme. Let $f : X \to Y$ and $g : Z \to Y$
be morphisms of locally Noetherian formal algebraic spaces over $S$.
\begin{enumerate}
\item If $f$ is flat and $g_{red} : Z_{red} \to Y_{red}$ is
locally of finite type, then the base change
$X \times_Y Z \to Z$ is flat.
\item If $f$ is flat and locally of finite type, then
the base change $X \times_Y Z \to Z$ is flat and locally of finite type.
\end{enumerate}

\label{lemma-scheme-theoretic-image-is-proper}
Let $S$ be a scheme. Let
$$
\xymatrix{
X \ar[rr]_h \ar[rd]_f & & Y \ar[ld]^g \\
& B
}
$$
be a commutative diagram of morphism of algebraic spaces over $S$.
Assume
\begin{enumerate}
\item $X \to B$ is a proper morphism,
\item $Y \to B$ is separated and locally of finite type,
\end{enumerate}
Then the scheme theoretic image $Z \subset Y$ of $h$
is proper over $B$ and $X \to Z$ is surjective.

\label{lemma-family-associated-closed-specialization}
In the situation of Example \ref{example-family-associated-closed}
assume $S$ is locally Noetherian and $Z$ is flat over $S$ in dimensions
$\geq r$. Then $[Z/X/S]_r$ is a relative $r$-cycle on $X/S$.

\label{lemma-vanishing-base-change}
In Situation \ref{situation-vanishing}.
\begin{enumerate}
\item Given an affine morphism $X' \to X$ of algebraic spaces, we have
$H^1(X', \mathcal{F}') = 0$ for every quasi-coherent
$\mathcal{O}_{X'}$-module $\mathcal{F}'$.
\item Given an $A$-algebra $A'$ setting $X' = X \times_{\Spec(A)} \Spec(A')$
the morphism $X' \to X$ is affine and $\Gamma(X', \mathcal{O}_{X'}) = A'$.
\end{enumerate}

\label{lemma-van-den-bergh}
Let $Y$ be a quasi-compact and quasi-separated scheme.
Let $f : X \to Y$ be a proper, flat morphism of finite presentation
with relative dualizing complex $\omega_{X/Y}^\bullet$
(Remark \ref{remark-relative-dualizing-complex}).
There is a canonical isomorphism
\begin{equation}
\label{equation-pre-rigid}
\mathcal{O}_X =
c(L\text{pr}_1^*\omega_{X/Y}^\bullet) =
c(L\text{pr}_2^*\omega_{X/Y}^\bullet)
\end{equation}
and a canonical isomorphism
\begin{equation}
\label{equation-rigid}
\omega_{X/Y}^\bullet =
c\left(L\text{pr}_1^*\omega_{X/Y}^\bullet
\otimes_{\mathcal{O}_{X \times_Y X}}^\mathbf{L}
L\text{pr}_2^*\omega_{X/Y}^\bullet\right)
\end{equation}
where $c$ is the right adjoint of
Lemma \ref{lemma-twisted-inverse-image}
for the diagonal $\Delta : X \to X \times_Y X$.

\label{lemma-branches}
In the situation of Definition \ref{definition-formal-branches}
there is a canonical surjection from the set of formal branches of
$\mathcal{X}$ through $x_0$ to the set of irreducible components of
$|\mathcal{X}|$ containing $x_0$ in $|\mathcal{X}|$.

\label{lemma-colimits-flat}
Colimits and tensor product.
\begin{enumerate}
\item A filtered colimit of flat presheaves of modules
is flat. A direct sum of flat presheaves of modules is flat.
\item A filtered colimit of flat sheaves of modules is flat.
A direct sum of flat sheaves of modules is flat.
\end{enumerate}

\label{lemma-check-finiteness-local-cohomology-by-annihilator-complex}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. Let $K$ be an object of $D_{\textit{Coh}}^+(A)$.
Let $n \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $H^i_T(K)$ is finite for $i \leq n$,
\item there exists an ideal $J \subset A$ with $V(J) \subset T$
such that $J$ annihilates $H^i_T(K)$ for $i \leq n$.
\end{enumerate}
If $T = V(I) = Z$ for an ideal $I \subset A$, then these are also
equivalent to
\begin{enumerate}
\item[(3)] there exists an $e \geq 0$ such that $I^e$ annihilates
$H^i_Z(K)$ for $i \leq n$.
\end{enumerate}

\label{lemma-descending-property-universal-homeomorphism}
The property $\mathcal{P}(f) =$``$f$ is a universal homeomorphism''
is fpqc local on the base.

\label{proposition-approximate}
\begin{reference}
Our proof follows closely the proof given in \cite[Theorem 1.2.2]{CLO}.
\end{reference}
Let $X$ be a quasi-compact and quasi-separated algebraic space over
$\Spec(\mathbf{Z})$. There exist a directed set $I$
and an inverse system of algebraic spaces $(X_i, f_{ii'})$ over $I$
such that
\begin{enumerate}
\item the transition morphisms $f_{ii'}$ are affine
\item each $X_i$ is quasi-separated and of finite type over
$\mathbf{Z}$, and
\item $X = \lim X_i$.
\end{enumerate}

\label{lemma-base-change-fibres-geometrically-connected}
Let $f : X \to Y$ be a morphism of schemes.
Let $g : Y' \to Y$ be any morphism, and denote
$f' : X' \to Y'$ the base change of $f$.
Then
\begin{align*}
\{y' \in Y' \mid X'_{y'}\text{ is geometrically connected}\} \\
= g^{-1}(\{y \in Y \mid X_y\text{ is geometrically connected}\}).
\end{align*}

\label{proposition-smooth-covering-compute-direct-image}
Let $f : \mathcal{U} \to \mathcal{X}$ and $g : \mathcal{X} \to \mathcal{Y}$
be composable $1$-morphisms of algebraic stacks.
\begin{enumerate}
\item Assume that $f$ is representable by algebraic spaces, surjective and
smooth.
\begin{enumerate}
\item If $\mathcal{F}$ is in $\textit{Ab}(\mathcal{X}_\etale)$
then there is a spectral sequence
$$
E_1^{p, q} = R^q(g \circ f_p)_*f_p^{-1}\mathcal{F}
\Rightarrow
R^{p + q}g_*\mathcal{F}
$$
in $\textit{Ab}(\mathcal{Y}_\etale)$ with higher direct images
computed in the \'etale topology.
\item If $\mathcal{F}$ is in
$\textit{Mod}(\mathcal{X}_\etale, \mathcal{O}_\mathcal{X})$ then
there is a spectral sequence
$$
E_1^{p, q} = R^q(g \circ f_p)_*f_p^{-1}\mathcal{F}
\Rightarrow
R^{p + q}g_*\mathcal{F}
$$
in $\textit{Mod}(\mathcal{Y}_\etale, \mathcal{O}_\mathcal{Y})$.
\end{enumerate}
\item Assume that $f$ is representable by algebraic spaces, surjective,
flat, and locally of finite presentation.
\begin{enumerate}
\item If $\mathcal{F}$ is in $\textit{Ab}(\mathcal{X})$ then there is
a spectral sequence
$$
E_1^{p, q} = R^q(g \circ f_p)_*f_p^{-1}\mathcal{F}
\Rightarrow
R^{p + q}g_*\mathcal{F}
$$
in $\textit{Ab}(\mathcal{Y})$ with higher direct images
computed in the fppf topology.
\item If $\mathcal{F}$ is in $\textit{Mod}(\mathcal{O}_\mathcal{X})$ then
there is a spectral sequence
$$
E_1^{p, q} = R^q(g \circ f_p)_*f_p^{-1}\mathcal{F}
\Rightarrow
R^{p + q}g_*\mathcal{F}
$$
in $\textit{Mod}(\mathcal{O}_\mathcal{Y})$.
\end{enumerate}
\end{enumerate}

\label{lemma-higher-direct-images-zero-above-dimension-fibre}
\begin{slogan}
For proper maps, stalks of higher direct images are trivial in degrees
larger than the dimension of the fibre.
\end{slogan}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
Let $\overline{y}$ be a geometric point of $Y$.
Assume
\begin{enumerate}
\item $Y$ locally Noetherian,
\item $f$ is proper, and
\item $\dim(X_{\overline{y}}) = d$.
\end{enumerate}
Then for any coherent sheaf $\mathcal{F}$ on $X$ we have
$(R^pf_*\mathcal{F})_{\overline{y}} = 0$ for all $p > d$.

\label{lemma-groupoid-on-field-open-multiplication}
In
Situation \ref{situation-groupoid-on-field}
the composition morphism $c : R \times_{s, U, t} R \to R$ is flat and
universally open.
In
Situation \ref{situation-group-over-field}
the group law $m : G \times_k G \to G$ is flat and
universally open.

\label{lemma-functoriality-galois-normal}
In diagram (\ref{equation-translation}) the following are equivalent
\begin{enumerate}
\item the image of $h'$ is normal, and
\item for every connected object $X'$ of $\mathcal{C}'$ such that
there is a morphism from the final object of $\mathcal{C}''$
to $H'(X')$ we have that $H'(X')$ is isomorphic to a finite coproduct
of final objects.
\end{enumerate}

\label{lemma-finite-type-Noetherian-quasi-separated}
Let $f : X \to S$ be locally of finite type with $S$ locally Noetherian.
Then $f$ is quasi-separated.

\label{lemma-chern-classes-E-tensor-L}
In Situation \ref{situation-setup} let $X/B$ be good.
Let $\mathcal{E}$ be a finite locally free sheaf of
rank $r$ on $X$. Let $\mathcal{L}$ be an invertible
sheaf on $X$. Then we have
\begin{equation}
\label{equation-twist}
c_i({\mathcal E} \otimes {\mathcal L})
=
\sum\nolimits_{j = 0}^i
\binom{r - i + j}{j} c_{i - j}({\mathcal E}) c_1({\mathcal L})^j
\end{equation}
in $A^*(X)$.

\label{lemma-surjective-proper-ph}
Let $f : Y \to X$ be a surjective proper morphism of schemes.
Then $\{Y \to X\}$ is a ph covering.

\label{lemma-formal-smoothness-representable}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
which is representable by algebraic spaces. Then the following are equivalent
\begin{enumerate}
\item $f$ is formally smooth,
\item for every scheme $T$ and morphism $T \to \mathcal{Y}$
the morphism $\mathcal{X} \times_\mathcal{Y} T \to T$
is formally smooth as a morphism of algebraic spaces.
\end{enumerate}

\label{lemma-pre-genus-in-CM-1}
We have $\Curvesstack^{h0, 1} \subset \Curvesstack^{CM, 1}$
as open substacks of $\Curvesstack$.

\label{lemma-parse-equation-strictly-standard-one}
Let $R$ be a ring. Let $A = R[x_1, \ldots, x_n]/(f_1, \ldots, f_m)$
and write $I = (f_1, \ldots, f_m)$. Let $a \in A$. Then
(\ref{equation-strictly-standard-one}) implies
there exists an $A$-linear map
$\psi : \bigoplus\nolimits_{i = 1, \ldots, n} A \text{d}x_i \to A^{\oplus c}$
such that the composition
$$
A^{\oplus c} \xrightarrow{(f_1, \ldots, f_c)}
I/I^2 \xrightarrow{f \mapsto \text{d}f}
\bigoplus\nolimits_{i = 1, \ldots, n} A \text{d}x_i
\xrightarrow{\psi}
A^{\oplus c}
$$
is multiplication by $a$. Conversely, if such a $\psi$ exists, then
$a^c$ satisfies (\ref{equation-strictly-standard-one}).

\label{lemma-lift-purity-general}
In Situation \ref{situation-local-lefschetz}.
Let $V$ be finite \'etale over $U$. Assume
\begin{enumerate}
\item $H^1_\mathfrak m(A)$ and $H^2_\mathfrak m(A)$
are annihilated by a power of $f$,
\item $V_0 = V \times_U U_0$ is equal to $Y_0 \times_{X_0} U_0$
for some $Y_0 \to X_0$ finite \'etale.
\end{enumerate}
Then $V = Y \times_X U$ for some $Y \to X$ finite \'etale.

\label{lemma-sum-injective-modules}
Let $R$ be a Noetherian ring. A direct sum of injective modules
is injective.

\label{lemma-ubiquity-uc}
The following types of schemes are universally catenary.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Cohen-Macaulay scheme.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a $1$-dimensional
Noetherian domain.
\item And so on.
\end{enumerate}

\label{lemma-RF-commutes-with-Rlim}
Let $F : \mathcal{A} \to \mathcal{B}$ be an additive functor of
abelian categories. Assume
\begin{enumerate}
\item $\mathcal{A}$ is a Grothendieck abelian category,
\item $\mathcal{B}$ has exact countable products, and
\item $F$ commutes with countable products.
\end{enumerate}
Then
$RF : D(\mathcal{A}) \to D(\mathcal{B})$ commutes with derived limits.

\label{lemma-openness-versality}
In Situation \ref{situation-contractions} the functor
$F$ satisfies openness of versality.

\label{lemma-pushforward-quasi-coherent}
Schemes, Lemma \ref{schemes-lemma-push-forward-quasi-coherent}
is sharp in the sense that one can neither drop the assumption
of quasi-compactness nor the assumption of quasi-separatedness.

\label{lemma-finite-flat-trace}
Let $A \to B$ be a finite flat map of Noetherian rings.
Then $\text{Trace}_{B/A} \in \omega_{B/A}$ is the trace element.

\label{lemma-proper-push-pull-fppf-etale}
In Lemma \ref{lemma-push-pull-fppf-etale} if $f$ is proper, then we have
\begin{enumerate}
\item $a_Y^{-1} \circ f_{small, *} = f_{big, fppf, *} \circ a_X^{-1}$, and
\item
$a_Y^{-1}(Rf_{small, *}K) = Rf_{big, fppf, *}(a_X^{-1}K)$
for $K$ in $D^+(X_\etale)$ with torsion cohomology sheaves.
\end{enumerate}

\label{proposition-get-weil}
Assume given data (D0), (D1), and (D2') satisfying axioms (A1) -- (A8).
Then we have a Weil cohomology theory.

\label{lemma-base-change-cech-complex}
Let
$$
\xymatrix{
\mathcal{V} \ar[d]_g \ar[r]_h & \mathcal{U} \ar[d]^f \\
\mathcal{Y} \ar[r]^e & \mathcal{X}
}
$$
be a $2$-fibre product of categories fibred in groupoids over
$(\Sch/S)_{fppf}$ and let $\mathcal{F}$ be an abelian presheaf
on $\mathcal{X}$. Then the map
$e^{-1}\mathcal{K}^\bullet(f, \mathcal{F}) \to
\mathcal{K}^\bullet(g, e^{-1}\mathcal{F})$
of
Lemma \ref{lemma-generalities-sheafified}
is an isomorphism of complexes of abelian presheaves.

\label{lemma-quasi-separated-very-reasonable}
An algebraic space which is Zariski locally quasi-separated is very reasonable.
In particular any quasi-separated algebraic space is very reasonable.

\label{lemma-quasi-compact-dense-open-separated}
Let $X$ be a quasi-compact scheme.
There exists a dense open $V \subset X$ which is separated.

\label{lemma-quasi-compact-quasi-separated-spectral}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$. The topological space $|X|$ is a spectral space.

\label{lemma-flat-finite-type-finitely-presented-over-dense-open}
\begin{slogan}
$S$-flat and finite type extensions of finitely presented modules
on a (good) open are also $X$-finitely presented.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes. Let $\mathcal{F}$ be a
quasi-coherent $\mathcal{O}_X$-module. Let $U \subset S$ be open.
Assume
\begin{enumerate}
\item $f$ is locally of finite presentation,
\item $\mathcal{F}$ is of finite type and flat over $S$,
\item $U \subset S$ is retrocompact and scheme theoretically dense,
\item $\mathcal{F}|_{f^{-1}U}$ is of finite presentation.
\end{enumerate}
Then $\mathcal{F}$ is of finite presentation.

\label{lemma-locally-closed-in-noetherian}
Let $j : \mathcal{X} \to \mathcal{Y}$ be an immersion of algebraic stacks.
\begin{enumerate}
\item If $\mathcal{Y}$ is locally Noetherian, then
$\mathcal{X}$ is locally Noetherian and $j$ is quasi-compact.
\item If $\mathcal{Y}$ is Noetherian, then $\mathcal{X}$ is Noetherian.
\end{enumerate}

\label{lemma-syntomic-syntomic-local-source}
The property $\mathcal{P}(f)=$``$f$ is syntomic''
is syntomic local on the source.

\label{lemma-resolution-property-ample-relative}
Let $f : X \to Y$ be a morphism of schemes. Assume
\begin{enumerate}
\item $Y$ is quasi-compact and quasi-separated and has the resolution property,
\item there exists an $f$-ample invertible module on $X$.
\end{enumerate}
Then $X$ has the resolution property.

\label{lemma-sheaf-with-exact-support-quasi-coherent}
Let $i : Z \to X$ be a pseudo-coherent closed immersion of schemes
(any closed immersion if $X$ is locally Noetherian).
Then
\begin{enumerate}
\item $R\SheafHom(\mathcal{O}_Z, -)$ maps $D^+_\QCoh(\mathcal{O}_X)$
into $D^+_\QCoh(\mathcal{O}_Z)$, and
\item if $X = \Spec(A)$ and $Z = \Spec(B)$, then the diagram
$$
\xymatrix{
D^+(B) \ar[r] & D_\QCoh^+(\mathcal{O}_Z) \\
D^+(A) \ar[r] \ar[u]^{R\Hom(B, -)} &
D_\QCoh^+(\mathcal{O}_X) \ar[u]_{R\SheafHom(\mathcal{O}_Z, -)}
}
$$
is commutative.
\end{enumerate}

\label{lemma-affine-jacobson}
An affine scheme $\Spec(R)$ is Jacobson if and only if
the ring $R$ is Jacobson.

\label{lemma-numerical-type-minimal-model}
In Situation \ref{situation-regular-model}. The following
are equivalent
\begin{enumerate}
\item $X$ is a minimal model, and
\item the numerical type associated to $X$ is minimal.
\end{enumerate}

\label{lemma-flat}
Let $B \to C$ be a ring map. If
\begin{enumerate}
\item the coprojections $C \to C \otimes_B C$ are flat and
\item $B \to C$ is universally injective,
\end{enumerate}
then $B \to C$ is faithfully flat.

\label{lemma-good-diagram}
In Situation \ref{situation-limit-noetherian}.
Let $X \to B$ be a quasi-separated and finite type
morphism of algebraic spaces.
Then there exists an $i \in I$ and a diagram
\begin{equation}
\label{equation-good-diagram}
\vcenter{
\xymatrix{
X \ar[r] \ar[d] & W \ar[d] \\
B \ar[r] & B_i
}
}
\end{equation}
such that $W \to B_i$ is of finite type and such that
the induced morphism $X \to B \times_{B_i} W$ is a closed
immersion.

\label{lemma-etale-permanence}
Let $S$ be a scheme. Let $X, Y$ be algebraic spaces \'etale over
an algebraic space $Z$. Any morphism $X \to Y$ over $Z$ is \'etale.

\label{lemma-deform-property-fp-over-ft}
Let $S$ be a scheme. Consider a commutative diagram
$$
\xymatrix{
(X \subset X') \ar[rr]_{(f, f')} \ar[rd] & & (Y \subset Y') \ar[ld] \\
& (B \subset B')
}
$$
of thickenings of algebraic spaces over $S$.
Assume $Y' \to B'$ locally of finite type,
$X' \to B'$ flat and locally of finite presentation,
$X = B \times_{B'} X'$, and $Y = B \times_{B'} Y'$. Then
\begin{enumerate}
\item $f$ is representable if and only if $f'$ is representable,
\label{item-representable-fp-over-ft}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat-fp-over-ft}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism-fp-over-ft}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion-fp-over-ft}
\item $f$ is quasi-compact if and only if $f'$ is quasi-compact,
\label{item-quasi-compact-fp-over-ft}
\item $f$ is universally closed if and only if $f'$ is universally closed,
\label{item-universally-closed-fp-over-ft}
\item $f$ is (quasi-)separated if and only if $f'$ is (quasi-)separated,
\label{item-separated-fp-over-ft}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism-fp-over-ft}
\item $f$ is surjective if and only if $f'$ is surjective,
\label{item-surjective-fp-over-ft}
\item $f$ is universally injective if and only if $f'$ is universally injective,
\label{item-universally-injective-fp-over-ft}
\item $f$ is affine if and only if $f'$ is affine,
\label{item-affine-fp-over-ft}
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite-fp-over-ft}
\item
\label{item-relative-dimension-d-fp-over-ft}
$f$ is locally of finite type of relative dimension $d$ if and only if
$f'$ is locally of finite type of relative dimension $d$,
\item $f$ is universally open if and only if $f'$ is universally open,
\label{item-universally-open-fp-over-ft}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic-fp-over-ft}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth-fp-over-ft}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified-fp-over-ft}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale-fp-over-ft}
\item $f$ is proper if and only if $f'$ is proper,
\label{item-proper-fp-over-ft}
\item $f$ is finite if and only if $f'$ is finite,
\label{item-finite-fp-over-ft}
\item
\label{item-finite-locally-free-fp-over-ft}
$f$ is finite locally free (of rank $d$) if and only if $f'$
is finite locally free (of rank $d$), and
\item add more here.
\end{enumerate}

\label{lemma-flat-finite-type-finitely-presented-over-dense-open-X}
Let $f : X \to S$ be a morphism of schemes. Let $U \subset S$ be open.
Assume
\begin{enumerate}
\item $f$ is locally of finite type and flat,
\item $U \subset S$ is retrocompact and scheme theoretically dense,
\item $f|_{f^{-1}U} : f^{-1}U \to U$ is locally of finite presentation.
\end{enumerate}
Then $f$ is of locally of finite presentation.

\label{lemma-cohomology-projective-space-over-ring}
\begin{reference}
\cite[III Proposition 2.1.12]{EGA}
\end{reference}
Let $R$ be a ring.
Let $n \geq 0$ be an integer.
We have
$$
H^q(\mathbf{P}^n, \mathcal{O}_{\mathbf{P}^n_R}(d)) =
\left\{
\begin{matrix}
(R[T_0, \ldots, T_n])_d & \text{if} & q = 0,\ d \geq 0 \\
\left(\frac{1}{T_0 \ldots T_n} R[\frac{1}{T_0}, \ldots, \frac{1}{T_n}]\right)_d
& \text{if} & q = n,\ d < 0 \\
0 & \text{if} & q, n, d\text{ not as above}
\end{matrix}
\right.
$$
as $R$-modules.

\label{lemma-regular-model-field}
\begin{reference}
\cite[Lemma 2.6]{Artin-Winters}
\end{reference}
In Situation \ref{situation-regular-model} let $d = \gcd(m_1, \ldots, m_n)$.
Let $D = \sum (m_i/d) C_i$ as an effective Cartier divisor. Then there exists
a sequence of effective Cartier divisors
$$
(X_k)_{red} = Z_0 \subset Z_1 \subset \ldots \subset Z_m = D
$$
such that $Z_j = Z_{j - 1} + C_{i_j}$ for some $i_j \in \{1, \ldots, n\}$
for $j = 1, \ldots, m$ and such that $H^0(Z_j, \mathcal{O}_{Z_j})$
is a field finite over $k$ for $j = 0, \ldots m$.

\label{lemma-sheaf-property-fpqc}
Let $F$ be a contravariant functor on the category
of schemes with values in sets. Then $F$ satisfies
the sheaf property for the fpqc topology if and only
if it satisfies
\begin{enumerate}
\item the sheaf property for every Zariski covering, and
\item the sheaf property for any standard fpqc covering.
\end{enumerate}
Moreover, in the presence of (1) property (2) is equivalent to
property
\begin{enumerate}
\item[(2')] the sheaf property for $\{V \to U\}$
with $V$, $U$ affine and $V \to U$ faithfully flat.
\end{enumerate}

\label{lemma-coherent-diagonal-affine-fp}
The diagonal of $\Cohstack_{X/B}$ over $B$ is affine
and of finite presentation.

\label{lemma-thickening-scheme}
Let $S$ be a scheme. Let $X \subset X'$ be a thickening of algebraic spaces
over $S$. If $X$ is (representable by) a scheme, then so is $X'$.

\label{lemma-well-defined-if-you-can-find-good-factorization}
Consider a commutative diagram
$$
\xymatrix{
S \ar[r] & B \\
& A \ar[lu] \ar[u]
}
$$
of Noetherian local rings with $S \to B$ surjective, $A \to S$ flat, and
$S/\mathfrak m_A S$ a regular local ring. The following are equivalent
\begin{enumerate}
\item $\Ker(S \to B)$ is generated by a regular sequence, and
\item $A^\wedge \to B^\wedge$ is a complete intersection homomorphism
as defined above.
\end{enumerate}

\label{lemma-neron-functorial}
In Situation \ref{situation-neron} N\'eron's blowup is functorial
in the following sense
\begin{enumerate}
\item if $a \in A$, $a \not \in \mathfrak p$, then N\'eron's blowup
of $A_a$ is $A'_a$, and
\item if $B \to A$ is a surjection of flat finite type $R$-algebras
with kernel $I$, then $A'$ is the quotient of $B'/IB'$ by its
$\pi$-power torsion.
\end{enumerate}

\label{theorem-nagata}
\begin{reference}
\cite{CLO}
\end{reference}
Let $S$ be a scheme. Let $B$ be a quasi-compact and quasi-separated
algebraic space over $S$. Let $X \to B$ be a separated, finite type morphism.
Then $X$ has a compactification over $B$.

\label{lemma-pullback-base-change-pullback}
In Situation \ref{situation-setup-base-change} let $Y \to X \to S$ be locally
of finite type and let $Y' \to X' \to S'$ be the base change by $S' \to S$.
Assume $f : Y \to X$ is flat of relative dimension $r$. Then $f' : Y' \to X'$
is flat of relative dimension $r$ and the diagrams
$$
\vcenter{
\xymatrix{
Z_{k + r}(Y) \ar[r]_{g^*} & Z_{k + c + r}(Y') \\
Z_k(X) \ar[r]^{g^*} \ar[u]^{f^*} & Z_{k + c}(X') \ar[u]_{(f')^*}
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\CH_{k + r}(Y) \ar[r]_{g^*} & \CH_{k + c + r}(Y') \\
\CH_k(X) \ar[r]^{g^*} \ar[u]^{f^*} & \CH_{k + c}(X') \ar[u]_{(f')^*}
}
}
$$
of cycle and chow groups commutes.

\label{lemma-bounded-in-image-upstairs}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C}) \to
(\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$ be a morphism of ringed topoi.
Let $K$ be an object of $D(\mathcal{O}_\mathcal{C})$. Assume
\begin{enumerate}
\item $f$ is flat,
\item $K$ is bounded below,
\item $f^*Rf_*H^q(K) \to H^q(K)$ is an isomorphism.
\end{enumerate}
Then $f^*Rf_*K \to K$ is an isomorphism.

\label{lemma-image-affine-finite-morphism-affine-Noetherian}
Let $S$ be a scheme. Let $f : Y \to X$ be a morphism of algebraic
spaces over $S$. Assume
\begin{enumerate}
\item $f$ finite,
\item $f$ surjective,
\item $Y$ affine, and
\item $X$ Noetherian.
\end{enumerate}
Then $X$ is affine.

\label{lemma-characterize-etale}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent
\begin{enumerate}
\item $f$ is \'etale, and
\item $f$ is locally of finite presentation, flat, and unramified,
\item $f$ is locally of finite presentation, flat, and its diagonal
is \'etale.
\end{enumerate}

\label{lemma-gerbe-descent}
Let
$$
\xymatrix{
\mathcal{X}' \ar[r] \ar[d] & \mathcal{X} \ar[d] \\
\mathcal{Y}' \ar[r] & \mathcal{Y}
}
$$
be a fibre product of algebraic stacks.
If $\mathcal{Y}' \to \mathcal{Y}$ is surjective, flat, and locally
of finite presentation and $\mathcal{X}'$ is a gerbe over $\mathcal{Y}'$,
then $\mathcal{X}$ is a gerbe over $\mathcal{Y}$.

\label{lemma-universally-catenary-local-rings-universally-catenary}
Let $S$ be a locally Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $S$ is universally catenary, and
\item all local rings $\mathcal{O}_{S, s}$ of $S$ are universally catenary.
\end{enumerate}

\label{lemma-base-change-integral}
The base change of an integral (resp.\ finite) morphism is integral
(resp.\ finite).

\label{lemma-flat-up-down-henselization}
Let $S$ be a scheme and $s \in S$ a point. Denote $\mathcal{O}_{S, s}^h$
(resp.\ $\mathcal{O}_{S, s}^{sh}$) the henselization (resp.\ strict
henselization), see
Algebra, Definition \ref{algebra-definition-henselization}.
Let $M^{sh}$ be a $\mathcal{O}_{S, s}^{sh}$-module.
The following are equivalent
\begin{enumerate}
\item $M^{sh}$ is flat over $\mathcal{O}_{S, s}$,
\item $M^{sh}$ is flat over $\mathcal{O}_{S, s}^h$, and
\item $M^{sh}$ is flat over $\mathcal{O}_{S, s}^{sh}$.
\end{enumerate}
If $M^{sh} = M^h \otimes_{\mathcal{O}_{S, s}^h} \mathcal{O}_{S, s}^{sh}$
this is also equivalent to
\begin{enumerate}
\item[(4)] $M^h$ is flat over $\mathcal{O}_{S, s}$, and
\item[(5)] $M^h$ is flat over $\mathcal{O}_{S, s}^h$.
\end{enumerate}
If $M^h = M \otimes_{\mathcal{O}_{S, s}} \mathcal{O}_{S, s}^h$
this is also equivalent to
\begin{enumerate}
\item[(6)] $M$ is flat over $\mathcal{O}_{S, s}$.
\end{enumerate}

\label{lemma-polarized-existence}
Consider the stack $\Polarizedstack$ over the base
scheme $\Spec(\mathbf{Z})$. Then every formal object is effective.

\label{lemma-descending-property-isomorphism}
The property $\mathcal{P}(f) =$``$f$ is an isomorphism''
is fpqc local on the base.

\label{lemma-representable-sheaf-fpqc}
Any representable presheaf on $\Sch/S$ satisfies the
sheaf condition for the fpqc topology.

\label{lemma-base-change-finite-type}
A base change of a finite type morphism is finite type.
The same holds for locally of finite type.

\label{proposition-quasi-coherent}
With $S$, $\varphi : U \to X$, and $(U, R, s, t, c)$ as above.
For any quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$ the
sheaf $\varphi^*\mathcal{F}$ comes equipped with a canonical
isomorphism
$$
\alpha : t^*\varphi^*\mathcal{F} \longrightarrow s^*\varphi^*\mathcal{F}
$$
which satisfies the conditions of
Groupoids, Definition \ref{groupoids-definition-groupoid-module}
and therefore defines a quasi-coherent sheaf on $(U, R, s, t, c)$.
The functor $\mathcal{F} \mapsto (\varphi^*\mathcal{F}, \alpha)$
defines an equivalence of categories
$$
\begin{matrix}
\text{Quasi-coherent} \\
\mathcal{O}_X\text{-modules}
\end{matrix}
\longleftrightarrow
\begin{matrix}
\text{Quasi-coherent modules}\\
\text{on }(U, R, s, t, c)
\end{matrix}
$$

\label{lemma-descend-pseudo-coherent}
Let $X$ be a scheme. Let $E$ be an object of $D(\mathcal{O}_X)$.
The following are equivalent
\begin{enumerate}
\item $E$ is $m$-pseudo-coherent, and
\item $\epsilon^*E$ is $m$-pseudo-coherent on the small \'etale site of $X$.
\end{enumerate}
Here $\epsilon$ is as in (\ref{equation-epsilon}).

\label{lemma-coherent-qs-lfp}
The morphism $\Cohstack_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{lemma-tor-dimension-affine}
Let $X = \Spec(A)$ be an affine scheme. Let $M^\bullet$ be a
complex of $A$-modules and let $E$ be the corresponding object
of $D(\mathcal{O}_X)$. Then
\begin{enumerate}
\item $E$ has tor amplitude in $[a, b]$ if and only if $M^\bullet$
has tor amplitude in $[a, b]$.
\item $E$ has finite tor dimension if and only if $M^\bullet$
has finite tor dimension.
\end{enumerate}

\label{lemma-Weierstrass-smooth-cover}
The morphism $W \xrightarrow{(E_W, f_W, 0_W)} \mathcal{M}_{1, 1}$ is smooth
and surjective.

\label{theorem-resolve}
\begin{reference}
\cite[Theorem on page 151]{Lipman}
\end{reference}
Let $Y$ be a two dimensional integral Noetherian scheme. The following are
equivalent
\begin{enumerate}
\item there exists an alteration $X \to Y$ with $X$ regular,
\item there exists a resolution of singularities of $Y$,
\item $Y$ has a resolution of singularities by normalized blowups,
\item the normalization $Y^\nu \to Y$ is finite, $Y^\nu$ has
finitely many singular points $y_1, \ldots, y_m$, and for each
$y_i$ the completion of $\mathcal{O}_{Y^\nu, y_i}$ is normal.
\end{enumerate}

\label{lemma-avramov}
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
Then the following are equivalent
\begin{enumerate}
\item $B$ is a complete intersection,
\item $A$ and $B/\mathfrak m_A B$ are complete intersections.
\end{enumerate}

\label{lemma-curves-open-and-closed-in-spaces}
The $1$-morphism (\ref{equation-curves-over-proper-spaces})
$$
\Curvesstack \longrightarrow \Spacesstack'_{fp, flat, proper}
$$
is representable by open and closed immersions.

\label{lemma-kill-colimit-general}
In Lemma \ref{lemma-kill-colimit-weak-general} if instead of the empty
condition (2) we assume
\begin{enumerate}
\item[(2')] if $\mathfrak p \in V(I)$, $\mathfrak p \not \in V(J) \cap V(I)$,
then
$\text{depth}_{A_\mathfrak p}(M_\mathfrak p) +
\dim((A/\mathfrak p)_\mathfrak q) > s$
for all $\mathfrak q \in V(\mathfrak p) \cap V(J) \cap V(I)$,
\end{enumerate}
then the conditions also imply that $H^i_{J_0}(M)$ is a finite
$A$-module for $i \leq s$.

\label{lemma-open}
Let $S$ be a scheme. Let $(U \subset X, j : V \to X)$ be an elementary
distinguished square of algebraic spaces over $S$. Let $T$ be a closed
subset of $|X| \setminus |U|$ and let $(T, E, m)$ be a triple as in
Definition \ref{definition-approximation-holds}. If
\begin{enumerate}
\item approximation holds for $(j^{-1}T, E|_V, m)$, and
\item the sheaves $H^i(E)$ for $i \geq m$ are supported on $T$,
\end{enumerate}
then approximation holds for $(T, E, m)$.

\label{lemma-formal-objects-different-filtration}
In the situation above, $\widehat{\mathcal{F}}_\mathcal{I}(R)$ is equivalent
to the category $\widehat{\mathcal{F}}(R)$.

\label{lemma-characterize-trivial}
In Situation \ref{situation-regular-model} let $d = \gcd(m_1, \ldots, m_n)$.
If $\mathcal{L}$ is an invertible $\mathcal{O}_X$-module which
\begin{enumerate}
\item restricts to the trivial invertible module on $C$, and
\item has degree $0$ on each $C_i$,
\end{enumerate}
then $\mathcal{L}^{\otimes d} \cong \mathcal{O}_X$.

\label{lemma-catenary-check-irreducible}
Let $S$ be a locally Noetherian scheme. Then $S$ is universally catenary
if and only if the irreducible components of $S$ are universally catenary.

\label{lemma-integral-B}
Let $f : X \to Y$ be an integral morphism of schemes.
Then property (B) holds.

\label{lemma-descending-property-proper}
The property $\mathcal{P}(f) =$``$f$ is proper''
is fpqc local on the base.

\label{lemma-bimodule-over-tensor}
Let $R$ be a ring. Let $(A, \text{d})$ and $(B, \text{d})$
be differential graded algebras over $R$. The construction above
defines an equivalence of categories
$$
\begin{matrix}
\text{differential graded}\\
(A, B)\text{-bimodules}
\end{matrix}
\longleftrightarrow
\begin{matrix}
\text{right differential graded }\\
A^{opp} \otimes_R B\text{-modules}
\end{matrix}
$$

\label{lemma-NL-formally-etale}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is formally \'etale,
\item $H^{-1}(\NL_{X/Y}) = H^0(\NL_{X/Y}) = 0$.
\end{enumerate}

\label{lemma-periodic-determinant-easy-case}
Let $R$ be a local ring with residue field $\kappa$.
Let $M$ be a finite length $R$-module.
\begin{enumerate}
\item if $\varphi : M \to M$ is an isomorphism then
$\det_\kappa(M, \varphi, 0) = \det_\kappa(\varphi)$.
\item if $\psi : M \to M$ is an isomorphism then
$\det_\kappa(M, 0, \psi) = \det_\kappa(\psi)^{-1}$.
\end{enumerate}

\label{lemma-homo-change}
In Situation \ref{situation-ABC} given a diagram
$$
\xymatrix{x\ar[r]^f\ar[d]_a & y\ar[d]^b\\
z\ar[r]^g & w}
$$
in $\text{Comp}(\mathcal{A})$ commuting up to homotopy. Then
\begin{enumerate}
\item If $f$ is an admissible monomorphism, then $b$ is homotopic
to a morphism $b'$ which makes the diagram commute.
\item If $g$ is an admissible epimorphism, then $a$ is homotopic
to a morphism $a'$ which makes the diagram commute.
\end{enumerate}

\label{lemma-lisse-etale-functorial-cohomology}
With assumptions and notation as in Lemma \ref{lemma-lisse-etale-functorial}
the canonical (base change) map
$$
g^{-1}Rf_*\mathcal{F} \longrightarrow Rf'_*(g')^{-1}\mathcal{F}
$$
is an isomorphism for any abelian sheaf $\mathcal{F}$
on $\mathcal{X}_\etale$ (resp.\ $\mathcal{X}_{fppf}$).

\label{lemma-picard-group-genus-nonpositive}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type $T$.
If the genus $g$ of $T$ is $\leq 0$, then $\Pic(T) = \mathbf{Z}$.

\label{lemma-base-change-quasi-compact}
The base change of a quasi-compact morphism of algebraic stacks
by any morphism of algebraic stacks is quasi-compact.

\label{lemma-countable-affine-formal-algebraic-space}
Let $S$ be a scheme. Let $X$ be an affine formal algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item there exists a system $X_1 \to X_2 \to X_3 \to \ldots$
of thickenings of affine schemes over $S$ such that $X = \colim X_n$,
\item there exists a choice $X = \colim X_\lambda$ as in
Definition \ref{definition-affine-formal-algebraic-space}
such that $\Lambda$ is countable.
\end{enumerate}

\label{lemma-descending-property-thickening}
The property of being a thickening is fpqc local.
Similarly for first order thickenings.

\label{lemma-perfect-for-R}
With $k$, $n$, and $R$ as above, for an object $K$ of $D(R)$
the following are equivalent
\begin{enumerate}
\item $\sum_{i \in \mathbf{Z}} \dim_k H^i(K) < \infty$, and
\item $K$ is a compact object.
\end{enumerate}

\label{lemma-factor-small-extension}
Let $f: B \to A$ be a surjective ring map in $\mathcal{C}_\Lambda$.
Then $f$ can be factored as a composition of small extensions.

\label{lemma-cohomology-istar-Z}
For all $q \geq 1$, $H_\etale^q(X, \bigoplus_{x \in X_0} {i_x}_*
\underline{\mathbf{Z}}) = 0$.

\label{lemma-module-differentials-quasi-coherent}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Then $\Omega_{X/Y}$ is a quasi-coherent $\mathcal{O}_X$-module.

\label{lemma-surjective-finite-morphism-ample}
Let $R$ be a Noetherian ring. Let $f : Y \to X$ be a morphism of
algebraic spaces proper over $R$. Let $\mathcal{L}$ be an
invertible $\mathcal{O}_X$-module. Assume $f$ is finite and surjective.
The following are equivalent
\begin{enumerate}
\item $X$ is a scheme and $\mathcal{L}$ is ample, and
\item $Y$ is a scheme and $f^*\mathcal{L}$ is ample.
\end{enumerate}

\label{lemma-basic-example-pushout}
Let $A' \to A$ be a surjection of rings and let $B \to A$ be a ring map.
Let $B' = B \times_A A'$ be the fibre product of rings. Set
$S = \Spec(A)$, $S' = \Spec(A')$, $T = \Spec(B)$, and $T' = \Spec(B')$.
Then
$$
\vcenter{
\xymatrix{
S \ar[r]_i \ar[d]_f & S' \ar[d]^{f'} \\
T \ar[r]^{i'} & T'
}
}
\quad\text{corresponding to}\quad
\vcenter{
\xymatrix{
A & A' \ar[l] \\
B \ar[u] & B' \ar[l] \ar[u]
}
}
$$
is a pushout of schemes.

\label{lemma-hom-from-Af}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $f$ be a global
section of $\mathcal{O}$. Let $K \in D(\mathcal{O})$.
The following are equivalent
\begin{enumerate}
\item $R\SheafHom_\mathcal{O}(\mathcal{O}_f, K) = 0$,
\item $R\SheafHom_\mathcal{O}(L, K) = 0$ for all $L$ in $D(\mathcal{O}_f)$,
\item $T(K, f) = 0$.
\end{enumerate}

\label{lemma-zariski-etale-smooth}
Any \'etale covering is a smooth covering, and a fortiori,
any Zariski covering is a smooth covering.

\label{lemma-transitive-lci-at-end}
With assumptions as in Lemma \ref{lemma-exact-sequence-NL}
assume that $B/I^nB \to C/I^nC$ is a local complete intersection
homomorphism for all $n$. Then
$H^{-1}(\NL_{B/A}^\wedge \otimes_B C) \to H^{-1}(\NL_{C/A}^\wedge)$
is injective.

\label{lemma-quasi-coherence-direct-sums}
Let $X$ be a scheme. Then $D_\QCoh(\mathcal{O}_X)$
has direct sums.

\label{lemma-codimension-0-points-dense}
Let $S$ be a scheme and let $X$ be an algebraic space over $S$.
The set of codimension $0$ points of $X$ is dense in $|X|$.

\label{lemma-cone}
The cone on a morphism of strictly perfect complexes is
strictly perfect.

\label{lemma-hom-cartesian-objects-derived}
In Situation \ref{situation-simplicial-site}.
If $K, K' \in D(\mathcal{C}_{total})$.
Assume
\begin{enumerate}
\item $K$ is cartesian,
\item $\Hom(K_i[i - 1], K'_i) = 0$ for $i > 1$.
\end{enumerate}
Then any map $\{K_n \to K'_n\}$ between the associated simplicial systems 
of $K$ and $K'$ comes from a map $K \to K'$ in $D(\mathcal{C}_{total})$.

\label{lemma-permanence-pseudo-coherent}
Let $f : X \to Y$ be a morphism of algebraic spaces pseudo-coherent
over a base algebraic space $B$. Then $f$ is pseudo-coherent.

\label{lemma-gorenstein}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item If $X$ has a dualizing complex $\omega_X^\bullet$, then
\begin{enumerate}
\item $X$ is Gorenstein $\Leftrightarrow$ $\omega_X^\bullet$ is an invertible
object of $D(\mathcal{O}_X)$,
\item $\mathcal{O}_{X, x}$ is Gorenstein $\Leftrightarrow$
$\omega_{X, x}^\bullet$ is an invertible object of $D(\mathcal{O}_{X, x})$,
\item $U = \{x \in X \mid \mathcal{O}_{X, x}\text{ is Gorenstein}\}$
is an open Gorenstein subscheme.
\end{enumerate}
\item If $X$ is Gorenstein, then $X$ has a dualizing complex if and
only if $\mathcal{O}_X[0]$ is a dualizing complex.
\end{enumerate}

\label{lemma-smooth-formally-smooth}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is smooth, and
\item the morphism $f$ is locally of finite presentation and
formally smooth.
\end{enumerate}

\label{lemma-when-jshriek-compact}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $U$ be an object of
$\mathcal{C}$. The $\mathcal{O}$-module $j_!\mathcal{O}_U$ is a
compact object of $D(\mathcal{O})$ if there exists an integer $d$ such that
\begin{enumerate}
\item $H^p(U, \mathcal{F}) = 0$ for all $p > d$, and
\item the functors $\mathcal{F} \mapsto H^p(U, \mathcal{F})$
commute with direct sums.
\end{enumerate}

\label{lemma-proper-f-shriek}
Let $f : X \to Y$ be a proper morphism of schemes.
Then $f_! = f_*$.

\label{lemma-decompose-quasi-finite-morphism}
Let $f : Y \to X$ be a quasi-finite and finitely presented
morphism of affine schemes.
\begin{enumerate}
\item There exists a surjective morphism of affine schemes $X' \to X$ and a
closed subscheme $Z' \subset Y' = X' \times_X Y$ such that
\begin{enumerate}
\item $Z' \subset Y'$ is a thickening, and
\item $Z' \to X'$ is a finite \'etale morphism.
\end{enumerate}
\item There exists a finite partition $X = \coprod X_i$ by
locally closed, constructible, affine strata, and surjective finite locally
free morphisms $X'_i \to X_i$ such that the reduction of
$Y'_i = X'_i \times_X Y \to X'_i$ is isomorphic to
$\coprod_{j = 1}^{n_i} (X'_i)_{red} \to (X'_i)_{red}$ for some $n_i$.
\end{enumerate}

\label{proposition-rickard}
Let $R$ be a ring. Let $(A, \text{d})$ and $(B, \text{d})$ be
differential graded $R$-algebras. Let $F : D(A, \text{d}) \to D(B, \text{d})$
be an $R$-linear equivalence of triangulated categories. Assume that
\begin{enumerate}
\item $A = H^0(A)$, and
\item $B$ is K-flat as a complex of $R$-modules.
\end{enumerate}
Then there exists an $(A, B)$-bimodule $N$ as in
Lemma \ref{lemma-tilting-equivalence}.

\label{lemma-immersion-universal-thickening}
Let $S$ be a scheme.
Let $i : Z \to X$ be an immersion of algebraic spaces over $S$. Then
\begin{enumerate}
\item $i$ is formally unramified,
\item the universal first order thickening of $Z$ over $X$ is the first order
infinitesimal neighbourhood of $Z$ in $X$ of
Definition \ref{definition-first-order-infinitesimal-neighbourhood},
\item the conormal sheaf of $i$ in the sense of
Definition \ref{definition-conormal-sheaf}
agrees with the conormal sheaf of $i$ in the sense of
Definition \ref{definition-universal-thickening}.
\end{enumerate}

\label{lemma-pro-h-V}
Let $X \to Y$ be a morphism of affine schemes. The following are equivalent
\begin{enumerate}
\item $\{X \to Y\}$ is a standard V covering
(Topologies, Definition \ref{topologies-definition-standard-V-covering}),
\item $X = \lim X_i$ is a directed limit of affine schemes over $Y$
such that $\{X_i \to Y\}$ is a ph covering for each $i$, and
\item $X = \lim X_i$ is a directed limit of affine schemes over $Y$
such that $\{X_i \to Y\}$ is an h covering for each $i$.
\end{enumerate}

\label{lemma-category-fibred}
In the situation above the category
$\mathcal{C}_{X/\Lambda}$ is fibred over $X_{Zar}$.

\label{proposition-Hartshorne-Lichtenbaum-vanishing}
\begin{reference}
\cite[Theorem 3.1]{CD}
\end{reference}
Let $A$ be a Noetherian local ring with completion $A^\wedge$.
Let $I \subset A$ be an ideal such that
$$
\dim V(IA^\wedge + \mathfrak p) \geq 1
$$
for every minimal prime $\mathfrak p \subset A^\wedge$ of dimension $\dim(A)$.
Then $\text{cd}(A, I) < \dim(A)$.

\label{lemma-quasi-compact-dominant}
\begin{slogan}
Morphisms whose image contains the generic points are dominant
\end{slogan}
Let $f : X \to S$ be a quasi-compact morphism of schemes.
Then $f$ is dominant if and only if for every irreducible
component $Z \subset S$ the generic point of $Z$ is in the
image of $f$.

\label{lemma-Noetherian-approximation-smooth}
Let $f : X \to S$ be a morphism of affine schemes, which is smooth.
Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ is smooth.

\label{lemma-smash-nilpotence}
\begin{reference}
\cite{nilpotence}
\end{reference}
Let $k$ be a field. Let $X$ be a geometrically irreducible
smooth projective scheme over $k$. Let $x, x' \in X$ be $k$-rational points.
For $n$ large enough the class of the zero cycle
$$
([x] - [x']) \times \ldots \times ([x] - [x']) \in
\CH_0(X^n)
$$
is torsion.

\label{lemma-characterize-flat-closed-immersions}
Let $X$ be a scheme. The rule which associates to a closed subscheme
of $X$ its underlying closed subset defines a bijection
$$
\left\{
\begin{matrix}
\text{closed subschemes }Z \subset X \\
\text{such that }Z \to X\text{ is flat}
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{closed subsets }Z \subset X \\
\text{closed under generalizations}
\end{matrix}
\right\}
$$
If $Z \subset X$ is such a closed subscheme, every morphism of schemes
$g : Y \to X$ with $g(Y) \subset Z$ set theoretically factors (scheme
theoretically) through $Z$.

\label{lemma-monomorphism}
Let $S$ be a scheme.
Let $j : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item $j$ is a monomorphism (as in Definition \ref{definition-monomorphism}),
\item $j$ is a monomorphism in the category of algebraic spaces over $S$, and
\item the diagonal morphism $\Delta_{X/Y} : X \to X \times_Y X$ is
an isomorphism.
\end{enumerate}

\label{theorem-check-flatness-at-associated-points}
Let $f : X \to S$ be locally of finite type.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module of finite type.
Let $x \in X$ with image $s \in S$.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is flat at $x$ over $S$, and
\item for every $x' \in \text{Ass}_{X_s}(\mathcal{F}_s)$ which
specializes to $x$ we have that $\mathcal{F}$ is flat at $x'$ over $S$.
\end{enumerate}

\label{lemma-hom-into-depth}
Let $X$ be a locally Noetherian scheme. Let $\mathcal{F}$, $\mathcal{G}$
be coherent $\mathcal{O}_X$-modules and $x \in X$.
\begin{enumerate}
\item If $\mathcal{G}_x$ has depth $\geq 1$, then
$\SheafHom_{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})_x$
has depth $\geq 1$.
\item If $\mathcal{G}_x$ has depth $\geq 2$, then
$\Hom_{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})_x$ has depth $\geq 2$.
\end{enumerate}

\label{lemma-algebraizable}
In Situation \ref{situation-algebraize} let $(\mathcal{F}_n)$ be an
object of $\textit{Coh}(U, I\mathcal{O}_U)$. Let $A', I', \mathfrak a'$
be the $I$-adic completions of $A, I, \mathfrak a$. Set $X' = \Spec(A')$
and $U' = X' \setminus V(\mathfrak a')$. The following are equivalent
\begin{enumerate}
\item $(\mathcal{F}_n)$ extends to $X$, and
\item the pullback of $(\mathcal{F}_n)$ to $U'$ is the completion
of a coherent $\mathcal{O}_{U'}$-module.
\end{enumerate}

\label{lemma-stable-reduction}
Let $R$ be a discrete valuation ring with fraction field $K$.
Let $C$ be a smooth projective curve over $K$ with
$K = H^0(C, \mathcal{O}_C)$ having genus $g \geq 2$.
The following are equivalent
\begin{enumerate}
\item $C$ has semistable reduction
(Semistable Reduction, Definition \ref{models-definition-semistable}), or
\item there is a stable family of curves over $R$ with generic fibre $C$.
\end{enumerate}

\label{lemma-is-limit}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $E \in D(\mathcal{O})$.
Assume there exists a function $p(-) : \mathbf{Z} \to \mathbf{Z}$
and a subset $\mathcal{B} \subset \Ob(\mathcal{C})$ such that
\begin{enumerate}
\item every object of $\mathcal{C}$ has a covering whose members are
elements of $\mathcal{B}$,
\item $H^p(V, H^{m - p}(E)) = 0$ for $p > p(m)$ and $V \in \mathcal{B}$.
\end{enumerate}
Then the map $E \to R\lim \tau_{\geq -n} E$ of
Derived Categories, Remark
\ref{derived-remark-map-into-derived-limit-truncations}
is an isomorphism in $D(\mathcal{O})$.

\label{lemma-funny-gamma}
Let $\mathcal{C}$ be a site with fibre products.
Let $X$ be an object of $\mathcal{C}$.
Let $K, L, M$ be simplicial objects of $\text{SR}(\mathcal{C}, X)$.
Let $a : K \to L$, $b : M \to L$ be morphisms.
Assume
\begin{enumerate}
\item $K$ is a hypercovering of $X$,
\item the morphism $M_0 \to L_0$ is a covering, and
\item for all $n \geq 0$ in the diagram
$$
\xymatrix{
M_{n + 1} \ar[dd] \ar[rr] \ar[rd]^\gamma &
&
(\text{cosk}_n \text{sk}_n M)_{n + 1} \ar[dd] \\
&
L_{n + 1}
\times_{(\text{cosk}_n \text{sk}_n L)_{n + 1}}
(\text{cosk}_n \text{sk}_n M)_{n + 1}
\ar[ld] \ar[ru]
& \\
L_{n + 1} \ar[rr] & & (\text{cosk}_n \text{sk}_n L)_{n + 1}
}
$$
the arrow $\gamma$ is a covering.
\end{enumerate}
Then the fibre product $K \times_L M$ is a hypercovering of $X$.

\label{lemma-constant-smooth-statements}
In Situation \ref{situation-what-to-prove}
assume $X$ is smooth and $\mathcal{F} = \underline{\mathbf{Z}/\ell\mathbf{Z}}$
for some prime number $\ell$. Then statements
(\ref{item-vanishing}) -- (\ref{item-surjective}) hold
for $\mathcal{F}$.

\label{theorem-splitting}
Let $A$ be a finite central simple $k$-algebra.
Let $k'/k$ be a finite field extension.
The following are equivalent
\begin{enumerate}
\item $k'$ splits $A$, and
\item there exists a finite central simple algebra $B$ similar to $A$
such that $k' \subset B$ and $[B : k] = [k' : k]^2$.
\end{enumerate}

\label{lemma-NL-up-to-qis}
In the situation above there is a canonical isomorphism
$\NL(\alpha) = \NL_{\mathcal{B}/\mathcal{A}}$ in $D(\mathcal{B})$.

\label{lemma-flattening-module-map}
Let $A$ be a ring. Let $u : M \to N$ be a surjective map of $A$-modules.
If $M$ is projective as an $A$-module, then there exists an ideal
$I \subset A$ such that for any ring map $\varphi : A \to B$
the following are equivalent
\begin{enumerate}
\item $u \otimes 1 : M \otimes_A B \to N \otimes_A B$ is an
isomorphism, and
\item $\varphi(I) = 0$.
\end{enumerate}

\label{lemma-formally-unramified}
Let $(A, \mathfrak m)$ be a local Noetherian ring. Let
$X$ be an algebraic space over $A$. Assume
\begin{enumerate}
\item $A$ is analytically unramified
(Algebra, Definition \ref{algebra-definition-analytically-unramified}),
\item $X$ is locally of finite type over $A$,
\item $X \to \Spec(A)$ is \'etale at every point of codimension $0$ in $X$.
\end{enumerate}
Then the normalization of $X$ is finite over $X$.

\label{lemma-stein-factorization-etale}
\begin{reference}
\cite[Expose X, Proposition 1.2, p. 262]{SGA1}.
\end{reference}
Let $f : X \to S$ be a proper morphism of schemes.
Let $X \to S' \to S$ be the Stein factorization of $f$, see
More on Morphisms, Theorem
\ref{more-morphisms-theorem-stein-factorization-general}.
If $f$ is of finite presentation, flat, with geometrically
reduced fibres, then $S' \to S$ is finite \'etale.

\label{lemma-shriek-proper-and-open-base-change}
Let $b : Y_1 \to Y$ be a morphism of schemes. Consider a commutative diagram
of schemes
$$
\vcenter{
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
}
\quad\text{and let}\quad
\vcenter{
\xymatrix{
X'_1 \ar[r]_{g'_1} \ar[d]_{f'_1} & X_1 \ar[d]^{f_1} \\
Y'_1 \ar[r]^{g_1} & Y_1
}
}
$$
be the base change by $b$. Assume $f$ and $f'$ proper and
$g$ and $g'$ separated and locally quasi-finite.
For a ring $\Lambda$ and $K$ in $D(X'_\etale, \Lambda)$
there is commutative diagram
$$
\xymatrix{
b^{-1}g_!Rf'_*K \ar[d] \ar[r] &
g_{1, !}(b')^{-1}Rf'_*K \ar[r] &
g_{1, !}Rf'_{1, *}(a')^{-1}K \ar[d] \\
b^{-1}Rf_*g'_!K \ar[r] &
Rf_{1, *}a^{-1}g'_!K \ar[r] &
Rf_{1, *}g'_{1, !}(a')^{-1}K
}
$$
in $D(Y_{1, \etale}, \Lambda)$ where $a : X_1 \to X$, $a' : X'_1 \to X'$,
$b' : Y'_1 \to Y'$ are the projections, the vertical maps are the arrows
of Lemma \ref{lemma-shriek-proper-and-open}
and the horizontal arrows are the base change map
(from \'Etale Cohomology, Section
\ref{etale-cohomology-section-base-change-preliminaries})
and the base change map of Lemma \ref{lemma-base-change-f-shriek-separated}.

\label{lemma-descent-data-sheaves}
Let $S$ be a scheme. Let $\{X_i \to X\}_{i \in I}$ be an fppf
covering of algebraic spaces over $S$ (Topologies on Spaces,
Definition \ref{spaces-topologies-definition-fppf-covering}).
There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{descent data }(V_i, \varphi_{ij})\\
\text{relative to }\{X_i \to X\}
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{sheaves }F\text{ on }(\Sch/S)_{fppf}\text{ endowed}\\
\text{with a map }F \to X\text{ such that each}\\
X_i \times_X F\text{ is an algebraic space}
\end{matrix}
\right\}.
$$
Moreover,
\begin{enumerate}
\item the algebraic space $X_i \times_X F$ on the right hand side
corresponds to $V_i$ on the left hand side, and
\item the sheaf $F$ is an algebraic space\footnote{We will see
later that this is always the case if $I$ is not too large, see
Bootstrap, Lemma \ref{bootstrap-lemma-descend-algebraic-space}.}
if and only if the
corresponding descent datum $(X_i, \varphi_{ij})$ is effective.
\end{enumerate}

\label{lemma-locally-free-rank-r-pullback}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $\mathcal{F}$ be a finite type, quasi-coherent
$\mathcal{O}_X$-module. The closed subspaces
$$
X = Z_{-1} \supset Z_0 \supset Z_1 \supset Z_2 \ldots
$$
defined by the Fitting ideals of $\mathcal{F}$ have the following
properties
\begin{enumerate}
\item The intersection $\bigcap Z_r$ is empty.
\item The functor $(\Sch/X)^{opp} \to \textit{Sets}$ defined by the rule
$$
T \longmapsto
\left\{
\begin{matrix}
\{*\} & \text{if }\mathcal{F}_T\text{ is locally generated by }
\leq r\text{ sections} \\
\emptyset & \text{otherwise}
\end{matrix}
\right.
$$
is representable by the open subspace $X \setminus Z_r$.
\item The functor $F_r : (\Sch/X)^{opp} \to \textit{Sets}$ defined by the rule
$$
T \longmapsto
\left\{
\begin{matrix}
\{*\} & \text{if }\mathcal{F}_T\text{ locally free rank }r\\
\emptyset & \text{otherwise}
\end{matrix}
\right.
$$
is representable by the locally closed subspace $Z_{r - 1} \setminus Z_r$
of $X$.
\end{enumerate}
If $\mathcal{F}$ is of finite presentation, then
$Z_r \to X$, $X \setminus Z_r \to X$, and $Z_{r - 1} \setminus Z_r \to X$
are of finite presentation.

\label{lemma-proper-compact-support}
Let $X$ be a proper scheme over a field $k$. Then
$H^0_c(X, \mathcal{F}) = H^0(X, \mathcal{F})$.

\label{lemma-relative-dualizing-noetherian}
Let $\varphi : R \to A$ be a flat finite type ring map of Noetherian rings.
Then the relative dualizing complex $\omega_{A/R}^\bullet = \varphi^!(R)$
of Section \ref{section-relative-dualizing-complexes-Noetherian}
is a relative dualizing complex in the sense of
Definition \ref{definition-relative-dualizing-complex}.

\label{lemma-countable-coherent}
Let $R$ be a countable ring. Then $R$ is coherent if and only if
$R^\mathbf{N}$ is a flat $R$-module.

\label{proposition-crystals-on-affine}
The functor
$$
\begin{matrix}
\text{crystals in quasi-coherent} \\
\mathcal{O}_{X/S}\text{-modules on }\text{Cris}(X/S)
\end{matrix}
\longrightarrow
\begin{matrix}
\text{pairs }(M, \nabla)\text{ satisfying} \\
\text{(\ref{item-complete}), (\ref{item-connection}),
(\ref{item-integrable}), and (\ref{item-topologically-quasi-nilpotent})}
\end{matrix}
$$
of Lemma \ref{lemma-crystals-on-affine}
is an equivalence of categories.

\label{lemma-predeformation-category}
The functor $p : \mathcal{F} \to \mathcal{C}_\Lambda$ defined above
is a predeformation category.

\label{lemma-base-change-universally-open}
The base change of a universally open morphism of algebraic stacks
by any morphism of algebraic stacks is universally open.

\label{lemma-pullback-c1}
Given a commutative diagram
$$
\xymatrix{
X' \ar[r]_f \ar[d] & X \ar[d] \\
S' \ar[r] & S
}
$$
of schemes the diagrams
$$
\xymatrix{
\Pic(X') \ar[d]_{c_1^{dR}} &
\Pic(X) \ar[d]^{c_1^{dR}} \ar[l]^{f^*} \\
H^2_{dR}(X'/S') &
H^2_{dR}(X/S) \ar[l]_{f^*}
}
\quad
\xymatrix{
\Pic(X') \ar[d]_{c_1^{Hodge}} &
\Pic(X) \ar[d]^{c_1^{Hodge}} \ar[l]^{f^*} \\
H^1(X', \Omega^1_{X'/S'}) &
H^1(X, \Omega^1_{X/S}) \ar[l]_{f^*}
}
$$
commute.

\label{lemma-key-purity-ramification}
Let $f : X \to \Spec(A)$ be a finite type morphism.
Let $x \in X$ be a point. Assume
\begin{enumerate}
\item $A$ is an excellent regular local ring,
\item $\mathcal{O}_{X, x}$ is normal of dimension $2$,
\item $f$ is \'etale outside of $\overline{\{x\}}$.
\end{enumerate}
Then $f$ is \'etale at $x$.

\label{lemma-reach-point-closure-Noetherian}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Assume $f$ finite type and $\mathcal{Y}$ locally Noetherian.
Let $y \in |\mathcal{Y}|$ be a point in the closure of the image of $|f|$.
Then there exists a commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & \mathcal{X} \ar[d]^f \\
\Spec(A) \ar[r] & \mathcal{Y}
}
$$
of algebraic stacks where $A$ is a discrete valuation ring and $K$
is its field of fractions mapping the closed point of $\Spec(A)$ to $y$.

\label{lemma-Jacobson-universally-Jacobson}
Let $S$ be a Jacobson scheme.
Any scheme locally of finite type over $S$ is Jacobson.

\label{lemma-S1-S2-localize}
Let $\mathcal{F}$ be a category cofibered in groupoids over
$\mathcal{C}_\Lambda$. Let $x_0 \in \Ob(\mathcal{F}(k))$.
Let $\mathcal{F}_{x_0}$ be the category cofibred in groupoids over
$\mathcal{C}_\Lambda$ constructed in
Remark \ref{remark-localize-cofibered-groupoid}.
\begin{enumerate}
\item If $\mathcal{F}$ satisfies (S1), then so does $\mathcal{F}_{x_0}$.
\item If $\mathcal{F}$ satisfies (S2), then so does $\mathcal{F}_{x_0}$.
\end{enumerate}

\label{lemma-base-change-quasi-compact}
The base change of a quasi-compact morphism of algebraic spaces
by any morphism of algebraic spaces is quasi-compact.

\label{lemma-criterion-baer}
\begin{reference}
\cite[Theorem 1]{Baer}
\end{reference}
Let $R$ be a ring. An $R$-module $Q$ is injective if and only if in every
commutative diagram
$$
\xymatrix{
\mathfrak{a} \ar[d] \ar[r] &  Q \\
R \ar@{-->}[ru]
}
$$
for $\mathfrak{a} \subset R$ an ideal, the dotted arrow exists.

\label{lemma-unramified-formally-unramified}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is unramified,
\item the morphism $f$ is locally of finite type and $\Omega_{X/Y} = 0$, and
\item the morphism $f$ is locally of finite type and formally unramified.
\end{enumerate}

\label{lemma-CM-local-ring-fibre}
The property of morphisms of germs of schemes
\begin{align*}
& \mathcal{P}((X, x) \to (S, s)) = \\
& \text{the local ring }
\mathcal{O}_{X_s, x}
\text{ of the fibre is Noetherian and Cohen-Macaulay}
\end{align*}
is \'etale local on the source-and-target (Descent, Definition
\ref{descent-definition-local-source-target-at-point}).

\label{lemma-limits}
The category of divided power rings has all limits and they agree with
limits in the category of rings.

\label{lemma-immersion-differentials}
Let $S$ be a scheme. If $X \to Y$ is an immersion
of algebraic spaces over $S$ then $\Omega_{X/S}$ is zero.

\label{lemma-immersions-monomorphisms}
An immersion of algebraic spaces is a monomorphism.
In particular, any immersion is separated.

\label{lemma-characterize-injective}
\begin{slogan}
To check that an object is injective, one only needs to check that lifting
holds for subobjects of a generator.
\end{slogan}
Let $\mathcal{A}$ be a Grothendieck abelian category with generator $U$.
An object $I$ of $\mathcal{A}$ is injective if and only if in every
commutative diagram
$$
\xymatrix{
M \ar[d] \ar[r] &  I \\
U \ar@{-->}[ru]
}
$$
for $M \subset U$ a subobject, the dotted arrow exists.

\label{lemma-characterize-representable-universally-open}
Let $S$ be a scheme. Let $f : X \to Y$ be a representable morphism of
algebraic spaces over $S$. The following are equivalent
\begin{enumerate}
\item $f$ is universally open
(in the sense of Section \ref{section-representable}), and
\item for every morphism of algebraic spaces $Z \to Y$ the morphism of
topological spaces $|Z \times_Y X| \to |Z|$ is open.
\end{enumerate}

\label{lemma-depth-dualizing-module}
Let $(A, \mathfrak m, \kappa)$ be a Noetherian local ring with
normalized dualizing complex $\omega_A^\bullet$. Let $d = \dim(A)$
and $\omega_A = H^{-d}(\omega_A^\bullet)$. Then
\begin{enumerate}
\item the support of $\omega_A$ is the union of the irreducible components
of $\Spec(A)$ of dimension $d$,
\item $\omega_A$ satisfies $(S_2)$, see
Algebra, Definition \ref{algebra-definition-conditions}.
\end{enumerate}

\label{lemma-descend-invertible-modules}
With notation and assumptions as in
Lemma \ref{lemma-descend-finite-presentation}. Then
\begin{enumerate}
\item any finite locally free $\mathcal{O}_X$-module is the pullback
of a finite locally free $\mathcal{O}_{X_i}$-module for some $i$,
\item any invertible $\mathcal{O}_X$-module is the pullback of an invertible
$\mathcal{O}_{X_i}$-module for some $i$.
\end{enumerate}

\label{proposition-quasi-coherent-sheaf-fpqc}
For any quasi-coherent sheaf $\mathcal{F}$ on $S$ the presheaf
$$
\begin{matrix}
\mathcal{F}^a : & \Sch/S & \to & \textit{Ab}\\
& (f: T \to S) & \mapsto & \Gamma(T, f^*\mathcal{F})
\end{matrix}
$$
is an $\mathcal{O}$-module which satisfies the sheaf condition for the
fpqc topology.

\label{lemma-unramified-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is unramified''
is \'etale local on the source.

\label{lemma-contract-when-quasi-projective}
Let $S$ be a Noetherian scheme. Let $f : X \to S$ be a morphism of finite type.
Let $E \subset X$ be an exceptional curve of the first kind which is in a
fibre of $f$.
\begin{enumerate}
\item If $X$ is projective over $S$, then there exists a contraction
$X \to X'$ of $E$ and $X'$ is projective over $S$.
\item If $X$ is quasi-projective over $S$, then there exists a contraction
$X \to X'$ of $E$ and $X'$ is quasi-projective over $S$.
\end{enumerate}

\label{lemma-better-characterize-relative-limit-preserving}
Let $S$ be a scheme. Let $X \to Y$ be a morphism of algebraic spaces
over $S$. The equivalent conditions (1) and (2) of
Proposition \ref{proposition-characterize-locally-finite-presentation}
are also equivalent to
\begin{enumerate}
\item[(3)] for every directed limit $T = \lim T_i$ of quasi-compact
and quasi-separated algebraic spaces $T_i$ over $S$ with affine
transition morphisms the diagram of sets
$$
\xymatrix{
\colim_i \Mor(T_i, X) \ar[r] \ar[d] & \Mor(T, X) \ar[d] \\
\colim_i \Mor(T_i, Y) \ar[r] & \Mor(T, Y)
}
$$
is a fibre product diagram.
\end{enumerate}

\label{lemma-properties-pure-spreadout}
In (\ref{equation-star}) if there exists a pure spreadout, then
\begin{enumerate}
\item elements of $N$ have content ideals in $A$, and
\item if $u : N \to M$ is a morphism to a flat $A$-module $M$
such that $N/\mathfrak m N \to M/\mathfrak m M$ is injective
for all maximal ideals $\mathfrak m$ of $A$, then $u$ is
$A$-universally injective.
\end{enumerate}

\label{lemma-kunneth-de-rham-relative}
Assume $X \to S$ and $Y \to S$ are smooth and quasi-compact
and the morphisms $X \to X \times_S X$ and $Y \to Y \times_S Y$ are affine.
Then the relative cup product
$$
Ra_*\Omega^\bullet_{X/S}
\otimes_{\mathcal{O}_S}^\mathbf{L}
Rb_*\Omega^\bullet_{Y/S}
\longrightarrow
Rf_*\Omega^\bullet_{X \times_S Y/S}
$$
is an isomorphism in $D(\mathcal{O}_S)$.

\label{lemma-cohomology-powers-ideal-times-F}
\begin{reference}
\cite[III Cor 3.3.2]{EGA}
\end{reference}
Let $A$ be a Noetherian ring.
Let $I \subset A$ be an ideal.
Set $B = \bigoplus_{n \geq 0} I^n$.
Let $f : X \to \Spec(A)$ be a proper morphism.
Let $\mathcal{F}$ be a coherent sheaf on $X$.
Then for every $p \geq 0$ the graded $B$-module
$\bigoplus_{n \geq 0} H^p(X, I^n\mathcal{F})$ is
a finite $B$-module.

\label{lemma-shrink-complete}
With assumption and notation as in
Definition \ref{definition-shrink-complete}
we have:
\begin{enumerate}
\item
\label{item-shrink-base-complete}
If $S' \subset S$ is a standard open neighbourhood of $s$, then
setting $X' = X_{S'}$, $Z'_k = Z_{S'}$ and $Y'_k = Y_{S'}$ we obtain a
standard shrinking.
\item
\label{item-shrink-on-Y-complete}
Let $W \subset Y_n$ be a standard open neighbourhood of $y$.
Then there exists a standard shrinking with $Y'_n = W \times_S S'$.
\item
\label{item-shrink-on-X-complete}
Let $U \subset X$ be an open neighbourhood of $x$.
Then there exists a standard shrinking with $X' \subset U$.
\end{enumerate}

\label{theorem-gabriel-popescu}
Let $\mathcal{A}$ be a Grothendieck abelian category. Then there exists
a (noncommutative) ring $R$ and functors $G : \mathcal{A} \to \text{Mod}_R$
and $F : \text{Mod}_R \to \mathcal{A}$ such that
\begin{enumerate}
\item $F$ is the left adjoint to $G$,
\item $G$ is fully faithful, and
\item $F$ is exact.
\end{enumerate}
Moreover, the functors are the ones constructed above.

\label{lemma-when-stack-in-sets}
Let $\mathcal{C}$ be a site. Under the equivalence
$$
\left\{
\begin{matrix}
\text{the category of presheaves}\\
\text{of sets over }\mathcal{C}
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{the category of categories}\\
\text{fibred in sets over }\mathcal{C}
\end{matrix}
\right\}
$$
of
Categories, Lemma \ref{categories-lemma-2-category-fibred-sets}
the stacks in sets correspond precisely to the sheaves.

\label{lemma-flat-lci}
\begin{slogan}
Syntomic equals flat plus lci (for algebraic spaces).
\end{slogan}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent
\begin{enumerate}
\item $f$ is flat and a local complete intersection morphism, and
\item $f$ is syntomic.
\end{enumerate}

\label{lemma-when-invertible}
Let $S$ be a graded ring. Set $X = \text{Proj}(S)$.
Let $f \in S$ be homogeneous of degree $d > 0$.
The sheaves $\mathcal{O}_X(nd)|_{D_{+}(f)}$ are invertible,
and in fact trivial for all $n \in \mathbf{Z}$
(see Modules, Definition \ref{modules-definition-invertible}).
The maps (\ref{equation-multiply}) restricted to $D_{+}(f)$
$$
\mathcal{O}_X(nd)|_{D_{+}(f)} \otimes_{\mathcal{O}_{D_{+}(f)}}
\mathcal{O}_X(m)|_{D_{+}(f)}
\longrightarrow
\mathcal{O}_X(nd + m)|_{D_{+}(f)},
$$
the maps (\ref{equation-multiply-on-sheaf}) restricted to $D_+(f)$
$$
\mathcal{O}_X(nd)|_{D_{+}(f)} \otimes_{\mathcal{O}_{D_{+}(f)}}
\mathcal{F}(m)|_{D_{+}(f)}
\longrightarrow
\mathcal{F}(nd + m)|_{D_{+}(f)},
$$
and the maps (\ref{equation-multiply-more-generally})
restricted to $D_{+}(f)$
$$
\widetilde M(nd)|_{D_{+}(f)}
=
\widetilde M|_{D_{+}(f)}
\otimes_{\mathcal{O}_{D_{+}(f)}}
\mathcal{O}_X(nd)|_{D_{+}(f)}
\longrightarrow
\widetilde{M(nd)}|_{D_{+}(f)}
$$
are isomorphisms for all $n, m \in \mathbf{Z}$.

\label{lemma-unramified-formally-unramified}
\begin{slogan}
Unramified morphisms are the same as formally unramified morphism that
are locally of finite type.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is unramified (resp.\ G-unramified), and
\item the morphism $f$ is locally of finite type (resp.\ locally of finite
presentation) and formally unramified.
\end{enumerate}

\label{lemma-resolution-property-finite-number}
Let $X$ be a scheme. Suppose given
\begin{enumerate}
\item a finite affine open covering $X = U_1 \cup \ldots \cup U_m$
\item finite type quasi-coherent ideals $\mathcal{I}_j$
with $V(\mathcal{I}_j) = X \setminus U_j$
\end{enumerate}
Then $X$ has the resolution property if and only if $\mathcal{I}_j$
is the quotient of a finite locally free $\mathcal{O}_X$-module
for $j = 1, \ldots, m$.

\label{lemma-descend-finite-type}
Let $X$ be a scheme. Let $\mathcal{F}$ be an $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is of finite type as an $\mathcal{O}_X$-module, and
\item $\epsilon^*\mathcal{F}$ is of finite type as an
$\mathcal{O}_\etale$-module on the small \'etale site of $X$.
\end{enumerate}
Here $\epsilon$ is as in (\ref{equation-epsilon}).

\label{lemma-affine-flat-Noetherian-CM}
In Situation \ref{situation-shriek} let $f : X \to Y$ be a morphism
of $\textit{FTS}_S$. Let $x \in X$. If $f$ is flat, then
the following are equivalent
\begin{enumerate}
\item $f$ is Cohen-Macaulay at $x$,
\item $f^!\mathcal{O}_Y$ has a unique nonzero cohomology sheaf
in a neighbourhood of $x$.
\end{enumerate}

\label{lemma-finite-dim}
In Situation \ref{situation-contractions} the tangent spaces of
the functor $F$ are finite dimensional.

\label{lemma-identify-pseudo-coherent-noetherian}
Let $S$ be a scheme. Let $X$ be a Noetherian algebraic space over $S$.
Let $E$ be an object of $D_\QCoh(\mathcal{O}_X)$. For
$m \in \mathbf{Z}$ the following are equivalent
\begin{enumerate}
\item $H^i(E)$ is coherent for $i \geq m$ and zero for $i \gg 0$, and
\item $E$ is $m$-pseudo-coherent.
\end{enumerate}
In particular, $E$ is pseudo-coherent if and only if $E$ is an object
of $D^-_{\textit{Coh}}(\mathcal{O}_X)$.

\label{lemma-descending-property-affine}
The property $\mathcal{P}(f) =$``$f$ is affine''
is fpqc local on the base.

\label{proposition-stack-fpqc}
\begin{reference}
Proposition 3.3.6 of ``Intro to Algebraic Stacks'' by
Anatoly Preygel.
\end{reference}
Let $\mathcal{X}$ be an algebraic stack with quasi-affine\footnote{It suffices
to assume ind-quasi-affine.} diagonal. Then
$\mathcal{X}$ satisfies descent for fpqc coverings.

\label{lemma-presentation-rig-smooth}
Let $A$ be a ring. Let $f_1, \ldots, f_m \in A[x_1, \ldots, x_n]$
and set $B = A[x_1, \ldots, x_n]/(f_1, \ldots, f_m)$. Assume $m \leq n$
and set $g = \det_{1 \leq i, j \leq m}(\partial f_j/\partial x_i)$.
Then
\begin{enumerate}
\item $g$ annihilates $\Ext^1_B(\NL_{B/A}, N)$ for every $B$-module $N$,
\item if $n = m$, then multiplication by $g$ on $\NL_{B/A}$ is $0$ in $D(B)$.
\end{enumerate}

\label{lemma-characterize-surjective}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
which is representable by algebraic spaces. The following are equivalent:
\begin{enumerate}
\item $|f| : |\mathcal{X}| \to |\mathcal{Y}|$ is surjective, and
\item $f$ is surjective
(in the sense of Section \ref{section-properties-morphisms}).
\end{enumerate}

\label{lemma-module-quotient-direct-sum}
In Situation \ref{situation-quasi-compact-objects} assume
(\ref{item-enough}) holds.
\begin{enumerate}
\item Every sheaf of sets is the target of a surjective map
whose source is a coproduct $\coprod h_{U_i}^\#$ with $U_i$ in $\mathcal{B}$.
\item If $\mathcal{O}$ is a sheaf of rings, then every $\mathcal{O}$-module
is a quotient of a direct sum $\bigoplus\nolimits j_{U_i!}\mathcal{O}_{U_i}$
with $U_i$ in $\mathcal{B}$.
\end{enumerate}

\label{lemma-divisor-delta-dimension}
Let $(S, \delta)$ be as in Situation \ref{situation-setup}.
Let $X$ be locally of finite type over $S$. Assume $X$ is
integral.
\begin{enumerate}
\item If $Z \subset X$ is an integral closed subscheme, then
the following are equivalent:
\begin{enumerate}
\item $Z$ is a prime divisor,
\item $Z$ has codimension $1$ in $X$, and
\item $\dim_\delta(Z) = \dim_\delta(X) - 1$.
\end{enumerate}
\item If $Z$ is an irreducible component of an effective Cartier
divisor on $X$, then $\dim_\delta(Z) = \dim_\delta(X) - 1$.
\end{enumerate}

\label{lemma-generic-point-in-constructible}
Let $X$ be a scheme and let $E \subset X$ be a locally constructible subset.
Let $\xi \in X$ be a generic point of an irreducible component of $X$.
\begin{enumerate}
\item If $\xi \in E$, then an open neighbourhood of
$\xi$ is contained in $E$.
\item If $\xi \not \in E$, then an open neighbourhood
of $\xi$ is disjoint from $E$.
\end{enumerate}

\label{lemma-characterize-affine}
\begin{reference}
\cite[II, Corollary 1.3.2]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item The morphism $f$ is affine.
\item There exists an affine open covering $S = \bigcup W_j$
such that each $f^{-1}(W_j)$ is affine.
\item There exists a quasi-coherent sheaf of $\mathcal{O}_S$-algebras
$\mathcal{A}$ and an isomorphism
$X \cong \underline{\Spec}_S(\mathcal{A})$
of schemes over $S$. See
Constructions, Section \ref{constructions-section-spec} for notation.
\end{enumerate}
Moreover, in this case $X = \underline{\Spec}_S(f_*\mathcal{O}_X)$.

\label{lemma-closed-is-complete}
Let $I \subset R$ be an ideal of a ring. Let $M$ be an $I$-adically complete
$R$-module and let $N \subset M$ be a submodule. The following are equivalent
\begin{enumerate}
\item $N$ is closed in $M$,
\item $N = \bigcap_{n \geq 1} (N + I^n M)$,
\item $M/N$ is $I$-adically complete
\end{enumerate}
If $I$ is finitely generated, these conditions imply that $N$
is $I$-adically complete.

\label{lemma-variant-torsors-sheaf-stack-in-groupoids}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p :
\mathcal{G}/\mathcal{B}\textit{-Torsors}
\longrightarrow
(\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{lemma-open-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is open''
is fppf local on the source.

\label{lemma-cd-maximal}
Let $(A, \mathfrak m)$ be a Noetherian local ring of dimension $d$.
Then $H^d_\mathfrak m(A)$ is nonzero and $\text{cd}(A, \mathfrak m) = d$.

\label{lemma-universal-finite-syntomic}
With notation as in Example \ref{example-universal-finite-syntomic}
there is an open subscheme $U_d \subset X_d$ with the following property:
a morphism of schemes $X \to X_d$ factors through $U_d$ if and only
if $Y_d \times_{X_d} X \to X$ is syntomic.

\label{lemma-injective-epimorphism}
Let $R \to S$ be an epimorphism of rings. Let $E$ be an $S$-module.
If $E$ is injective as an $R$-module, then $E$ is an injective $S$-module.

\label{lemma-skyscraper-modules-exact}
Let $(\Sh(\mathcal{C}), \mathcal{O})$ be a ringed topos.
Let $p$ be a point of the topos $\Sh(\mathcal{C})$.
\begin{enumerate}
\item The functor
$p_* : \textit{Mod}(\mathcal{O}_p) \to \textit{Mod}(\mathcal{O})$,
$M \mapsto p_*M$ is exact.
\item The canonical surjection $p^{-1}p_*M \to M$ is $\mathcal{O}_p$-linear.
\item The functorial direct sum decomposition
$p^{-1}p_*M = M \oplus I(M)$ of Lemma \ref{lemma-skyscraper-exact}
is {\bf not} $\mathcal{O}_p$-linear in general.
\end{enumerate}

\label{lemma-projection-formula-flat}
\begin{reference}
See \cite[Chapter V, C), Section 7, formula (10)]{Serre_algebre_locale}
for a more general formula.
\end{reference}
Let $f : X \to Y$ be a flat proper morphism of nonsingular varieties.
Set $e = \dim(X) - \dim(Y)$. Let $\alpha$ be an $r$-cycle on $X$ and let
$\beta$ be a $s$-cycle on $Y$. Assume that $\alpha$ and $f^*(\beta)$ intersect
properly. Then $f_*(\alpha)$ and $\beta$ intersect properly and
$$
f_*(\alpha) \cdot \beta = f_*( \alpha \cdot f^*\beta)
$$

\label{lemma-smooth-properties}
Let $\varphi : \mathcal{F} \to \mathcal{G}$ and $\psi : \mathcal{G}
\to \mathcal{H}$ be morphisms of categories cofibered in groupoids over
$\mathcal{C}_\Lambda$.
\begin{enumerate}
\item If $\varphi$ and $\psi$ are smooth, then $\psi \circ \varphi$ is smooth.
\item If $\varphi$ is essentially surjective and $\psi \circ \varphi$ is
smooth, then $\psi$ is smooth.
\item If $\mathcal{G}' \to \mathcal{G}$ is a morphism of categories
cofibered in groupoids and $\varphi$ is smooth, then
$\mathcal{F} \times_\mathcal{G} \mathcal{G}' \to \mathcal{G}'$ is smooth.
\end{enumerate}

\label{lemma-resolution-property-goes-down-finite-flat}
Let $f : X \to Y$ be a surjective finite locally free morphism of schemes.
If $X$ has the resolution property, so does $Y$.

\label{lemma-spaces-RS-star}
Let
$$
\xymatrix{
T \ar[r] \ar[d] & T' \ar[d] \\
S \ar[r] & S'
}
$$
be a pushout in the category of schemes where
$T \to T'$ is a thickening and $T \to S$ is affine, see
More on Morphisms, Lemma \ref{more-morphisms-lemma-pushout-along-thickening}.
Then the functor on fibre categories
$$
\begin{matrix}
\Spacesstack'_{fp, flat, proper, S'} \\
\downarrow \\
\Spacesstack'_{fp, flat, proper, S}
\times_{\Spacesstack'_{fp, flat, proper, T}}
\Spacesstack'_{fp, flat, proper, T'}
\end{matrix}
$$
is an equivalence.

\label{lemma-zariski-etale-smooth}
Any \'etale covering is a smooth covering, and a fortiori,
any Zariski covering is a smooth covering.

\label{lemma-compare-cohomology-etale-ph}
Let $S$ be a scheme and let $X$ be an algebraic space over $S$.
With $a_X : \Sh((\textit{Spaces}/X)_{ph}) \to \Sh(X_\etale)$
as above:
\begin{enumerate}
\item $H^q(X_\etale, \mathcal{F}) = H^q_{ph}(X, a_X^{-1}\mathcal{F})$
for a torsion abelian sheaf $\mathcal{F}$ on $X_\etale$,
\item $H^q(X_\etale, K) = H^q_{ph}(X, a_X^{-1}K)$ for $K \in D^+(X_\etale)$
with torsion cohomology sheaves
\end{enumerate}
Example: if $A$ is a torsion abelian group, then
$H^q_\etale(X, \underline{A}) = H^q_{ph}(X, \underline{A})$.

\label{lemma-adic-homomorphism}
Let $A$ and $B$ be pre-adic topological rings. Let
$\varphi : A \to B$ be a continuous ring homomorphism.
\begin{enumerate}
\item If $\varphi$ is adic, then $\varphi$ is taut.
\item If $B$ is complete, $A$ has a finitely generated
ideal of definition, and $\varphi$ is taut, then $\varphi$ is adic.
\end{enumerate}
In particular the conditions ``$\varphi$ is adic'' and ``$\varphi$ is taut''
are equivalent on the category $\textit{WAdm}^{adic*}$.

\label{lemma-unramified-quasi-finite}
If $f$ is unramified at $x$ then $f$ is quasi-finite at $x$.
In particular, an unramified morphism is locally quasi-finite.

\label{proposition-characterize-locally-finite-presentation}
\begin{reference}
This is a special case of \cite[Lemma 2.3.15]{Emerton-Gee}
\end{reference}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent
\begin{enumerate}
\item $f$ is limit preserving,
\item $f$ is limit preserving on objects, and
\item $f$ is locally of finite presentation.
\end{enumerate}

\label{lemma-proper-flat-geom-red-connected}
Let $f : X \to S$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is proper, flat, and of finite presentation, and
\item the geometric fibres of $f$ are reduced and connected.
\end{enumerate}
Then $f_*\mathcal{O}_X = \mathcal{O}_S$ and this holds
after any base change.

\label{lemma-eventually-relative-dimension}
Assumptions and notation as in Situation \ref{situation-descent-property}.
Let $d \geq 0$. If
\begin{enumerate}
\item $f$ has relative dimension $\leq d$
(Morphisms of Spaces, Definition
\ref{spaces-morphisms-definition-relative-dimension}), and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i$ such that $f_i$ has relative dimension $\leq d$.

\label{lemma-scheme-theoretic-image-reduced}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Assume $X$ is reduced. Then
\begin{enumerate}
\item the scheme theoretic image $Z$ of $f$ is the reduced induced algebraic
space structure on $\overline{|f|(|X|)}$, and
\item for any \'etale morphism $V \to Y$ the scheme theoretic image of
$X \times_Y V \to V$ is equal to $Z \times_Y V$.
\end{enumerate}

\label{theorem-dilatations-general}
Let $S$ be a scheme. Let $X$ be a locally Noetherian algebraic space over $S$.
Let $T \subset |X|$ be a closed subset. Let $U \subset X$ be the open subspace
with $|U| = |X| \setminus T$. The completion functor
(\ref{equation-completion-functor})
$$
\left\{
\begin{matrix}
\text{morphisms of algebraic spaces}\\
f : X' \to X\text{ which are locally}\\
\text{of finite type and such that}\\
f^{-1}U \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{morphisms }g : W \to X_{/T}\\
\text{of formal algebraic spaces}\\
\text{with }W\text{ locally Noetherian}\\
\text{and }g\text{ rig-\'etale}
\end{matrix}
\right\}
$$
sending $f : X' \to X$ to $f_{/T} : X'_{/T'} \to X_{/T}$ is an equivalence.

\label{lemma-hilb-d-An}
Let $X \to S$ be a morphism of affine schemes. Let $d \geq 0$. Then
$\Hilbfunctor^d_{X/S}$ is representable.

\label{lemma-residual-gerbe-regular}
A reduced, locally Noetherian algebraic stack $\mathcal{Z}$ such that
$|\mathcal{Z}|$ is a singleton is regular.

\label{lemma-isom-pseudo-torsor-aut}
Let $\mathcal{X}$ be an algebraic stack.
Let $T$ be a scheme and let $x, y$ be objects of the fibre category of
$\mathcal{X}$ over $T$. Then
\begin{enumerate}
\item $\mathit{Isom}_\mathcal{X}(y, y)$ is a group algebraic space
over $T$, and
\item $\mathit{Isom}_\mathcal{X}(x, y)$ is a pseudo torsor for
$\mathit{Isom}_\mathcal{X}(y, y)$ over $T$.
\end{enumerate}

\label{lemma-intersection-number-integer}
In the situation of Definition \ref{definition-intersection-number}
the intersection number
$(\mathcal{L}_1 \cdots \mathcal{L}_d \cdot Z)$
is an integer.

\label{lemma-modules-abelian}
Let $G$ be a topological group. Let $R$ be a ring.
For every $i \geq 0$ the diagram
$$
\xymatrix{
\text{Mod}_{R, G} \ar[rr]_{H^i(G, -)} \ar[d] & &
\text{Mod}_R \ar[d] \\
\text{Mod}_G \ar[rr]^{H^i(G, -)} & &
\textit{Ab}
}
$$
whose vertical arrows are the forgetful functors is commutative.

\label{lemma-criterion-proper}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Assume $f$ is of finite type and quasi-separated.
Then the following are equivalent
\begin{enumerate}
\item $f$ is proper, and
\item $f$ satisfies both the uniqueness and existence parts
of the valuative criterion.
\end{enumerate}

\label{lemma-there-is-a-scheme-integral-over}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$.
\begin{enumerate}
\item There exists a surjective integral morphism $Y \to X$ where $Y$
is a scheme,
\item given a surjective \'etale morphism $U \to X$ we may choose
$Y \to X$ such that for every $y \in Y$ there is an open neighbourhood
$V \subset Y$ such that $V \to X$ factors through $U$.
\end{enumerate}

\label{lemma-action-by-derivations-etale-localization}
Let $S$ be a scheme. Consider a commutative diagram of first order
thickenings
$$
\vcenter{
\xymatrix{
(T_2 \subset T_2') \ar[d]_{(h, h')} \ar[rr]_{(a_2, a_2')} & &
(X_2 \subset X_2') \ar[d]^{(f, f')} \\
(T_1 \subset T_1') \ar[rr]^{(a_1, a_1')} & &
(X_1 \subset X_1')
}
}
\quad
\begin{matrix}
\text{and a commutative} \\
\text{diagram}
\end{matrix}
\quad
\vcenter{
\xymatrix{
X_2' \ar[r] \ar[d] & B_2 \ar[d] \\
X_1' \ar[r] & B_1
}
}
$$
of algebraic spaces over $S$
with $X_2 \to X_1$ and $B_2 \to B_1$ \'etale.
For any $\mathcal{O}_{T_1}$-linear map
$\theta_1 : a_1^*\Omega_{X_1/B_1} \to \mathcal{C}_{T_1/T'_1}$ let
$\theta_2$ be the composition
$$
\xymatrix{
a_2^*\Omega_{X_2/B_2} \ar@{=}[r] &
h^*a_1^*\Omega_{X_1/B_1} \ar[r]^-{h^*\theta_1} &
h^*\mathcal{C}_{T_1/T'_1} \ar[r] &
\mathcal{C}_{T_2/T'_2}
}
$$
(equality sign is explained in the proof). Then the diagram
$$
\xymatrix{
T_2' \ar[rr]_{\theta_2 \cdot a_2'} \ar[d] & & X'_2 \ar[d] \\
T_1' \ar[rr]^{\theta_1 \cdot a_1'} & & X'_1
}
$$
commutes where the actions $\theta_2 \cdot a_2'$ and $\theta_1 \cdot a_1'$
are as in Remark \ref{remark-action-by-derivations}.

\label{lemma-tau-nonzero}
Let $k$ be a field and let $A$ be a finite $k$-algebra. Assume $A$
is local with residue field $k'$. The following are equivalent
\begin{enumerate}
\item $\text{Trace}_{A/k}$ is nonzero,
\item $\tau_{A/k} \in \omega_{A/k}$ is nonzero, and
\item $k'/k$ is separable and $\text{length}_A(A)$ is prime
to the characteristic of $k$.
\end{enumerate}

\label{lemma-get-a-stack}
\begin{reference}
Lemma in an email of Matthew Emerton dated June 15, 2016
\end{reference}
Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $\mathcal{X} \to \mathcal{Z}$ and $\mathcal{Y} \to \mathcal{Z}$
be $1$-morphisms of categories fibred in groupoids over $(\Sch/S)_{fppf}$.
If $\mathcal{X} \to \mathcal{Z}$ is representable by algebraic spaces
and $\mathcal{Y}$ is a stack in groupoids, then
$\mathcal{X} \times_\mathcal{Z} \mathcal{Y}$ is a stack in groupoids.

\label{lemma-length-closed-immersion}
Let $S$ be a scheme. Let $i : Y \to X$ be a closed immersion of
algebraic spaces over $S$. Let $\mathcal{G}$ be a quasi-coherent
$\mathcal{O}_Y$-module. Let $y \in |Y|$ with image $x \in |X|$.
Let $d \in \{0, 1, 2, \ldots, \infty\}$. The following are
equivalent
\begin{enumerate}
\item $\mathcal{G}$ has length $d$ at $y$, and
\item $i_*\mathcal{G}$ has length $d$ at $x$.
\end{enumerate}

\label{lemma-get-openness-obstruction-theory}
\begin{reference}
This is \cite[Theorem 4.4]{Hall-coherent}
\end{reference}
Let $S$ be a locally Noetherian scheme. Let $\mathcal{X}$ be a category fibred
in groupoids over $(\Sch/S)_{fppf}$. Assume
\begin{enumerate}
\item $\Delta : \mathcal{X} \to \mathcal{X} \times \mathcal{X}$ is
representable by algebraic spaces,
\item $\mathcal{X}$ has (RS*),
\item $\mathcal{X}$ is limit preserving,
\item there exists an obstruction theory\footnote{Analyzing the proof
the reader sees that in fact it suffices to check
the functoriality (ii) of obstruction classes in
Definition \ref{definition-obstruction-theory}
for maps $(y, B' \to B) \to (x, A' \to A)$
with $B = A$ and $y = x$.},
\item for an object $x$ of $\mathcal{X}$ over $\Spec(A)$
and $A$-modules $M_n$, $n \geq 1$ we have
\begin{enumerate}
\item $T_x(\prod M_n) = \prod T_x(M_n)$,
\item $\mathcal{O}_x(\prod M_n) \to \prod \mathcal{O}_x(M_n)$
is injective.
\end{enumerate}
\end{enumerate}
Then $\mathcal{X}$ satisfies openness of versality.

\label{lemma-property-spaces-too}
Let $P$ be a property of morphisms of algebraic spaces as above.
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
representable by algebraic spaces. The following are equivalent:
\begin{enumerate}
\item $f$ has $P$,
\item for every algebraic space $Z$ and morphism $Z \to \mathcal{Y}$
the morphism $Z \times_\mathcal{Y} \mathcal{X} \to Z$ has $P$.
\end{enumerate}

\label{lemma-prestable-one-piece-per-genus}
There is a decomposition into open and closed substacks
$$
\Curvesstack^{prestable} = \coprod\nolimits_{g \geq 0}
\Curvesstack^{prestable}_g
$$
where each $\Curvesstack^{prestable}_g$ is characterized as follows:
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{prestable}_g$,
\item $X \to S$ is a prestable family of curves and
$R^1f_*\mathcal{O}_X$ is a locally free $\mathcal{O}_S$-module of rank $g$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}_g$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and the genus of $X$ is $g$.
\end{enumerate}
\end{enumerate}

\label{theorem-bondal-van-den-bergh}
\begin{reference}
In the projective case this is \cite[Theorem A.1]{BvdB}
\end{reference}
Let $X$ be a proper scheme over a field $k$.
Let $F : D_{perf}(\mathcal{O}_X)^{opp} \to \text{Vect}_k$
be a $k$-linear cohomological functor such that
$$
\sum\nolimits_{n \in \mathbf{Z}} \dim_k F(E[n]) < \infty
$$
for all $E \in D_{perf}(\mathcal{O}_X)$. Then $F$ is isomorphic to a functor
of the form $E \mapsto \Hom_X(E, K)$ for some
$K \in D^b_{\textit{Coh}}(\mathcal{O}_X)$.

\label{lemma-base-change-finite-type}
A base change of a finite type morphism is finite type.
The same holds for locally of finite type.

\label{lemma-coherent-on-projective-space}
Let $k$ be a field. Let $n \geq 0$. Let
$K \in D_\QCoh(\mathcal{O}_{\mathbf{P}^n_k})$.
The following are equivalent
\begin{enumerate}
\item $K$ is in $D^b_{\textit{Coh}}(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}}
\dim_k H^i(\mathbf{P}^n_k, E \otimes^\mathbf{L} K) < \infty$
for each perfect object $E$ of
$D(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}}
\dim_k \Ext^i_{\mathbf{P}^n_k}(E, K) < \infty$
for each perfect object $E$ of $D(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}} \dim_k H^i(\mathbf{P}^n_k,
K \otimes^\mathbf{L} \mathcal{O}_{\mathbf{P}^n_k}(d)) < \infty$
for $d = 0, 1, \ldots, n$.
\end{enumerate}

\label{lemma-set-theoretically-invariant-invariant-when-reduced}
In the situation of Definition \ref{definition-set-theoretically-invariant}.
Let $\phi : U \to X$ be a morphism of algebraic spaces over $B$.
Assume
\begin{enumerate}
\item $\phi$ is set-theoretically $R$-invariant,
\item $R$ is reduced, and
\item $X$ is locally separated over $B$.
\end{enumerate}
Then $\phi$ is $R$-invariant.

\label{lemma-restate-axiom-c}
In Situation \ref{situation-ABC}
let $f: x \to y$ be a morphism in $\text{Comp}(\mathcal{A})$.
The triangle $(y, c(f), x[1], i, p, f[1])$ is the triangle associated
to the admissible short exact sequence 
$$
\xymatrix{y\ar[r] & c(f) \ar[r] & x[1]}
$$
where the cone $c(f)$ is defined as in Lemma \ref{lemma-get-triangle}.

\label{lemma-cd-is-one}
Let $I \subset A$ be a finitely generated ideal of a ring $A$. If
$\text{cd}(A, I) = 1$ then $\Spec(A) \setminus V(I)$ is nonempty affine.

\label{lemma-chevalley}
Let $f : X \to Y$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $f$ is quasi-compact and locally of finite presentation, and
\item $Y$ is quasi-compact and quasi-separated.
\end{enumerate}
Then the image of every constructible subset of $X$ is constructible in $Y$.

\label{lemma-base-change-universally-closed}
The base change of a universally closed morphism of algebraic stacks
by any morphism of algebraic stacks is universally closed.

\label{lemma-family-of-curves-not-scheme}
There exists a field $k$ and a family of curves
$X \to \mathbf{A}^1_k$ such that $X$ is not a scheme.

\label{lemma-compare-injectives}
Let $S$ be a scheme.
Let $Y \to X$ be a morphism of $(\textit{Spaces}/S)_\etale$.
\begin{enumerate}
\item If $\mathcal{I}$ is injective in
$\textit{Ab}((\textit{Spaces}/X)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}$ is injective in $\textit{Ab}(Y_\etale)$,
\item $\mathcal{I}|_{X_\etale}$ is injective in $\textit{Ab}(X_\etale)$,
\end{enumerate}
\item If $\mathcal{I}^\bullet$ is a K-injective complex
in $\textit{Ab}((\textit{Spaces}/X)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(Y_\etale)$,
\item $\mathcal{I}^\bullet|_{X_\etale}$ is a K-injective complex in
$\textit{Ab}(X_\etale)$,
\end{enumerate}
\end{enumerate}
The corresponding statements for modules do not hold.

\label{lemma-functor-and-cycles}
Let $f : Y \to X$ be a morphism of smooth projective schemes over $k$.
Let $[\Gamma_f] \in \text{Corr}^0(X, Y)$ be as in
Example \ref{example-graph-correspondence}. Then
\begin{enumerate}
\item pushforward of cycles by the correspondence $[\Gamma_f]$
agrees with the Gysin map $f^! : \CH^*(X) \to \CH^*(Y)$,
\item pullback of cycles by the correspondence $[\Gamma_f]$
agrees with the pushforward map $f_* : \CH_*(Y) \to \CH_*(X)$,
\item if $X$ and $Y$ are equidimensional of dimensions $d$ and $e$,
then
\begin{enumerate}
\item pushforward of cycles by the correspondence
$[\Gamma_f^t]$ of Remark \ref{remark-transpose}
corresponds to pushforward of cycles by $f$, and
\item pullback of cycles by the correspondence
$[\Gamma_f^t]$ of Remark \ref{remark-transpose}
corresponds to the Gysin map $f^!$.
\end{enumerate}
\end{enumerate}

\label{lemma-eventually-separated}
Let $S$ be a scheme. Let $Y$ be an algebraic space over $S$.
Let $X = \lim X_i$ be a directed limit of algebraic spaces over $Y$
with affine transition morphisms. Assume
\begin{enumerate}
\item $Y$ is quasi-separated,
\item $X_i$ is quasi-compact and quasi-separated,
\item the morphism $X \to Y$ is separated.
\end{enumerate}
Then $X_i \to Y$ is separated for all $i$ large enough.

\label{lemma-algebraic-residue-field-extension-closed-point-fibre}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$ be a point. Set $s = f(x)$.
If $\kappa(x)/\kappa(s)$
is an algebraic field extension, then
\begin{enumerate}
\item $x$ is a closed point of its fibre, and
\item if in addition $s$ is a closed point of $S$, then
$x$ is a closed point of $X$.
\end{enumerate}

\label{lemma-dgm-abelian}
Let $(A, d)$ be a differential graded algebra. The category
$\text{Mod}_{(A, \text{d})}$ is abelian and has arbitrary limits and colimits.

\label{lemma-finite-disjoint-quasi-compact}
A finite disjoint union of quasi-compact algebraic spaces is
a quasi-compact algebraic space.

\label{lemma-identifies-residue-fields}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of decent
algebraic spaces over $S$. Let $x \in |X|$ be a point
with image $y = f(x) \in |Y|$.
The following are equivalent
\begin{enumerate}
\item $f$ induces an isomorphism $\kappa(y) \to \kappa(x)$, and
\item the induced morphism $\Spec(\kappa(x)) \to Y$ is a monomorphism.
\end{enumerate}

\label{lemma-schemes-morphisms-RS}
Example \ref{example-schemes-morphisms}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{X \to Y}$ is a deformation category
for any morphism of schemes $X \to Y$ over $k$.

\label{lemma-check-on-generators}
Let $A$ be a ring. Let $I$ be an ideal of $A$. Let $\gamma_n : I \to I$,
$n \geq 1$ be a sequence of maps. Assume
\begin{enumerate}
\item[(a)] (1), (3), and (4) of Definition \ref{definition-divided-powers}
hold for all $x, y \in I$, and
\item[(b)] properties (2) and (5) hold for $x$ in
some set of generators of $I$ as an ideal.
\end{enumerate}
Then $\gamma$ is a divided power structure on $I$.

\label{lemma-compose-after-separated}
Let $S$ be a scheme.
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of algebraic spaces over $S$.
\begin{enumerate}
\item If $g \circ f$ is separated then so is $f$.
\item If $g \circ f$ is locally separated then so is $f$.
\item If $g \circ f$ is quasi-separated then so is $f$.
\end{enumerate}

\label{proposition-when-gerbe-over}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is a gerbe over $\mathcal{Y}$, and
\item $f : \mathcal{X} \to \mathcal{Y}$ and
$\Delta : \mathcal{X} \to \mathcal{X} \times_\mathcal{Y} \mathcal{X}$
are surjective, flat, and locally of finite presentation.
\end{enumerate}

\label{lemma-spectral-qcqs}
Let $\mathcal{X}$ be a quasi-compact and quasi-separated algebraic stack.
Then $|\mathcal{X}|$ is a spectral topological space.

\label{lemma-groupoid-characteristic-zero-smooth}
Let $S$ be a scheme. Let $(U, R, s, t, c)$ be a groupoid scheme
over $S$. Assume
\begin{enumerate}
\item $U = \Spec(k)$ with $k$ a field,
\item $s, t$ are locally of finite type, and
\item the characteristic of $k$ is zero.
\end{enumerate}
Then $s, t : R \to U$ are smooth.

\label{lemma-id-cone-null}
In Situation \ref{situation-ABC}
given any object $x$ of $\mathcal{A}$, and the cone $C(1_x)$ of the
identity morphism $1_x : x \to x$, the identity morphism on
$C(1_x)$ is homotopic to zero.

\label{lemma-ind-etale-implies}
Let $A \to B$ be ind-\'etale. Then $A \to B$ is weakly \'etale
(More on Algebra, Definition \ref{more-algebra-definition-weakly-etale}).

\label{lemma-pic-functor-qs-lfp}
The morphism $\Picardfunctor_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{lemma-relative-effective-cartier-algebra}
Let $A \to B$ be a ring map. Let $f \in B$. Assume that
\begin{enumerate}
\item $A \to B$ is flat,
\item $f$ is a nonzerodivisor, and
\item $A \to B/fB$ is flat.
\end{enumerate}
Then for every ideal $I \subset A$ the map
$f : B/IB \to B/IB$ is injective.

\label{lemma-smoothing-curve-isolated-lci}
Let $k$ be a field and let $X$ be a scheme over $k$. Assume
\begin{enumerate}
\item $X$ is separated, finite type over $k$ and $\dim(X) \leq 1$,
\item $X$ is a local complete intersection over $k$, and
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
Then there exists a flat, separated, finite type morphism $Y \to \Spec(k[[t]])$
whose generic fibre is smooth and whose special fibre is
isomorphic to $X$.

\label{lemma-completion-polynomial-ring-not-flat}
There exists a ring such that the completion $R[[x]]$ of $R[x]$
at $(x)$ is not flat over $R$ and a fortiori not flat over $R[x]$.

\label{lemma-prestable-curves}
There exist an open substack $\Curvesstack^{prestable} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{prestable}$,
\item $X \to S$ is a prestable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
and $k = H^0(X, \mathcal{O}_X)$.
\end{enumerate}
\end{enumerate}

\label{lemma-normal-integral-sections}
Let $S$ be a scheme. Let $X$ be a normal integral algebraic space over $S$.
Then $\Gamma(X, \mathcal{O}_X)$ is a normal domain.

\label{lemma-blowup-still-good}
Let $(A, \mathfrak m, \kappa)$ be a Nagata local normal domain of
dimension $2$. Assume $A$ defines a rational singularity and that
the completion $A^\wedge$ of $A$ is normal. Then
\begin{enumerate}
\item $A^\wedge$ defines a rational singularity, and
\item if $X \to \Spec(A)$ is the blowing up in $\mathfrak m$, then
for a closed point $x \in X$ the completion $\mathcal{O}_{X, x}$ is normal.
\end{enumerate}

\label{lemma-trace-unique}
Let $A \to B$ be a flat quasi-finite map of Noetherian rings.
Then there is at most one trace element in $\omega_{B/A}$.

\label{lemma-in-smooth-locus}
In the situation above the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through the open where $\Curvesstack \to \Spec(\mathbf{Z})$ is smooth,
\item the deformation category $\Deformationcategory_X$ is unobstructed.
\end{enumerate}

\label{theorem-descent-modules}
If $A \to B$ is faithfully flat then descent data with respect to $A\to B$
are effective.

\label{lemma-bounded-below}
If $U = \Spec(A)$ is an affine scheme, then the bounded
below version
\begin{equation}
\label{equation-compare-bounded-adequate}
D^+(\textit{Adeq}(\mathcal{O}))
\longrightarrow
D^+_{\textit{Adeq}}(\mathcal{O})
\end{equation}
of the functor above is an equivalence.

\label{lemma-get-a-closed}
Let $f : X \to S$ and $\mathcal{E}$ be as in
Lemma \ref{lemma-diagonal-picard-flat-proper}
and in addition assume $\mathcal{E}$ is an invertible $\mathcal{O}_X$-module.
If moreover the geometric fibres of $f$ are
integral, then $Z$ is closed in $S$.

\label{lemma-well-nigh-affine}
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is well-nigh affine, and
\item there exists a groupoid scheme $(U, R, s, t, c)$ with $U$ and
$R$ affine and $s, t : R \to U$ finite locally free such that
$\mathcal{X} = [U/R]$.
\end{enumerate}
If true then $\mathcal{X}$ is quasi-compact, quasi-DM, and separated.

\label{lemma-check-universally-injective}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic
spaces over $S$. Assume
\begin{enumerate}
\item $f$ is locally of finite type,
\item for every \'etale morphism $V \to Y$ the map $|X \times_Y V| \to |V|$
is injective.
\end{enumerate}
Then $f$ is universally injective.

\label{lemma-smooth}
In Example \ref{example-rings} let $P$ be a smooth $k$-algebra. Then
$T\Deformationcategory_P = (0)$.

\label{lemma-lifting-along-small-extension}
Consider a commutative diagram in a predeformation category $\mathcal{F}$
$$
\vcenter{
\xymatrix{
y \ar[r] \ar[d] & x_2 \ar[d]^{a_2} \\
x_1 \ar[r]^{a_1}        & x
}
}
\quad\text{lying over}
\vcenter{
\xymatrix{
A_1 \times_A A_2 \ar[r] \ar[d] & A_2 \ar[d]^{f_2} \\
A_1 \ar[r]^{f_1} & A
}
}
$$
in $\mathcal{C}_\Lambda$ where
$f_2 : A_2 \to A$ is a small extension.
Assume there is a map $h : A_1 \to A_2$ such that $f_2 = f_1 \circ h$.
Let $I = \Ker(f_2)$. Consider the ring map
$$
g : A_1 \times_A A_2 \longrightarrow k[I] = k \oplus I, \quad
(u, v) \longmapsto \overline{u} \oplus (v - h(u))
$$
Choose a pushforward $y \to g_*y$. Assume $\mathcal{F}$ satisfies (S2).
If there exists a morphism $x_1 \to g_*y$, then there exists a
morphism $b: x_1 \to x_2$ such that $a_1 =  a_2 \circ b$.

\label{lemma-universally-injective}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item the map $X(K) \to Y(K)$ is injective for every field $K$ over $S$
\item for every morphism $Y' \to Y$ of algebraic spaces over $S$
the induced map $|Y' \times_Y X| \to |Y'|$ is injective, and
\item the diagonal morphism $X \to X \times_Y X$ is surjective.
\end{enumerate}

\label{lemma-set-points-where-fibres-smooth}
Let
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
S' \ar[r]^g & S
}
$$
be a cartesian diagram of schemes. Let $W \subset X$, resp.\ $W' \subset X'$
be the open subscheme of points where $f$, resp.\ $f'$ is smooth.
Then $W' = (g')^{-1}(W)$ if
\begin{enumerate}
\item $f$ is flat and locally of finite presentation, or
\item $f$ is locally of finite presentation and $g$ is flat.
\end{enumerate}

\label{lemma-flat-dedekind-complementary-module-trace}
If the Dedekind different of $A \to B$ is defined and $A \to B$ is flat, then
\begin{enumerate}
\item the canonical isomorphism $\mathcal{L}_{B/A} \to \omega_{B/A}$
sends $1 \in \mathcal{L}_{B/A}$ to the trace element
$\tau_{B/A} \in \omega_{B/A}$, and
\item the Dedekind different is
$\mathfrak{D}_{B/A} = \{b \in B \mid b\omega_{B/A} \subset B\tau_{B/A}\}$.
\end{enumerate}

\label{lemma-affine-thickenings-colimits}
In Situation \ref{situation-affine}.
\begin{enumerate}
\item $\text{CRIS}(C/A)$ has finite products (but not infinite ones),
\item $\text{CRIS}(C/A)$ has all finite nonempty colimits and
(\ref{equation-forget-affine}) commutes with these, and
\item $\text{Cris}(C/A)$ has all finite nonempty colimits and
$\text{Cris}(C/A) \to \text{CRIS}(C/A)$ commutes with them.
\end{enumerate}

\label{lemma-smooth-etale-permanence}
Let $X \to Y \to Z$ be morphisms of schemes. Assume $X \to Z$ smooth
and $Y \to Z$ \'etale. Then $X \to Y$ is smooth.

\label{lemma-descent-ascent}
Let $\varphi : A \to B$ be a homomorphism of Noetherian rings. Assume
\begin{enumerate}
\item $A \to B$ is syntomic and induces a surjective map on spectra, or
\item $A \to B$ is a faithfully flat local complete intersection, or
\item $A \to B$ is faithfully flat of finite type with Gorenstein fibres.
\end{enumerate}
Then $K \in D(A)$ is a dualizing complex for $A$ if and only if
$K \otimes_A^\mathbf{L} B$ is a dualizing complex for $B$.

\label{lemma-perfect}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $E$ be an object of $D(\mathcal{O})$.
The following are equivalent
\begin{enumerate}
\item $E$ is perfect, and
\item $E$ is pseudo-coherent and locally has finite tor dimension.
\end{enumerate}

\label{proposition-presheaves-injectives}
For abelian presheaves on a category there is a functorial injective
embedding.

\label{lemma-pseudo-coherent-hocolim}
Let $S$ be a scheme.
Let $X$ be a quasi-compact and quasi-separated algebraic space over $S$.
Let $K \in D(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item $K$ is pseudo-coherent, and
\item $K = \text{hocolim} K_n$ where
$K_n$ is perfect and $\tau_{\geq -n}K_n \to \tau_{\geq -n}K$
is an isomorphism for all $n$.
\end{enumerate}

\label{lemma-RS-fiber-square}
Let $\mathcal{F}$ be a category cofibered in groupoids over
$\mathcal{C}_\Lambda$ satisfying (RS). Given a commutative diagram
in $\mathcal{F}$
$$
\vcenter{
\xymatrix{
y \ar[r] \ar[d] & x_2 \ar[d]   \\
x_1 \ar[r]      & x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
A_1 \times_A A_2 \ar[r] \ar[d] & A_2 \ar[d] \\
A_1 \ar[r]      & A.
}
}
$$
with $A_2 \to A$ surjective, then it is a fiber square.

\label{lemma-properties-covering-imply-diagonal}
Let $\mathcal{X}$ be an algebraic stack.
Let $W$ be an algebraic space, and let $f : W \to \mathcal{X}$
be a surjective, flat, locally finitely presented morphism.
\begin{enumerate}
\item If $f$ is unramified (i.e., \'etale, i.e., $\mathcal{X}$
is Deligne-Mumford), then $\mathcal{X}$ is DM.
\item If $f$ is locally quasi-finite, then $\mathcal{X}$ is quasi-DM.
\end{enumerate}

\label{lemma-descending-fppf-property-immersion}
The property $\mathcal{P}(f) =$``$f$ is an immersion''
is fppf local on the base.

\label{lemma-relative-isomorphism-approximation}
With notation an assumptions as in Lemma \ref{lemma-relative-map-approximation}
assume that $\varphi$ induces an isomorphism on completions.
Then we can choose our diagram such that $f$ is \'etale.

\label{lemma-derived-diagonal}
Let $A \to B$ be a ring map such that $B = B \otimes_A^\mathbf{L} B$.
Then $L_{B/A} = 0$ in $D(B)$.

\label{lemma-essential-extensions-in-injective}
Let $R$ be a ring. Let $I$ be an injective $R$-module. Let $E \subset I$
be a submodule. The following are equivalent
\begin{enumerate}
\item $E$ is injective, and
\item for all $E \subset E' \subset I$ with $E \subset E'$ essential
we have $E = E'$.
\end{enumerate}
In particular, an $R$-module is injective if and only if every essential
extension is trivial.

\label{lemma-F-zero-closed-pure}
In Situation \ref{situation-iso}. Assume
\begin{enumerate}
\item $f$ is of finite presentation, and
\item $\mathcal{G}$ is of finite presentation,
flat over $B$, and pure relative to $B$.
\end{enumerate}
Then $F_{zero}$ is an algebraic space and $F_{zero} \to B$
is a closed immersion. If $\mathcal{F}$ is of finite type, then
$F_{zero} \to B$ is of finite presentation.

\label{lemma-local-source-target-global-implies-local}
Let $\mathcal{P}$ be a property of morphisms of schemes
which is \'etale local on the source-and-target.
Consider the property $\mathcal{Q}$ of morphisms
of germs associated to $\mathcal{P}$ in
Descent, Lemma \ref{descent-lemma-local-source-target-global-implies-local}.
Then
\begin{enumerate}
\item $\mathcal{Q}$ is \'etale local on the source-and-target.
\item given a morphism of algebraic spaces $f : X \to Y$ and $x \in |X|$
the following are equivalent
\begin{enumerate}
\item $f$ has $\mathcal{Q}$ at $x$, and
\item there is an open neighbourhood $X' \subset X$ of $x$
such that $X' \to Y$ has $\mathcal{P}$.
\end{enumerate}
\item given a morphism of algebraic spaces $f : X \to Y$
the following are equivalent:
\begin{enumerate}
\item $f$ has $\mathcal{P}$,
\item for every $x \in |X|$ the morphism $f$ has $\mathcal{Q}$ at $x$.
\end{enumerate}
\end{enumerate}

\label{lemma-higher-vanishing-structure-sheaf}
If $X$ is a countably indexed affine formal algebraic space, then
we have $H^n(X_\etale, \mathcal{O}_X) = 0$ for $n > 0$.

\label{lemma-family-flat-dominated-covering}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family of
morphisms of schemes with target $T$. Assume that
\begin{enumerate}
\item each $f_i$ is flat, and
\item the family $\{f_i : T_i \to T\}_{i \in I}$ can be refined by an
fpqc covering of $T$.
\end{enumerate}
Then $\{f_i : T_i \to T\}_{i \in I}$ is an fpqc covering of $T$.

\label{lemma-reduce-to-field}
\begin{slogan}
Proving Popescu approximation reduces to algebras over a field
\end{slogan}
If for every Situation \ref{situation-global} where $R$
is a field PT holds, then PT holds in general.

\label{lemma-strict-transform}
In the situation of Definition \ref{definition-strict-transform}.
\begin{enumerate}
\item The strict transform $X'$ of $X$ is the blowup of $X$ in the closed
subspace $f^{-1}Z$ of $X$.
\item For a quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$ the
strict transform $\mathcal{F}'$ is canonically isomorphic to
the pushforward along $X' \to X \times_B B'$ of the strict transform of
$\mathcal{F}$ relative to the blowing up $X' \to X$.
\end{enumerate}

\label{lemma-scheme-theoretic-image-existence}
Let $f : \mathcal{Y} \to \mathcal{X}$ be a morphism of algebraic stacks.
Then the scheme theoretic image of $f$ exists.

\label{lemma-representable-by-spaces-permanence}
Let $S$ be a scheme. Let $a : F \to G$ and $b : G \to H$ be
transformations of functors $(\Sch/S)_{fppf}^{opp} \to \textit{Sets}$.
Assume
\begin{enumerate}
\item $\Delta : G \to G \times_H G$ is representable
by algebraic spaces, and
\item $b \circ a : F \to H$ is representable by algebraic spaces.
\end{enumerate}
Then $a$ is representable by algebraic spaces.

\label{lemma-essentially-surjective-general}
In Situation \ref{situation-local-lefschetz} assume
\begin{enumerate}
\item $A$ is $f$-adically complete,
\item $f$ is a nonzerodivisor,
\item $H^1_\mathfrak m(A/fA)$ and $H^2_\mathfrak m(A/fA)$
are finite $A$-modules.
\end{enumerate}
Then the restriction functor
$$
\colim_{U_0 \subset U' \subset U\text{ open}} \textit{F\'Et}_{U'}
\longrightarrow
\textit{F\'Et}_{U_0}
$$
is an equivalence.

\label{lemma-hom-hypercovering}
Let $\mathcal{C}$ be a site with fibre products.
Let $X$ be an object of $\mathcal{C}$.
Let $L$ be a simplicial object of $\text{SR}(\mathcal{C}, X)$.
Let $n \geq 0$. Consider the commutative diagram
\begin{equation}
\label{equation-diagram}
\xymatrix{
\Hom(\Delta[1], L)_{n + 1} \ar[r] \ar[d] &
(\text{cosk}_n \text{sk}_n \Hom(\Delta[1], L))_{n + 1} \ar[d] \\
(L \times L)_{n + 1} \ar[r] &
(\text{cosk}_n \text{sk}_n (L \times L))_{n + 1}
}
\end{equation}
coming from the morphism defined above.
We can identify the terms in this diagram as follows,
where
$\partial \Delta[n + 1] = i_{n!}\text{sk}_n \Delta[n + 1]$
is the $n$-skeleton of the $(n + 1)$-simplex:
\begin{eqnarray*}
\Hom(\Delta[1], L)_{n + 1}
& = &
\Hom(\Delta[1] \times \Delta[n + 1], L)_0 \\
(\text{cosk}_n \text{sk}_n \Hom(\Delta[1], L))_{n + 1}
& = &
\Hom(\Delta[1] \times \partial \Delta[n + 1], L)_0 \\
(L \times L)_{n + 1}
& = &
\Hom(
(\Delta[n + 1] \amalg \Delta[n + 1], L)_0 \\
(\text{cosk}_n \text{sk}_n (L \times L))_{n + 1}
& = &
\Hom(
\partial \Delta[n + 1]
\amalg
\partial \Delta[n + 1], L)_0
\end{eqnarray*}
and the morphism between these objects of $\text{SR}(\mathcal{C}, X)$
come from the commutative diagram of simplicial sets
\begin{equation}
\label{equation-dual-diagram}
\xymatrix{
\Delta[1] \times \Delta[n + 1] &
\Delta[1] \times \partial\Delta[n + 1] \ar[l] \\
\Delta[n + 1] \amalg \Delta[n + 1] \ar[u] &
\partial\Delta[n + 1] \amalg \partial\Delta[n + 1]
\ar[l] \ar[u]
}
\end{equation}
Moreover the fibre product of the bottom arrow and the
right arrow in (\ref{equation-diagram}) is equal to
$$
\Hom(U, L)_0
$$
where $U \subset \Delta[1] \times \Delta[n + 1]$
is the smallest simplicial subset such that both
$\Delta[n + 1] \amalg \Delta[n + 1]$ and
$\Delta[1] \times \partial\Delta[n + 1]$ map into it.

\label{lemma-unique-point}
Let $S$ be a scheme.
Let $Z$ be an algebraic space over $S$. The following are equivalent
\begin{enumerate}
\item $Z$ is reduced and $|Z|$ is a singleton,
\item there exists a surjective flat morphism $\Spec(k) \to Z$
where $k$ is a field, and
\item there exists a locally of finite type, surjective, flat morphism
$\Spec(k) \to Z$ where $k$ is a field.
\end{enumerate}

\label{lemma-ideal-projective-not-locally-free}
There exists a ring $R$ and an ideal $I$ such that $I$ is projective as
an $R$-module but not locally free as an $R$-module.

\label{lemma-composition-quasi-compact}
The composition of a pair of quasi-compact morphisms of algebraic spaces
is quasi-compact.

\label{lemma-base-change-fibres-geometrically-reduced}
Let $f : X \to Y$ be a morphism of schemes.
Let $g : Y' \to Y$ be any morphism, and denote
$f' : X' \to Y'$ the base change of $f$.
Then
\begin{align*}
\{y' \in Y' \mid X'_{y'}\text{ is geometrically reduced}\} \\
= g^{-1}(\{y \in Y \mid X_y\text{ is geometrically reduced}\}).
\end{align*}

\label{lemma-base-change-universally-closed}
The base change of a universally closed morphism of algebraic spaces
by any morphism of algebraic spaces is universally closed.

\label{lemma-taut-descent-weakly-adic}
In the situation above, if $B$ is weakly pre-adic, then $A$
is weakly pre-adic.

\label{lemma-compare-cohomology-LC}
With $X \in \Ob(\textit{LC}_{qc})$ and
$a_X : \Sh(\textit{LC}_{qc}/X) \to \Sh(X)$ as above:
\begin{enumerate}
\item for an abelian sheaf $\mathcal{F}$ on $X$ we have
$H^n(X, \mathcal{F}) = H^n_{qc}(X, a_X^{-1}\mathcal{F})$,
\item for $K \in D^+(X)$ we have $H^n(X, K) = H^n_{qc}(X, a_X^{-1}K)$.
\end{enumerate}
For example, if $A$ is an abelian group, then we have
$H^n(X, \underline{A}) = H^n_{qc}(X, \underline{A})$.

\label{lemma-uniqueness-relative-dualizing}
Let $R \to A$ be a flat ring map of finite presentation.
Any two relative dualizing complexes for $R \to A$ are isomorphic.

\label{lemma-w-local-morphism-equal-points-stalks-is-iso}
Let $A \to B$ be ring map such that
\begin{enumerate}
\item $A \to B$ identifies local rings,
\item the topological spaces $\Spec(B)$, $\Spec(A)$ are w-local,
\item $\Spec(B) \to \Spec(A)$ is w-local, and
\item $\pi_0(\Spec(B)) \to \pi_0(\Spec(A))$ is bijective.
\end{enumerate}
Then $A \to B$ is an isomorphism

\label{lemma-non-quasi-separated-group-scheme}
There exists a flat group scheme of finite type over the infinite
dimensional affine space which is not quasi-separated.

\label{lemma-flat-precompose-pus}
In diagram (\ref{equation-base-change}) the map
$a \circ Rg_* \leftarrow Rg'_* \circ a'$ is an isomorphism.

\label{lemma-easy-kunneth}
Let $a : \mathcal{Y} \to \mathcal{X}$ and $b : \mathcal{Z} \to \mathcal{X}$
be representable by schemes, quasi-compact, quasi-separated, and flat.
Then $a_{\QCoh, *}\mathcal{O}_\mathcal{Y}
\otimes_{\mathcal{O}_\mathcal{X}}
b_{\QCoh, *}\mathcal{O}_\mathcal{Z} =
f_{\QCoh, *}\mathcal{O}_{\mathcal{Y} \times_\mathcal{X} \mathcal{Z}}$
where $f : \mathcal{Y} \times_\mathcal{X} \mathcal{Z} \to \mathcal{X}$
is the obvious morphism.

\label{lemma-forget-injectives}
The forgetful functor $\textit{Ab}(\mathcal{C})\to \textit{PAb}(\mathcal{C})$
transforms injectives into injectives.

\label{theorem-openness-flatness}
\begin{reference}
\cite[IV Theorem 11.3.1]{EGA}
\end{reference}
Let $S$ be a scheme.
Let $f : X \to S$ be a morphism which is locally of finite presentation.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module which is
locally of finite presentation. Then
$$
U = \{x \in X \mid \mathcal{F}\text{ is flat over }S\text{ at }x\}
$$
is open in $X$.

\label{proposition-trace-well-defined}
Let $K\in D_{perf}(\Lambda)$ and $f\in \text{End}_{D(\Lambda)}(K)$. Then the
trace $\text{Tr}(f)\in \Lambda^\natural$ is well defined.

\label{lemma-diagonal-unramified-morphism}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item If $f$ is unramified, then the diagonal morphism
$\Delta : X \to X \times_S X$ is an open immersion.
\item If $f$ is locally of finite type
and $\Delta$ is an open immersion, then $f$ is unramified.
\item If $f$ is locally of finite presentation and $\Delta$ is an open
immersion, then $f$ is G-unramified.
\end{enumerate}

\label{lemma-depth-drops-by-one}
Let $A$ be a Noetherian ring, let $I \subset A$ be an ideal, and
let $M$ a finite $A$-module with $IM \not = M$.
\begin{enumerate}
\item If $x \in I$ is a nonzerodivisor on $M$, then
$\text{depth}_I(M/xM) = \text{depth}_I(M) - 1$.
\item Any $M$-regular sequence $x_1, \ldots, x_r$ in $I$ can be extended to an
$M$-regular sequence in $I$ of length $\text{depth}_I(M)$.
\end{enumerate}

\label{lemma-restrict-and-shriek-from-etale-ctf}
Let $\Lambda$ be a Noetherian ring.
If $j : U \to X$ is an \'etale morphism of schemes, then
\begin{enumerate}
\item $K|_U \in D_{ctf}(U_\etale, \Lambda)$ if
$K \in D_{ctf}(X_\etale, \Lambda)$, and
\item $j_!M \in D_{ctf}(X_\etale, \Lambda)$ if
$M \in D_{ctf}(U_\etale, \Lambda)$ and
the morphism $j$ is quasi-compact and quasi-separated.
\end{enumerate}

\label{lemma-composition-separated}
All of the separation axioms listed in Definition \ref{definition-separated}
are stable under composition of morphisms.

\label{lemma-finite-flat}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item $f$ is finite locally free,
\item $f$ is finite, flat, and locally of finite presentation.
\end{enumerate}
If $Y$ is locally Noetherian these are also equivalent to
\begin{enumerate}
\item[(3)] $f$ is finite and flat.
\end{enumerate}

\label{lemma-noether-different-base-change}
Let $A \to B$ be a finite type ring map. Let $A \to A'$ be a flat ring map.
Set $B' = B \otimes_A A'$.
\begin{enumerate}
\item The annihilator $J'$ of $\Ker(B' \otimes_{A'} B' \to B')$ is
$J \otimes_A A'$ where $J$ is the annihilator of $\Ker(B \otimes_A B \to B)$.
\item The Noether different $\mathfrak{D}'$ of $B'$ over $A'$ is
$\mathfrak{D}B'$, where $\mathfrak{D}$ is
the Noether different of $B$ over $A$.
\end{enumerate}

\label{lemma-composition-trivial}
In diagram (\ref{equation-translation}) the following are equivalent
\begin{enumerate}
\item $h \circ h'$ is trivial, and
\item the image of $H' \circ H$ consists of objects isomorphic to finite
coproducts of final objects.
\end{enumerate}

\label{lemma-composition-universally-injective}
The composition of a pair of universally injective morphisms of
algebraic stacks is universally injective.

\label{lemma-projective-space-bundle}
Let $S$ be a scheme. Let $n \geq 0$. Then
$\mathbf{P}^n_S$ is a projective bundle over $S$.

\label{lemma-base-change-universally}
In Situation \ref{situation-pre-pure}.
\begin{enumerate}
\item $\mathcal{F}$ is universally pure above $y$, and
\item for every morphism $(Y', y') \to (Y, y)$ of pointed algebraic spaces
the pullback $\mathcal{F}_{Y'}$ is pure above $y'$.
\end{enumerate}
In particular, $\mathcal{F}$ is universally pure relative to $Y$ if and
only if every base change $\mathcal{F}_{Y'}$ of $\mathcal{F}$ is
pure relative to $Y'$.

\label{lemma-decent-Jacobson-ft-pts}
Let $S$ be a scheme. Let $X$ be a decent Jacobson algebraic space over $S$.
Then $X_{\text{ft-pts}} \subset |X|$ is the set of closed points.

\label{lemma-divisor-delta-dimension}
In Situation \ref{situation-setup} let $X/B$ be good. Assume $X$ is
integral.
\begin{enumerate}
\item If $Z \subset X$ is an integral closed subspace, then
the following are equivalent:
\begin{enumerate}
\item $Z$ is a prime divisor,
\item $|Z|$ has codimension $1$ in $|X|$, and
\item $\dim_\delta(Z) = \dim_\delta(X) - 1$.
\end{enumerate}
\item If $Z$ is an irreducible component of an effective Cartier
divisor on $X$, then $\dim_\delta(Z) = \dim_\delta(X) - 1$.
\end{enumerate}

\label{lemma-perfect-into-support-on-T}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $f \in \Gamma(X, \mathcal{O}_X)$.
For any morphism $\alpha : E \to E'$ in
$D_\QCoh(\mathcal{O}_X)$ such that
\begin{enumerate}
\item $E$ is perfect, and
\item $E'$ is supported on $T = V(f)$
\end{enumerate}
there exists an $n \geq 0$ such that $f^n \alpha  = 0$.

\label{lemma-pre-genus-curves}
There exist an open substack $\Curvesstack^{h0, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{h0, 1}$,
\item $f_*\mathcal{O}_X = \mathcal{O}_S$, this holds
after arbitrary base change, and the fibres of $f$ have dimension $1$,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{h0, 1}$,
\item $H^0(X, \mathcal{O}_X) = k$ and $\dim(X) = 1$.
\end{enumerate}
\end{enumerate}

\label{lemma-nullity-cartesian-objects-derived}
In Situation \ref{situation-simplicial-site}.
If $K, K' \in D(\mathcal{C}_{total})$.
Assume
\begin{enumerate}
\item $K$ is cartesian,
\item $\Hom(K_i[i], K'_i) = 0$ for $i > 0$, and
\item $\Hom(K_i[i + 1], K'_i) = 0$ for $i \geq 0$.
\end{enumerate}
Then any map $K \to K'$ which induces the zero map $K_0 \to K'_0$ is zero.

\label{theorem-DM}
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is DM,
\item $\mathcal{X}$ is Deligne-Mumford, and
\item there exists a scheme $W$ and a surjective \'etale
morphism $W \to \mathcal{X}$.
\end{enumerate}

\label{lemma-etale-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is \'etale''
is \'etale local on the source.

\label{theorem-countable}
\begin{reference}
Slight improvement of \cite{AT}
\end{reference}
Let $K$ be an algebraically closed field. Let $\mathbf{X}$ be a smooth proper
scheme over $K$. There are at most countably many isomorphism classes
of smooth proper schemes $\mathbf{Y}$ over $K$ which are derived
equivalent to $\mathbf{X}$.

\label{lemma-dimension-quasi-finite}
Let $S$ be a scheme. Let $X \to Y$ be a locally quasi-finite morphism
of algebraic spaces over $S$. Then $\dim(X) \leq \dim(Y)$.

\label{lemma-composition-lci}
The composition of local complete intersection morphisms is
a local complete intersection.

\label{lemma-fibre-product-after-map}
Let $S$ be a scheme. Let $f : X \to Z$, $g : Y \to Z$ and $Z \to T$
be morphisms of formal algebraic spaces over $S$. Consider the induced
morphism $i : X \times_Z Y \to X \times_T Y$. Then
\begin{enumerate}
\item $i$ is representable (by schemes), locally of finite type,
locally quasi-finite, separated, and a monomorphism,
\item if $Z \to T$ is separated, then $i$ is a closed immersion, and
\item if $Z \to T$ is quasi-separated, then $i$ is quasi-compact.
\end{enumerate}

\label{lemma-support-family}
Taking the support as in Remark \ref{remark-supports-family}
is compatible with base change, restriction, and flat pullback.

\label{lemma-smallest-where-descends-versal}
Let $\mathcal{F}$ be a category cofibred in groupoids over
$\mathcal{C}_\Lambda$ which has (S1). Let $\xi$ be a versal formal object
of $\mathcal{F}$ lying over $R$. There exists a morphism $\xi' \to \xi$
lying over $R' \subset R$ with the following minimality properties
\begin{enumerate}
\item for every $f : R \to A$ with $A \in \Ob(\mathcal{C}_\Lambda)$
the pushforwards
$$
\vcenter{
\xymatrix{
\xi' \ar[d] \ar[r] & x' \ar[d] \\
\xi \ar[r] & x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
R' \ar[d] \ar[r] & f(R') \ar[d] \\
R \ar[r] & A
}
}
$$
produce a minimal object $x' \to x$ of $\mathcal{S}_x$, and
\item for any morphism of formal objects $\xi'' \to \xi'$
the corresponding morphism $R'' \to R'$ is surjective.
\end{enumerate}

\label{lemma-characterize-finite}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is finite,
\item $f$ is proper with finite fibres,
\item $f$ is proper and locally quasi-finite,
\item $f$ is universally closed, separated, locally of finite type
and has finite fibres.
\end{enumerate}

\label{lemma-unramified-omega-zero}
Let $f : X \to S$ be a morphism of schemes. Then
\begin{enumerate}
\item $f$ is unramified if and only if $f$ is locally of finite type
and $\Omega_{X/S} = 0$, and
\item $f$ is G-unramified if and only if $f$ is locally of finite presentation
and $\Omega_{X/S} = 0$.
\end{enumerate}

\label{lemma-gkn-representable}
Let $0 < k < n$.
The functor $G(k, n)$ of (\ref{equation-gkn}) is representable by a scheme.

\label{lemma-glueing-sheaves}
Let $S \in \Ob(\Sch_{fppf})$. Let $F$ be a presheaf of sets on
$(\Sch/S)_{fppf}$. Assume
\begin{enumerate}
\item $F$ is a sheaf for the Zariski topology on $(\Sch/S)_{fppf}$,
\item there exists an index set $I$ and subfunctors $F_i \subset F$ such that
\begin{enumerate}
\item each $F_i$ is an fppf sheaf,
\item each $F_i \to F$ is representable by algebraic spaces,
\item $\coprod F_i \to F$ becomes surjective after fppf sheafification.
\end{enumerate}
\end{enumerate}
Then $F$ is an fppf sheaf.

\label{lemma-lift-purity}
In Situation \ref{situation-local-lefschetz}.
Let $V$ be finite \'etale over $U$. Assume
\begin{enumerate}
\item $A$ has depth $\geq 3$,
\item $V_0 = V \times_U U_0$ is equal to $Y_0 \times_{X_0} U_0$
for some $Y_0 \to X_0$ finite \'etale.
\end{enumerate}
Then $V = Y \times_X U$ for some $Y \to X$ finite \'etale.

\label{theorem-multiplicity-with-koszul}
\begin{reference}
\cite[Theorem 1 in part B of Chapter IV]{Serre_algebre_locale}
\end{reference}
Let $A$ be a Noetherian local ring. Let $I = (f_1, \ldots, f_r) \subset A$
be an ideal of definition. Let $M$ be a finite $A$-module. Then
$$
e_I(M, r) = \sum
(-1)^i\text{length}_A H_i(K_\bullet(f_1, \ldots, f_r) \otimes_A M)
$$

\label{lemma-characterize-gorenstein}
Let $A$ be a Noetherian ring. The following are equivalent
\begin{enumerate}
\item $A$ has finite injective dimension as a module over itself,
\item $A$ is Gorenstein and finite dimensional.
\end{enumerate}
In this case $A[0]$ is a dualizing complex.

\label{lemma-torsors-over-field-torsion}
Let $G$ be a smooth commutative group algebraic space over a field $K$.
Then $H^1_{fppf}(\Spec(K), G)$ is torsion.

\label{lemma-zariski-h}
An fppf covering is a h covering. Hence syntomic, smooth, \'etale,
and Zariski coverings are h coverings as well.

\label{lemma-composition-is-addition}
The bijection (\ref{equation-isomorphism}) is an isomorphism
of groups.

\label{lemma-quasi-affine-closed-in-finite-presentation}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Assume
\begin{enumerate}
\item $f$ is locally of finite type and quasi-affine, and
\item $Y$ is quasi-compact and quasi-separated.
\end{enumerate}
Then there exists a morphism of finite presentation
$f' : X' \to Y$ and a closed immersion $X \to X'$ over $Y$.

\label{lemma-trace-base}
Assume given data (D0), (D1), and (D2') satisfying axioms (A1) -- (A7).
Then axiom (C)(d) of Section \ref{section-axioms} holds.

\label{lemma-base-change-stabilizer-preserving}
Let
$$
\xymatrix{
\mathcal{X}' \ar[r] \ar[d]_{f'} & \mathcal{X} \ar[d]^f \\
\mathcal{Y}' \ar[r] & \mathcal{Y}
}
$$
be a cartesian diagram of algebraic stacks.
\begin{enumerate}
\item Let $x' \in |\mathcal{X}'|$ with image $x \in |\mathcal{X}|$.
If $f$ induces an isomorphism between automorphism groups at
$x$ and $f(x)$ (Remark \ref{remark-identify-automorphism-groups}), then
$f'$ induces an isomorphism between automorphism groups at $x'$ and $f(x')$.
\item If $\mathcal{I}_\mathcal{X} \to
\mathcal{X} \times_\mathcal{Y} \mathcal{I}_\mathcal{Y}$ is an isomorphism,
then $\mathcal{I}_{\mathcal{X}'} \to
\mathcal{X}' \times_{\mathcal{Y}'} \mathcal{I}_{\mathcal{Y}'}$
is an isomorphism.
\end{enumerate}

\label{theorem-complexes-algebraic}
\begin{reference}
\cite{lieblich-complexes}
\end{reference}
Let $S$ be a scheme. Let $f : X \to B$ be morphism of algebraic spaces
over $S$. Assume that $f$ is proper, flat, and of finite presentation.
Then $\Complexesstack_{X/B}$ is an algebraic stack over $S$.

\label{lemma-fully-faithful-minimal}
\begin{reference}
\cite[Corollary 1.11]{Bhatt-local}
\end{reference}
In Situation \ref{situation-local-lefschetz}. Assume
\begin{enumerate}
\item $H^1_\mathfrak m(A)$ and $H^2_\mathfrak m(A)$ are
annihilated by a power of $f$, and
\item $A$ is henselian or more generally $(A, (f))$ is a henselian pair.
\end{enumerate}
Then the restriction functor
$\textit{F\'Et}_U \longrightarrow \textit{F\'Et}_{U_0}$
is fully faithful.

\label{lemma-push-omega-a}
With notation as above we have
\begin{enumerate}
\item $\Omega^p_{L^\star/S, n} =
\Omega^p_{L^\star/S, 0} \otimes_{\mathcal{O}_X} \mathcal{L}^{\otimes n}$
for all $n \in \mathbf{Z}$ as quasi-coherent $\mathcal{O}_X$-modules,
\item $\Omega^\bullet_{X/S} = \Omega^\bullet_{L/X, 0}$
as complexes, and
\item for $n > 0$ and $p \geq 0$ we have
$\Omega^p_{L/X, n} = \Omega^p_{L^\star/S, n}$.
\end{enumerate}

\label{lemma-trace-well-defined}
Let $\varphi : R[x]/(x^p - a) \to R[y]/(y^p - b)$ be an $R$-algebra
homomorphism. Then $\text{Tr}_x = \text{Tr}_y \circ \varphi$.

\label{lemma-groupoid-on-field-geometrically-irreducible}
In
Situation \ref{situation-groupoid-on-field}
the algebraic space $R$ is geometrically unibranch. In
Situation \ref{situation-group-over-field}
the algebraic space $G$ is geometrically unibranch.

\label{lemma-profinite-group-cohomology-torsion}
Let $G$ be a profinite topological group.
Then
\begin{enumerate}
\item $H^i(G, M)$ is torsion for $i > 0$ and any $G$-module $M$, and
\item $H^i(G, M) = 0$ if $M$ is a $\mathbf{Q}$-vector space.
\end{enumerate}

\label{theorem-stable-reduction}
\begin{reference}
\cite[Corollary 2.7]{DM}
\end{reference}
Let $R$ be a discrete valuation ring with fraction field $K$. Let $C$ be a
smooth projective curve over $K$ with $H^0(C, \mathcal{O}_C) = K$
and genus $g \geq 2$. Then
\begin{enumerate}
\item there exists an extension of discrete valuation rings $R \subset R'$
inducing a finite separable extension of fraction fields $K'/K$ and
a stable family of curves $Y \to \Spec(R')$ of genus $g$ with
$Y_{K'} \cong C_{K'}$ over $K'$, and
\item there exists a finite separable extension $L/K$ and a stable
family of curves $Y \to \Spec(A)$ of genus $g$ where $A \subset L$
is the integral closure of $R$ in $L$ such that
$Y_L \cong C_L$ over $L$.
\end{enumerate}

\label{lemma-composition-universally-submersive}
The composition of a pair of (universally) submersive morphisms of
algebraic stacks is (universally) submersive.

\label{lemma-Noetherian-approximation-geometrically-irreducible}
Let $f : X \to S$ be a morphism of affine schemes, which is
of finite presentation with geometrically irreducible fibres.
Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ has geometrically irreducible fibres.

\label{lemma-excision-modifications}
Let $S$ be a scheme. Consider a separated \'etale morphism
$f : V \to W$ of algebraic spaces over $S$.
Assume there exists a
closed subspace $T \subset W$ such that $f^{-1}T \to T$ is
an isomorphism. Then, with $W^0 = W \setminus T$ and
$V^0 = f^{-1}W^0$ the base change functor
$$
\left\{
\begin{matrix}
g : X \to W\text{ morphism of algebraic spaces} \\
g^{-1}(W^0) \to W^0\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
h : Y \to V\text{ morphism of algebraic spaces} \\
h^{-1}(V^0) \to V^0\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

\label{theorem-enough-injectives}
The category of abelian sheaves on a site is an abelian category
which has enough injectives.

\label{lemma-surjective-graded-rings-map-relative-proj}
With hypotheses and notation as in Lemma \ref{lemma-morphism-relative-proj}
above. Assume $\mathcal{A}_d \to \mathcal{B}_d$ is surjective for
$d \gg 0$. Then
\begin{enumerate}
\item $U(\psi) = Q$,
\item $r_\psi : Q \to R$ is a closed immersion, and
\item the maps $\theta : r_\psi^*\mathcal{O}_P(n) \to \mathcal{O}_Q(n)$
are surjective but not isomorphisms in general (even if
$\mathcal{A} \to \mathcal{B}$ is surjective).
\end{enumerate}

\label{lemma-rig-etale-descent}
Let $S$ be a scheme. Let $f : X \to Y$ and $g : Y \to Z$
be morphisms of locally Noetherian formal algebraic spaces over $S$.
Assume
\begin{enumerate}
\item $g$ is locally of finite type,
\item $f$ is rig-smooth (resp.\ rig-\'etale) and rig-surjective,
\item $g \circ f$ is rig-smooth (resp.\ rig-\'etale)
\end{enumerate}
then $g$ is rig-smooth (resp.\ rig-\'etale).

\label{lemma-support-sheaf-rings-closed}
The support of a sheaf of rings on the small \'etale site of an
algebraic space is closed.

\label{lemma-ample-immersion-into-proj}
Let $X$ be a scheme. Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Set $S = \Gamma_*(X, \mathcal{L})$.
Assume $\mathcal{L}$ is ample. Then the canonical morphism of schemes
$f : X \longrightarrow \text{Proj}(S)$ of Lemma \ref{lemma-map-into-proj}
is an open immersion with dense image.

\label{lemma-CM}
Let $f : X \to Y$ be a morphism of schemes.
Assume all fibres of $f$ are locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is Cohen-Macaulay, and
\item $f$ is flat and its fibres are Cohen-Macaulay schemes.
\end{enumerate}

\label{lemma-tensor-with-compact-fully-faithful}
With notation and assumptions as in Lemma \ref{lemma-tensor-hom-adjoint}.
Assume
\begin{enumerate}
\item $N$ defines a compact object of $D(B, \text{d})$, and
\item the map $H^k(A) \to \Hom_{D(B, \text{d})}(N, N[k])$ is an
isomorphism for all $k \in \mathbf{Z}$.
\end{enumerate}
Then the functor $-\otimes_A^\mathbf{L} N$ is fully faithful.

\label{lemma-surjection-from-quasi-compact}
Let
$$
\xymatrix{
\mathcal{X} \ar[rr]_f \ar[rd]_p & &
\mathcal{Y} \ar[dl]^q \\
& \mathcal{Z}
}
$$
be a $2$-commutative diagram of morphisms of algebraic stacks.
If $f$ is surjective and $p$ is quasi-compact, then $q$ is quasi-compact.

\label{lemma-tate}
\begin{reference}
\cite[Appendix]{Mazur-Roberts}
\end{reference}
Let $A \to P$ be a ring map. Let $f_1, \ldots, f_n \in P$ be a
Koszul regular sequence. Assume $B = P/(f_1, \ldots, f_n)$
is flat over $A$. Let $g_1, \ldots, g_n \in P \otimes_A B$
be a Koszul regular sequence generating the kernel of the multiplication
map $P \otimes_A B \to B$. Write $f_i \otimes 1 = \sum g_{ij} g_j$.
Then the annihilator of $\Ker(B \otimes_A B \to B)$ is a principal
ideal generated by the image of $\det(g_{ij})$.

\label{lemma-finite-type-separated}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic
spaces over $S$ which is of finite type and separated.
Let $Y'$ be the normalization of $Y$ in $X$. Picture:
$$
\xymatrix{
X \ar[rd]_f \ar[rr]_{f'} & & Y' \ar[ld]^\nu \\
& Y &
}
$$
Then there exists an open subspace $U' \subset Y'$ such that
\begin{enumerate}
\item $(f')^{-1}(U') \to U'$ is an isomorphism, and
\item $(f')^{-1}(U') \subset X$ is the set of points at which
$f$ is quasi-finite.
\end{enumerate}

\label{lemma-free-summand-in-ideal-finite-proj-dim}
\begin{reference}
\cite{Vasconcelos}
\end{reference}
Let $R$ be a Noetherian local ring. Let $I \subset R$ be an ideal
of finite projective dimension over $R$. If $F \subset I/I^2$ is a
direct summand isomorphic to $R/I$, then there exists a nonzerodivisor
$x \in I$ such that the image of $x$ in $I/I^2$ generates $F$.

\label{lemma-exists-smooth}
There exists an $R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$
such that the equivalent conditions of Lemma \ref{lemma-smooth}
hold and moreover $H_1(L_{k/\Lambda}) = \mathfrak m_R/\mathfrak m_R^2$
and $\Omega_{R/\Lambda} \otimes_R k = \Omega_{k/\Lambda}$.

\label{lemma-characterize-finite-type}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of formal algebraic
spaces over $S$. The following are equivalent
\begin{enumerate}
\item $f$ is of finite type,
\item $f$ is representable by algebraic spaces and is of finite type in
the sense of
Bootstrap, Definition \ref{bootstrap-definition-property-transformation}.
\end{enumerate}

\label{lemma-mod-Koszul-regular-ideal}
Let $A \to B$ be a surjective ring map whose kernel $I$ is Koszul.
Then $L_{B/A}$ is quasi-isomorphic to $I/I^2[1]$.

\label{lemma-group-over-field-locally-finite-type-dimension}
In
Situation \ref{situation-group-over-field}
assume $G$ locally of finite type.
For all $g \in |G|$
\begin{enumerate}
\item $\dim(G) = \dim_g(G)$,
\item if the transcendence degree of $g$ over $k$ is $0$, then
$\dim(G) = \dim(\mathcal{O}_{G, \overline{g}})$.
\end{enumerate}

\label{lemma-globally-generated}
In Situation \ref{situation-rational}.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module. Then
\begin{enumerate}
\item $H^p(X, \mathcal{F}) = 0$ for $p \not \in \{0, 1\}$, and
\item $H^1(X, \mathcal{F}) = 0$ if $\mathcal{F}$ is globally generated.
\end{enumerate}

\label{lemma-geometrically-reduced}
Let $k$ be a field. Let $X$ be an algebraic space over $k$.
The following are equivalent
\begin{enumerate}
\item $X$ is geometrically reduced,
\item for some surjective \'etale morphism $U \to X$ where $U$
is a scheme, $U$ is geometrically reduced,
\item for any \'etale morphism $U \to X$
where $U$ is a scheme, $U$ is geometrically reduced.
\end{enumerate}

\label{lemma-geometrically-unibranch}
\begin{reference}
Compare with \cite[Proposition 2.3]{Etale-coverings}
\end{reference}
Let $X$ be a Noetherian scheme. The following are equivalent
\begin{enumerate}
\item $X$ is geometrically unibranch (Definition \ref{definition-unibranch}),
\item for every point $x \in X$ which is not the generic point of
an irreducible component of $X$, the punctured spectrum of the
strict henselization $\mathcal{O}_{X, x}^{sh}$ is connected.
\end{enumerate}

\label{lemma-composition-universally-submersive}
The composition of a pair of (universally) submersive morphisms of
algebraic spaces is (universally) submersive.

\label{proposition-kollar}
\begin{reference}
See \cite{k-coherent} and see \cite[IV, Proposition 7.2.2]{EGA}
for a special case.
\end{reference}
\begin{slogan}
Weak analogue of Hartogs' Theorem: On Noetherian schemes, the
restriction of a coherent sheaf to an open set with complement
of codimension 2 in the sheaf's support, is coherent.
\end{slogan}
Let $j : U \to X$ be an open immersion of locally Noetherian schemes
with complement $Z$. Let $\mathcal{F}$ be a coherent $\mathcal{O}_U$-module.
The following are equivalent
\begin{enumerate}
\item $j_*\mathcal{F}$ is coherent,
\item for $x \in \text{Ass}(\mathcal{F})$ and
$z \in Z \cap \overline{\{x\}}$ and any associated prime
$\mathfrak p$ of the completion $\mathcal{O}_{\overline{\{x\}}, z}^\wedge$
we have $\dim(\mathcal{O}_{\overline{\{x\}}, z}^\wedge/\mathfrak p) \geq 2$.
\end{enumerate}

\label{proposition-affine-smooth-lift-to-first-order}
\begin{reference}
Email of Matthew Emerton dated April 27, 2016.
\end{reference}
Let $\mathcal{X} \subset \mathcal{X}'$ be a first order thickening
of algebraic stacks. Let $W$ be an affine scheme and let
$W \to \mathcal{X}$ be a smooth morphism. Then there exists
a cartesian diagram
$$
\xymatrix{
W \ar[d] \ar[r] & W' \ar[d] \\
\mathcal{X} \ar[r] & \mathcal{X}'
}
$$
with $W' \to \mathcal{X}'$ smooth and $W'$ affine.

\label{lemma-characterize-affine-formal-algebraic-space}
Let $S$ be a scheme. Let $X$ be a sheaf on $(\Sch/S)_{fppf}$.
Then $X$ is an affine formal algebraic space if and only if
the following hold
\begin{enumerate}
\item any morphism $U \to X$ where $U$ is an affine scheme over $S$
factors through a morphism $T \to X$ which is representable and a
thickening with $T$ an affine scheme over $S$, and
\item a set theoretic condition as in Remark \ref{remark-set-theoretic}.
\end{enumerate}

\label{lemma-base-change-finite-presentation}
A base change of a morphism of finite presentation is of finite presentation.
The same holds for locally of finite presentation.

\label{lemma-nice-meromorphic-function}
In Situation \ref{situation-vanishing} there exists a nonzero
$f \in \mathfrak m$ such that for every $i = 1, \ldots, r$ there exist
\begin{enumerate}
\item a closed point $x_i \in C_i$ with $x_i \not \in C_j$ for $j \not = i$,
\item a factorization $f = g_i f_i$ of $f$ in $\mathcal{O}_{X, x_i}$
such that $g_i \in \mathfrak m_{x_i}$ maps to a nonzero element
of $\mathcal{O}_{C_i, x_i}$.
\end{enumerate}

\label{lemma-characterize-formally-unramified}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces over
$S$. The following are equivalent:
\begin{enumerate}
\item $f$ is formally unramified, and
\item $\Omega_{X/Y} = 0$.
\end{enumerate}

\label{proposition-pic-curve}
Let $k$ be a separably closed field. Let $X$ be a smooth projective
curve over $k$. The Picard functor $\Picardfunctor_{X/k}$ is representable.

\label{proposition-tate-map}
There exists a unique rule that to every locally quasi-finite syntomic
morphism of locally Noetherian schemes $Y \to X$ assigns an isomorphism
$$
c_{Y/X} : \det(\NL_{Y/X}) \longrightarrow \omega_{Y/X}
$$
satisfying the following two properties
\begin{enumerate}
\item the section $\delta(\NL_{Y/X})$ is mapped to $\tau_{Y/X}$, and
\item the rule is compatible with restriction to opens and with
base change.
\end{enumerate}

\label{lemma-taut-descent-weakly-admissible}
In the situation above, if $B$ is weakly pre-admissible, then
$A$ is weakly pre-admissible.

\label{lemma-kill-colimit-support-general}
If in Lemma \ref{lemma-kill-colimit-weak-general} we additionally assume
\begin{enumerate}
\item[(6)] if $\mathfrak p \not \in V(I)$, $\mathfrak p \in T$, then
$\text{depth}_{A_\mathfrak p}(M_\mathfrak p) > s$,
\end{enumerate}
then $H^i_{J_0}(M) = H^i_J(M) = H^i_{J + I}(M)$ for $i \leq s$ and these
modules are annihilated by a power of $I$.

\label{lemma-rickard-rings}
Let $R$ be a ring.
Let $A$ and $B$ be $R$-algebras. The following are equivalent
\begin{enumerate}
\item there is an $R$-linear equivalence $D(A) \to D(B)$
of triangulated categories,
\item there exists an object $P$ of $D(B)$ such that
\begin{enumerate}
\item $P$ can be represented by a finite complex
of finite projective $B$-modules,
\item if $K \in D(B)$ with $\Ext^i_B(P, K) = 0$ for
$i \in \mathbf{Z}$, then $K = 0$, and
\item $\Ext^i_B(P, P) = 0$ for $i \not = 0$ and
equal to $A$ for $i= 0$.
\end{enumerate}
\end{enumerate}
Moreover, if $B$ is flat as an $R$-module, then this is also
equivalent to
\begin{enumerate}
\item[(3)] there exists an $(A, B)$-bimodule $N$ such that
$- \otimes_A^\mathbf{L} N : D(A) \to D(B)$ is an equivalence.
\end{enumerate}

\label{lemma-quasi-compact-existence-universally-closed}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Assume
\begin{enumerate}
\item $f$ is quasi-compact, and
\item $f$ satisfies the existence part of the valuative criterion.
\end{enumerate}
Then $f$ is universally closed.

\label{lemma-dualizing-base-change-of-flat}
If $A \to B$ is flat, then the base change map (\ref{equation-bc-dualizing})
induces an isomorphism $\omega_{B/A} \otimes_B B_1 \to \omega_{B_1/A_1}$.

\label{lemma-derived-lower-shriek-bounded}
Let $f : X \to Y$ be a finite type separated morphism of quasi-compact
and quasi-separated schemes. Let $\Lambda$ be a ring. The functors $Rf_!$
constructed in Section \ref{section-derived-lower-shriek-compactification}
are bounded in the following sense: There exists an integer $N$ such that
for $E \in D^+_{tors}(X_\etale, \Lambda)$ or $E \in D(X_\etale, \Lambda)$
if $\Lambda$ is torsion, we have
\begin{enumerate}
\item $H^i(Rf_!(\tau_{\leq a}E) \to H^i(Rf_!(E))$ is an isomorphism
for $i \leq a$,
\item $H^i(Rf_!(E)) \to H^i(Rf_!(\tau_{\geq b - N}E))$ is an isomorphism
for $i \geq b$,
\item if $H^i(E) = 0$ for $i \not \in [a, b]$ for some
$-\infty \leq a \leq b \leq \infty$, then $H^i(Rf_!(E)) = 0$
for $i \not \in [a, b + N]$.
\end{enumerate}

\label{lemma-filter-Noetherian-space}
Let $S$ be a scheme. Let $X$ be a Noetherian algebraic space over $S$.
Let $U \subset X$ be a proper dense open subspace. Then there exists an
affine scheme $V$ and an \'etale morphism $V \to X$ such that
\begin{enumerate}
\item the open subspace $W = U \cup \Im(V \to X)$ is strictly larger
than $U$,
\item $(U \subset W, V \to W)$ is a distinguished square, and
\item $U \times_W V \to U$ has dense image.
\end{enumerate}

\label{lemma-eventually-proper}
Assumptions and notation as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is proper, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i$ such that $f_i$ is proper.

\label{lemma-fully-faithful-general-better}
In Situation \ref{situation-local-lefschetz} assume
\begin{enumerate}
\item $A$ has a dualizing complex and is $f$-adically complete,
\item every irreducible component of $X$ not contained in $X_0$
has dimension $\geq 3$.
\end{enumerate}
Then the restriction functor
$$
\colim_{U_0 \subset U' \subset U\text{ open}} \textit{F\'Et}_{U'}
\longrightarrow
\textit{F\'Et}_{U_0}
$$
is fully faithful.

\label{lemma-NL-formally-etale}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is formally \'etale,
\item $H^{-1}(\NL_{X/Y}) = H^0(\NL_{X/Y}) = 0$.
\end{enumerate}

\label{lemma-descend-isomorphism}
Notation and assumptions as in Situation \ref{situation-descent-property}. If
\begin{enumerate}
\item $f$ is an isomorphism,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is an isomorphism for some $i \geq 0$.

\label{theorem-popescu}
Any regular homomorphism of Noetherian rings is a filtered colimit
of smooth ring maps.

\label{lemma-simplicial-site}
Let $X$ be a simplicial space. Then $X_{Zar}$
as defined above is a site.

\label{lemma-prepare-geometric-cap}
In Situation \ref{situation-setup} let $Y/B$ be good.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_Y$-module.
Let $s \in \Gamma(Y, \mathcal{L})$ be a regular section and
assume $\dim_\delta(Y) \leq k + 1$.
Write $[Y]_{k + 1} = \sum n_i[Y_i]$ where $Y_i \subset Y$ are the
irreducible components of $Y$ of $\delta$-dimension $k + 1$.
Set $s_i = s|_{Y_i} \in \Gamma(Y_i, \mathcal{L}|_{Y_i})$. Then
\begin{equation}
\label{equation-equal-as-cycles}
[Z(s)]_k =  \sum n_i[Z(s_i)]_k
\end{equation}
as $k$-cycles on $Y$.

\label{lemma-comparison-ph-etale}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item For $\mathcal{F} \in \Sh(X_\etale)$ we have
$\epsilon_{X, *}a_X^{-1}\mathcal{F} = \pi_X^{-1}\mathcal{F}$
and $a_{X, *}a_X^{-1}\mathcal{F} = \mathcal{F}$.
\item For $\mathcal{F} \in \textit{Ab}(X_\etale)$ torsion we have
$R^i\epsilon_{X, *}(a_X^{-1}\mathcal{F}) = 0$ for $i > 0$.
\end{enumerate}

\label{lemma-normal-scheme-with-alg-closed-function-field}
Let $X$ be an integral normal scheme with separably closed
function field.
\begin{enumerate}
\item A separated \'etale morphism $U \to X$ is a
disjoint union of open immersions.
\item All local rings of $X$ are strictly henselian.
\end{enumerate}

\label{lemma-descending-property-finite-presentation}
The property $\mathcal{P}(f) =$``$f$ is of finite presentation''
is fpqc local on the base.

\label{lemma-gerbe-of-lifts-first-order}
In Remark \ref{remark-gerbe-of-lifts} assume $\mathcal{X} \subset \mathcal{X}'$
is a first order thickening. Then
\begin{enumerate}
\item the automorphism sheaves of objects of the gerbe
$p : \mathcal{C} \to W_{spaces, \etale}$ constructed
in Remark \ref{remark-gerbe-of-lifts} are abelian, and
\item the sheaf of groups $\mathcal{G}$ constructed in
Stacks, Lemma \ref{stacks-lemma-gerbe-abelian-auts}
is a quasi-coherent $\mathcal{O}_W$-module.
\end{enumerate}

\label{lemma-taut-weakly-admissible}
Let $\varphi : A \to B$ be a continuous map of weakly admissible topological
rings. The following are equivalent
\begin{enumerate}
\item $\varphi$ is taut,
\item for every weak ideal of definition $I \subset A$ the closure of
$\varphi(I)B$ is a weak ideal of definition of $B$ and these form a
fundamental system of weak ideals of definition of $B$.
\end{enumerate}

\label{lemma-integral-A}
Let $f : X \to Y$ be an integral morphism of schemes.
Then property (A) holds.

\label{lemma-BG-algebraic}
\begin{slogan}
Gerbes are algebraic if and only if the associated groups are flat
and locally of finite presentation
\end{slogan}
Let $S$ be a scheme and let $B$ be an algebraic space over $S$.
Let $G$ be a group algebraic space over $B$.
Endow $B$ with the trivial action of $G$.
Then the quotient stack $[B/G]$ is an algebraic stack
if and only if $G$ is flat and locally of finite presentation over $B$.

\label{proposition-torsion-complete}
\begin{reference}
This is a special case of \cite[Theorem 1.1]{Porta-Liran-Yekutieli}.
\end{reference}
Let $A$ be a ring and let $I \subset A$ be a finitely generated ideal.
The functors $R\Gamma_Z$ and ${\ }^\wedge$
define quasi-inverse equivalences of categories
$$
D_{I^\infty\text{-torsion}}(A) \leftrightarrow D_{comp}(A, I)
$$

\label{lemma-push-coherent}
\begin{reference}
See \cite[Chapter V]{Serre_algebre_locale}.
\end{reference}
Suppose that $f : X \to Y$ is a proper morphism of varieties.
Let $\mathcal{F}$ be a coherent sheaf with
$\dim(\text{Supp}(\mathcal{F})) \leq k$, then
$f_*[\mathcal{F}]_k = [f_*\mathcal{F}]_k$. In particular, if
$Z \subset X$ is a closed subscheme of dimension $\leq k$, then
$f_*[Z]_k = [f_*\mathcal{O}_Z]_k$.

\label{proposition-flat-finite-type-finite-presentation-domain}
Let $R$ be a domain. Let $R \to S$ be a ring map of finite type.
Let $M$ be a finite $S$-module.
\begin{enumerate}
\item If $S$ is flat over $R$, then $S$ is a finitely presented $R$-algebra.
\item If $M$ is flat as an $R$-module, then $M$ is finitely presented
as an $S$-module.
\end{enumerate}

\label{lemma-support-affine-open}
Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $\Spec(A) = U \subset X$ be an affine open, and set
$M = \Gamma(U, \mathcal{F})$.
Let $x \in U$, and let $\mathfrak p \subset A$ be the corresponding prime.
The following are equivalent
\begin{enumerate}
\item $\mathfrak p$ is in the support of $M$, and
\item $x$ is in the support of $\mathcal{F}$.
\end{enumerate}

\label{lemma-geomred-in-CM}
We have $\Curvesstack^{geomred} \subset \Curvesstack^{CM}$
as open substacks of $\Curvesstack$.

\label{lemma-lift-map-plus}
The result of Lemma \ref{lemma-lift-map} holds even for
$L \in D^+_{\textit{Coh}}(\mathcal{O}_X)$.

\label{lemma-genus-zero}
The only minimal numerical type of genus zero is
$n = 1$, $m_1 = 1$, $a_{11} = 0$, $w_1 = 1$, $g_1 = 0$.

\label{lemma-analogue-triangle-independent-splittings}
In Situation \ref{situation-ABC}
let $0 \to x \to y \to z \to 0$ be an admissible short
exact sequence in $\text{Comp}(\mathcal{A})$. The triangle
$$
\xymatrix{x\ar[r] & y\ar[r] & z\ar[r]^{\delta} & x[1]}
$$
with $\delta : z \to x[1]$ as defined in Lemma \ref{lemma-get-triangle}
is up to canonical isomorphism in $K(\mathcal{A})$, independent of the
choices made in Lemma \ref{lemma-get-triangle}.

\label{lemma-category-affine-over}
Let $S$ be a scheme. Let $X$ be an affine formal algebraic space over $S$.
Assume $X$ is McQuillan and let $A$ be the weakly admissible topological
ring associated to $X$. Then there is an anti-equivalence of categories
between
\begin{enumerate}
\item the category $\mathcal{C}$ introduced above, and
\item the category of maps $Y \to X$ of finite type of
affine formal algebraic spaces.
\end{enumerate}

\label{lemma-thickening-properties}
\begin{reference}
\cite[Theorem 2.2.5]{Conrad-moduli}
\end{reference}
Let $\mathcal{X} \subset \mathcal{X}'$ be a thickening of algebraic
stacks. Then
\begin{enumerate}
\item $\mathcal{X}$ is an algebraic space if and only if $\mathcal{X}'$
is an algebraic space,
\item $\mathcal{X}$ is a scheme if and only if $\mathcal{X}'$ is a scheme,
\item $\mathcal{X}$ is DM if and only if $\mathcal{X}'$ is DM,
\item $\mathcal{X}$ is quasi-DM if and only if $\mathcal{X}'$ is quasi-DM,
\item $\mathcal{X}$ is separated if and only if $\mathcal{X}'$ is separated,
\item $\mathcal{X}$ is quasi-separated if and only if $\mathcal{X}'$ is
quasi-separated, and
\item add more here.
\end{enumerate}

\label{lemma-finite-dimension}
Let $S$ be a locally Noetherian scheme. Assume
\begin{enumerate}
\item $\mathcal{X}$ is an algebraic stack,
\item $U$ is a scheme locally of finite type over $S$, and
\item $(\Sch/U)_{fppf} \to \mathcal{X}$ is a smooth surjective
morphism.
\end{enumerate}
Then, for any $\mathcal{F} = \mathcal{F}_{\mathcal{X}, k, x_0}$ as in
Section \ref{section-predeformation-categories}
the tangent space $T\mathcal{F}$ and infinitesimal automorphism space
$\text{Inf}(\mathcal{F})$ have finite dimension over $k$.

\label{lemma-quasi-compact-h1-zero-covering}
\begin{reference}
\cite{Serre-criterion}, \cite[II, Theorem 5.2.1 (d') and IV (1.7.17)]{EGA}
\end{reference}
\begin{slogan}
Serre's criterion for affineness.
\end{slogan}
Let $X$ be a scheme.
Assume that
\begin{enumerate}
\item $X$ is quasi-compact,
\item for every quasi-coherent sheaf of ideals
$\mathcal{I} \subset \mathcal{O}_X$ we have $H^1(X, \mathcal{I}) = 0$.
\end{enumerate}
Then $X$ is affine.

\label{lemma-finite-type-rings-TI}
In Lemma \ref{lemma-rings-TI} if $P$ is a finite type $k$-algebra, then
\begin{enumerate}
\item $\text{Inf}(\Deformationcategory_P)$ is finite dimensional if and only if
$\dim(P) = 0$, and
\item $T\Deformationcategory_P$ is finite dimensional if
$\Spec(P) \to \Spec(k)$ is smooth except at a finite number of points.
\end{enumerate}

\label{lemma-properties-diagonal}
\begin{slogan}
Diagonals of morphisms of algebraic stacks are representable by
algebraic spaces and locally of finite type.
\end{slogan}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Then
\begin{enumerate}
\item $\Delta_f$ is representable by algebraic spaces,
and
\item $\Delta_f$ is locally of finite type.
\end{enumerate}

\label{theorem-trace}
Let $X$ be a projective curve over a finite field $k$, $\Lambda$ a finite ring
and $K \in D_{ctf}(X, \Lambda)$. Then the global and local Lefschetz numbers
of $K$ are equal, i.e.,
\begin{equation}
\label{equation-trace-formula}
\text{Tr}(\pi^*_X |_{R\Gamma(X_{\bar k}, K)})
=
\sum\nolimits_{x\in X(k)} \text{Tr}(\pi_X |_{K_{\bar x}})
\end{equation}
in $\Lambda^\natural$.

\label{theorem-cohomology-hypercoverings}
Let $\mathcal{C}$ be a site with fibre products.
Let $X$ be an object of $\mathcal{C}$. Let $i \geq 0$.
The functors
\begin{eqnarray*}
\textit{Ab}(\mathcal{C}) & \longrightarrow & \textit{Ab} \\
\mathcal{F} & \longmapsto & H^i(X, \mathcal{F}) \\
\mathcal{F} & \longmapsto & \check{H}^i_{\text{HC}}(X, \mathcal{F})
\end{eqnarray*}
are canonically isomorphic.

\label{proposition-spaces-diagonal-representable}
Let $S$ be a locally Noetherian scheme. Let
$F : (\Sch/S)_{fppf}^{opp} \to \textit{Sets}$ be a functor. Assume that
\begin{enumerate}
\item $\Delta : F \to F \times F$ is representable by algebraic spaces,
\item $F$ satisfies axioms [-1], [0], [1], [2], [3], [4], [5]
(see Section \ref{section-axioms-functors}), and
\item $\mathcal{O}_{S, s}$ is a G-ring for all finite type points $s$ of $S$.
\end{enumerate}
Then $F$ is an algebraic space.

\label{lemma-finite-proper}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces over
$S$. The following are equivalent
\begin{enumerate}
\item $f$ is finite, and
\item $f$ is affine and proper.
\end{enumerate}

\label{lemma-Rf-shriek-for-quasi-finite}
Let $f : X \to Y$ be a quasi-finite separated morphism of quasi-compact and
quasi-separated schemes. Then the functors $Rf_!$ constructed in
Section \ref{section-derived-lower-shriek-compactification}
agree with the restriction of the functor
$f_! : D(X_\etale, \Lambda) \to D(Y_\etale, \Lambda)$
constructed in Section \ref{section-derived-duality-locally-quasi-finite}
to their common domains of definition.

\label{lemma-first-construction}
Given a ring $A$ there exists a faithfully flat ind-\'etale $A$-algebra $C$
such that every faithfully flat \'etale ring map $C \to B$ has a retraction.

\label{lemma-silly}
Let $A$ be a ring. Let $I$ be an ideal of $A$.
\begin{enumerate}
\item If $\gamma$ is a divided power structure\footnote{Here
and in the following, $\gamma$ stands short for a sequence
of maps $\gamma_1, \gamma_2, \gamma_3, \ldots$ from $I$ to $I$.}
on $I$, then
$n! \gamma_n(x) = x^n$ for $n \geq 1$, $x \in I$.
\end{enumerate}
Assume $A$ is torsion free as a $\mathbf{Z}$-module.
\begin{enumerate}
\item[(2)] A divided power structure on $I$, if it exists, is unique.
\item[(3)] If $\gamma_n : I \to I$ are maps then
$$
\gamma\text{ is a divided power structure}
\Leftrightarrow
n! \gamma_n(x) = x^n\ \forall x \in I, n \geq 1.
$$
\item[(4)] The ideal $I$ has a divided power structure
if and only if there exists
a set of generators $x_i$ of $I$ as an ideal such that
for all $n \geq 1$ we have $x_i^n \in (n!)I$.
\end{enumerate}

\label{lemma-smooth-formally-smooth}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is smooth.
\item The morphism $f$ is locally of finite presentation and
formally smooth.
\end{enumerate}

\label{lemma-formally-permanence}
Let $S$ be a scheme.
Let $F, G, H : (\Sch/S)_{fppf}^{opp} \to \textit{Sets}$.
Let $a : F \to G$, $b : G \to H$ be transformations of functors.
Assume $b$ is formally unramified.
\begin{enumerate}
\item If $b \circ a$ is formally unramified then $a$ is formally unramified.
\item If $b \circ a$ is formally \'etale then $a$ is formally \'etale.
\item If $b \circ a$ is formally smooth then $a$ is formally smooth.
\end{enumerate}

\label{lemma-locally-finite-type-surjective-geometric-points}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Assume $f$ is locally of finite type. The following are equivalent:
\begin{enumerate}
\item $f$ is surjective, and
\item for every algebraically closed field $k$ over $S$ the induced
map $X(k) \to Y(k)$ is surjective.
\end{enumerate}

\label{lemma-1}
\begin{reference}
See \cite{Lech-inequalities} and \cite[Lemma 1 page 299]{MatCA}.
\end{reference}
Let $A$ be a ring. If $f_1, \ldots, f_{r - 1}, f_rg_r$
are independent, then $f_1, \ldots, f_r$ are independent.

\label{lemma-restriction-injective-to-component-site}
\begin{slogan}
An injective abelian sheaf on a simplicial site is injective on each component
\end{slogan}
In Situation \ref{situation-simplicial-site}.
If $\mathcal{I}$ is injective in $\textit{Ab}(\mathcal{C}_{total})$,
then $\mathcal{I}_n$ is injective in $\textit{Ab}(\mathcal{C}_n)$.
If $\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(\mathcal{C}_{total})$,
then $\mathcal{I}_n^\bullet$ is K-injective in $\textit{Ab}(\mathcal{C}_n)$.

\label{lemma-group-scheme-over-field-separated}
In Situation \ref{situation-groupoid-on-field}
assume $R$ is a decent space. Then $R$ is a separated algebraic space.
In Situation \ref{situation-group-over-field} assume that
$G$ is a decent algebraic space. Then $G$ is separated algebraic space.

\label{lemma-global-weird-permanence-etale}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of schemes.
Assume
\begin{enumerate}
\item $Y$ is integral and geometrically unibranch,
\item $g \circ f$ is \'etale,
\item every irreducible component of $X$ dominates $Y$.
\end{enumerate}
Then $f$ is \'etale and $g$ is \'etale at every point in
the image of $f$.

\label{lemma-characterize-representable-by-algebraic-spaces}
Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $f : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of algebraic
stacks over $S$. The following are equivalent:
\begin{enumerate}
\item for $U \in \Ob((\Sch/S)_{fppf})$
the functor $f : \mathcal{X}_U \to \mathcal{Y}_U$ is faithful,
\item the functor $f$ is faithful, and
\item $f$ is representable by algebraic spaces.
\end{enumerate}

\label{lemma-ubiquity-nagata}
The following types of schemes are Nagata.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Noetherian complete local ring.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a Dedekind ring of
characteristic zero.
\item And so on.
\end{enumerate}

\label{lemma-Noetherian-topology}
Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item If $\mathcal{X}$ is locally Noetherian then $|\mathcal{X}|$
is a locally Noetherian topological space.
\item If $\mathcal{X}$ is quasi-compact and locally Noetherian, then
$|\mathcal{X}|$ is a Noetherian topological space.
\end{enumerate}

\label{lemma-composition-relative-conditions}
Having property $(\beta)$, being decent, or being reasonable
is preserved under compositions.

\label{lemma-relative-proj}
In Situation \ref{situation-relative-proj}.
The functor $F$ above is representable by a scheme.

\label{proposition-isom}
In Situation \ref{situation-hom} assume that
\begin{enumerate}
\item $f$ is of finite presentation, and
\item $\mathcal{F}$ and $\mathcal{G}$ are finitely presented
$\mathcal{O}_X$-modules, flat over $B$, with support proper over $B$.
\end{enumerate}
Then the functor $\mathit{Isom}(\mathcal{F}, \mathcal{G})$ is
an algebraic space affine of finite presentation over $B$.

\label{lemma-commutative-chern-perfect}
Let $(S, \delta)$ be as in Situation \ref{situation-setup}.
Let $X$ be locally of finite type over $S$.
Let $E \in D(\mathcal{O}_X)$ be perfect. If the Chern classes
of $E$ are defined then
\begin{enumerate}
\item $c_p(E)$ is in the center of the algebra $A^*(X)$, and
\item if $g : X' \to X$ is locally of finite type and $c \in A^*(X' \to X)$,
then $c \circ c_p(E) = c_p(Lg^*E) \circ c$.
\end{enumerate}

\label{lemma-parasitic-in-terms-flat-fppf}
Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item Let $\mathcal{F}$ be an $\mathcal{O}_\mathcal{X}$-module
with the flat base change property on $\mathcal{X}_\etale$.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is parasitic, and
\item $g^*\mathcal{F} = 0$ where
$g : \Sh(\mathcal{X}_{lisse,\etale}) \to
\Sh(\mathcal{X}_\etale)$ is as in Lemma \ref{lemma-lisse-etale}.
\end{enumerate}
\item Let $\mathcal{F}$ be an $\mathcal{O}_\mathcal{X}$-module on
$\mathcal{X}_{fppf}$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is parasitic, and
\item $g^*\mathcal{F} = 0$ where
$g :  \Sh(\mathcal{X}_{flat,fppf}) \to \Sh(\mathcal{X}_{fppf})$
is as in Lemma \ref{lemma-lisse-etale}.
\end{enumerate}
\end{enumerate}

\label{lemma-finite-presentation-finite-type}
A morphism which is locally of finite presentation is locally of finite type.
A morphism of finite presentation is of finite type.

\label{lemma-dimension-decent-space}
Let $S$ be a scheme. Dimension as defined in
Properties of Spaces, Section \ref{spaces-properties-section-dimension}
behaves well on decent algebraic spaces $X$ over $S$.
\begin{enumerate}
\item If $x \in |X|$, then $\dim_x(|X|) = \dim_x(X)$, and
\item $\dim(|X|) = \dim(X)$.
\end{enumerate}

\label{lemma-composition-separated}
All of the separation axioms listed in
Definition \ref{definition-separated-morphism}
are stable under composition of morphisms.

\label{lemma-gorenstein}
Let $A$ be a Noetherian ring.
\begin{enumerate}
\item If $A$ has a dualizing complex $\omega_A^\bullet$, then
\begin{enumerate}
\item $A$ is Gorenstein $\Leftrightarrow$ $\omega_A^\bullet$ is an invertible
object of $D(A)$,
\item $A_\mathfrak p$ is Gorenstein $\Leftrightarrow$
$(\omega_A^\bullet)_\mathfrak p$ is an invertible object of
$D(A_\mathfrak p)$,
\item $\{\mathfrak p \in \Spec(A) \mid A_\mathfrak p\text{ is Gorenstein}\}$
is an open subset.
\end{enumerate}
\item If $A$ is Gorenstein, then $A$ has a dualizing complex if and
only if $A[0]$ is a dualizing complex.
\end{enumerate}

\label{lemma-extend-hilb-to-spaces}
In Situation \ref{situation-hilb}. Let $T$ be an algebraic space over $S$.
We have
$$
\Mor_{\Sh((\Sch/S)_{fppf})}(T, \Hilbfunctor_{X/B}) =
\left\{
\begin{matrix}
(h, Z)\text{ where }h : T \to B,\ Z \subset X_T \\
\text{finite presentation, flat, proper over }T
\end{matrix}
\right\}
$$
where $X_T = X \times_{B, h} T$.

\label{lemma-monomorphism-injective-points}
\begin{slogan}
Monomorphisms of stacks are injective on points.
\end{slogan}
A monomorphism of algebraic stacks induces an injective map of
sets of points.

\label{lemma-dualizing-syntomic-quasi-finite}
Let $f : Y \to X$ be a morphism of locally Noetherian schemes. If $f$
satisfies the equivalent conditions of Lemma \ref{lemma-syntomic-quasi-finite}
then $\omega_{Y/X}$ is an invertible $\mathcal{O}_Y$-module.

\label{lemma-refine-by-h}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family
of morphisms such that $f_i$ is locally of finite presentation for all $i$.
The following are equivalent
\begin{enumerate}
\item $\{T_i \to T\}_{i \in I}$ is an h covering,
\item there is an h covering which refines $\{T_i \to T\}_{i \in I}$, and
\item $\{\coprod_{i \in I} T_i \to T\}$ is an h covering.
\end{enumerate}

\label{lemma-representations-RS}
Example \ref{example-representations}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{V, \rho_0}$ is a deformation category
for any finite dimensional representation
$\rho_0 : \Gamma \to \text{GL}_k(V)$.

\label{lemma-functor-quasi-coherent-from-affine-diagonal}
Let $R$ be a ring. Let $X$ and $Y$ be schemes over $R$. Assume $X$ is
quasi-compact with affine diagonal.
There is an equivalence of categories between
\begin{enumerate}
\item the category of $R$-linear exact functors
$F : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Y)$
which commute with arbitrary direct sums, and
\item the full subcategory of $\QCoh(\mathcal{O}_{X \times_R Y})$ consisting
of $\mathcal{K}$ such that
\begin{enumerate}
\item $\mathcal{K}$ is flat over $X$,
\item for $\mathcal{F} \in \QCoh(\mathcal{O}_X)$ we have
$R^q\text{pr}_{2, *}(\text{pr}_1^*\mathcal{F}
\otimes_{\mathcal{O}_{X \times_R Y}} \mathcal{K}) = 0$ for $q > 0$.
\end{enumerate}
\end{enumerate}
given by sending $\mathcal{K}$ to the functor $F$ in (\ref{equation-FM-QCoh}).

\label{lemma-pic-diagonal-affine-fp}
The diagonal of $\Picardstack_{X/B}$ over $B$ is affine
and of finite presentation.

\label{lemma-geometrically-reduced-curves}
There exist an open substack $\Curvesstack^{geomred} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item the fibres of the morphism $X \to S$ are geometrically reduced
(More on Morphisms of Spaces, Definition
\ref{spaces-more-morphisms-definition-geometrically-reduced-fibre}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item $X$ is geometrically reduced over $k$.
\end{enumerate}
\end{enumerate}

\label{lemma-deform-property-fp-over-ft}
Consider a commutative diagram
$$
\xymatrix{
(X \subset X') \ar[rr]_{(f, f')} \ar[rd] & & (Y \subset Y') \ar[ld] \\
& (S \subset S')
}
$$
of thickenings. Assume $Y' \to S'$ locally of finite type,
$X' \to S'$ flat and locally of finite presentation,
$X = S \times_{S'} X'$, and $Y = S \times_{S'} Y'$. Then
\begin{enumerate}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat-fp-over-ft}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism-fp-over-ft}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion-fp-over-ft}
\item $f$ is quasi-compact if and only if $f'$ is quasi-compact,
\label{item-quasi-compact-fp-over-ft}
\item $f$ is universally closed if and only if $f'$ is universally closed,
\label{item-universally-closed-fp-over-ft}
\item $f$ is (quasi-)separated if and only if $f'$ is (quasi-)separated,
\label{item-separated-fp-over-ft}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism-fp-over-ft}
\item $f$ is surjective if and only if $f'$ is surjective,
\label{item-surjective-fp-over-ft}
\item $f$ is universally injective if and only if $f'$ is universally injective,
\label{item-universally-injective-fp-over-ft}
\item $f$ is affine if and only if $f'$ is affine,
\label{item-affine-fp-over-ft}
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite-fp-over-ft}
\item
\label{item-relative-dimension-d-fp-over-ft}
$f$ is locally of finite type of relative dimension $d$ if and only if
$f'$ is locally of finite type of relative dimension $d$,
\item $f$ is universally open if and only if $f'$ is universally open,
\label{item-universally-open-fp-over-ft}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic-fp-over-ft}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth-fp-over-ft}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified-fp-over-ft}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale-fp-over-ft}
\item $f$ is proper if and only if $f'$ is proper,
\label{item-proper-fp-over-ft}
\item $f$ is finite if and only if $f'$ is finite,
\label{item-finite-fp-over-ft}
\item
\label{item-finite-locally-free-fp-over-ft}
$f$ is finite locally free (of rank $d$) if and only if $f'$
is finite locally free (of rank $d$), and
\item add more here.
\end{enumerate}

\label{lemma-char-p}
Let $p$ be a prime number.
\begin{enumerate}
\item If $A$ is an $\mathbf{F}_p$-algebra, then $\colim_F A = A^{awn}$.
\item If $S$ is a scheme over $\mathbf{F}_p$, then the
h sheafification of $\mathcal{O}$ sends a quasi-compact
and quasi-separated $X$ to $\colim_F \Gamma(X, \mathcal{O}_X)$.
\end{enumerate}

\label{theorem-curves-algebraic}
\begin{reference}
See \cite[Proposition 3.3, page 8]{dJHS} and
\cite[Appendix B by Jack Hall, Theorem B.1]{Smyth}.
\end{reference}
The stack $\Curvesstack$ (Situation \ref{situation-curves})
is algebraic. In fact, for any algebraic space $B$ the stack
$B\text{-}\Curvesstack$ (Remark \ref{remark-curves-base-change})
is algebraic.

\label{lemma-descend-closed-immersion}
Notation and assumptions as in Situation \ref{situation-descent-property}. If
\begin{enumerate}
\item $f$ is a closed immersion,
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is a closed immersion for some $i \geq 0$.

\label{lemma-compare-cohomology-etale-fppf}
Let $S$ be a scheme and let $X$ be an algebraic space over $S$.
With $a_X : \Sh((\textit{Spaces}/X)_{fppf}) \to \Sh(X_\etale)$
as above:
\begin{enumerate}
\item $H^q(X_\etale, \mathcal{F}) = H^q_{fppf}(X, a_X^{-1}\mathcal{F})$
for an abelian sheaf $\mathcal{F}$ on $X_\etale$,
\item $H^q(X_\etale, K) = H^q_{fppf}(X, a_X^{-1}K)$ for $K \in D^+(X_\etale)$.
\end{enumerate}
Example: if $A$ is an abelian group, then
$H^q_\etale(X, \underline{A}) = H^q_{fppf}(X, \underline{A})$.

\label{lemma-birational-birational}
Let $S$ be a scheme. Let $f : X \to Y$ be a birational morphism of
algebraic spaces over $S$ which are decent and have finitely many
irreducible components. Assume one of the following conditions is satisfied
\begin{enumerate}
\item $f$ is locally of finite type and $Y$ reduced (i.e., integral),
\item $f$ is locally of finite presentation.
\end{enumerate}
Then there exist dense opens $U \subset X$ and $V \subset Y$
such that $f(U) \subset V$ and $f|_U : U \to V$ is an isomorphism.

\label{lemma-flat-module}
\begin{slogan}
Flatness is the same for modules and sheaves.
\end{slogan}
Let $X = \Spec(R)$ be an affine scheme.
Let $\mathcal{F} = \widetilde{M}$ for some $R$-module $M$.
The quasi-coherent sheaf $\mathcal{F}$ is a flat
$\mathcal{O}_X$-module if and only if $M$ is a flat $R$-module.

\label{lemma-descending-property-lci}
The property $\mathcal{P}(f) =$``$f$ is a local complete intersection
morphism'' is fpqc local on the base.

\label{lemma-isolated-sings-curves}
There exist an open substack
$\Curvesstack^{+} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{+}$,
\item the singular locus of $X \to S$ endowed
with any/some closed subspace structure is finite over $S$.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{+}$,
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
\end{enumerate}

\label{lemma-simple-module}
Let $A$ be a $k$-algebra. If $A$ is finite, then
\begin{enumerate}
\item $A$ has a simple module,
\item any nonzero module contains a simple submodule,
\item a simple module over $A$ has finite dimension over $k$, and
\item if $M$ is a simple $A$-module, then $\text{End}_A(M)$ is a
skew field.
\end{enumerate}

\label{lemma-groupoid-on-field-explain-points}
Let $S$ be a scheme. Let $(U, R, s, t, c)$ be a groupoid scheme
over $S$. Assume $U = \Spec(k)$ with $k$ a field.
For any point $r \in R$ there exist
\begin{enumerate}
\item a field extension $k'/k$ with $k'$ algebraically closed,
\item a point $r' \in R'$ where $(U', R', s', t', c')$ is the
restriction of $(U, R, s, t, c)$ via $\Spec(k') \to \Spec(k)$
\end{enumerate}
such that
\begin{enumerate}
\item the point $r'$ maps to $r$ under the morphism $R' \to R$, and
\item the maps $s', t' : R' \to \Spec(k')$ induce isomorphisms
$k' \to \kappa(r')$.
\end{enumerate}

\label{lemma-rig-etale-finite-type}
A rig-\'etale morphism of locally Noetherian formal algebraic spaces
is locally of finite type.

\label{theorem-flattening-map}
In
Situation \ref{situation-iso}
assume
\begin{enumerate}
\item $f$ is of finite presentation,
\item $\mathcal{F}$ is of finite presentation, flat over $S$, and
pure relative to $S$, and
\item $u$ is surjective.
\end{enumerate}
Then $F_{iso}$ is representable by a closed immersion $Z \to S$.
Moreover $Z \to S$ is of finite presentation if $\mathcal{G}$ is
of finite presentation.

\label{lemma-pushout-along-closed-immersion-and-integral}
In More on Morphisms, Situation
\ref{more-morphisms-situation-pushout-along-closed-immersion-and-integral},
for example if $Z \to Y$ and $Z \to X$ are closed immersions of schemes,
there is an equivalence of categories
$$
\textit{F\'Et}_{Y \amalg_Z X}
\longrightarrow
\textit{F\'Et}_Y
\times_{\textit{F\'Et}_Z}
\textit{F\'Et}_X
$$

\label{lemma-curves-qs-lfp}
The morphism $\Curvesstack \to \Spec(\mathbf{Z})$ is quasi-separated and
locally of finite presentation.

\label{lemma-descending-property-finite-locally-free}
The property $\mathcal{P}(f) =$``$f$ is finite locally free''
is fpqc local on the base.

\label{lemma-flat-rig-surjective}
Let $A$ be a Noetherian ring complete with respect to an ideal $I$.
Let $B$ be an $I$-adically complete $A$-algebra. Assume that
\begin{enumerate}
\item the $I$-torsion in $A$ is $0$,
\item $A/I^n \to B/I^nB$ is flat and of finite type for all $n$.
\end{enumerate}
Then $\text{Spf}(B) \to \text{Spf}(A)$ is rig-surjective if and only
if $A/I \to B/IB$ is faithfully flat.

\label{lemma-epsilon}
Let $e\in G$ denote the neutral element. The map
$$
\begin{matrix}
\Lambda[G] & \longrightarrow & \Lambda^{\natural}\\
\sum \lambda_g\cdot g & \longmapsto & \lambda_e
\end{matrix}
$$
factors through $\Lambda[G]^\natural$. We denote
$\varepsilon : \Lambda[G]^\natural\to \Lambda^\natural$ the induced map.

\label{theorem-existence-derived}
In Situation \ref{situation-existence-derived}
there exists a pseudo-coherent $K$ in $D(\mathcal{O}_X)$
such that $K_n = K \otimes_{\mathcal{O}_X}^\mathbf{L} \mathcal{O}_{X_n}$
for all $n$ compatibly with the maps $\varphi_n$.

\label{lemma-closed-immersion-proper}
A closed immersion of algebraic spaces is a proper morphism of
algebraic spaces.

\label{lemma-type-local}
Let $S$ be a scheme. Let
$$
P \in
\left\{
\begin{matrix}
countably\ indexed,\\
countably\ indexed\ and\ classical,\\
weakly\ adic,\ adic*,\ Noetherian
\end{matrix}
\right\}
$$
Let $X$ be a formal algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item if $Y$ is an affine formal algebraic space and
$f : Y \to X$ is representable by algebraic spaces and \'etale,
then $Y$ has property $P$,
\item for some $\{X_i \to X\}_{i \in I}$ as in
Definition \ref{definition-formal-algebraic-space}
each $X_i$ has property $P$.
\end{enumerate}

\label{lemma-pic-gerbe-over-pic-functor}
The morphism $\Picardstack_{X/B} \to \Picardfunctor_{X/B}$
turns the Picard stack into a gerbe over the Picard functor.

\label{lemma-finite-type-flat-over-integral-algebra}
Let $A \to B$ be a finite type, flat ring map with $A$ an integral
domain. Then $B$ is a finitely presented $A$-algebra.

\label{lemma-change-presentation-towards-constructibles}
In Situation \ref{situation-quasi-compact-objects} assume
(\ref{item-enough}), (\ref{item-enough-qc}), and (\ref{item-enough-qc-qs})
hold. Let $\mathcal{O}$ be a sheaf of rings. Assume given a map
$$
\bigoplus\nolimits_{j = 1, \ldots, m} j_{V_j!}\mathcal{O}_{V_j}
\longrightarrow
\bigoplus\nolimits_{i = 1, \ldots, n} j_{U_i!}\mathcal{O}_{U_i}
$$
with $U_i$ and $V_j$ in $\mathcal{B}$, and coverings
$\{U_{ik} \to U_i\}_{k \in K_i}$ with $U_{ik} \in \mathcal{B}$.
Then there exist finite subsets $K'_i \subset K_i$ and
a finite set $L$ of $W_l \in \mathcal{B}$ and a commutative diagram
$$
\xymatrix{
\bigoplus_{l \in L} j_{W_l!}\mathcal{O}_{W_l} \ar[d] \ar[r] &
\bigoplus_{i = 1, \ldots, n} \bigoplus_{k \in K'_i}
j_{U_{ik}!}\mathcal{O}_{U_{ik}} \ar[d] \\
\bigoplus_{j = 1, \ldots, m} j_{V_j!}\mathcal{O}_{V_j} \ar[r] &
\bigoplus_{i = 1, \ldots, n} j_{U_i!}\mathcal{O}_{U_i}
}
$$
inducing an isomorphism on cokernels of the horizontal maps.

\label{lemma-vanishing-affine-char-p-p}
Let $p$ be a prime. Let $S$ be a scheme of characteristic $p$.
\begin{enumerate}
\item If $S$ is affine, then
$H_\etale^q(S, \underline{\mathbf{Z}/p\mathbf{Z}}) = 0$ for all
$q \geq 2$.
\item If $S$ is a quasi-compact and quasi-separated scheme of
dimension $d$, then $H_\etale^q(S, \underline{\mathbf{Z}/p\mathbf{Z}}) = 0$
for all $q \geq 2 + d$.
\end{enumerate}

\label{lemma-Noetherian-finite-type-injective-into-flat-mod-m}
If in Situation \ref{situation-mod-injective} the ring $A$ is Noetherian
then the lemma holds.

\label{lemma-non-irreducible-minimal-type-genus-at-least-one}
If $n, m_i, a_{ij}, w_i, g_i$ is a minimal numerical type
with $n > 1$, then $g \geq 1$.

\label{lemma-splitting-principle}
In the situation above. Let $X \in \Ob(\mathcal{C})$. Let $\mathcal{E}_i$
be a finite collection of locally free $\mathcal{O}_X$-modules of rank $r_i$.
There exists a morphism $p : P \to X$ in $\mathcal{C}$ such that
\begin{enumerate}
\item $p^* : A(X) \to A(P)$ is injective,
\item each $p^*\mathcal{E}_i$ has a filtration whose successive quotients
$\mathcal{L}_{i, 1}, \ldots, \mathcal{L}_{i, r_i}$
are invertible $\mathcal{O}_P$-modules.
\end{enumerate}

\label{lemma-fibre-products-morphism}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$.
\begin{enumerate}
\item The functor $f$ transforms fibre products into fibre products.
\item If $f$ is faithful, then $f$ transforms equalizers into equalizers.
\end{enumerate}

\label{lemma-dimension-function-scheme}
Let $S$ be a scheme. Let $X$ be a locally Noetherian
quasi-separated algebraic space over $S$.
Let $\omega_X^\bullet$ be a dualizing complex on $X$. Then $X$ the function
$|X| \to \mathbf{Z}$ defined by
$$
x \longmapsto \delta(x)\text{ such that }
\omega_{X, \overline{x}}^\bullet[-\delta(x)]
\text{ is a normalized dualizing complex over }
\mathcal{O}_{X, \overline{x}}
$$
is a dimension function on $|X|$.

\label{lemma-ext-from-perfect-into-bounded-QCoh}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $K$ be a perfect object of $D(\mathcal{O}_X)$. Then
\begin{enumerate}
\item there exist integers $a \leq b$ such that for any
$L \in D_\QCoh(\mathcal{O}_X)$ with $H^i(L) = 0$ for $i \in [a, b]$
we have $\Hom_{D(\mathcal{O}_X)}(K, L) = 0$, and
\item if $L$ is bounded, then $\Ext^n_{D(\mathcal{O}_X)}(K, L)$
is zero for all but finitely many $n$.
\end{enumerate}

\label{lemma-henselian-finite-type-injective-into-flat-mod-m}
If in Situation \ref{situation-mod-injective} the ring $A$ is henselian
then the lemma holds.

\label{lemma-regular-model-genus}
\begin{reference}
\cite[Lemma 2.6]{Artin-Winters}
\end{reference}
In Situation \ref{situation-regular-model} let $d = \gcd(m_1, \ldots, m_n)$.
Let $D = \sum (m_i/d) C_i$ as an effective Cartier divisor on $X$. Then
$$
1 - g_C = d [\kappa : k] (1 - g_D)
$$
where $g_C$ is the genus of $C$, $g_D$ is the genus of $D$, and
$\kappa = H^0(D, \mathcal{O}_D)$.

\label{lemma-surjection-from-quasi-compact}
\begin{slogan}
The image of a quasi-compact algebraic space under a surjective morphism
is quasi-compact.
\end{slogan}
Let $S$ be a scheme.
\begin{enumerate}
\item If $X \to Y$ is a surjective morphism of algebraic spaces over $S$,
and $X$ is quasi-compact then $Y$ is quasi-compact.
\item If
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& Z
}
$$
is a commutative diagram of morphisms of algebraic spaces over $S$
and $f$ is surjective and $p$ is quasi-compact, then $q$ is quasi-compact.
\end{enumerate}

\label{lemma-composition-finite-type}
The composition of two morphisms which are locally of finite type is
locally of finite type. The same is true for morphisms of finite type.

\label{lemma-quotient-restricted-power-series-admissible}
In Lemma \ref{lemma-quotient-restricted-power-series}
if $B$ is admissible (for example adic), then the equivalent conditions
(a) -- (d) are also equivalent to
\begin{enumerate}
\item[(e)] $B \to A$ is taut and $B/J \to A/I$ is of finite type for
some ideal of definition $J \subset B$ where $I \subset A$ is
the closure of $JA$.
\end{enumerate}

\label{lemma-pullback-base-change-pushforward}
In Situation \ref{situation-setup-base-change} let $Y \to X \to S$ be locally
of finite type and let $Y' \to X' \to S'$ be the base change by $S' \to S$.
Assume $f : Y \to X$ is proper. Then $f' : Y' \to X'$ is proper and the diagram
$$
\vcenter{
\xymatrix{
Z_k(Y) \ar[r]_{g^*} \ar[d]_{f_*} & Z_{k + c}(Y') \ar[d]^{f'_*} \\
Z_k(X) \ar[r]^{g^*} & Z_{k + c}(X')
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\CH_k(Y) \ar[r]_{g^*} \ar[d]_{f_*} & \CH_{k + c}(Y') \ar[d]^{f'_*} \\
\CH_k(X) \ar[r]^{g^*} & \CH_{k + c}(X')
}
}
$$
of cycle and chow groups commutes.

\label{lemma-finite-support-f-shriek-separated}
Let $f : X \to Y$ be a separated and locally quasi-finite morphism
of schemes. Functorially in $\mathcal{F} \in \textit{Ab}(X_\etale)$
there is a canonical isomorphism(!)
$$
f_{p!}\mathcal{F} \longrightarrow f_!\mathcal{F}
$$
of abelian presheaves which identifies the sheaf
$f_!\mathcal{F}$ of Definition \ref{definition-f-shriek-separated}
with the presheaf $f_{p!}\mathcal{F}$ constructed above.

\label{lemma-where-smooth}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic
spaces over $S$. There is a largest open subspace $U \subset X$
such that $f|_U : U \to Y$ is smooth. Moreover, formation of
this open commutes with base change by
\begin{enumerate}
\item morphisms which are flat and
locally of finite presentation,
\item flat morphisms provided $f$ is locally of finite presentation.
\end{enumerate}

\label{lemma-cech-exact-presheaves}
The functor given by Equation (\ref{equation-cech-functor})
is an exact functor (see Homology, Lemma \ref{homology-lemma-exact-functor}).

\label{lemma-completion-countably-indexed}
\begin{reference}
Email by Ofer Gabber of September 11, 2014.
\end{reference}
Let $S$ be a scheme. Let $X = \Spec(A)$ be an affine scheme over $S$.
Let $T \subset X$ be a closed subscheme.
\begin{enumerate}
\item If the formal completion $X_{/T}$ is countably indexed
and there exist countably many $f_1, f_2, f_3, \ldots \in A$ such that
$T = V(f_1, f_2, f_3, \ldots)$, then $X_{/T}$ is adic*.
\item The conclusion of (1) is wrong if we omit the assumption that
$T$ can be cut out by countably many functions in $X$.
\end{enumerate}

\label{proposition-Garel}
\begin{reference}
\cite{Garel}
\end{reference}
Let $f : Y \to X$ be a finite syntomic morphism of schemes.
The maps $\Theta^p_{Y/X}$ of Lemma \ref{lemma-Garel} define a map of complexes
$$
\Theta_{Y/X} :
f_*\Omega^\bullet_{Y/\mathbf{Z}}
\longrightarrow
\Omega^\bullet_{X/\mathbf{Z}}
$$
with the following properties
\begin{enumerate}
\item in degree $0$ we get
$\text{Trace}_f : f_*\mathcal{O}_Y \to \mathcal{O}_X$, see
Discriminants, Section \ref{discriminant-section-discriminant},
\item we have
$\Theta_{Y/X}(\omega \wedge \eta) = \omega \wedge \Theta_{Y/X}(\eta)$
for $\omega$ in $\Omega^\bullet_{X/\mathbf{Z}}$ and $\eta$
in $f_*\Omega^\bullet_{Y/\mathbf{Z}}$,
\item if $f$ is a morphism over a base scheme $S$, then
$\Theta_{Y/X}$ induces a map of complexes
$f_*\Omega^\bullet_{Y/S} \to \Omega^\bullet_{X/S}$.
\end{enumerate}

\label{lemma-local-purity}
Let $(A, \mathfrak m)$ be a regular local ring of dimension $d \geq 2$.
Set $X = \Spec(A)$ and $U = X \setminus \{\mathfrak m\}$. Then
\begin{enumerate}
\item the functor $\textit{F\'Et}_X \to \textit{F\'Et}_U$
is essentially surjective, i.e., purity holds for $A$,
\item any finite $A \to B$ with $B$ normal which
induces a finite \'etale morphism on punctured spectra is \'etale.
\end{enumerate}

\label{lemma-functor-modules}
Let $R$ be a ring. Let $A$ and $B$ be $R$-algebras. There is an
equivalence of categories between
\begin{enumerate}
\item the category of $R$-linear functors
$F : \text{Mod}_A \to \text{Mod}_B$ which
are right exact and commute with arbitrary direct sums, and
\item the category $\text{Mod}_{A \otimes_R B}$.
\end{enumerate}
given by sending $K$ to the functor $F$ in (\ref{equation-FM-modules}).

\label{lemma-base-change-quasi-finite}
A base change of a quasi-finite morphism is quasi-finite.
The same holds for locally quasi-finite.

\label{lemma-non-flat-group-scheme}
There exists a group scheme $G$ over a base $S$ whose identity
component is flat over $S$ but which is not flat over $S$.

\label{lemma-application-nice-K-injective}
Let $X$ be a scheme. Let $F : \textit{Mod}(\mathcal{O}_X) \to \textit{Ab}$
be an additive functor and $N \geq 0$ an integer. Assume that
\begin{enumerate}
\item $F$ commutes with countable direct products,
\item $R^pF(\mathcal{F}) = 0$ for all $p \geq N$ and $\mathcal{F}$
quasi-coherent.
\end{enumerate}
Then for $E \in D_\QCoh(\mathcal{O}_X)$
\begin{enumerate}
\item $H^i(RF(\tau_{\leq a}E)) \to H^i(RF(E))$ is an isomorphism
for $i \leq a$,
\item $H^i(RF(E)) \to H^i(RF(\tau_{\geq b - N + 1}E))$ is an isomorphism
for $i \geq b$,
\item if $H^i(E) = 0$ for $i \not \in [a, b]$ for some
$-\infty \leq a \leq b \leq \infty$, then $H^i(RF(E)) = 0$
for $i \not \in [a, b + N - 1]$.
\end{enumerate}

\label{lemma-check-separated-dvr}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks. Assume
\begin{enumerate}
\item $\mathcal{Y}$ is locally Noetherian,
\item $f$ is locally of finite type and quasi-separated,
\item for every commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r]_x \ar[d]_j & \mathcal{X} \ar[d]^f \\
\Spec(A) \ar[r]^y \ar@{-->}[ru] & \mathcal{Y}
}
$$
where $A$ is a discrete valuation ring and $K$ its fraction field
and any $2$-arrow $\gamma : y \circ j \to f \circ x$ the category
of dotted arrows (Morphisms of Stacks, Definition
\ref{stacks-morphisms-definition-fill-in-diagram})
is either empty or a setoid with exactly one isomorphism class.
\end{enumerate}
Then $f$ is separated.

\label{lemma-base-change-universally-injective}
The base change of a universally injective morphism of algebraic stacks
by any morphism of algebraic stacks is universally injective.

\label{lemma-lim-not-quasi-compact}
There exists an inverse system of quasi-compact topological spaces
over $\mathbf{N}$ whose limit is not quasi-compact.

\label{lemma-triangle-independent-splittings}
Let $(A, \text{d})$ be a differential graded algebra. Let
$0 \to K \to L \to M \to 0$ be an admissible short exact sequence
of differential graded $A$-modules. The triangle
\begin{equation}
\label{equation-triangle-associated-to-admissible-ses}
K \to L \to M \xrightarrow{\delta} K[1]
\end{equation}
with $\delta$ as in Lemma \ref{lemma-admissible-ses} is, up to canonical
isomorphism in $K(\text{Mod}_{(A, \text{d})})$, independent of the choices
made in Lemma \ref{lemma-admissible-ses}.

\label{lemma-lisse-etale-structure-sheaf}
Let $\mathcal{X}$ be an algebraic stack. Notation as in
Lemmas \ref{lemma-lisse-etale} and \ref{lemma-lisse-etale-modules}.
\begin{enumerate}
\item We have $g_!\mathcal{O}_{\mathcal{X}_{lisse,\etale}} =
\mathcal{O}_\mathcal{X}$.
\item We have $g_!\mathcal{O}_{\mathcal{X}_{flat, fppf}} =
\mathcal{O}_\mathcal{X}$.
\end{enumerate}

\label{lemma-lqf-f-shriek-separated-colimits}
Let $f : X \to Y$ be a morphism of schemes which is separated and
locally quasi-finite. Then
\begin{enumerate}
\item for $\mathcal{F}$ in $\textit{Ab}(X_\etale)$ and a geometric
point $\overline{y} : \Spec(k) \to Y$ we have
$$
(f_!\mathcal{F})_{\overline{y}} =
\bigoplus\nolimits_{f(\overline{x}) = \overline{y}} \mathcal{F}_{\overline{x}}
$$
functorially in $\mathcal{F}$, and
\item the functor $f_!$ is exact.
\end{enumerate}

\label{lemma-affine-over-well-nigh-affine}
Let the algebraic stack $\mathcal{X}$ be well-nigh affine.
\begin{enumerate}
\item If $\mathcal{X}$ is an algebraic space, then it is affine.
\item If $\mathcal{X}' \to \mathcal{X}$ is an affine morphism
of algebraic stacks, then $\mathcal{X}'$ is well-nigh affine.
\end{enumerate}

\label{lemma-zariski-etale-smooth-syntomic-fppf-ph}
Any fppf covering is a ph covering, and a fortiori,
any syntomic, smooth, \'etale or Zariski covering is a ph covering.

\label{lemma-ample-tensor-globally-generated}
\begin{reference}
\cite[II Proposition 4.5.6(ii)]{EGA}
\end{reference}
Let $X$ be a scheme. Let $\mathcal{L}$ and $\mathcal{M}$
be invertible $\mathcal{O}_X$-modules. If
\begin{enumerate}
\item $\mathcal{L}$ is ample, and
\item the open sets $X_t$ where $t \in \Gamma(X, \mathcal{M}^{\otimes m})$
for $m > 0$ cover $X$,
\end{enumerate}
then $\mathcal{L} \otimes \mathcal{M}$ is ample.

\label{lemma-verify-site-h}
Let $S$ be a scheme. Let $\Sch_h$ be a big h
site containing $S$. Then $(\textit{Aff}/S)_h$ is a site.

\label{lemma-finite-etale-stack}
The functor
$$
p : \textit{F\'Et} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack over $(\Sch/S)_{fppf}$.

\label{lemma-h-limit-preserving}
Let $S$ be a scheme. Let $F$ be a contravariant functor defined
on the category of all schemes over $S$. If
\begin{enumerate}
\item $F$ satisfies the sheaf property for the h topology, and
\item $F$ is limit preserving
(Limits, Remark \ref{limits-remark-limit-preserving}),
\end{enumerate}
then $F$ satisfies the sheaf property for the V topology.

\label{lemma-immersion-differentials}
If $X \to S$ is an immersion, or more generally a monomorphism, then
$\Omega_{X/S}$ is zero.

\label{lemma-tensor-simple}
Let $A$, $A'$ be two simple $k$-algebras one of which is finite and central
over $k$. Then $A \otimes_k A'$ is simple.

\label{lemma-cartesian-equivalent-descent-datum}
Let $f : X \to S$ be a morphism of schemes. The construction
$$
\begin{matrix}
\text{category of cartesian } \\
\text{schemes over } (X/S)_\bullet
\end{matrix}
\longrightarrow
\begin{matrix}
\text{ category of descent data} \\
\text{ relative to } X/S
\end{matrix}
$$
of Lemma \ref{lemma-cartesian-over}
is an equivalence of categories.

\label{lemma-noncomplete-completion}
There exists a local ring $R$ and a maximal ideal $\mathfrak m$ such that
the completion $R^\wedge$ of $R$ with respect to $\mathfrak m$ has the
following properties
\begin{enumerate}
\item $R^\wedge$ is local, but its maximal ideal is not equal to
$\mathfrak m R^\wedge$,
\item $R^\wedge$ is not a complete local ring, and
\item $R^\wedge$ is not $\mathfrak m$-adically complete as an $R$-module.
\end{enumerate}

\label{lemma-keel-mori-diagonal}
Let $\mathcal{X}$ be an algebraic stack. Assume
$\mathcal{I}_\mathcal{X} \to \mathcal{X}$ is finite.
Let $f : \mathcal{X} \to M$ be the moduli space constructed in
Theorem \ref{theorem-keel-mori}.
\begin{enumerate}
\item If $\mathcal{X}$ is quasi-separated, then $M$ is quasi-separated.
\item If $\mathcal{X}$ is separated, then $M$ is separated.
\item Add more here, for example relative versions of the above.
\end{enumerate}

\label{lemma-locally-finite-presentation-limit-preserving}
Let $S$ be a scheme. Let $\mathcal{X}$ be an algebraic stack
over $S$. If $\mathcal{X} \to S$ is locally of finite presentation,
then $\mathcal{X}$ is limit preserving in the sense of
Artin's Axioms, Definition \ref{artin-definition-limit-preserving}
(equivalently: the morphism $\mathcal{X} \to S$ is limit preserving).

\label{lemma-RS-fiber-product-morphisms}
Let
$$
\xymatrix{
\mathcal{H} \times_\mathcal{F} \mathcal{G} \ar[r] \ar[d] &
\mathcal{G} \ar[d]^g \\
\mathcal{H} \ar[r]^f & \mathcal{F}
}
$$
be $2$-fibre product of categories cofibered in groupoids over
$\mathcal{C}_\Lambda$. If $\mathcal{F}, \mathcal{G}, \mathcal{H}$
all satisfy (RS), then $\mathcal{H} \times_\mathcal{F} \mathcal{G}$
satisfies (RS).

\label{lemma-category-fibred-space}
In the situation above the category
$\mathcal{C}_{X/\Lambda}$ is fibred over $X_\etale$.

\label{lemma-nonsplit-locally-split}
There exists a ring $R$ and a nonsplit sequence of modules
which becomes split Zariski locally.

\label{lemma-DM-curves}
There exist an open substack $\Curvesstack^{DM} \subset \Curvesstack$
with the following properties
\begin{enumerate}
\item $\Curvesstack^{DM} \subset \Curvesstack$ is the maximal
open substack which is DM,
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{DM}$,
\item the group algebraic space $\mathit{Aut}_S(X)$ is unramified over $S$,
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{DM}$,
\item $\mathit{Aut}(X)$ is geometrically reduced over $k$ and
has dimension $0$,
\item $\mathit{Aut}(X) \to \Spec(k)$ is unramified.
\end{enumerate}
\end{enumerate}

\label{lemma-coherent-hom}
Let $\mathcal{X}$ be a locally Noetherian algebraic stack. Let $\mathcal{F}$
and $\mathcal{G}$ be coherent be $\mathcal{O}_\mathcal{X}$-modules. Then
the internal hom $hom(\mathcal{F}, \mathcal{G})$
constructed in Lemma \ref{lemma-internal-hom-fp-into-qcoh}
is a coherent $\mathcal{O}_\mathcal{X}$-module.

\label{lemma-modification-of-dim-2-is-projective-over-complete}
If $(A, \mathfrak m, \kappa)$ is a complete Noetherian local domain
of dimension $2$, then every modification of $\Spec(A)$ is projective over $A$.

\label{lemma-etale-formally-etale}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is \'etale, and
\item the morphism $f$ is locally of finite presentation and
formally \'etale.
\end{enumerate}

\label{lemma-finite-B}
Let $f : X \to Y$ be a finite morphism of schemes.
Then property (B) holds.

\label{lemma-descending-property-thickening}
The property of being a thickening is fpqc local.
Similarly for first order thickenings.

\label{lemma-nagata-universally-Japanese}
Let $X$ be a scheme.
The following are equivalent:
\begin{enumerate}
\item $X$ is Nagata, and
\item $X$ is locally Noetherian and universally Japanese.
\end{enumerate}

\label{lemma-dimension-at-finite-type-point}
If $\mathcal{X}$ is a locally Noetherian algebraic stack, and if
$x \in |\mathcal{X}|$, then
for any open substack $\mathcal{V}$ of $\mathcal{X}$ containing $x$,
there is a finite type point $x_0 \in |\mathcal{V}|$ such that
$\dim_{x_0}(\mathcal{X}) = \dim_x(\mathcal{V})$.

\label{lemma-base-change-universally-submersive}
The base change of a universally submersive morphism of algebraic spaces
by any morphism of algebraic spaces is universally submersive.

\label{lemma-lqf-f-shriek-stalk}
Let $f : X \to Y$ be a locally quasi-finite morphism of schemes. Then
\begin{enumerate}
\item for $\mathcal{F}$ in $\textit{Ab}(X_\etale)$ and a geometric
point $\overline{y} : \Spec(k) \to Y$ we have
$$
(f_!\mathcal{F})_{\overline{y}} =
\bigoplus\nolimits_{f(\overline{x}) = \overline{y}} \mathcal{F}_{\overline{x}}
$$
functorially in $\mathcal{F}$, and
\item the functor $f_! : \textit{Ab}(X_\etale) \to \textit{Ab}(Y_\etale)$
is exact and commutes with direct sums.
\end{enumerate}

\label{lemma-completion-polynomial-ring-not-flat-bis}
If $R$ is a valuation ring of dimension $> 1$, then $R[[x]]$
is flat over $R$ but not flat over $R[x]$.

\label{lemma-divide-by-torsion}
Let $A$ be a ring and let $I \subset A$ be a finitely generated ideal.
Let $M$ be an $A$-module. Let $Z = V(I)$.
Then $H^0_I(M) = H^0_Z(M)$. Let $N$ be the common value and
set $M' = M/N$. Then
\begin{enumerate}
\item $H^0_I(M') = 0$ and $H^p_I(M) = H^p_I(M')$ and $H^p_I(N) = 0$
for all $p > 0$,
\item $H^0_Z(M') = 0$ and $H^p_Z(M) = H^p_Z(M')$ and $H^p_Z(N) = 0$
for all $p > 0$.
\end{enumerate}

\label{lemma-characterize-unramified}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent
\begin{enumerate}
\item $f$ is unramified, and
\item $f$ is locally of finite type and its diagonal is \'etale.
\end{enumerate}

\label{lemma-descending-property-locally-finite-type}
The property $\mathcal{P}(f) =$``$f$ is locally of finite type''
is fpqc local on the base.

\label{lemma-descent-surjective}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Let $\mathcal{Y}' \to \mathcal{Y}$ be a surjective morphism of algebraic
stacks. If the base change $f' : \mathcal{Y}' \times_\mathcal{Y} \mathcal{X}
\to \mathcal{Y}'$ of $f$ is surjective, then $f$ is surjective.

\label{lemma-number-of-branches-1}
Let $X$ be a scheme. Let $x \in X$.
\begin{enumerate}
\item The number of branches of $X$ at $x$ is $1$ if and only if
$X$ is unibranch at $x$.
\item The number of geometric branches of $X$ at $x$ is $1$ if and only if
$X$ is geometrically unibranch at $x$.
\end{enumerate}

\label{lemma-representable-quasi-separated-diagonal-quasi-compact}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
representable by algebraic spaces. Then the following are equivalent
\begin{enumerate}
\item $f$ is quasi-separated,
\item $\Delta_f$ is quasi-compact, or
\item $\Delta_f$ is of finite type.
\end{enumerate}

\label{lemma-quasi-separated-h1-zero-covering}
\begin{reference}
\cite{Serre-criterion}, \cite[II, Theorem 5.2.1]{EGA}
\end{reference}
\begin{slogan}
Serre's criterion for affineness.
\end{slogan}
Let $X$ be a scheme. Assume that
\begin{enumerate}
\item $X$ is quasi-compact,
\item $X$ is quasi-separated, and
\item $H^1(X, \mathcal{I}) = 0$ for every quasi-coherent sheaf
of ideals $\mathcal{I}$ of finite type.
\end{enumerate}
Then $X$ is affine.

\label{lemma-Noetherian-topology}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item If $X$ is locally Noetherian then $|X|$ is a locally Noetherian
topological space.
\item If $X$ is quasi-compact and locally Noetherian, then $|X|$
is a Noetherian topological space.
\end{enumerate}

\label{lemma-functor-quasi-coherent-from-separated}
In Lemma \ref{lemma-functor-quasi-coherent-from-affine-diagonal}
let $F$ and $\mathcal{K}$ correspond. If $X$ is separated and
flat over $R$, then there is a surjection
$\mathcal{O}_X \boxtimes F(\mathcal{O}_X) \to \mathcal{K}$.

\label{lemma-diagonal-negative}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type of genus $g$.
If $n > 1$, then $a_{ii} < 0$ for all $i$.

\label{lemma-reduced-is-locally-reduced}
Let $X$ be a scheme. Then $X$ is reduced if and only if $X$ is
``locally reduced'' in the sense of Definition \ref{definition-locally-P}.

\label{lemma-refine-by-V}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family
of morphisms. The following are equivalent
\begin{enumerate}
\item $\{T_i \to T\}_{i \in I}$ is a V covering,
\item there is a V covering which refines $\{T_i \to T\}_{i \in I}$, and
\item $\{\coprod_{i \in I} T_i \to T\}$ is a V covering.
\end{enumerate}

\label{lemma-descending-property-unramified}
The property $\mathcal{P}(f) =$``$f$ is unramified''
is fpqc local on the base.

\label{lemma-trivial-local-pic-regular}
Let $(A, \mathfrak m)$ be a regular local ring. Then the Picard
group of the punctured spectrum of $A$ is trivial.

\label{lemma-thickening-affine-scheme}
\begin{slogan}
Affineness is insensitive to thickenings
\end{slogan}
\begin{reference}
The case of a finite order thickening is \cite[Proposition 5.1.9]{EGA1}.
\end{reference}
Any thickening of an affine scheme is affine.

\label{lemma-curve-isolated-lci}
In Example \ref{example-schemes} let $X$ be a scheme over $k$. Assume
\begin{enumerate}
\item $X$ is separated, finite type over $k$ and $\dim(X) \leq 1$,
\item $X$ is a local complete intersection over $k$, and
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
Then $\Deformationcategory_X$ is unobstructed.

\label{lemma-group-quotient-stack-in-groupoids}
Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p : [[X/G]] \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\label{lemma-deform}
Let $(f, f') : (X \subset X') \to (S \subset S')$ be a morphism
of first order thickenings. Assume that $f$ is flat.
Then the following are equivalent
\begin{enumerate}
\item $f'$ is flat and $X = S \times_{S'} X'$, and
\item the canonical map $f^*\mathcal{C}_{S/S'} \to \mathcal{C}_{X/X'}$
is an isomorphism.
\end{enumerate}

\label{lemma-NL-smooth}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is smooth, and
\item $f$ is locally of finite presentation,
$H^{-1}(\NL_{X/Y}) = 0$, and $H^0(\NL_{X/Y}) = \Omega_{X/Y}$
is finite locally free.
\end{enumerate}

\label{lemma-vanishing-separated}
In Situation \ref{situation-vanishing} the morphism $p : X \to \Spec(A)$ is
separated.

\label{proposition-matlis}
Let $(R, \mathfrak m, \kappa)$ be a complete local Noetherian ring.
Let $E$ be an injective hull of $\kappa$ over $R$. The functor
$D(-) = \Hom_R(-, E)$ induces an anti-equivalence
$$
\left\{
\begin{matrix}
R\text{-modules with the} \\
\text{descending chain condition}
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
R\text{-modules with the} \\
\text{ascending chain condition}
\end{matrix}
\right\}
$$
and we have $D \circ D = \text{id}$ on either side of the equivalence.

\label{lemma-finite-separated-flat-locally-finite-presentation}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$ which
is separated, flat, and locally of finite presentation.
In this case
\begin{enumerate}
\item $(X/Y)_{fin} \to Y$ is separated, representable, and \'etale, and
\item if $Y$ is a scheme, then $(X/Y)_{fin}$ is (representable by) a scheme.
\end{enumerate}

\label{lemma-describe-categories}
Let $(R, \mathfrak m, \kappa)$ be a Noetherian local ring.
Let $E$ be an injective hull of $\kappa$.
\begin{enumerate}
\item For an $R$-module $M$ the following are equivalent:
\begin{enumerate}
\item $M$ satisfies the ascending chain condition,
\item $M$ is a finite $R$-module, and
\item there exist $n, m$ and an exact sequence
$R^{\oplus m} \to R^{\oplus n} \to M \to 0$.
\end{enumerate}
\item For an $R$-module $M$ the following are equivalent:
\begin{enumerate}
\item $M$ satisfies the descending chain condition,
\item $M$ is $\mathfrak m$-power torsion and
$\dim_\kappa(M[\mathfrak m]) < \infty$, and
\item there exist $n, m$ and an exact sequence
$0 \to M \to E^{\oplus n} \to E^{\oplus m}$.
\end{enumerate}
\end{enumerate}

\label{lemma-locally-finite-type-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally of finite type''
is fppf local on the source.

\label{lemma-smooth-surjective-morphism-implies-algebraic}
Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $u : \mathcal{U} \to \mathcal{X}$ be a $1$-morphism of
stacks in groupoids over $(\Sch/S)_{fppf}$. If
\begin{enumerate}
\item $\mathcal{U}$ is representable by an algebraic space, and
\item $u$ is representable by algebraic spaces, surjective and smooth,
\end{enumerate}
then $\mathcal X$ is an algebraic stack over $S$.

\label{lemma-K-agrees-affine}
Let $X = \Spec(R)$ be an affine scheme. Then $K_0(X) = K_0(R)$
and if $R$ is Noetherian then $K'_0(X) = K'_0(R)$.

\label{lemma-base-change-universal-homeomorphism}
The base change of a universal homeomorphism of algebraic stacks
by any morphism of algebraic stacks is a universal homeomorphism.

\label{lemma-base-change-separated}
All of the separation axioms listed in
Definition \ref{definition-separated}
are stable under base change.

\label{lemma-decent-irreducible-closed}
Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
There are canonical bijections between the following sets:
\begin{enumerate}
\item the set of points of $X$, i.e., $|X|$,
\item the set of irreducible closed subsets of $|X|$,
\item the set of integral closed subspaces of $X$.
\end{enumerate}
The bijection from (1) to (2) sends $x$ to $\overline{\{x\}}$.
The bijection from (3) to (2) sends $Z$ to $|Z|$.

\label{lemma-relative-approximation}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Assume that
\begin{enumerate}
\item $X$ is quasi-compact and quasi-separated, and
\item $Y$ is quasi-separated.
\end{enumerate}
Then $X = \lim X_i$ is a limit of a directed inverse system of algebraic spaces
$X_i$ of finite presentation over $Y$ with affine transition morphisms
over $Y$.

\label{lemma-descend-separated}
Notation and assumptions as in Situation \ref{situation-descent}.
If $X$ is separated, then $X_i$ is separated for some $i \in I$.

\label{lemma-morphism-finite-type-bounded-dimension}
Let $f : X \to Y$ be a morphism of finite type with $Y$ quasi-compact.
Then the dimension of the fibres of $f$ is bounded.

\label{lemma-chow-noetherian-separated}
\begin{reference}
\cite[IV Theorem 3.1]{Kn}
\end{reference}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Assume $f$ separated of finite type, and $Y$ separated and
Noetherian. Then there exists a commutative diagram
$$
\xymatrix{
X \ar[rd] & X' \ar[l] \ar[d] \ar[r] & \mathbf{P}^n_Y \ar[ld] \\
& Y
}
$$
where $X' \to X$ is a $U$-admissible blowup for some dense open
$U \subset X$ and the morphism $X' \to \mathbf{P}^n_Y$ is an immersion.

\label{lemma-omega-locally-quasi-coherent}
In Situation \ref{situation-global}.
The sheaf of differentials $\Omega_{X/S}$ has the following two
properties:
\begin{enumerate}
\item $\Omega_{X/S}$ is locally quasi-coherent, and
\item for any morphism $(U, T, \delta) \to (U', T', \delta')$
of $\text{Cris}(X/S)$ where $f : T \to T'$ is a closed immersion
the map $c_f : f^*(\Omega_{X/S})_{T'} \to (\Omega_{X/S})_T$ is surjective.
\end{enumerate}

\label{lemma-versal-criterion}
Let $\mathcal{F}$ be a predeformation category satisfying (S1) and
(S2). Let $\xi$ be a formal object of $\mathcal{F}$ corresponding to
$\underline{\xi} : \underline{R}|_{\mathcal{C}_\Lambda} \to \mathcal{F}$, see
Remark \ref{remark-formal-objects-yoneda}.
Then $\xi$ is versal if and only if the following two conditions hold:
\begin{enumerate}
\item the map
$d\underline{\xi} : T\underline{R}|_{\mathcal{C}_\Lambda} \to T\mathcal{F}$
on tangent spaces is surjective, and
\item given a diagram in $\widehat{\mathcal{F}}$
$$
\vcenter{
\xymatrix{
            &  y \ar[d] \\
\xi \ar[r]  &  x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
         &   B  \ar[d]^{f} \\
R \ar[r] &   A
}
}
$$
in $\widehat{\mathcal{C}}_\Lambda$ with $B \to A$ a small extension of
Artinian rings, then there exists a ring map $R \to B$ such that
$$
\xymatrix{
         &   B  \ar[d]^{f} \\
R \ar[ur] \ar[r] &   A
}
$$
commutes.
\end{enumerate}

\label{lemma-unramified-locally-finite-type}
An unramified morphism is locally of finite type.
A G-unramified morphism is locally of finite presentation.

\label{lemma-integral-algebra-directed-colimit-finite}
Let $X$ be a scheme. Assume $X$ is quasi-compact and quasi-separated.
Let $\mathcal{A}$ be an integral quasi-coherent $\mathcal{O}_X$-algebra.
Then
\begin{enumerate}
\item $\mathcal{A}$ is the directed colimit of its finite
quasi-coherent $\mathcal{O}_X$-subalgebras, and
\item $\mathcal{A}$ is a direct colimit of finite and finitely
presented quasi-coherent $\mathcal{O}_X$-algebras.
\end{enumerate}

\label{lemma-catenary-local-rings-catenary}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is catenary, and
\item for any $x \in X$ the local ring $\mathcal{O}_{X, x}$ is
catenary.
\end{enumerate}

\label{lemma-kill-colimit}
In Lemma \ref{lemma-kill-colimit-weak} if instead of the empty
condition (2) we assume
\begin{enumerate}
\item[(2')] if $\mathfrak p \in V(I)$ and $\mathfrak p \not = \mathfrak m$,
then $\text{depth}_{A_\mathfrak p}(M_\mathfrak p) + \dim(A/\mathfrak p) > s$,
\end{enumerate}
then the conditions also imply that $H^i_{J_0}(M)$ is a finite
$A$-module for $i \leq s$.

\label{proposition-regular-ideal}
\begin{reference}
Variant of \cite[Corollary 1]{Vasconcelos}. See also
\cite{Iyengar} and \cite{Ferrand-lci}.
\end{reference}
Let $R$ be a Noetherian ring. Let $I \subset R$ be an ideal
which has finite projective dimension and such that $I/I^2$ is
finite locally free over $R/I$. Then $I$ is a regular ideal
(More on Algebra, Definition \ref{more-algebra-definition-regular-ideal}).

\label{lemma-picard-rank-1}
Let $n, m_i, a_{ij}, w_i, g_i$ be a numerical type $T$.
The Picard group of $T$ is a finitely generated abelian group of rank $1$.

\label{lemma-quasi-coherence-scalar-restriction}
\begin{reference}
\cite[I, Proposition 9.6.1]{EGA}
\end{reference}
Let $S$ be a scheme and let $\mathcal{A}$ be a quasi-coherent
$\mathcal{O}_S$-algebra. An $\mathcal{A}$-module is
quasi-coherent as an $\mathcal{O}_S$-module if and only if
it is quasi-coherent as an $\mathcal{A}$-module.

\label{lemma-sections-upstairs-submersive}
Let $S$ be a scheme. Let $f : X \to S$ be a morphism such that
\begin{enumerate}
\item $f$ is submersive, and
\item the geometric fibres of $f$ are connected.
\end{enumerate}
Let $\mathcal{F}$ be a sheaf on $S_\etale$.
Then $\Gamma(S, \mathcal{F}) = \Gamma(X, f^{-1}_{small}\mathcal{F})$.

\label{lemma-representable-diagonal}
\begin{slogan}
The diagonal of a presheaf is representable by algebraic spaces if and only if
every map from a scheme to the presheaf is representable by algebraic spaces.
\end{slogan}
Let $S$ be a scheme.
If $F$ is a presheaf on $(\Sch/S)_{fppf}$.
The following are equivalent:
\begin{enumerate}
\item $\Delta_F : F \to F \times F$ is representable by algebraic spaces,
\item for every scheme $T$ any map $T \to F$ is representable by algebraic
spaces, and
\item for every algebraic space $X$ any map $X \to F$ is representable
by algebraic spaces.
\end{enumerate}

\label{lemma-shriek-equals-star-finite-etale}
Let $j : U \to X$ be finite and \'etale. Then the map
$j_! \to j_*$ of Lemma \ref{lemma-shriek-into-star-separated-etale}
is an isomorphism
on abelian sheaves and sheaves of $\Lambda$-modules.

\label{lemma-gerbe-of-lifts-stack}
The category $p : \mathcal{C} \to W_{spaces, \etale}$ constructed
in Remark \ref{remark-gerbe-of-lifts} is a stack in groupoids.

\label{lemma-valuation-ring-finite-type-injective-into-flat-mod-m}
If in Situation \ref{situation-mod-injective} the ring $A$ is a
valuation ring then the lemma holds.

\label{lemma-injective-hull-indecomposable}
Let $\mathfrak p \subset R$ be a prime of a ring $R$.
Let $E$ be the injective hull of $R/\mathfrak p$. Then
\begin{enumerate}
\item $E$ is indecomposable,
\item $E$ is the injective hull of $\kappa(\mathfrak p)$,
\item $E$ is the injective hull of $\kappa(\mathfrak p)$
over the ring $R_\mathfrak p$.
\end{enumerate}

\label{lemma-structure-quasi-compact-quasi-separated}
\begin{reference}
\cite[Proposition 3.32]{Yasuda}
\end{reference}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
formal algebraic space over $S$. Then $X = \colim X_\lambda$
for a system of algebraic spaces $(X_\lambda, f_{\lambda \mu})$
over a directed set $\Lambda$ where each
$f_{\lambda \mu} : X_\lambda \to X_\mu$ is a thickening.

\label{lemma-match-separated}
Let $S$ be a scheme.
Let $f : X \to Y$ be a representable morphism of algebraic spaces over $S$.
\begin{enumerate}
\item The morphism $f$ is locally separated.
\item The morphism $f$ is (quasi-)separated in the sense of
Definition \ref{definition-separated}
above if and only if $f$ is (quasi-)separated in the sense of
Section \ref{section-representable}.
\end{enumerate}
In particular, if $f : X \to Y$ is a morphism of schemes over $S$, then
$f$ is (quasi-)separated in the sense of
Definition \ref{definition-separated}
if and only if $f$ is (quasi-)separated as a morphism of schemes.

\label{lemma-pullback-and-intersection-product}
Let $f : X \to Y$ be a morphism of nonsingular projective varieties.
The pullback map on chow groups satisfies:
\begin{enumerate}
\item $f^* : \CH^*(Y) \to \CH^*(X)$ is a ring map,
\item $(g \circ f)^* = f^* \circ g^*$ for a composable pair $f, g$,
\item the projection formula holds: $f_*(\alpha) \cdot \beta =
f_*( \alpha \cdot f^*\beta)$, and
\item if $f$ is flat then it agrees with the previous definition.
\end{enumerate}

\label{lemma-cd-sum}
Let $I, J \subset A$ be finitely generated ideals of a ring $A$.
Then $\text{cd}(A, I + J) \leq \text{cd}(A, I) + \text{cd}(A, J)$.

\label{theorem-bootstrap}
\begin{slogan}
Artin's theorem on representability of flat groupoids
\end{slogan}
Let $S$ be a scheme. Let $F : \mathcal{X} \to \mathcal{Y}$
be a $1$-morphism of stacks in groupoids over $(\Sch/S)_{fppf}$. If
\begin{enumerate}
\item $\mathcal{X}$ is representable by an algebraic space, and
\item $F$ is representable by algebraic spaces, surjective, flat and
locally of finite presentation,
\end{enumerate}
then $\mathcal{Y}$ is an algebraic stack.

\label{lemma-simplicial-sheaf-cohomology-site-zero}
In Situation \ref{situation-simplicial-site}. Let $K$ be an object of
$D(\mathcal{C}_{total})$.
\begin{enumerate}
\item If $H^{-p}(\mathcal{C}_p, K_p) = 0$ for all $p \geq 0$, then
$H^0(\mathcal{C}_{total}, K) = 0$.
\item If $R\Gamma(\mathcal{C}_p, K_p) = 0$
for all $p \geq 0$, then $R\Gamma(\mathcal{C}_{total}, K) = 0$.
\end{enumerate}

\label{lemma-effective}
Let $S$ be a locally Noetherian scheme. Let $\mathcal{X}$ be an algebraic
stack over $S$. The functor (\ref{equation-approximation}) is an equivalence.

\label{lemma-zariski}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
Let $V \subset Y$ be an open subspace. If
\begin{enumerate}
\item $f$ is separated, locally of finite type, and flat,
\item $f^{-1}(V) \to V$ is an isomorphism, and
\item $V \to Y$ is quasi-compact and scheme theoretically dense,
\end{enumerate}
then $f$ is an open immersion.

\label{lemma-invariant-set-theoretically-invariant}
In the situation of Definition \ref{definition-set-theoretically-invariant}.
An invariant morphism is set-theoretically invariant.

\label{lemma-NL-smooth}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is smooth, and
\item $f$ is locally of finite presentation,
$H^{-1}(\NL_{X/Y}) = 0$, and $H^0(\NL_{X/Y}) = \Omega_{X/Y}$
is finite locally free.
\end{enumerate}

\label{lemma-resolution-property-ample}
Let $X$ be a scheme. If $X$ has an ample invertible $\mathcal{O}_X$-module,
then $X$ has the resolution property.

\label{proposition-compute-bivariant}
\begin{reference}
\cite[Proposition 17.4.2]{F}
\end{reference}
Let $(S, \delta)$ be as in Situation \ref{situation-setup}.
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of schemes locally
of finite type over $S$. If $g$ is smooth of relative dimension $d$, then
$A^p(X \to Y) = A^{p - d}(X \to Z)$.

\label{lemma-locally-quasi-finite}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces.
Assume $f$ is locally of finite type. The following are equivalent
\begin{enumerate}
\item $f$ is locally quasi-finite,
\item for every morphism $\Spec(k) \to Y$ where $k$ is a field
the space $|X_k|$ is discrete. Here $X_k = \Spec(k) \times_Y X$.
\end{enumerate}

\label{lemma-first-chern-class}
In Situation \ref{situation-setup} let $X/B$ be good.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
The first Chern class of $\mathcal{L}$ on $X$ of
Definition \ref{definition-chern-classes}
is equal to the bivariant class of Lemma \ref{lemma-cap-c1-bivariant}.

\label{lemma-vanishing-above-dimension}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$. Assume $\dim(X) \leq d$ for some integer $d$.
Let $\mathcal{F}$ be a quasi-coherent sheaf $\mathcal{F}$ on $X$.
\begin{enumerate}
\item $H^q(X, \mathcal{F}) = 0$ for $q > d$,
\item $H^d(X, \mathcal{F}) \to H^d(U, \mathcal{F})$ is surjective
for any quasi-compact open $U \subset X$,
\item $H^q_Z(X, \mathcal{F}) = 0$ for $q > d$ for any closed subspace
$Z \subset X$ whose complement is quasi-compact.
\end{enumerate}

\label{lemma-characterize-quasi-excellent}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is quasi-excellent, and
\item $X$ is a G-scheme and J-2.
\end{enumerate}

\label{lemma-base-change-local-isomorphism}
Let $A \to B$ and $A \to A'$ be ring maps. Let $B' = B \otimes_A A'$
be the base change of $B$.
\begin{enumerate}
\item If $A \to B$ is a local isomorphism, then $A' \to B'$ is a
local isomorphism.
\item If $A \to B$ identifies local rings, then $A' \to B'$
identifies local rings.
\end{enumerate}

\label{lemma-non-separated-group-space}
There exists a group algebraic space of finite type over a field
which is not separated (and not even quasi-separated or locally separated).

\label{lemma-unique-point}
Let $\mathcal{Z}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{Z}$ is reduced and $|\mathcal{Z}|$ is a singleton,
\item there exists a surjective flat morphism $\Spec(k) \to \mathcal{Z}$
where $k$ is a field, and
\item there exists a locally of finite type, surjective, flat morphism
$\Spec(k) \to \mathcal{Z}$ where $k$ is a field.
\end{enumerate}

\label{lemma-punctured-still-connected}
\begin{reference}
\cite[Theorem 1.6]{Varbaro}
\end{reference}
Let $(A, \mathfrak m)$ be a Noetherian complete local ring.
Let $I$ be a proper ideal of $A$.
Set $X = \Spec(A)$ and $Y = V(I)$.
Denote
\begin{enumerate}
\item $d$ the minimal dimension of an irreducible component of $X$, and
\item $c$ the minimal dimension of a closed subset $Z \subset X$
such that $X \setminus Z$ is disconnected.
\end{enumerate}
Then for $Z \subset Y$ closed we have $Y \setminus Z$ is connected if
$\dim(Z) < \min(c, d - 1) - \text{cd}(A, I)$. In particular, the punctured
spectrum of $A/I$ is connected if $\text{cd}(A, I) < \min(c, d - 1)$.

\label{lemma-composition-finite-type}
The composition of finite type morphisms is of finite type.
The same holds for locally of finite type.

\label{proposition-find-w-contractible}
For every ring $A$ there exists a faithfully flat, ind-\'etale ring
map $A \to D$ such that $D$ is w-contractible.

\label{lemma-trivial-implications}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
\begin{enumerate}
\item If $f$ is separated, then $f$ is quasi-separated.
\item If $f$ is DM, then $f$ is quasi-DM.
\item If $f$ is representable by algebraic spaces, then $f$ is DM.
\end{enumerate}

\label{lemma-descend-smooth}
With notation and assumptions as in
Situation \ref{situation-descent-property}. If
\begin{enumerate}
\item $f$ is smooth,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is smooth for some $i \geq 0$.

\label{lemma-characterize-excellent}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is excellent, and
\item $X$ is quasi-excellent and universally catenary.
\end{enumerate}

\label{lemma-cartesian-square-Rf-upper-shriek}
Consider a cartesian square
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
$$
of quasi-compact and quasi-separated schemes with $f$ separated and
of finite type. Then we have $Rf^! \circ Rg_* = Rg'_* \circ R(f')^!$.

\label{lemma-finite-presentation-finite-type}
A morphism which is locally of finite presentation is locally of finite type.
A morphism of finite presentation is of finite type.

\label{lemma-morphism-good-diagram}
In Situation \ref{situation-limit-noetherian}.
Let $f : X \to Y$ be a morphism of algebraic spaces quasi-separated
and of finite type over $B$. Let
$$
\vcenter{
\xymatrix{
X \ar[r] \ar[d] & W \ar[d] \\
B \ar[r] & B_{i_1}
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
Y \ar[r] \ar[d] & V \ar[d] \\
B \ar[r] & B_{i_2}
}
}
$$
be diagrams as in (\ref{equation-good-diagram}). Let
$X = \lim_{i \geq i_1} X_i$ and
$Y = \lim_{i \geq i_2} Y_i$ be the corresponding
limit descriptions as in Lemma \ref{lemma-limit-from-good-diagram}.
Then there exists an $i_0 \geq \max(i_1, i_2)$ and a morphism
$$
(f_i)_{i \geq i_0} : (X_i)_{i \geq i_0} \to (Y_i)_{i \geq i_0}
$$
of inverse systems over $(B_i)_{i \geq i_0}$ such that
such that $f = \lim_{i \geq i_0} f_i$.
If $(g_i)_{i \geq i_0} : (X_i)_{i \geq i_0} \to (Y_i)_{i \geq i_0}$
is a second morphism of inverse systems over $(B_i)_{i \geq i_0}$ such that
such that $f = \lim_{i \geq i_0} g_i$
then $f_i = g_i$ for all $i \gg i_0$.

\label{lemma-CM-curves}
There exist an open substack $\Curvesstack^{CM} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{CM}$,
\item the morphism $X \to S$ is Cohen-Macaulay,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{CM}$,
\item $X$ is Cohen-Macaulay.
\end{enumerate}
\end{enumerate}

\label{lemma-twisted-inverse-image}
\begin{reference}
This is almost the same as \cite[Example 4.2]{Neeman-Grothendieck}.
\end{reference}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism between quasi-separated and quasi-compact
algebraic spaces over $S$. The functor $Rf_* : D_\QCoh(X) \to D_\QCoh(Y)$
has a right adjoint.

\label{lemma-reduction-scheme}
\begin{reference}
\cite[3.1.12]{CLO}
\end{reference}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
If $X_{red}$ is a scheme, then $X$ is a scheme.

\label{lemma-K-flat-resolution}
Let $R$ be a ring. Let $(B, \text{d})$ be a differential graded $R$-algebra.
There exists a quasi-isomorphism $(A, \text{d}) \to (B, \text{d})$ of
differential graded $R$-algebras with the following properties
\begin{enumerate}
\item $A$ is K-flat as a complex of $R$-modules,
\item $A$ is a free graded $R$-algebra.
\end{enumerate}

\label{lemma-dg-hull-acyclic}
The functors $F, G$ of Lemma \ref{lemma-dg-hull} have
the following properties. Given a graded $\mathcal{A}$-module
$\mathcal{N}$ we have
\begin{enumerate}
\item the counit $\mathcal{N} \to F(G(\mathcal{N}))$ is injective,
\item the map $\overline{\text{d}} : \mathcal{N} \to
\Coker(\mathcal{N} \to F(G(\mathcal{N})))[1]$ is an isomorphism, and
\item $G(\mathcal{N})$ is an acyclic differential graded $\mathcal{A}$-module.
\end{enumerate}

\label{lemma-application-nice-K-injective}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $F : \textit{Mod}(\mathcal{O}_X) \to \textit{Ab}$
be a functor and $N \geq 0$ an integer. Assume that
\begin{enumerate}
\item $F$ is left exact,
\item $F$ commutes with countable direct products,
\item $R^pF(\mathcal{F}) = 0$ for all $p \geq N$ and $\mathcal{F}$
quasi-coherent.
\end{enumerate}
Then for $E \in D_\QCoh(\mathcal{O}_X)$
\begin{enumerate}
\item $H^i(RF(\tau_{\leq a}E) \to H^i(RF(E))$ is an isomorphism
for $i \leq a$,
\item $H^i(RF(E)) \to H^i(RF(\tau_{\geq b - N + 1}E))$ is an isomorphism
for $i \geq b$,
\item if $H^i(E) = 0$ for $i \not \in [a, b]$ for some
$-\infty \leq a \leq b \leq \infty$, then $H^i(RF(E)) = 0$
for $i \not \in [a, b + N - 1]$.
\end{enumerate}

\label{lemma-injective-pushforward}
Let $S$ be a scheme. Let $X$ be a Noetherian algebraic space over $S$. If
$\mathcal{J}$ is an injective object of $\QCoh(\mathcal{O}_X)$,
then
\begin{enumerate}
\item $H^p(U, \mathcal{J}|_U) = 0$ for $p > 0$ and for
every quasi-compact and quasi-separated algebraic space $U$ \'etale over $X$,
\item for any morphism $f : X \to Y$ of algebraic spaces over $S$
with $Y$ quasi-separated we have $R^pf_*\mathcal{J} = 0$ for $p > 0$.
\end{enumerate}

\label{proposition-there-is-a-scheme-finite-over}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$.
\begin{enumerate}
\item There exists a surjective finite morphism $Y \to X$
of finite presentation where $Y$ is a scheme,
\item given a surjective \'etale morphism $U \to X$ we may choose
$Y \to X$ such that for every $y \in Y$ there is an open neighbourhood
$V \subset Y$ such that $V \to X$ factors through $U$.
\end{enumerate}

\label{lemma-cotangent-complex-polynomial-algebra}
If $B$ is a polynomial algebra over the ring $A$, then
$L_{B/A}$ is quasi-isomorphic to $\Omega_{B/A}[0]$.

\label{lemma-base-change-NL}
Consider a cartesian diagram of schemes
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d] & X \ar[d] \\
Y' \ar[r] & Y
}
$$
The canonical map $(g')^*\NL_{X/Y} \to \NL_{X'/Y'}$ induces
an isomorphism on $H^0$ and a surjection on $H^{-1}$.

\label{lemma-quasi-coherence-internal-hom}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $L, K$ be objects of $D(\mathcal{O}_X)$.
If either
\begin{enumerate}
\item $L$ in $D^+_\QCoh(\mathcal{O}_X)$ and $K$ is pseudo-coherent,
\item $L$ in $D_\QCoh(\mathcal{O}_X)$ and $K$ is perfect,
\end{enumerate}
then $R\SheafHom(K, L)$ is in $D_\QCoh(\mathcal{O}_X)$.

\label{lemma-compute-L-product-sheaves-rings}
Let $\mathcal{C}$ be a site. Let $\mathcal{A} \to \mathcal{B}$
and $\mathcal{A} \to \mathcal{B}'$ be homomorphisms of sheaves of rings
on $\mathcal{C}$. Then
$$
L_{\mathcal{B} \times \mathcal{B}'/\mathcal{A}}
\longrightarrow
L_{\mathcal{B}/\mathcal{A}} \oplus L_{\mathcal{B}'/\mathcal{A}}
$$
is an isomorphism in $D(\mathcal{B} \times \mathcal{B}')$.

\label{lemma-noetherian-finite-type-finite-presentation}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
\begin{enumerate}
\item If $\mathcal{Y}$ is locally Noetherian and $f$ locally of finite type
then $f$ is locally of finite presentation.
\item If $\mathcal{Y}$ is locally Noetherian and $f$ of finite type and
quasi-separated then $f$ is of finite presentation.
\end{enumerate}

\label{lemma-geometrically-connected-generic-fibre}
Let $f : X \to Y$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $Y$ is irreducible with generic point $\eta$,
\item $X_\eta$ is geometrically connected, and
\item $f$ is of finite type.
\end{enumerate}
Then there exists a nonempty open subscheme $V \subset Y$
such that $X_V \to V$ has geometrically connected fibres.

\label{lemma-Mor-diagonal-closed}
The diagonal of $\mathit{Mor}_B(Y, X) \to B$ is a closed immersion
of finite presentation.

\label{lemma-representable-morphism-to-algebraic}
Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $\mathcal{X} \to \mathcal{Y}$ be a morphism of stacks in groupoids
over $(\Sch/S)_{fppf}$. Assume that
\begin{enumerate}
\item $\mathcal{X} \to \mathcal{Y}$ is representable by algebraic spaces, and
\item $\mathcal{Y}$ is an algebraic stack over $S$.
\end{enumerate}
Then $\mathcal{X}$ is an algebraic stack over $S$.

\label{lemma-etale-covering-restriction-of-scalars}
Let $S$ be a scheme. Let $X' \to X \to Z \to B$ be morphisms of
algebraic spaces over $S$. Assume
\begin{enumerate}
\item $X' \to X$ is \'etale, and
\item $Z \to B$ is finite locally free.
\end{enumerate}
Then $\text{Res}_{Z/B}(X') \to \text{Res}_{Z/B}(X)$ is representable
by algebraic spaces and \'etale. If $X' \to X$ is also surjective,
then $\text{Res}_{Z/B}(X') \to \text{Res}_{Z/B}(X)$ is surjective.

\label{lemma-pic-over-pic}
In Situation \ref{situation-pic}
the functor $\Picardfunctor_{X/B}$ is the sheafification of
the functor $T \mapsto \Ob(\Picardstack_{X/B, T})/\cong$.

\label{lemma-proper-flat-geom-red-connected}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$. Assume
\begin{enumerate}
\item $f$ is proper, flat, and of finite presentation, and
\item the geometric fibres of $f$ are reduced and connected.
\end{enumerate}
Then $f_*\mathcal{O}_X = \mathcal{O}_Y$ and this holds
after any base change.

\label{lemma-Noetherian-approximation-flat}
Let $f : X \to S$ be a morphism of affine schemes, which is of finite
presentation and flat. Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ is flat.

\label{lemma-smooth-formally-smooth}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is smooth.
\item The morphism $f$ is locally of finite presentation, and
formally smooth.
\end{enumerate}

\label{lemma-lci-permanence}
Let
$$
\xymatrix{
\mathcal{X} \ar[rr]_f \ar[rd] & & \mathcal{Y} \ar[ld] \\
& \mathcal{Z}
}
$$
be a commutative diagram of morphisms of algebraic stacks.
Assume $\mathcal{Y} \to \mathcal{Z}$ is smooth and
$\mathcal{X} \to \mathcal{Z}$ is a local complete intersection morphism.
Then $f : \mathcal{X} \to \mathcal{Y}$ is a
local complete intersection morphism.

\label{lemma-conormal-functorial-flat}
Let
$$
\xymatrix{
Z \ar[r]_i \ar[d]_f & X \ar[d]^g \\
Z' \ar[r]^{i'} & X'
}
$$
be a fibre product diagram in the category of schemes with
$i$, $i'$ immersions. Then the canonical map
$f^*\mathcal{C}_{Z'/X'} \to \mathcal{C}_{Z/X}$ of
Lemma \ref{lemma-conormal-functorial}
is surjective. If $g$ is flat, then it is an isomorphism.

\label{lemma-kernel-localization}
In Definition \ref{definition-derived-category}
the kernel of the localization functor
$Q : K(\textit{Mod}(\mathcal{A}, \text{d})) \to D(\mathcal{A}, \text{d})$
is the category $\text{Ac}$ of Lemma \ref{lemma-acyclics}.

\label{lemma-gorenstein-morphism}
Let $f : X \to Y$ be a morphism of schemes.
Assume all fibres of $f$ are locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is Gorenstein, and
\item $f$ is flat and its fibres are Gorenstein schemes.
\end{enumerate}

\label{proposition-serre-galois}
\begin{reference}
\cite[Chapter II, Section 3, Proposition 5]{SerreGaloisCohomology}
\end{reference}
Let $K$ be a field with separable algebraic closure $K^{sep}$.
Assume that for any finite extension $K'$ of $K$ we have
$\text{Br}(K') = 0$. Then
\begin{enumerate}
\item $H^q(\text{Gal}(K^{sep}/K), (K^{sep})^*) = 0$
for all $q \geq 1$, and
\item $H^q(\text{Gal}(K^{sep}/K), M) = 0$
for any torsion $\text{Gal}(K^{sep}/K)$-module $M$ and any $q \geq 2$,
\end{enumerate}

\label{lemma-different-syntomic-quasi-finite}
Let $f : Y \to X$ be a morphism of Noetherian schemes. If $f$
satisfies the equivalent conditions of Lemma \ref{lemma-syntomic-quasi-finite}
then the different $\mathfrak{D}_f$ of $f$ is the K\"ahler different
of $f$.

\label{lemma-equivalence-categories-spaces-over-pushout}
In the situation of Lemma \ref{lemma-categories-spaces-over-pushout}
the functor $F \circ G$ is isomorphic to the identity functor.

\label{lemma-pure-projective}
Let $A$ be a ring.
\begin{enumerate}
\item A module is pure projective if and only if
it is a direct summand of a direct sum of finitely presented $A$-modules.
\item For any module $M$ there exists a universally exact sequence
$0 \to N \to P \to M \to 0$ with $P$ pure projective.
\end{enumerate}

\label{lemma-quasi-affine-O-ample}
Let $X$ be a scheme.
Then $X$ is quasi-affine if and only if $\mathcal{O}_X$ is ample.

\label{lemma-curves-RS-star}
Let
$$
\xymatrix{
T \ar[r] \ar[d] & T' \ar[d] \\
S \ar[r] & S'
}
$$
be a pushout in the category of schemes where
$T \to T'$ is a thickening and $T \to S$ is affine, see
More on Morphisms, Lemma \ref{more-morphisms-lemma-pushout-along-thickening}.
Then the functor on fibre categories
$$
\Curvesstack_{S'}
\longrightarrow
\Curvesstack_S
\times_{\Curvesstack_T}
\Curvesstack_{T'}
$$
is an equivalence.

\label{lemma-characterize-finite}
(For a more general version see
More on Morphisms, Lemma \ref{more-morphisms-lemma-characterize-finite}.)
Let $f : X \to S$ be a morphism of schemes.
Assume $S$ is locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is finite, and
\item $f$ is proper with finite fibres.
\end{enumerate}

\label{lemma-NL-is-limit}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal.
Let $B$ be an object of (\ref{equation-C-prime}). Then
\begin{enumerate}
\item the pro-objects
$\{\NL_{B/A}^\wedge \otimes_B B/I^nB\}$ and $\{\NL_{B_n/A_n}\}$
of $D(B)$ are strictly isomorphic (see proof for elucidation),
\item $\NL_{B/A}^\wedge = R\lim \NL_{B_n/A_n}$ in $D(B)$.
\end{enumerate}
Here $B_n$ and $A_n$ are as in Section \ref{section-two-categories}.

\label{lemma-conormal-algebra-functorial-flat}
Let $S$ be a scheme. Let
$$
\xymatrix{
Z \ar[r]_i \ar[d]_f & X \ar[d]^g \\
Z' \ar[r]^{i'} & X'
}
$$
be a cartesian square of algebraic spaces over $S$ with
$i$, $i'$ immersions. Then the canonical map
$f^*\mathcal{C}_{Z'/X', *} \to \mathcal{C}_{Z/X, *}$ of
Lemma \ref{lemma-conormal-algebra-functorial}
is surjective. If $g$ is flat, then it is an isomorphism.

\label{theorem-fully-faithful}
\begin{reference}
\cite[Theorem 2.2]{Orlov-K3}; this is shown in \cite{Noah}
without the assumption that $X$ be projective
\end{reference}
Let $k$ be a field. Let $X$ and $Y$ be smooth proper schemes over $k$
with $X$ projective over $k$. Any $k$-linear fully faithful exact 
functor $F : D_{perf}(\mathcal{O}_X) \to D_{perf}(\mathcal{O}_Y)$
is a Fourier-Mukai functor for some kernel in
$D_{perf}(\mathcal{O}_{X \times Y})$.

\label{lemma-cat-dotted-arrows-composition}
Assume given a $2$-commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r]_-x \ar[dd]_j & \mathcal{X} \ar[d]^f \\
& \mathcal{Y} \ar[d]^g \\
\Spec(A) \ar[r]^-z & \mathcal{Z}
}
$$
Choose a $2$-arrow $\gamma : z \circ j \to g \circ f \circ x$.
Let $\mathcal{C}$ be the category of dotted arrows for
the outer rectangle and $\gamma$. Let $\mathcal{C}'$ be the
category of dotted arrows for the square
$$
\xymatrix{
\Spec(K) \ar[r]_-{f \circ x} \ar[d]_j & \mathcal{Y} \ar[d]^g \\
\Spec(A) \ar[r]^-z & \mathcal{Z}
}
$$
and $\gamma$. Then $\mathcal{C}$ is equivalent to a category $\mathcal{C}''$ 
which has the following property: there is 
a functor $\mathcal{C}'' \to \mathcal{C}'$
which turns $\mathcal{C}''$ into a category fibred in groupoids over
$\mathcal{C}'$ and whose fibre categories are categories of dotted arrows
for certain squares of the form
$$
\xymatrix{
\Spec(K) \ar[r]_-x \ar[d]_j & \mathcal{X} \ar[d]^f \\
\Spec(A) \ar[r]^-y & \mathcal{Y}
}
$$
and some choices of $y \circ j \to f \circ x$.

\label{lemma-eventual-iso-graded-rings-map-relative-proj}
With hypotheses and notation as in Lemma \ref{lemma-morphism-relative-proj}
above. Assume $\mathcal{A}_d \to \mathcal{B}_d$ is an isomorphism for all
$d \gg 0$. Then
\begin{enumerate}
\item $U(\psi) = Y$,
\item $r_\psi : Y \to X$ is an isomorphism, and
\item the maps $\theta : r_\psi^*\mathcal{O}_X(n) \to \mathcal{O}_Y(n)$
are isomorphisms.
\end{enumerate}

\label{lemma-dimension-zero}
\begin{reference}
Email from Ofer Gabber dated June 4, 2016
\end{reference}
Let $X$ be a scheme of dimension zero. The following are equivalent
\begin{enumerate}
\item $X$ is quasi-separated,
\item $X$ is separated,
\item $X$ is Hausdorff,
\item every affine open is closed.
\end{enumerate}
In this case the connected components of $X$ are points and every
quasi-compact open of $X$ is affine. In particular, if $X$
is quasi-compact, then $X$ is affine.

\label{lemma-kernel}
Let $(A, I, \gamma)$ be a divided power ring.
\begin{enumerate}
\item If $\varphi : (A, I, \gamma) \to (B, J, \delta)$ is a
homomorphism of divided power rings, then $\Ker(\varphi) \cap I$
is preserved by $\gamma_n$ for all $n \geq 1$.
\item Let $\mathfrak a \subset A$ be an ideal and set
$I' = I \cap \mathfrak a$. The following are equivalent
\begin{enumerate}
\item $I'$ is preserved by $\gamma_n$ for all $n > 0$,
\item $\gamma$ extends to $A/\mathfrak a$, and
\item there exist a set of generators $x_i$ of $I'$ as an ideal
such that $\gamma_n(x_i) \in I'$ for all $n > 0$.
\end{enumerate}
\end{enumerate}

\label{lemma-fibre-diagram}
Let $S$ be a scheme. Let $X \to Z \to B$ be morphisms of
algebraic spaces over $S$. The following diagram
$$
\xymatrix{
\mathit{Mor}_B(Z, X) \ar[r] & \mathit{Mor}_B(Z, Z) \\
\text{Res}_{Z/B}(X) \ar[r] \ar[u] & B \ar[u]_{\text{id}_Z}
}
$$
is a cartesian diagram of sheaves on $(\Sch/S)_{fppf}$.

\label{lemma-preserves-products}
Let $R$ be an $S$-algebra. Then the functor
$\text{Mod}_R \to S\text{-Alg}/R$ described above preserves finite products.

\label{lemma-quasi-compact-gives-quasi-compact}
In the situation above. If $f$ is quasi-compact, then
$f_{/T}$ is quasi-compact.

\label{lemma-resolve-general}
Let $k \to A \to \Lambda \supset \mathfrak q$ be as in
Situation \ref{situation-local} where
\begin{enumerate}
\item $k$ is a field of characteristic $p > 0$,
\item $\Lambda$ is Noetherian and geometrically regular over $k$,
\item $\mathfrak q$ is minimal over $\mathfrak h_A$.
\end{enumerate}
Then $k \to A \to \Lambda \supset \mathfrak q$ can be resolved.

\label{lemma-versal-implies-smooth}
Let $S$ be a locally Noetherian scheme. Let $f : U \to V$
be a morphism of schemes locally of finite type over $S$.
Let $u_0 \in U$ be a finite type point. The following are equivalent
\begin{enumerate}
\item $f$ is smooth at $u_0$,
\item $f$ viewed as an object of $(\Sch/V)_{fppf}$ over $U$ is
versal at $u_0$.
\end{enumerate}

\label{proposition-lift-smooth}
\begin{slogan}
Smooth and syntomic algebras lift along surjections
\end{slogan}
Let $R \to R_0$ be a surjective ring map with kernel $I$.
\begin{enumerate}
\item If $R_0 \to A_0$ is a syntomic ring map, then there exists a syntomic
ring map $R \to A$ such that $A/IA \cong A_0$.
\item If $R_0 \to A_0$ is a smooth ring map, then there exists a smooth
ring map $R \to A$ such that $A/IA \cong A_0$.
\end{enumerate}

\label{lemma-flat-base-change-scheme-theoretic-image}
\begin{slogan}
Taking scheme theoretic images commutes with flat base change
in the quasi-compact case
\end{slogan}
Let $f : X \to Y$ be a flat morphism of schemes. Let $g : V \to Y$ be a
quasi-compact morphism of schemes. Let $Z \subset Y$ be the scheme theoretic
image of $g$ and let $Z' \subset X$ be the scheme theoretic image of the
base change $V \times_Y X \to X$. Then $Z' = f^{-1}Z$.

\label{lemma-isolated-dim-0-locally-noetherian}
Let $x$ be a point of a locally Noetherian scheme $X$.
Then $\dim_x(X) = 0$ if and only if $x$ is an isolated point of $X$.

\label{lemma-hilbert-stack-relative-space}
Let $S$ be a scheme. Let $F : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism
of stacks in groupoids over $(\Sch/S)_{fppf}$ such that
\begin{enumerate}
\item $\mathcal{X}$ is representable by an algebraic space, and
\item $F$ is representable by algebraic spaces, surjective, flat, and
locally of finite presentation.
\end{enumerate}
Then $\mathcal{H}_d(\mathcal{X}/\mathcal{Y})$ is an algebraic stack.

\label{lemma-lqf-base-change-f-shriek}
Consider a cartesian square
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
$$
of schemes with $f$ locally quasi-finite. There is an isomorphism
$g^{-1}f_!\mathcal{F} \to f'_!(g')^{-1}\mathcal{F}$ functorial for
$\mathcal{F}$ in $\textit{Ab}(X_\etale)$ which is compatible with
the descriptions of stalks given in Lemma \ref{lemma-lqf-f-shriek-stalk}
(see proof for the precise statement).

\label{lemma-extend-q-to-spaces}
In Situation \ref{situation-q}. Let $T$ be an algebraic space over $S$.
We have
$$
\Mor_{\Sh((\Sch/S)_{fppf})}(T,  \text{Q}_{\mathcal{F}/X/B}) =
\left\{
\begin{matrix}
(h, \mathcal{F}_T \to \mathcal{Q}) \text{ where }
h : T \to B \text{ and}\\
\mathcal{Q}\text{ is quasi-coherent and flat over }T
\end{matrix}
\right\}
$$
where $\mathcal{F}_T$ denotes the pullback of $\mathcal{F}$
to the algebraic space $X \times_{B, h} T$. Similarly, we have
$$
\Mor_{\Sh((\Sch/S)_{fppf})}(T,  \text{Q}^{fp}_{\mathcal{F}/X/B}) =
\left\{
\begin{matrix}
(h, \mathcal{F}_T \to \mathcal{Q}) \text{ where }
h : T \to B \text{ and}\\
\mathcal{Q}\text{ is of finite presentation and flat over }T
\end{matrix}
\right\}
$$

\label{lemma-unique-point-better}
Let $\mathcal{Z}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{Z}$ is reduced, locally Noetherian, and $|\mathcal{Z}|$
is a singleton, and
\item there exists a locally finitely presented, surjective, flat morphism
$\Spec(k) \to \mathcal{Z}$ where $k$ is a field.
\end{enumerate}

\label{lemma-base-change-transformation}
\begin{slogan}
A base change of a representable by algebraic spaces morphism of
presheaves is representable by algebraic spaces.
\end{slogan}
Let $S$ be a scheme. Let
$$
\xymatrix{
G' \times_G F \ar[r] \ar[d]^{a'} & F \ar[d]^a \\
G' \ar[r] & G
}
$$
be a fibre square of presheaves on $(\Sch/S)_{fppf}$.
If $a$ is representable by algebraic spaces so is $a'$.

\label{lemma-refined-valuative-criterion-universally-closed}
Let $S$ be a scheme. Let $f : X \to Y$ and $h : U \to X$ be morphisms of
algebraic spaces over $S$. If
\begin{enumerate}
\item $f$ and $h$ are quasi-compact,
\item $|h|(|U|)$ is dense in $|X|$, and
\end{enumerate}
given any commutative solid diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & U \ar[r] & X \ar[d] \\
\Spec(A) \ar[rr] \ar@{-->}[rru] & & Y
}
$$
where $A$ is a valuation ring with field of fractions $K$
\begin{enumerate}
\item[(3)] there exists at most one dotted arrow making the diagram
commute, and
\item[(4)] there exists an extension $K'/K$ of fields, a
valuation ring $A' \subset K'$ dominating $A$ and a morphism
$\Spec(A') \to X$ such that the following diagram commutes
$$
\xymatrix{
\Spec(K') \ar[r] \ar[d] & \Spec(K) \ar[r] & U \ar[r] & X \ar[d] \\
\Spec(A') \ar[r] \ar[rrru] & \Spec(A) \ar[rr] & & Y
}
$$
\end{enumerate}
then $f$ is universally closed. If moreover
\begin{enumerate}
\item[(5)] $f$ is quasi-separated
\end{enumerate}
then $f$ is separated and universally closed.

\label{lemma-nonexistence-qc-dense-open-subscheme}
There exists a quasi-compact and quasi-separated algebraic space
which does not contain a quasi-compact dense open subscheme.

\label{lemma-characterize-geometrically-disconnected}
Let $k$ be a field. Let $X$ be an algebraic space over $k$.
The following are equivalent
\begin{enumerate}
\item $X$ is geometrically connected,
\item for every finite separable field extension $k'/k$
the algebraic space $X_{k'}$ is connected.
\end{enumerate}

\label{lemma-diagonal-unramified-morphism}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
\begin{enumerate}
\item If $f$ is unramified, then the diagonal morphism
$\Delta_{X/Y} : X \to X \times_Y X$ is an open immersion.
\item If $f$ is locally of finite type
and $\Delta_{X/Y}$ is an open immersion, then $f$ is unramified.
\end{enumerate}

\label{lemma-trace-map}
\begin{reference}
The proof given here follows the argument given in
\cite[Remark 3.4]{MS}
\end{reference}
Let $f : X' \to X$ be a proper birational morphism of integral Noetherian
schemes with $X$ regular. The map $\mathcal{O}_X \to Rf_*\mathcal{O}_{X'}$
canonically splits in $D(\mathcal{O}_X)$.

\label{lemma-compare-injectives}
Let $S$ be a scheme. Let $T$ be an object of $(\Sch/S)_\proetale$.
\begin{enumerate}
\item If $\mathcal{I}$ is injective in $\textit{Ab}((\Sch/S)_\proetale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}$ is injective in $\textit{Ab}(T_\proetale)$,
\item $\mathcal{I}|_{S_\proetale}$ is injective in $\textit{Ab}(S_\proetale)$,
\end{enumerate}
\item If $\mathcal{I}^\bullet$ is a K-injective complex
in $\textit{Ab}((\Sch/S)_\proetale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(T_\proetale)$,
\item $\mathcal{I}^\bullet|_{S_\proetale}$ is a K-injective complex in
$\textit{Ab}(S_\proetale)$,
\end{enumerate}
\end{enumerate}

\label{lemma-closed-immersion-gives-closed-immersion}
In the situation above. If $f$ is a closed immersion, then
$f_{/T}$ is a closed immersion.

\label{lemma-generic-point-in-schematic-locus}
Let $S$ be a scheme. Let $X$ be a quasi-separated algebraic space over $S$.
Let $x \in |X|$. The following are equivalent
\begin{enumerate}
\item $x$ is a point of codimension $0$ on $X$,
\item the local ring of $X$ at $x$ has dimension $0$, and
\item $x$ is a generic point of an irreducible component of $|X|$.
\end{enumerate}
If true, then there exists an open subspace of $X$
containing $x$ which is a scheme.

\label{lemma-describe-sheaves-simplicial-site-site}
In Situation \ref{situation-simplicial-site} there is an equivalence of
categories between
\begin{enumerate}
\item $\Sh(\mathcal{C}_{total})$, and
\item the category of systems $(\mathcal{F}_n, \mathcal{F}(\varphi))$
described above.
\end{enumerate}
In particular, the topos $\Sh(\mathcal{C}_{total})$ only depends on
the topoi $\Sh(\mathcal{C}_n)$ and the morphisms of topoi $f_\varphi$.

\label{lemma-triseq}
In Situation \ref{situation-ABC} let $x_i \to y_i \to z_i$
be morphisms in $\mathcal{A}$ ($i=1,2,3$) such that
$x_2 \to y_2\to z_2$ is an admissible short exact sequence.
Let $b : y_1 \to y_2$ and $b' : y_2\to y_3$ be morphisms
in $\text{Comp}(\mathcal{A})$ such that
$$
\vcenter{
\xymatrix{
x_1 \ar[d]_0 \ar[r] &
y_1 \ar[r] \ar[d]_b &
z_1 \ar[d]_0 \\
x_2 \ar[r] & y_2 \ar[r] & z_2
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
x_2 \ar[d]^0 \ar[r] &
y_2 \ar[r] \ar[d]^{b'} &
z_2 \ar[d]^0 \\
x_3 \ar[r] & y_3 \ar[r] & z_3
}
}
$$
commute up to homotopy. Then $b'\circ b$ is homotopic to $0$.

\label{lemma-tensor-product}
Let $R$ be a ring and let $A$, $B$ be $R$-algebras. The object $E$
in (\ref{equation-tensor-product}) satisfies
$$
H^i(E) =
\left\{
\begin{matrix}
0 & \text{if} & i \geq -1 \\
\text{Tor}_1^R(A, B) & \text{if} & i = -2
\end{matrix}
\right.
$$

\label{lemma-make-smaller-flatness-ideal}
Let $A$ be a local ring. Let $I \subset A$ be an ideal.
Let $U \subset \Spec(A)$ be quasi-compact open.
Let $M$ be an $A$-module. Assume that
\begin{enumerate}
\item $M/IM$ is flat over $A/I$,
\item $M$ is flat over $U$,
\end{enumerate}
Then $M/I_2M$ is flat over $A/I_2$ where
$I_2 = \Ker(I \to \Gamma(U, I/I^2))$.

\label{lemma-gabriel-popescu-left-adjoint}
The functor $G$ above has a left adjoint
$F : \text{Mod}_R \to \mathcal{A}$.

\label{lemma-second-equivalence}
Notation and assumptions as above.
The functor $\pi_!$ induces an equivalence of categories between
\begin{enumerate}
\item the category
$\textit{Lift}_\mathcal{O}(i_*\underline{\mathcal{G}}, A')$, and
\item the category $\textit{Lift}(\mathcal{G}, A')$.
\end{enumerate}

\label{lemma-Noetherian-approximation-geometrically-connected}
Let $f : X \to S$ be a morphism of affine schemes, which is
of finite presentation with geometrically connected fibres.
Then there exists a diagram as in
Lemma \ref{lemma-Noetherian-approximation}
such that in addition $f_0$ has geometrically connected fibres.

\label{lemma-ringed-stalk-not-zero}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Consider the statements
\begin{enumerate}
\item (\ref{equation-one-is-never-zero}) is an isomorphism, and
\item for every point $p$ of $\mathcal{C}$ the stalk $\mathcal{O}_p$
is not the zero ring.
\end{enumerate}
We always have (1) $\Rightarrow$ (2) and if $\mathcal{C}$ has enough points
then (1) $\Leftrightarrow$ (2).

\label{lemma-global-unramified-dominant-unibranch-is-etale}
\begin{reference}
\cite[Expose I, Corollary 9.11]{SGA1}
\end{reference}
Let $f : X \to Y$ be a morphism of schemes. Assume
\begin{enumerate}
\item $Y$ is integral and geometrically unibranch,
\item at least one irreducible component of $X$ dominates $Y$,
\item $f$ is unramified, and
\item $X$ is connected.
\end{enumerate}
Then $f$ is \'etale and $X$ is irreducible.

\label{lemma-finite-permanence}
Let $S$ be a scheme.
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of algebraic spaces over $S$.
\begin{enumerate}
\item If $g \circ f$ is finite and $g$ separated then $f$ is finite.
\item If $g \circ f$ is integral and $g$ separated then $f$ is integral.
\end{enumerate}

\label{lemma-fibre-products}
Let $p : \mathcal{X} \to (\Sch/S)_{fppf}$
be a category fibred in groupoids.
\begin{enumerate}
\item The category $\mathcal{X}$ has fibre products.
\item If the $\mathit{Isom}$-presheaves of $\mathcal{X}$
are representable by algebraic spaces, then $\mathcal{X}$ has equalizers.
\item If $\mathcal{X}$ is an algebraic stack (or more generally
a quotient stack), then $\mathcal{X}$ has equalizers.
\end{enumerate}

\label{lemma-smooth-RS-groupoid-in-functors-quotient}
Let $(U, R, s, t, c)$ be a smooth groupoid in functors on $\mathcal{C}_\Lambda$.
Assume $U$ and $R$ satisfy (RS). Then $[U/R]$ satisfies (RS).

\label{lemma-base-change-universally-submersive}
The base change of a universally submersive morphism of algebraic stacks
by any morphism of algebraic stacks is universally submersive.

\label{theorem-quasi-DM}
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is quasi-DM, and
\item there exists a scheme $W$ and a surjective, flat, locally finitely
presented, locally quasi-finite morphism $W \to \mathcal{X}$.
\end{enumerate}

\label{lemma-tensor-central-simple}
The tensor product of finite central simple algebras over $k$ is finite,
central, and simple.

\label{lemma-descending-property-separated}
The property $\mathcal{P}(f) =$``$f$ is separated''
is fpqc local on the base.

\label{lemma-descending-property-quasi-compact-immersion}
The property $\mathcal{P}(f) =$``$f$ is a quasi-compact immersion''
is fpqc local on the base.

\label{lemma-actual-computation}
In the situation of Lemma \ref{lemma-agreement-with-loc-chern}
say $\dim_\delta(X) = n$. Then we have
\begin{enumerate}
\item $c_t(Z \to X, i_*\mathcal{O}_Z) \cap [X]_n = 0$ for
$t = 1, \ldots, r - 1$,
\item $c_r(Z \to X, i_*\mathcal{O}_Z) \cap [X]_n =
(-1)^{r - 1}(r - 1)![Z]_{n - r}$,
\item $ch_t(Z \to X, i_*\mathcal{O}_Z) \cap [X]_n = 0$ for
$t = 0, \ldots, r - 1$, and
\item $ch_r(Z \to X, i_*\mathcal{O}_Z) \cap [X]_n = [Z]_{n - r}$.
\end{enumerate}

\label{theorem-wedderburn}
\begin{slogan}
Simple finite algebras over a field are matrix algebras over a skew field.
\end{slogan}
Let $A$ be a simple finite $k$-algebra. Then $A$ is a matrix algebra over
a finite $k$-algebra $K$ which is a skew field.

\label{lemma-lift-map}
Let $A$ be a ring. Given a solid diagram
$$
\xymatrix{
0 \ar[r] &
L \ar[d]_\varphi \ar[r] &
\underline{A^{\oplus n}} \ar[r] \ar@{..>}[ld] &
\underline{A^{\oplus m}} \\
& \underline{M}
}
$$
of module-valued functors on $\textit{Alg}_A$
with exact row there exists a dotted arrow making the diagram commute.

\label{lemma-verify-site-proetale}
Let $S$ be a scheme. Let $\Sch_\proetale$ be a big pro-\'etale site
containing $S$. Both $S_\proetale$ and $(\textit{Aff}/S)_\proetale$ are sites.

\label{lemma-dualizing-base-flat-flat}
Let $A \to B$ be a flat quasi-finite homomorphism of Noetherian rings.
Then $\omega_{B/A}$ is a flat $A$-module.

\label{lemma-quasi-coherence-pushforward}
If $f : X \to Y$ is a morphism of affine schemes given by the ring map
$A \to B$, then the diagram
$$
\xymatrix{
D(B) \ar[d] \ar[r] & D_\QCoh(\mathcal{O}_X) \ar[d]^{Rf_*} \\
D(A) \ar[r] & D_\QCoh(\mathcal{O}_Y)
}
$$
commutes.

\label{lemma-site-fpqc}
The collection of fpqc coverings on the category of schemes
satisfies the axioms of site.

\label{lemma-F-G-monos}
Let $f : M \to G(A)$ be an injective map in $\text{Mod}_R$.
Then the adjoint map $f' : F(M) \to A$ is injective too.

\label{lemma-characterize-finite-locally-constant}
Let $X$ be a scheme and $\mathcal{F}$ a sheaf of sets on $X_\etale$.
Then the following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is finite locally constant, and
\item $\mathcal{F} = h_U$ for some finite \'etale morphism $U \to X$.
\end{enumerate}

\label{lemma-facts-pext}
Let $A$ be a ring.
\begin{enumerate}
\item $\text{Pext}^i_A(M, N) = 0$ for $i > 0$ whenever $N$ is pure injective,
\item $\text{Pext}^i_A(M, N) = 0$ for $i > 0$ whenever $M$ is pure projective,
in particular if $M$ is an $A$-module of finite presentation,
\item $\text{Pext}^i_A(M, N)$ is also the $i$th cohomology module
of the complex $\Hom_A(P_\bullet, N)$ where $P_\bullet$
is a pure projective resolution of $M$.
\end{enumerate}

\label{lemma-discriminant}
Let $\pi : X \to Y$ be a morphism of schemes which is finite locally
free. Then $\pi$ is \'etale if and only if its discriminant is empty.

\label{lemma-conormal-functorial-flat}
Let $S$ be a scheme. Let
$$
\xymatrix{
Z \ar[r]_i \ar[d]_f & X \ar[d]^g \\
Z' \ar[r]^{i'} & X'
}
$$
be a fibre product diagram of algebraic spaces over $S$. Assume
$i$, $i'$ immersions. Then the canonical map
$f^*\mathcal{C}_{Z'/X'} \to \mathcal{C}_{Z/X}$ of
Lemma \ref{lemma-conormal-functorial}
is surjective. If $g$ is flat, then it is an isomorphism.

\label{lemma-locally-ringed-space-direct-summand-free}
Let $X$ be a locally ringed space. A direct summand of a finite free
$\mathcal{O}_X$-module is finite locally free.

\label{lemma-geom-irreducible-generic-fibre}
Let $f : X \to Y$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $Y$ is irreducible with generic point $\eta$,
\item $X_\eta$ is geometrically irreducible, and
\item $f$ is of finite type.
\end{enumerate}
Then there exists a nonempty open subscheme $V \subset Y$
such that $X_V \to V$ has geometrically irreducible fibres.

\label{lemma-characterize-representable-universally-closed}
Let $S$ be a scheme. Let $f : X \to Y$ be a representable morphism of
algebraic spaces over $S$. The following are equivalent
\begin{enumerate}
\item $f$ is universally closed
(in the sense of Section \ref{section-representable}), and
\item for every morphism of algebraic spaces $Z \to Y$ the morphism of
topological spaces $|Z \times_Y X| \to |Z|$ is closed.
\end{enumerate}

\label{lemma-formal-completion-types}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $T \subset |X|$ be a closed subset. Let $X_{/T}$ be the
formal completion of $X$ along $T$.
\begin{enumerate}
\item If $X \setminus T \to X$ is quasi-compact,
then $X_{/T}$ is locally adic*.
\item If $X$ is locally Noetherian, then $X_{/T}$ is locally
Noetherian.
\end{enumerate}

\label{lemma-representable-by-spaces-limit-preserving}
Let $p : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$. If $p$ is
representable by algebraic spaces, then the following are equivalent:
\begin{enumerate}
\item $p$ is limit preserving on objects, and
\item $p$ is locally of finite presentation (see
Algebraic Stacks,
Definition \ref{algebraic-definition-relative-representable-property}).
\end{enumerate}

\label{lemma-lisse-etale-cohomology}
Let $\mathcal{X}$ be an algebraic stack. Notation as in
Lemma \ref{lemma-lisse-etale}.
\begin{enumerate}
\item For an abelian sheaf $\mathcal{F}$ on $\mathcal{X}_\etale$ we have
\begin{enumerate}
\item $H^p(\mathcal{X}_\etale, \mathcal{F}) =
H^p(\mathcal{X}_{lisse,\etale}, g^{-1}\mathcal{F})$, and
\item $H^p(x, \mathcal{F}) =
H^p(\mathcal{X}_{lisse,\etale}/x, g^{-1}\mathcal{F})$
for any object $x$ of $\mathcal{X}_{lisse,\etale}$.
\end{enumerate}
The same holds for sheaves of modules.
\item For an abelian sheaf $\mathcal{F}$ on $\mathcal{X}_{fppf}$ we have
\begin{enumerate}
\item $H^p(\mathcal{X}_{fppf}, \mathcal{F}) =
H^p(\mathcal{X}_{flat,fppf}, g^{-1}\mathcal{F})$, and
\item $H^p(x, \mathcal{F}) =
H^p(\mathcal{X}_{flat,fppf}/x, g^{-1}\mathcal{F})$
for any object $x$ of $\mathcal{X}_{flat,fppf}$.
\end{enumerate}
The same holds for sheaves of modules.
\end{enumerate}

\label{lemma-generator-with-support}
\begin{reference}
\cite[Theorem 6.8]{Rouquier-dimensions}
\end{reference}
Let $X$ be a quasi-compact and quasi-separated scheme. Let $T \subset X$ be a
closed subset such that $X \setminus T$ is quasi-compact. With notation
as above, the category $D_{\QCoh, T}(\mathcal{O}_X)$ is generated by a
single perfect object.

\label{lemma-glueing-gives-functor-spec}
In Situation \ref{situation-relative-spec}.
The scheme $\pi : \underline{\Spec}_S(\mathcal{A}) \to S$
constructed in Lemma \ref{lemma-glue-relative-spec}
and the scheme representing the functor $F$ are
canonically isomorphic as schemes over $S$.

\label{lemma-torsion-direct-image}
Let $f : X \to Y$ be a quasi-compact and quasi-separated
morphism of schemes.
\begin{enumerate}
\item If $\mathcal{F}$ is a torsion abelian sheaf on $X_\etale$, then
$R^nf_*\mathcal{F}$ is a torsion abelian sheaf on $Y_\etale$ for all $n$.
\item If $K$ in $D^+(X_\etale)$ has torsion cohomology sheaves, then
$Rf_*K$ is an object of $D^+(Y_\etale)$ whose cohomology sheaves are
torsion abelian sheaves.
\end{enumerate}

\label{proposition-vanishing-affine}
\begin{slogan}
Serre's criterion for affineness in the setting of algebraic spaces.
\end{slogan}
A quasi-compact and quasi-separated algebraic space is affine
if and only if all higher cohomology groups of quasi-coherent sheaves
vanish. More precisely, any algebraic space as in
Situation \ref{situation-vanishing} is an affine scheme.

\label{lemma-H0-L-morphism-ringed-spaces}
Let $f : (X, \mathcal{O}_X) \to (S, \mathcal{O}_S)$ be a morphism of
ringed spaces. Then $H^0(L_{X/S}) = \Omega_{X/S}$.

\label{lemma-coh-noetherian-from-affine-flat}
In Lemma \ref{lemma-functor-quasi-coherent-from-affine}
or in Lemma \ref{lemma-functor-quasi-coherent-from-affine-diagonal-pre}
if $F$ is an exact functor, then the corresponding object
$\mathcal{K}$ of $\QCoh(\mathcal{O}_{X \times_R Y})$ is flat over $X$.

\label{lemma-point-finite-type}
Let $\mathcal{X}$ be an algebraic stack.
Let $x \in |\mathcal{X}|$. The following are equivalent:
\begin{enumerate}
\item There exists a morphism $\Spec(k) \to \mathcal{X}$
which is locally of finite type and represents $x$.
\item There exists a scheme $U$, a closed point $u \in U$, and a smooth
morphism $\varphi : U \to \mathcal{X}$ such that $\varphi(u) = x$.
\end{enumerate}

\label{lemma-composition-finite-presentation}
The composition of morphisms of finite presentation is of finite presentation.
The same holds for locally of finite presentation.

\label{lemma-dimension-product-varieties}
Let $X$ and $Y$ be varieties. Then $X \times Y$ is a variety and
$\dim(X \times Y) = \dim(X) + \dim(Y)$.

\label{lemma-flat-base-change-lci}
A flat base change of a local complete intersection morphism is
a local complete intersection morphism.

\label{lemma-composition-lci}
A composition of local complete intersection morphisms is a
local complete intersection morphism.

\label{lemma-pseudo-functor}
In Situation \ref{situation-shriek} the constructions of
Lemmas \ref{lemma-shriek-well-defined} and \ref{lemma-upper-shriek-composition}
define a pseudo functor from the category $\textit{FTS}_S$
into the $2$-category of categories (see Categories, Definition
\ref{categories-definition-functor-into-2-category}).

\label{lemma-flat-fp-dimension-over-dense-open}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$ which is flat and locally of finite type. Let $V \subset Y$ be an
open subspace such that $|V| \subset |Y|$ is dense and such that $X_V \to V$
has relative dimension $\leq d$. If also either
\begin{enumerate}
\item $f$ is locally of finite presentation, or
\item $V \to Y$ is quasi-compact,
\end{enumerate}
then $f : X \to Y$ has relative dimension $\leq d$.

\label{lemma-hom-into-S2}
Let $X$ be a locally Noetherian scheme. Let $\mathcal{F}$, $\mathcal{G}$
be coherent $\mathcal{O}_X$-modules.
\begin{enumerate}
\item If $\mathcal{G}$ has property $(S_1)$, then
$\SheafHom_{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})$ has property $(S_1)$.
\item If $\mathcal{G}$ has property $(S_2)$, then
$\SheafHom_{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})$ has property $(S_2)$.
\end{enumerate}

\label{lemma-ci-map-well-defined}
Let $A \to B$ be a local homomorphism of Noetherian complete local rings.
The following are equivalent
\begin{enumerate}
\item for some good factorization $A \to S \to B$ the kernel of
$S \to B$ is generated by a regular sequence, and
\item for every good factorization $A \to S \to B$ the kernel of
$S \to B$ is generated by a regular sequence.
\end{enumerate}

\label{lemma-composition-etale}
The composition of two \'etale morphisms of algebraic spaces
is \'etale.

\label{lemma-descending-property-integral}
The property $\mathcal{P}(f) =$``$f$ is integral''
is fpqc local on the base.

\label{lemma-composition-immersion}
Compositions of immersions of algebraic stacks are immersions.
Similarly for closed immersions and open immersions.

\label{lemma-map-between-smooth}
Let $\mathcal{F} \to \mathcal{G} \to \mathcal{H}$ be maps of categories
cofibred in groupoids over $\mathcal{C}_\Lambda$. If
\begin{enumerate}
\item $\mathcal{F}$, $\mathcal{G}$ are deformation categories
\item the map $T\mathcal{F} \to T\mathcal{G}$ is surjective, and
\item $\mathcal{F} \to \mathcal{H}$ is smooth.
\end{enumerate}
Then $\mathcal{F} \to \mathcal{G}$ is smooth.

\label{lemma-inverse-h2}
With notation as in Example \ref{example-decompose-P1}
\begin{enumerate}
\item
the motive $(X, c_0, 0)$ is isomorphic to the motive
$\mathbf{1} = (\Spec(k), 1, 0)$.
\item
the motive $(X, c_2, 0)$ is isomorphic to the motive
$\mathbf{1}(-1) = (\Spec(k), 1, -1)$.
\end{enumerate}

\label{lemma-composition-etale}
The composition of two \'etale morphisms of algebraic spaces
is \'etale.

\label{lemma-get-affine}
Let $j : Y \to X$ be an immersion of schemes.
Assume there exists an open $U \subset X$ with complement
$Z = X \setminus U$ such that
\begin{enumerate}
\item $U \to X$ is affine,
\item $j^{-1}(U) \to U$ is affine, and
\item $j(Y) \cap Z$ is closed.
\end{enumerate}
Then $j$ is affine. In particular, if $X$ is affine, so is $Y$.

\label{lemma-apply-modules}
Let $S$ be a graded ring. Let $M$ be a graded $S$-module.
Set $X = \text{Proj}(S)$. Assume $X$ is covered by the standard
opens $D_+(f)$ with $f \in S_1$, e.g., if $S$ is generated by $S_1$
over $S_0$. Then the sheaves $\mathcal{O}_X(n)$
are invertible and the maps
(\ref{equation-multiply}), (\ref{equation-multiply-on-sheaf}), and
(\ref{equation-multiply-more-generally}) are isomorphisms.
In particular, these maps induce isomorphisms
$$
\mathcal{O}_X(1)^{\otimes n} \cong
\mathcal{O}_X(n)
\quad
\text{and}
\quad
\widetilde{M} \otimes_{\mathcal{O}_X} \mathcal{O}_X(n) =
\widetilde{M}(n) \cong \widetilde{M(n)}
$$
Thus (\ref{equation-map-global-sections-degree-n}) becomes a map
\begin{equation}
\label{equation-map-global-sections-degree-n-simplified}
M_n \longrightarrow \Gamma(X, \widetilde{M}(n))
\end{equation}
and (\ref{equation-global-sections-more-generally}) becomes a map
\begin{equation}
\label{equation-global-sections-more-generally-simplified}
M \longrightarrow
\bigoplus\nolimits_{n \in \mathbf{Z}} \Gamma(X, \widetilde{M}(n)).
\end{equation}

\label{lemma-sheafhom-affine-adjoint}
With notation as above. The functor $R\SheafHom(f_*\mathcal{O}_Y, -)$
is the right adjoint of the functor $D(f_*\mathcal{O}_Y) \to D(\mathcal{O}_X)$.

\label{lemma-polarized-diagonal-separated-fp}
The diagonal of $\Polarizedstack$ is separated
and of finite presentation.

\label{lemma-characterize-trivial-pseudo-torsors}
In the situation of
Definition \ref{definition-pseudo-torsor}.
\begin{enumerate}
\item The algebraic space $X$ is a pseudo $G$-torsor if and only if for
every scheme $T$ over $B$ the set $X(T)$ is either empty or the action
of the group $G(T)$ on $X(T)$ is simply transitive.
\item A pseudo $G$-torsor $X$ is trivial if and only if the morphism
$X \to B$ has a section.
\end{enumerate}

\label{lemma-rig-flat-local-down}
Consider a commutative diagram
$$
\xymatrix{
B \ar[r] & B' \\
A \ar[r] \ar[u]^\varphi & A' \ar[u]_{\varphi'}
}
$$
in $\textit{WAdm}^{Noeth}$ with all arrows adic and topologically
of finite type. Assume $A \to A'$ flat and $B \to B'$ faithfully flat.
If $\varphi'$ is rig-flat, then $\varphi$ is rig-flat.

\label{lemma-representable-by-spaces-formally-smooth}
Let $p : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$. If $p$ is
representable by algebraic spaces, then the following are equivalent:
\begin{enumerate}
\item $p$ is formally smooth on objects, and
\item $p$ is formally smooth (see
Algebraic Stacks,
Definition \ref{algebraic-definition-relative-representable-property}).
\end{enumerate}

\label{lemma-restriction-to-components-functorial}
Let $f : Y \to X$ be a morphism of simplicial spaces. Then
$$
\xymatrix{
\Sh(Y_n) \ar[d] \ar[r]_{f_n} & \Sh(X_n) \ar[d] \\
\Sh(Y_{Zar}) \ar[r]^{f_{Zar}} & \Sh(X_{Zar})
}
$$
is a commutative diagram of topoi.

\label{lemma-quasi-coherence-pullback}
Let $f : Y \to X$ be a morphism of schemes.
\begin{enumerate}
\item The functor $Lf^*$ sends $D_\QCoh(\mathcal{O}_X)$
into $D_\QCoh(\mathcal{O}_Y)$.
\item If $X$ and $Y$ are affine and $f$ is given by the ring map
$A \to B$, then the diagram
$$
\xymatrix{
D(B) \ar[r] & D_\QCoh(\mathcal{O}_Y) \\
D(A) \ar[r] \ar[u]^{- \otimes_A^\mathbf{L} B} &
D_\QCoh(\mathcal{O}_X) \ar[u]_{Lf^*}
}
$$
commutes.
\end{enumerate}

\label{lemma-family-flat-fpqc-local-covering}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family of
morphisms of schemes with target $T$. Assume that
\begin{enumerate}
\item each $f_i$ is flat, and
\item there exists an fpqc covering
$\{g_j : S_j \to T\}_{j \in J}$ such that each
$\{S_j \times_T T_i \to S_j\}_{i \in I}$ is an fpqc covering.
\end{enumerate}
Then $\{f_i : T_i \to T\}_{i \in I}$ is an fpqc covering of $T$.

\label{lemma-uniqueness-extension}
Let $f : X \to S$ be a morphism of schemes. Assume $S$ is locally Noetherian
and $f$ locally of finite type. Let $r \geq 0$. Let $\alpha$ and $\beta$
be relative $r$-cycles on $X/S$. The following are equivalent
\begin{enumerate}
\item $\alpha = \beta$, and
\item $\alpha_\eta = \beta_\eta$ for any generic point $\eta \in S$
of an irreducible component of $S$.
\end{enumerate}

\label{lemma-chow-Noetherian}
\begin{reference}
\cite[II Theorem 5.6.1(a)]{EGA}
\end{reference}
Let $S$ be a Noetherian scheme.
Let $f : X \to S$ be a separated morphism of finite type.
Then there exist an $n \geq 0$ and a diagram
$$
\xymatrix{
X \ar[rd] & X' \ar[d] \ar[l]^\pi \ar[r] & \mathbf{P}^n_S \ar[dl] \\
& S &
}
$$
where $X' \to \mathbf{P}^n_S$ is an immersion, and
$\pi : X' \to X$ is proper and surjective. Moreover, we may
arrange it such that there exists a dense open subscheme
$U \subset X$ such that $\pi^{-1}(U) \to U$ is an isomorphism.

\label{lemma-relate-zero-affine}
In Situation \ref{situation-iso} suppose given an affine morphism
$i : Z \to X$ and a quasi-coherent $\mathcal{O}_Z$-module $\mathcal{H}$
such that $\mathcal{G} = i_*\mathcal{H}$. Let
$v : i^*\mathcal{F} \to \mathcal{H}$ be the map adjoint to $u$.
Then
\begin{enumerate}
\item $F_{v, zero} = F_{u, zero}$, and
\item if $i$ is a closed immersion, then $F_{v, surj} = F_{u, surj}$.
\end{enumerate}

\label{lemma-descending-property-quasi-affine}
The property $\mathcal{P}(f) =$``$f$ is quasi-affine''
is fpqc local on the base.

\label{lemma-separated-diagonal-proper}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item $f$ is separated,
\item $\Delta_{X/Y} : X \to X \times_Y X$ is universally closed, and
\item $\Delta_{X/Y} : X \to X \times_Y X$ is proper.
\end{enumerate}

\label{lemma-finite-cohomology}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $K$ be an object of
$D(\mathcal{O})$. Let $m \in \mathbf{Z}$.
\begin{enumerate}
\item If $K$ is $m$-pseudo-coherent and $H^i(K) = 0$
for $i > m$, then $H^m(K)$ is a finite type $\mathcal{O}$-module.
\item If $K$ is $m$-pseudo-coherent and $H^i(K) = 0$
for $i > m + 1$, then $H^{m + 1}(K)$ is a finitely presented
$\mathcal{O}$-module.
\end{enumerate}

\label{lemma-resolve}
Let $(A, \text{d})$ be a differential graded algebra.
Let $M$ be a differential graded $A$-module. There exists a homomorphism
$P \to M$ of differential graded $A$-modules such that
\begin{enumerate}
\item $P \to M$ is a quasi-isomorphism, and
\item $P$ has property (P).
\end{enumerate}

\label{lemma-factors-through-rational-equivalence}
\begin{reference}
Very weak form of \cite[Theorem 17.1]{F}
\end{reference}
Let $(S, \delta)$ be as in Situation \ref{situation-setup}.
Let $f : X \to Y$ be a morphism of schemes locally of finite type over $S$.
Let $p \in \mathbf{Z}$. Suppose given a rule
which assigns to every locally of finite type morphism $Y' \to Y$
and every $k$ a map
$$
c \cap - : Z_k(Y') \longrightarrow \CH_{k - p}(X')
$$
where $Y' = X' \times_X Y$, satisfying condition (3) of
Definition \ref{definition-bivariant-class}
whenever $\mathcal{L}'|_{D'} \cong \mathcal{O}_{D'}$. Then
$c \cap -$ factors through rational equivalence.

\label{lemma-disjoint-union-is-fpqc-covering}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family of
morphisms of schemes with target $T$. The following are equivalent
\begin{enumerate}
\item $\{f_i : T_i \to T\}_{i \in I}$ is an fpqc covering, and
\item setting $T' = \coprod_{i \in I} T_i$, and $f = \coprod_{i \in I} f_i$
the family $\{f : T' \to T\}$ is an fpqc covering.
\end{enumerate}

\label{lemma-compare-locally-constant}
Let $X$ be a scheme. Let $\Lambda$ be a ring.
The functor $\epsilon^{-1}$ defines an equivalence of categories
$$
\left\{
\begin{matrix}
\text{locally constant sheaves}\\
\text{of }\Lambda\text{-modules on }X_\etale\\
\text{of finite presentation}
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{locally constant sheaves}\\
\text{of }\Lambda\text{-modules on }X_\proetale\\
\text{of finite presentation}
\end{matrix}
\right\}
$$

\label{lemma-action-opens}
If $U \subset X$ and $V \subset Y$ are open and $f(U) \subset V$, then
$(\alpha \cap \beta)|_U$ is equal to $\alpha|_U \cap \beta|_V$.

\label{lemma-output-proper}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is proper if and only if $g$ is a formal modification
(Definition \ref{definition-formal-modification}).

\label{lemma-properties-form}
In Situation \ref{situation-regular-model} the symmetric bilinear form
(\ref{equation-form}) has the following properties
\begin{enumerate}
\item $(C_i \cdot C_j) \geq 0$ if $i \not = j$ with equality if and only
if $C_i \cap C_j = \emptyset$,
\item $(\sum m_i C_i \cdot C_j) = 0$,
\item there is no nonempty proper subset $I \subset \{1, \ldots, n\}$
such that $(C_i \cdot C_j) = 0$ for $i \in I$, $j \not \in I$.
\item $(\sum a_i C_i \cdot \sum a_i C_i) \leq 0$ with equality if and
only if there exists a $q \in \mathbf{Q}$ such that $a_i = qm_i$
for $i = 1, \ldots, n$,
\end{enumerate}

\label{lemma-family-is-one}
Let $S$ be a scheme.
Let $\{X_i \to X\}_{i \in I}$ be a family of morphisms
of algebraic spaces over $S$ with fixed target $X$.
Set $Y = \coprod_{i \in I} X_i$.
There is a canonical equivalence of categories
$$
\begin{matrix}
\text{category of descent data } \\
\text{relative to the family } \{X_i \to X\}_{i \in I}
\end{matrix}
\longrightarrow
\begin{matrix}
\text{ category of descent data} \\
\text{ relative to } Y/X
\end{matrix}
$$
which maps $(V_i, \varphi_{ij})$ to $(V, \varphi)$ with
$V = \coprod_{i\in I} V_i$ and $\varphi = \coprod \varphi_{ij}$.

\label{lemma-devissage-flat}
Assumptions and notation as in
Lemma \ref{lemma-elementary-devissage}.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is flat over $S$ in a neighbourhood of $x$,
\item $\mathcal{G}$ is flat over $S'$ in a neighbourhood of $z'$, and
\item $\pi_*\mathcal{G}$ is flat over $S'$ in a neighbourhood of $y'$.
\end{enumerate}
The following are equivalent also
\begin{enumerate}
\item[(a)] $\mathcal{F}_x$ is flat over $\mathcal{O}_{S, s}$,
\item[(b)] $\mathcal{G}_{z'}$ is flat over $\mathcal{O}_{S', s'}$, and
\item[(c)] $(\pi_*\mathcal{G})_{y'}$ is flat over $\mathcal{O}_{S', s'}$.
\end{enumerate}

\label{lemma-output-etale}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is \'etale if and only if $g$ is \'etale.

\label{lemma-sheaf-fpqc}
\begin{slogan}
Formal algebraic spaces are fpqc sheaves
\end{slogan}
Let $S$ be a scheme. Let $X$ be a formal algebraic space over $S$. Then
$X$ satisfies the sheaf property for the fpqc topology.

\label{lemma-composition-universally-open}
The composition of a pair of (universally) open morphisms of
algebraic stacks is (universally) open.

\label{lemma-lci-curves}
There exist an open substack $\Curvesstack^{lci} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{lci}$,
\item $X \to S$ is a local complete intersection morphism, and
\item $X \to S$ is a syntomic morphism.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{lci}$,
\item $X$ is a local complete intersection over $k$.
\end{enumerate}
\end{enumerate}

\label{lemma-composition-universal-homeomorphism}
The composition of a pair of universal homeomorphisms of
algebraic stacks is a universal homeomorphism.

\label{lemma-get-reasonable}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$. Assume
\begin{enumerate}
\item every quasi-compact scheme \'etale over $X$ has finitely many
irreducible components, and
\item every $x \in |X|$ of codimension $0$ on $X$ can be represented
by a monomorphism $\Spec(k) \to X$.
\end{enumerate}
Then $X$ is a reasonable algebraic space.

\label{lemma-quasi-affine-locally-closed}
Let $X$ be a quasi-affine scheme. For any quasi-compact immersion
$i : X' \to X$ the scheme $X'$ is quasi-affine.

\label{lemma-reflects-isomorphisms}
In Situation \ref{situation-formal-glueing} the functor
(\ref{equation-formal-glueing-spaces}) reflects isomorphisms.

\label{theorem-picard-group}
For any scheme $X$ we have canonical identifications
\begin{align*}
H_{fppf}^1(X, \mathbf{G}_m) & = H^1_{syntomic}(X, \mathbf{G}_m) \\
& = H^1_{smooth}(X, \mathbf{G}_m) \\
& = H_\etale^1(X, \mathbf{G}_m) \\
& = H^1_{Zar}(X, \mathbf{G}_m) \\
& = \Pic(X) \\
& = H^1(X, \mathcal{O}_X^*)
\end{align*}

\label{lemma-cartesian-object-derived-from-simplicial}
In Situation \ref{situation-simplicial-site}. Let
$(K_n, K_\varphi)$ be a simplicial system of the derived category.
Assume
\begin{enumerate}
\item $(K_n, K_\varphi)$ is cartesian,
\item $\Hom(K_i[t], K_i) = 0$ for $i \geq 0$ and $t > 0$.
\end{enumerate}
Then there exists a cartesian object $K$ of $D(\mathcal{C}_{total})$
whose associated simplicial system is isomorphic to $(K_n, K_\varphi)$.

\label{lemma-nodal-curves}
There exist an open substack $\Curvesstack^{nodal} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item $f$ is at-worst-nodal of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item the singularities of $X$ are at-worst-nodal and $X$
is equidimensional of dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-reformulate-purity}
Let $(A, \mathfrak m)$ be a Noetherian local ring. Set $X = \Spec(A)$
and let $U = X \setminus \{\mathfrak m\}$.
Let $V$ be finite \'etale
over $U$. Assume $A$ has depth $\geq 2$. The following are equivalent
\begin{enumerate}
\item $V = Y \times_X U$ for some $Y \to X$ finite \'etale,
\item $B = \Gamma(V, \mathcal{O}_V)$ is finite \'etale over $A$.
\end{enumerate}

\label{lemma-ubiquity-excellent}
The following types of schemes are excellent.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Noetherian complete local ring.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a Dedekind ring of
characteristic zero.
\end{enumerate}

\label{lemma-noetherian-unramified}
Let $f : X \to S$ be a morphism of schemes. Assume $S$ is locally Noetherian.
Then $f$ is unramified if and only if $f$ is G-unramified.

\label{lemma-zariski-etale-smooth-syntomic}
Any smooth covering is a syntomic covering, and a fortiori,
any \'etale or Zariski covering is a syntomic covering.

\label{lemma-etale-locally-finite-presentation}
\begin{slogan}
\'Etale implies locally of finite presentation.
\end{slogan}
An \'etale morphism of algebraic spaces is locally of finite presentation.

\label{lemma-constructing-invariant-opens}
Let $B \to S$ as in Section \ref{section-notation}.
Let $(U, R, s, t, c)$ be a groupoid in algebraic spaces over $B$.
\begin{enumerate}
\item If $s$ and $t$ are open, then for every open $W \subset U$
the open $s(t^{-1}(W))$ is $R$-invariant.
\item If $s$ and $t$ are open and quasi-compact, then $U$ has an open
covering consisting of $R$-invariant quasi-compact open subspaces.
\end{enumerate}

\label{lemma-action-base-change}
Forming $\alpha \cap \beta$ is compatible with flat base change
and flat pullback (see proof for elucidation).

\label{lemma-reach-points-scheme-theoretic-image}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a quasi-compact morphism of
algebraic stacks. Let $y \in |\mathcal{Y}|$ be a point in the closure
of the image of $|f|$. There exists a valuation ring $A$ with
fraction field $K$ and a commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & \mathcal{X} \ar[d] \\
\Spec(A) \ar[r] & \mathcal{Y}
}
$$
such that the closed point of $\Spec(A)$ maps to $y$.

\label{lemma-surjective-graded-rings-map-relative-proj}
With hypotheses and notation as in Lemma \ref{lemma-morphism-relative-proj}
above. Assume $\mathcal{A}_d \to \mathcal{B}_d$ is surjective for
$d \gg 0$. Then
\begin{enumerate}
\item $U(\psi) = Y$,
\item $r_\psi : Y \to X$ is a closed immersion, and
\item the maps $\theta : r_\psi^*\mathcal{O}_X(n) \to \mathcal{O}_Y(n)$
are surjective but not isomorphisms in general (even if
$\mathcal{A} \to \mathcal{B}$ is surjective).
\end{enumerate}

\label{lemma-composition-integral}
The composition of integral (resp.\ finite) morphisms is integral
(resp.\ finite).

\label{lemma-check-finiteness-local-cohomology-by-annihilator}
\begin{reference}
\cite[Lemma 3]{Faltings-annulators}
\end{reference}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. Let $M$ be a finite $A$-module. Let $n \geq 0$.
The following are equivalent
\begin{enumerate}
\item $H^i_T(M)$ is finite for $i \leq n$,
\item there exists an ideal $J \subset A$ with $V(J) \subset T$
such that $J$ annihilates $H^i_T(M)$ for $i \leq n$.
\end{enumerate}
If $T = V(I) = Z$ for an ideal $I \subset A$, then these are also
equivalent to
\begin{enumerate}
\item[(3)] there exists an $e \geq 0$ such that $I^e$ annihilates
$H^i_Z(M)$ for $i \leq n$.
\end{enumerate}

\label{lemma-eventual-iso-graded-rings-map-relative-proj}
With hypotheses and notation as in Lemma \ref{lemma-morphism-relative-proj}
above. Assume $\mathcal{A}_d \to \mathcal{B}_d$ is an isomorphism for all
$d \gg 0$. Then
\begin{enumerate}
\item $U(\psi) = Q$,
\item $r_\psi : Q \to P$ is an isomorphism, and
\item the maps $\theta : r_\psi^*\mathcal{O}_P(n) \to \mathcal{O}_Q(n)$
are isomorphisms.
\end{enumerate}

\label{lemma-neron-desingularization}
In Situation \ref{situation-neron}
assume that $R \to A$ is smooth at $\mathfrak q$
and that $R/\pi R \subset \Lambda/\pi \Lambda$ is a separable
extension of fields. Then after a finite number of affine N\'eron
blowups the algebra $A$ becomes smooth over $R$ at $\mathfrak p$.

\label{lemma-pseudo-torsor-implications}
Let $S$ be a scheme. Let $B$ be an algebraic space over $S$.
Let $G$ be a group algebraic space over $B$.
Let $X$ be a pseudo $G$-torsor over $B$.
Assume $G$ and $X$ locally of finite type over $B$.
\begin{enumerate}
\item If $G \to B$ is unramified, then $X \to B$ is unramified.
\item If $G \to B$ is locally quasi-finite, then $X \to B$ is
locally quasi-finite.
\end{enumerate}

\label{lemma-composition-quasi-finite}
The composition of two morphisms which are locally quasi-finite is
locally quasi-finite. The same is true for quasi-finite morphisms.

\label{lemma-divisor-special-fiber}
Let $X$ be a regular model of a smooth curve $C$ over $K$.
\begin{enumerate}
\item the special fibre $X_k$ is an effective Cartier divisor on $X$,
\item each irreducible component $C_i$ of $X_k$ is an effective
Cartier divisor on $X$,
\item $X_k = \sum m_i C_i$ (sum of effective Cartier divisors)
where $m_i$ is the multiplicity of $C_i$ in $X_k$,
\item $\mathcal{O}_X(X_k) \cong \mathcal{O}_X$.
\end{enumerate}

\label{lemma-smooth-permanence}
Let $S$ be a scheme. Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& B
}
$$
be a commutative diagram of morphisms of algebraic spaces over $S$. Assume that
\begin{enumerate}
\item $f$ is surjective, flat, and locally of finite presentation,
\item $p$ is smooth (resp.\ \'etale).
\end{enumerate}
Then $q$ is smooth (resp.\ \'etale).

\label{lemma-fibre-product-after-map}
\begin{slogan}
The top arrow of a ``magic diagram'' of algebraic spaces has nice
immersion-like properties, and under separatedness hypotheses
these get stronger.
\end{slogan}
Let $S$ be a scheme. Let $f : X \to Z$, $g : Y \to Z$ and $Z \to T$
be morphisms of algebraic spaces over $S$. Consider the induced morphism
$i : X \times_Z Y \to X \times_T Y$. Then
\begin{enumerate}
\item $i$ is representable, locally of finite type, locally quasi-finite,
separated and a monomorphism,
\item if $Z \to T$ is locally separated, then $i$ is an immersion,
\item if $Z \to T$ is separated, then $i$ is a closed immersion, and
\item if $Z \to T$ is quasi-separated, then $i$ is quasi-compact.
\end{enumerate}

\label{lemma-closed-immersion-proper}
A closed immersion of algebraic stacks is a proper morphism of
algebraic stacks.

\label{theorem-fundamental-group}
Let $X$ be a connected scheme.
\begin{enumerate}
\item There is a topology on $\pi_1(X, \overline{x})$ such that the open
subgroups form a fundamental system of open nbhds of $e\in \pi_1(X, \overline
x)$.
\item With topology of (1) the group
$\pi_1(X, \overline{x})$ is a profinite group.
\item The functor
$$
\begin{matrix}
\text{ schemes finite } \atop \text{ \'etale over }X & \to &
\text{ finite discrete continuous } \atop \pi_1(X, \overline{x})\text{-sets}\\
Y / X& \mapsto & F_{\overline{x}}(Y) \text{ with its natural action}
\end{matrix}
$$
is an equivalence of categories.
\end{enumerate}

\label{lemma-lifting-section}
Let $p: \mathcal{F} \to \mathcal{C}_\Lambda$ be a category cofibered in
groupoids. Consider a diagram of $\mathcal{F}$
$$
\vcenter{
\xymatrix{
y \ar[r] \ar[d]_a & x_\epsilon \ar[d]_e \\
x \ar[r]^d        & x_0
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
A \times_k k[\epsilon] \ar[r] \ar[d] & k[\epsilon] \ar[d] \\
A \ar[r] & k.
}
}
$$
in $\mathcal{C}_\Lambda$. Assume $\mathcal{F}$ satisfies (S2).
Then there exists a morphism $s : x \to y$ with $a \circ s = \text{id}_x$
if and only if there exists a morphism $s_\epsilon : x \to x_\epsilon$
with $e \circ s_\epsilon = d$.

\label{lemma-descending-property-flat}
The property $\mathcal{P}(f) =$``$f$ is flat''
is fpqc local on the base.

\label{lemma-dualizing-gorenstein-formal-fibres}
Let $A$ be a Noetherian local ring. If $A$ has a dualizing complex,
then the formal fibres of $A$ are Gorenstein.

\label{lemma-compute-i-star}
Let $i : Z \to X$ be a closed immersion of schemes.
Let $U \to X$ be an object of $X_\proetale$ such that
\begin{enumerate}
\item $U$ is affine and weakly contractible, and
\item every point of $U$ specializes to a point of $U \times_X Z$.
\end{enumerate}
Then $i_\proetale^{-1}\mathcal{F}(U \times_X Z) = \mathcal{F}(U)$
for all abelian sheaves on $X_\proetale$.

\label{lemma-locally-finite-presentation-universally-open}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item If $f$ is locally of finite presentation and generalizations lift
along $f$, then $f$ is open.
\item If $f$ is locally of finite presentation and generalizations lift
along every base change of $f$, then $f$ is universally open.
\end{enumerate}

\label{lemma-bivariant-weaker}
\begin{reference}
Weak form of \cite[Theorem 17.1]{F}
\end{reference}
Let $(S, \delta)$ be as in Situation \ref{situation-setup}.
Let $f : X \to Y$ be a morphism of schemes locally of finite type over $S$.
Let $p \in \mathbf{Z}$. Suppose given a rule
which assigns to every locally of finite type morphism $Y' \to Y$
and every $k$ a map
$$
c \cap - : \CH_k(Y') \longrightarrow \CH_{k - p}(X')
$$
where $Y' = X' \times_X Y$, satisfying conditions (1), (2) of
Definition \ref{definition-bivariant-class}
and condition (3) whenever $\mathcal{L}'|_{D'} \cong \mathcal{O}_{D'}$. Then
$c \cap -$ is a bivariant class.

\label{lemma-relative-proj-d}
In Situation \ref{situation-relative-proj}.
The functor $F_d$ is representable by a scheme.

\label{lemma-noah-pre}
\begin{reference}
Email from Noah Olander of Jun 9, 2020
\end{reference}
Let $k$ be a field. Let $X$ be a proper scheme over $k$ which is regular.
Let $F : D_{perf}(\mathcal{O}_X) \to D_{perf}(\mathcal{O}_X)$
be a $k$-linear exact functor. Assume for every coherent
$\mathcal{O}_X$-module $\mathcal{F}$ with $\dim(\text{Supp}(\mathcal{F})) = 0$
there is an isomorphism $\mathcal{F} \cong F(\mathcal{F})$.
Then $F$ is fully faithful.

\label{lemma-induction-principle}
\begin{reference}
\cite[Proposition 3.3.1]{BvdB}
\end{reference}
Let $X$ be a quasi-compact and quasi-separated scheme. Let $P$ be a property
of the quasi-compact opens of $X$. Assume that
\begin{enumerate}
\item $P$ holds for every affine open of $X$,
\item if $U$ is quasi-compact open, $V$ affine open,
$P$ holds for $U$, $V$, and $U \cap V$, then
$P$ holds for $U \cup V$.
\end{enumerate}
Then $P$ holds for every quasi-compact open of $X$
and in particular for $X$.

\label{theorem-finite-type-flat}
\begin{slogan}
The flat locus is open (non-Noetherian version).
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Assume
\begin{enumerate}
\item $X \to S$ is locally of finite presentation,
\item $\mathcal{F}$ is an $\mathcal{O}_X$-module of finite type, and
\item the set of weakly associated points of $S$ is locally finite in $S$.
\end{enumerate}
Then $U = \{x \in X \mid \mathcal{F}\text{ flat at }x\text{ over }S\}$
is open in $X$ and $\mathcal{F}|_U$ is an $\mathcal{O}_U$-module
of finite presentation and flat over $S$.

\label{lemma-closed-immersion}
Let $i : Z \to X$ be a closed immersion of schemes. Then
\begin{enumerate}
\item $i_\proetale^{-1}$ commutes with limits,
\item $i_{\proetale, *}$ is fully faithful, and
\item $i_\proetale^{-1}i_{\proetale, *} \cong \text{id}_{\Sh(Z_\proetale)}$.
\end{enumerate}

\label{lemma-zariski-open-cover-stack-is-space}
Let $\mathcal X$ be an algebraic stack.
Let $\mathcal{X}_i$, $i \in I$ be a set of open substacks of $\mathcal{X}$.
Assume
\begin{enumerate}
\item $\mathcal{X} = \bigcup_{i \in I} \mathcal{X}_i$, and
\item each $\mathcal{X}_i$ is an algebraic space.
\end{enumerate}
Then $\mathcal{X}$ is an algebraic space.

\label{lemma-characterize-perfect}
Let $\Lambda$ be a left Noetherian ring and $K\in D(\Lambda)$. Then $K$ is
perfect if and only if the two following conditions hold:
\begin{enumerate}
\item
$K$ has finite $\text{Tor}$-dimension, and
\item
for all $i \in \mathbf{Z}$, $H^i(K)$ is a finite $\Lambda$-module.
\end{enumerate}

\label{lemma-compact-support-h0}
Let $X$ be a separated scheme of finite type over a field $k$.
If $\mathcal{F}$ is a torsion abelian sheaf, then the abelian group
$H^0_c(X, \mathcal{F})$ defined in Definition \ref{definition-compact-support}
agrees with the abelian group $H^0_c(X, \mathcal{F})$ defined in
Definition \ref{definition-cohomology-compact-support}.

\label{lemma-continuous-representations-RS}
Example \ref{example-continuous-representations}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{V, \rho_0}$ is a deformation category
for any finite dimensional continuous representation
$\rho_0 : \Gamma \to \text{GL}_k(V)$.

\label{lemma-surjection}
\begin{slogan}
The cohomology of the cotangent complex of a surjective ring map is trivial in
degree zero; it is the kernel modulo its square in degree $-1$.
\end{slogan}
Let $A \to B$ be a surjective ring map with kernel $I$.
Then $H^0(L_{B/A}) = 0$ and $H^{-1}(L_{B/A}) = I/I^2$.
This isomorphism comes from the map (\ref{equation-comparison-map})
for the object $(A \to B)$ of $\mathcal{C}_{B/A}$.

\label{lemma-surjective-proper-ph}
Let $S$ be a scheme. Let $f : Y \to X$ be a surjective proper morphism
of algebraic spaces over $S$. Then $\{Y \to X\}$ is a ph covering.

\label{lemma-converse-existence-universally-closed}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Assume
\begin{enumerate}
\item $f$ is quasi-separated, and
\item $f$ is universally closed.
\end{enumerate}
Then $f$ satisfies the existence part of the valuative criterion.

\label{lemma-epi-not-surjective}
There exists an epimorphism of local rings of dimension $0$
which is not a surjection.

\label{lemma-nonfinite-h0}
Non-finite $H^0$.
\begin{enumerate}
\item There exists a ring $R$ and a projective scheme $X$
over $R$ such that $H^0(X, \mathcal{O}_X)$ is not
a finite $R$-module.
\item There exists a ring $R$ and a finite type quasi-coherent module
$\mathcal{F}$ on $\mathbf{P}^1_R$ such that
$H^0(\mathbf{P}^1_R, \mathcal{F})$ is not a finite $R$-module.
\end{enumerate}

\label{lemma-output-separated}
With assumptions and notation as in Theorem \ref{theorem-dilatations-general}
let $f : X' \to X$ correspond to $g : W \to X_{/T}$.
Then $f$ is separated $\Leftrightarrow$ $g$ is
separated and $\Delta_g : W \to W \times_{X_{/T}} W$ is rig-surjective.

\label{lemma-catenary-S2-equidimensional}
\begin{reference}
\cite[IV Corollary 5.10.9]{EGA}
\end{reference}
Let $A$ be a Noetherian local ring which is catenary and $(S_2)$.
Then $\Spec(A)$ is equidimensional.

\label{lemma-flat}
In Situation \ref{situation-flat}.
\begin{enumerate}
\item The functor $F_{flat}$ satisfies the sheaf property for the fpqc topology.
\item If $f$ is quasi-compact and locally of finite presentation
and $\mathcal{F}$ is of finite presentation, then the functor
$F_{flat}$ is limit preserving.
\end{enumerate}

\label{lemma-uniqueness-det}
Let $(R, \mathfrak m, \kappa)$ be any local ring.
The functor
$$
\det\nolimits_\kappa :
\left\{
\begin{matrix}
\text{finite length }R\text{-modules} \\
\text{with isomorphisms}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
1\text{-dimensional }\kappa\text{-vector spaces} \\
\text{with isomorphisms}
\end{matrix}
\right\}
$$
endowed with the maps $\gamma_{K \to L \to M}$ is characterized by
the following properties
\begin{enumerate}
\item its restriction to the subcategory of modules annihilated
by $\mathfrak m$ is isomorphic to the usual determinant functor
(see Lemma \ref{lemma-compare-det}), and
\item (1), (2) and (3) of Lemma \ref{lemma-det-exact-sequences}
hold.
\end{enumerate}

\label{lemma-check-conditions}
Let $k$ be a field. Let $X$ be a smooth projective curve over $k$
which has a $k$-rational point. Then the hypotheses of
Lemma \ref{lemma-flat-geometrically-connected-fibres-with-section}
are satisfied.

\label{lemma-dualizing-well-defined}
The module (\ref{equation-dualizing}) is well defined, i.e.,
independent of the choice of the factorization.

\label{lemma-directed-colimit-coherent}
Let $X$ be a Noetherian scheme. Every quasi-coherent $\mathcal{O}_X$-module
is the filtered colimit of its coherent submodules.

\label{lemma-characterize-OD}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item If $D \subset X$ is an effective Cartier divisor, then
the canonical section $1_D$ of $\mathcal{O}_X(D)$ is regular.
\item Conversely, if $s$ is a regular section of the invertible
sheaf $\mathcal{L}$, then there exists a unique effective
Cartier divisor $D = Z(s) \subset X$ and a unique isomorphism
$\mathcal{O}_X(D) \to \mathcal{L}$ which maps $1_D$ to $s$.
\end{enumerate}
The constructions
$D \mapsto (\mathcal{O}_X(D), 1_D)$ and $(\mathcal{L}, s) \mapsto Z(s)$
give mutually inverse maps
$$
\left\{
\begin{matrix}
\text{effective Cartier divisors on }X
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{pairs }(\mathcal{L}, s)\text{ consisting of an invertible}\\
\mathcal{O}_X\text{-module and a regular global section}
\end{matrix}
\right\}
$$

\label{proposition-compact}
Let $(A, \text{d})$ be a differential graded algebra. Let $E$ be an
object of $D(A, \text{d})$. Then the following are equivalent
\begin{enumerate}
\item $E$ is a compact object,
\item $E$ is a direct summand of an object of $D(A, \text{d})$
which is represented by a differential graded module $P$ which
has a finite filtration $F_\bullet$ by differential graded submodules
such that $F_iP/F_{i - 1}P$ are finite direct sums of shifts of $A$.
\end{enumerate}

\label{lemma-colimit-coherent}
Let $B \to S$ be as in Section \ref{section-notation}.
Let $(U, R, s, t, c)$ be a groupoid in algebraic spaces over $B$.
Assume that
\begin{enumerate}
\item $U$, $R$ are Noetherian,
\item $s, t$ are flat, quasi-compact, and quasi-separated.
\end{enumerate}
Then every quasi-coherent module $(\mathcal{F}, \alpha)$ on $(U, R, s, t, c)$
is a filtered colimit of coherent modules.

\label{lemma-characterize-Cohen-Macaulay}
Let $X$ be a scheme. The following are equivalent:
\begin{enumerate}
\item $X$ is Cohen-Macaulay,
\item $X$ is locally Noetherian and all of its local rings are Cohen-Macaulay,
and
\item $X$ is locally Noetherian and for any closed point $x \in X$
the local ring $\mathcal{O}_{X, x}$ is Cohen-Macaulay.
\end{enumerate}

\label{lemma-smooth}
Let $R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$. The following are
equivalent
\begin{enumerate}
\item $\underline{R}|_{\mathcal{C}_\Lambda}$ is smooth,
\item $\Lambda \to R$ is formally smooth in the $\mathfrak m_R$-adic topology,
\item $\Lambda \to R$ is flat and $R \otimes_\Lambda k'$ is
geometrically regular over $k'$, and
\item $\Lambda \to R$ is flat and $k' \to R \otimes_\Lambda k'$ is
formally smooth in the $\mathfrak m_R$-adic topology.
\end{enumerate}
In the classical case, these are also equivalent to
\begin{enumerate}
\item[(5)] $R$ is isomorphic to $\Lambda[[x_1, \ldots, x_n]]$
for some $n$.
\end{enumerate}

\label{lemma-bertini-irreducible}
\begin{reference}
\cite[Theorem 6.3 part 4)]{Jou}
\end{reference}
In Varieties, Situation \ref{varieties-situation-family-divisors} assume
\begin{enumerate}
\item $X$ is of finite type over $k$,
\item $X$ is geometrically irreducible over $k$,
\item there exist $v_1, v_2, v_3 \in V$ and an irreducible component
$Z$ of $H_{v_2} \cap H_{v_3}$ such that $Z \not \subset H_{v_1}$ and
$\text{codim}(Z, X) = 2$, and
\item every irreducible component $Y$ of $\bigcap_{v \in V} H_v$
has $\text{codim}(Y, X) \geq 2$.
\end{enumerate}
Then for general $v \in V \otimes_k k'$
the scheme $H_v$ is geometrically irreducible over $k'$.

\label{lemma-universal-finite-syntomic-smooth}
With notation as in Example \ref{example-universal-finite-syntomic}
and $U_d$ as in Lemma \ref{lemma-universal-finite-syntomic}
then $U_d$ is smooth over $\Spec(\mathbf{Z})$.

\label{lemma-base-change}
Let $S$ be a scheme. Let
$$
\xymatrix{
\mathcal{Y}' \times_\mathcal{Y} \mathcal{X} \ar[r]_{g'} \ar[d]_{f'} &
\mathcal{X} \ar[d]^f \\
\mathcal{Y}' \ar[r]^g & \mathcal{Y}
}
$$
be a $2$-cartesian diagram of categories fibred in groupoids over $S$.
Then we have a canonical isomorphism
$$
g^{-1}f_*\mathcal{F} \longrightarrow f'_*(g')^{-1}\mathcal{F}
$$
functorial in the presheaf $\mathcal{F}$ on $\mathcal{X}$.

\label{lemma-splitting-on-omega-a}
With notation as in More on Morphisms, Lemma \ref{more-morphisms-lemma-blowup}
for $a \geq 0$ there is a unique arrow
$Rb_*\Omega^a_{X'/S} \to \Omega^a_{X/S}$ in $D(\mathcal{O}_X)$
whose composition with $\Omega^a_{X/S} \to Rb_*\Omega^a_{X'/S}$
is the identity on $\Omega^a_{X/S}$.

\label{lemma-noetherian-finite-type-finite-presentation}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
\begin{enumerate}
\item If $Y$ is locally Noetherian and $f$ locally of finite type
then $f$ is locally of finite presentation.
\item If $Y$ is locally Noetherian and $f$ of finite type and quasi-separated
then $f$ is of finite presentation.
\end{enumerate}

\label{lemma-point-finite-type}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $x \in |X|$. The following are equivalent:
\begin{enumerate}
\item There exists a morphism $\Spec(k) \to X$
which is locally of finite type and represents $x$.
\item There exists a scheme $U$, a closed point $u \in U$, and an \'etale
morphism $\varphi : U \to X$ such that $\varphi(u) = x$.
\end{enumerate}

\label{lemma-codim-1-point-in-schematic-locus}
\begin{slogan}
Separated algebraic spaces are schemes in codimension 1.
\end{slogan}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $x \in |X|$. If $X$ is separated, locally Noetherian, and
the dimension of the local ring of $X$ at $x$ is $\leq 1$
(Properties of Spaces, Definition
\ref{spaces-properties-definition-dimension-local-ring}),
then there exists an open subspace of $X$ containing $x$ which is a scheme.

\label{lemma-bounded-below-truncation}
Let $S$ be a scheme.
Let $X$ be a quasi-compact and quasi-separated algebraic space over $S$. Let
$P \in D_{perf}(\mathcal{O}_X)$ and $E \in D_{\QCoh}(\mathcal{O}_X)$.
Let $a \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], E) = 0$ for $i \ll 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], \tau_{\leq a} E) = 0$ for $i \ll 0$.
\end{enumerate}

\label{lemma-topology-fibre}
\begin{slogan}
Fibers of field points of algebraic spaces have the
expected Zariski topologies.
\end{slogan}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$.
Let $y \in |Y|$ and assume that $y$ is represented by a quasi-compact
monomorphism $\Spec(k) \to Y$. Then $|X_k| \to |X|$ is a
homeomorphism onto $f^{-1}(\{y\}) \subset |X|$ with induced topology.

\label{lemma-local-isomorphism-implies}
Let $A \to B$ be a local isomorphism. Then
\begin{enumerate}
\item $A \to B$ is \'etale,
\item $A \to B$ identifies local rings,
\item $A \to B$ is quasi-finite.
\end{enumerate}

\label{lemma-image-affine-finite-morphism-affine-Noetherian}
Let $f : Y \to X$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $f$ finite,
\item $f$ surjective,
\item $Y$ affine, and
\item $X$ Noetherian.
\end{enumerate}
Then $X$ is affine.

\label{lemma-relative-comparison}
Let $X$ be a scheme.
\begin{enumerate}
\item For an abelian sheaf $\mathcal{F}$ on $X_\etale$
we have $R\epsilon_*(\epsilon^{-1}\mathcal{F}) = \mathcal{F}$.
\item For $K \in D^+(X_\etale)$ the map $K \to R\epsilon_*\epsilon^{-1}K$
is an isomorphism.
\end{enumerate}

\label{lemma-family-associated-module}
The construction in Example \ref{example-family-associated-module}
is compatible with base change, restriction, and flat pullback.

\label{lemma-number-of-branches-and-smooth}
Let $X \to S$ be a smooth morphism of schemes.
Let $x \in X$ with image $s \in S$.
Then
\begin{enumerate}
\item The number of geometric branches of $X$ at $x$
is equal to the number of geometric branches of $S$ at $s$.
\item If $\kappa(x)/\kappa(s)$ is a purely inseparable\footnote{In fact,
it would suffice if $\kappa(x)$ is geometrically irreducible over
$\kappa(s)$. If we ever need this we will add a detailed proof.}
extension of fields, then number of branches of $X$ at $x$
is equal to the number of branches of $S$ at $s$.
\end{enumerate}

\label{lemma-check-representable-covering}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Let $W$ be an algebraic space and let $W \to \mathcal{Y}$ be surjective,
locally of finite presentation, and flat. The following are equivalent
\begin{enumerate}
\item $f$ is representable by algebraic spaces, and
\item $W \times_\mathcal{Y} \mathcal{X}$ is an algebraic space.
\end{enumerate}

\label{lemma-generalities-sheafified}
Generalities on relative {\v C}ech complexes.
\begin{enumerate}
\item If
$$
\xymatrix{
\mathcal{V} \ar[d]_g \ar[r]_h & \mathcal{U} \ar[d]^f \\
\mathcal{Y} \ar[r]^e & \mathcal{X}
}
$$
is $2$-commutative diagram of categories fibred in groupoids over
$(\Sch/S)_{fppf}$, then there is a morphism
$e^{-1}\mathcal{K}^\bullet(f, \mathcal{F}) \to
\mathcal{K}^\bullet(g, e^{-1}\mathcal{F})$.
\item if $h$ and $e$ are equivalences, then the map of (1) is an isomorphism,
\item if $f, f' : \mathcal{U} \to \mathcal{X}$ are $2$-isomorphic, then
the associated relative {\v C}ech complexes are isomorphic,
\end{enumerate}

\label{theorem-chow-finite-type}
\begin{reference}
This is a result due to Ofer Gabber, see
\cite[Theorem 1.1]{olsson_proper}
\end{reference}
Let $f : \mathcal{X} \to Y$ be a morphism from an algebraic stack
to an algebraic space. Assume
\begin{enumerate}
\item $Y$ is quasi-compact and quasi-separated,
\item $f$ is separated of finite type.
\end{enumerate}
Then there exists a commutative diagram
$$
\xymatrix{
\mathcal{X} \ar[rd] & X \ar[l] \ar[d] \ar[r] & \overline{X} \ar[ld] \\
& Y
}
$$
where $X \to \mathcal{X}$ is proper surjective,
$X \to \overline{X}$ is an open immersion, and
$\overline{X} \to Y$ is proper morphism of algebraic spaces.

\label{lemma-Noetherian-approximation-combine}
(Noetherian approximation and combining properties.)
Let $P$, $Q$ be properties of morphisms of schemes which are stable
under base change. Let $f : X \to S$ be a morphism of finite presentation
of affine schemes. Assume we can find cartesian diagrams
$$
\vcenter{
\xymatrix{
X_1 \ar[d]_{f_1} & X \ar[l] \ar[d]^f \\
S_1 & S \ar[l]
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
X_2 \ar[d]_{f_2} & X \ar[l] \ar[d]^f \\
S_2 & S \ar[l]
}
}
$$
of affine schemes, with $S_1$, $S_2$ of finite type over $\mathbf{Z}$
and $f_1$, $f_2$ of finite type such that $f_1$ has property $P$
and $f_2$ has property $Q$. Then we can find a cartesian diagram
$$
\xymatrix{
X_0 \ar[d]_{f_0} & X \ar[l] \ar[d]^f \\
S_0 & S \ar[l]
}
$$
of affine schemes with $S_0$ of finite type over $\mathbf{Z}$
and $f_0$ of finite type such that $f_0$ has both property $P$ and
property $Q$.

\label{lemma-Artinian-affine}
Let $S$ be a scheme. Let $X$ be a quasi-separated algebraic space over $S$.
Let $A$ be an Artinian ring. Any morphism $\Spec(A) \to X$ is affine.

\label{lemma-immersion-universal-thickening}
Let $i : Z \to X$ be an immersion of schemes. Then
\begin{enumerate}
\item $i$ is formally unramified,
\item the universal first order thickening of $Z$ over $X$ is the first order
infinitesimal neighbourhood of $Z$ in $X$ of
Definition \ref{definition-first-order-infinitesimal-neighbourhood}, and
\item the conormal sheaf of $i$ in the sense of
Morphisms, Definition \ref{morphisms-definition-conormal-sheaf}
agrees with the conormal sheaf of $i$ in the sense of
Definition \ref{definition-universal-thickening}.
\end{enumerate}

\label{lemma-neron-colimit}
\begin{slogan}
Unramified extensions of DVRs are ind-smooth AKA N\'eron desingularization
\end{slogan}
Let $R \subset \Lambda$ be an extension of discrete valuation
rings which has ramification index $1$ and induces a separable
extension of residue fields and of fraction fields.
Then $\Lambda$ is a filtered colimit of smooth $R$-algebras.

\label{lemma-bootstrap-inherited}
In Situation \ref{situation-bootstrap} we have
\begin{enumerate}
\item[(E)] if $T' \subset T$ is a smaller specialization stable subset, then
$A, I, T', M$ satisfies the assumptions of Situation \ref{situation-bootstrap},
\item[(F)] if $S \subset A$ is a multiplicative subset, then
$S^{-1}A, S^{-1}I, T', S^{-1}M$
satisfies the assumptions of Situation \ref{situation-bootstrap}
where $T' \subset V(S^{-1}I)$ is the inverse image of $T$,
\item[(G)] the quadruple $A', I', T', M'$
satisfies the assumptions of Situation \ref{situation-bootstrap}
where $A', I', M'$ are the usual $I$-adic completions of $A, I, M$
and $T' \subset V(I')$ is the inverse image of $T$.
\end{enumerate}
Let $I \subset \mathfrak a \subset A$ be an ideal such that
$V(\mathfrak a) \subset T$. Then
\begin{enumerate}
\item[(A)] if $I$ is contained in the Jacobson radical of $A$,
then all hypotheses of
Lemmas \ref{lemma-kill-colimit-weak-general} and
\ref{lemma-kill-colimit-support-general} are satisfied
for $A, I, \mathfrak a, M$,
\item[(B)] if $A$ is complete with respect to $I$, then
all hypotheses except for possibly (5) of
Lemma \ref{lemma-algebraize-local-cohomology-general}
are satisfied for $A, I, \mathfrak a, M$,
\item[(C)] if $A$ is local with maximal ideal $\mathfrak m = \mathfrak a$,
then all hypotheses of
Lemmas \ref{lemma-kill-colimit-weak} and \ref{lemma-kill-colimit-support}
hold for $A, \mathfrak m, I, M$,
\item[(D)] if $A$ is local with maximal ideal $\mathfrak m = \mathfrak a$
and $I$-adically complete, then all hypotheses of
Lemma \ref{lemma-algebraize-local-cohomology}
hold for $A, \mathfrak m, I, M$,
\end{enumerate}

\label{lemma-finite-flat-over-almost-dense-subscheme-addendum}
In Lemma \ref{lemma-finite-flat-over-almost-dense-subscheme}
assume in addition that $s$ and $t$ are of finite presentation.
Then
\begin{enumerate}
\item the morphism $W' \to W$ is of finite presentation, and
\item if $u \in U$ is a point whose $R$-orbit consists of
generic points of irreducible components of $U$, then $u \in W$.
\end{enumerate}

\label{lemma-Cohen-Macaulay-over-regular}
Let $X$ be a regular scheme. Let $\mathcal{F}$ be a coherent
$\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is Cohen-Macaulay and $\text{Supp}(\mathcal{F}) = X$,
\item $\mathcal{F}$ is finite locally free of rank $> 0$.
\end{enumerate}

\label{lemma-monomorphism-injective-points}
Let $S$ be a scheme. If $X \to Y$ is a monomorphism of algebraic spaces
over $S$, then $|X| \to |Y|$ is injective.

\label{lemma-nilpotent}
Let $(A, \text{d})$ be a differential graded algebra.
Let $0 \to K_i \to L_i \to M_i \to 0$, $i = 1, 2, 3$
be admissible short exact sequence of differential graded $A$-modules.
Let $b : L_1 \to L_2$ and $b' : L_2 \to L_3$
be homomorphisms of differential graded modules such that
$$
\vcenter{
\xymatrix{
K_1 \ar[d]_0 \ar[r] &
L_1 \ar[r] \ar[d]_b &
M_1 \ar[d]_0 \\
K_2 \ar[r] & L_2 \ar[r] & M_2
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
K_2 \ar[d]^0 \ar[r] &
L_2 \ar[r] \ar[d]^{b'} &
M_2 \ar[d]^0 \\
K_3 \ar[r] & L_3 \ar[r] & M_3
}
}
$$
commute up to homotopy. Then $b' \circ b$ is homotopic to $0$.

\label{proposition-gabriel-rosenberg}
\begin{reference}
Special case of \cite[Theorem 1.2]{Brandenburg}
\end{reference}
Let $X$ and $Y$ be quasi-compact and quasi-separated schemes.
If $F : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Y)$
is an equivalence, then there exists an isomorphism
$f : Y \to X$ of schemes and an invertible $\mathcal{O}_Y$-module
$\mathcal{L}$ such that $F(\mathcal{F}) = f^*\mathcal{F} \otimes \mathcal{L}$.

\label{lemma-maximal-subfield-splits}
A maximal subfield of a finite central skew field $K$ over $k$ is
a splitting field for $K$.

\label{lemma-formal-object-effective}
In Situation \ref{situation-contractions} assume $X' \to S$ is separated.
Then every formal object for $F$ is effective.

\label{lemma-relation-with-naive-cotangent-complex}
Let $A \to B$ be a ring map. Then $\tau_{\geq -1}L_{B/A}$
is canonically quasi-isomorphic to the naive cotangent complex.

\label{lemma-dimension}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
The following quantities are equal:
\begin{enumerate}
\item The dimension of $X$.
\item The supremum of the dimensions of the local rings of $X$.
\item The supremum of $\dim_x(X)$ for $x \in |X|$.
\end{enumerate}

\label{lemma-criterion}
Let $k$ be a field. Let $G : (\Sch/k)^{opp} \to \textit{Groups}$ be a
functor. With terminology as in
Schemes, Definition \ref{schemes-definition-representable-by-open-immersions},
assume that
\begin{enumerate}
\item $G$ satisfies the sheaf property for the Zariski topology,
\item there exists a subfunctor $F \subset G$ such that
\begin{enumerate}
\item $F$ is representable,
\item $F \subset G$ is representable by open immersion,
\item for every field extension $K$ of $k$ and $g \in G(K)$
there exists a $g' \in G(k)$ such that $g'g \in F(K)$.
\end{enumerate}
\end{enumerate}
Then $G$ is representable by a group scheme over $k$.

\label{lemma-quasi-finite-over-base-j-proper}
Let $S$ be a scheme.
Let $(U, R, s, t, c)$ be a groupoid scheme over $S$.
Let $p \in S$ be a point, and let $u \in U$ be a point lying over $p$.
Assume assumptions (1) -- (6) of
Lemma \ref{lemma-quasi-finite-over-base}
hold as well as
\begin{enumerate}
\item[(7)] $j : R \to U \times_S U$ is universally closed\footnote{In view of
the other conditions this is equivalent to requiring $j$ to be proper.}.
\end{enumerate}
Then we can choose $(S', p') \to (S, p)$ and decompositions
$S' \times_S U = U' \amalg W$ and $S' \times_S R = R' \amalg W'$
and $u' \in U'$ such that (a) -- (g) of
Lemma \ref{lemma-quasi-finite-over-base}
hold as well as
\begin{enumerate}
\item[(h)] $R'$ is the restriction of $S' \times_S R$ to $U'$.
\end{enumerate}

\label{lemma-projective-space-grassmannian}
Let $n \geq 1$. There is a canonical isomorphism
$\mathbf{G}(n, n + 1) = \mathbf{P}^n_\mathbf{Z}$.

\label{lemma-fppf-open}
Let $f : \mathcal{X} \to \mathcal{Y}$ be flat and locally of finite
presentation. Then $|f| : |\mathcal{X}| \to |\mathcal{Y}|$ is open.

\label{lemma-contained-in}
Any set of big Zariski sites is contained in a common big Zariski site.
The same is true, mutatis mutandis, for big fppf and big \'etale sites.

\label{lemma-countable-dense-subset}
Let $S$ be a Noetherian scheme. Let $T \subset S$ be an infinite dense subset.
Then there exist a countable subset $E \subset T$ which is dense in $S$.

\label{lemma-category-fibred}
Let $X \to Y$ be a morphism of schemes.
\begin{enumerate}
\item The category $\mathcal{C}_{X/Y}$ is fibred over $X_{Zar}$.
\item The category $\mathcal{C}_{X/Y}$ is fibred over $Y_{Zar}$.
\item The category $\mathcal{C}_{X/Y}$ is fibred over the
category of pairs $(U, V)$ where $U \subset X$, $V \subset Y$ are
open and $f(U) \subset V$.
\end{enumerate}

\label{lemma-reduced-space}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item $X$ is reduced,
\item for every $x \in |X|$ the local ring of $X$ at $x$ is
reduced (Remark \ref{remark-list-properties-local-ring-local-etale-topology}).
\end{enumerate}
In this case $\Gamma(X, \mathcal{O}_X)$ is a reduced ring and
if $f \in \Gamma(X, \mathcal{O}_X)$ has $X = V(f)$, then $f = 0$.

\label{lemma-compute-ext-rel-perfect}
Let $f : X \to S$ be a morphism of schemes. Let $E, K \in D(\mathcal{O}_X)$.
Assume
\begin{enumerate}
\item $S$ is quasi-compact and quasi-separated,
\item $f$ is proper, flat, and of finite presentation,
\item $E$ is $S$-perfect,
\item $K$ is pseudo-coherent.
\end{enumerate}
Then there exists a pseudo-coherent $L \in D(\mathcal{O}_S)$ such that
$$
Rf_*R\SheafHom(K, E) = R\SheafHom(L, \mathcal{O}_S)
$$
and the same is true after arbitrary base change: given
$$
\vcenter{
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} &
X \ar[d]^f \\
S' \ar[r]^g &
S
}
}
\quad\quad
\begin{matrix}
\text{cartesian, then we have } \\
Rf'_*R\SheafHom(L(g')^*K, L(g')^*E) \\
= R\SheafHom(Lg^*L, \mathcal{O}_{S'})
\end{matrix}
$$

\label{lemma-sheaf}
Let $S$ be a scheme. Let $B$ be an algebraic space over $S$.
Let $X \subset X'$ and $Y \subset Y'$ be first order thickenings
over $B$. Assume given a morphism $a : X \to Y$ and a map
$A : a^*\mathcal{C}_{Y/Y'} \to \mathcal{C}_{X/X'}$ of
$\mathcal{O}_X$-modules. For an object $U'$ of
$(X')_{spaces, \etale}$ with $U = X \times_{X'} U'$
consider morphisms $a' : U' \to Y'$ such that
\begin{enumerate}
\item $a'$ is a morphism over $B$,
\item $a'|_U = a|_U$, and
\item the induced map
$a^*\mathcal{C}_{Y/Y'}|_U \to \mathcal{C}_{X/X'}|_U$
is the restriction of $A$ to $U$.
\end{enumerate}
Then the rule
\begin{equation}
\label{equation-sheaf}
U' \mapsto
\{a' : U' \to Y'\text{ such that (1), (2), (3) hold.}\}
\end{equation}
defines a sheaf of sets on $(X')_{spaces, \etale}$.

\label{lemma-annihilated-by-degree}
\begin{reference}
Argument taken from \cite{Saltman-torsion}.
\end{reference}
Let $S$ be a scheme. Let $\mathcal{A}$ be an Azumaya algebra which is
locally free of rank $d^2$ over $S$. Then the class
of $\mathcal{A}$ in the Brauer group of $S$ is annihilated by $d$.

\label{lemma-fibre-products-preserve-properties}
Let $f : \mathcal{X} \to \mathcal{Y}$, $g : \mathcal{Z} \to \mathcal{Y}$
be faithful $1$-morphisms of categories
fibred in groupoids over $(\Sch/S)_{fppf}$.
\begin{enumerate}
\item the functor $\mathcal{X} \times_\mathcal{Y} \mathcal{Z} \to \mathcal{Y}$
is faithful, and
\item if $\mathcal{X}, \mathcal{Z}$ have equalizers, so does
$\mathcal{X} \times_\mathcal{Y} \mathcal{Z}$.
\end{enumerate}

\label{lemma-bc-surjection}
Let $R \to A$ and $R \to R'$ be ring maps and $A' = A \otimes_R R'$.
Assume
\begin{enumerate}
\item $A$ is perfect as an $R$-module,
\item $A$ and $R'$ are tor independent over $R$.
\end{enumerate}
Then (\ref{equation-base-change}) is an isomorphism for all $K \in D(R)$.

\label{lemma-reduced-subscheme-closure}
Let $X$ be a scheme and let $U \subset X$ be a reduced open subscheme.
Then the following are equivalent
\begin{enumerate}
\item the scheme theoretic closure of $U$ in $X$ is $X$, and
\item $U$ is scheme theoretically dense in $X$.
\end{enumerate}
If this holds then $X$ is a reduced scheme.

\label{lemma-tor-qc-qs}
Let $S$ be a scheme. Let $X$ be a quasi-separated algebraic space over $S$.
Let $E$ be an object of $D_\QCoh(\mathcal{O}_X)$. Let $a \leq b$.
The following are equivalent
\begin{enumerate}
\item $E$ has tor amplitude in $[a, b]$, and
\item for all $\mathcal{F}$ in $\QCoh(\mathcal{O}_X)$
we have $H^i(E \otimes_{\mathcal{O}_X}^\mathbf{L} \mathcal{F}) = 0$
for $i \not \in [a, b]$.
\end{enumerate}

\label{lemma-orthogonal-koszul-complex}
\begin{reference}
\cite[Proposition 6.1]{Bokstedt-Neeman}
\end{reference}
In Situation \ref{situation-complex} denote $j : U \to X$ the open
immersion and let $K$ be the perfect object of $D(\mathcal{O}_X)$
corresponding to the Koszul complex on $f_1, \ldots, f_r$ over $A$.
For $E \in D_\QCoh(\mathcal{O}_X)$ the following are equivalent
\begin{enumerate}
\item $E = Rj_*(E|_U)$, and
\item $\Hom_{D(\mathcal{O}_X)}(K[n], E) = 0$ for all $n \in \mathbf{Z}$.
\end{enumerate}

\label{lemma-annihilate-Hp}
\begin{reference}
\cite[Lemma 1.9]{Bhatt-local}
\end{reference}
Let $A$ be a ring and let $J \subset I \subset A$ be finitely generated ideals.
Let $p \geq 0$ be an integer. Set $U = \Spec(A) \setminus V(I)$. If
$H^p(U, \mathcal{O}_U)$ is annihilated by $J^n$ for some $n$, then
$H^p(U, \mathcal{F})$ annihilated by $J^m$ for some $m = m(\mathcal{F})$
for every finite locally free $\mathcal{O}_U$-module $\mathcal{F}$.

\label{lemma-central-simple-algebra-pgln}
\begin{slogan}
Central simple algebras are classified by Galois cohomology of PGL.
\end{slogan}
Let $K$ be a field and let $K^{sep}$ be a separable algebraic closure.
Then the set of isomorphism classes of central simple algebras of degree
$d$ over $K$ is in bijection with the non-abelian cohomology
$H^1(\text{Gal}(K^{sep}/K), \text{PGL}_d(K^{sep}))$.

\label{lemma-openness-bounded-dimension-fibres}
\begin{reference}
\cite[IV Theorem 13.1.3]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
Let $n \geq 0$. Assume $f$ is locally of finite type.
The set
$$
U_n = \{x \in X \mid \dim_x X_{f(x)} \leq n\}
$$
is open in $X$.

\label{lemma-base-change-gerbe}
Let
$$
\xymatrix{
\mathcal{X}' \ar[r] \ar[d] & \mathcal{X} \ar[d] \\
\mathcal{Y}' \ar[r] & \mathcal{Y}
}
$$
be a fibre product of algebraic stacks.
If $\mathcal{X}$ is a gerbe over $\mathcal{Y}$, then
$\mathcal{X}'$ is a gerbe over $\mathcal{Y}'$.

\label{lemma-smooth-completion}
In Example \ref{example-rings} let $P$ be a $k$-algebra.
Let $J \subset P$ be an ideal.
Denote $P^\wedge$ the $J$-adic completion. If
\begin{enumerate}
\item $k \to P$ is of finite type, and
\item $\Spec(P) \to \Spec(k)$ is smooth on the complement of $V(J)$.
\end{enumerate}
then the functor between deformation categories of
Lemma \ref{lemma-completion}
$$
\Deformationcategory_P \longrightarrow \Deformationcategory_{P^\wedge}
$$
is smooth and induces an isomorphism on tangent spaces.

\label{lemma-normal-Noetherian}
Let $X$ be a Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $X$ is normal, and
\item $X$ is a finite disjoint union of normal integral schemes.
\end{enumerate}

\label{lemma-kernel-to-closure}
Let $K/k$ be an algebraic extension of fields.
Let $X$ be a finite type scheme over $k$.
The kernel of the map $\CH_i(X) \to \CH_i(X_K)$
constructed in Lemma \ref{lemma-chow-limit}
is torsion.

\label{lemma-characterize-motives}
Let $X$, $c_2$ be as in Example \ref{example-decompose-P1}.
Let $\mathcal{C}$ be a $\mathbf{Q}$-linear Karoubian symmetric
monoidal category. Any $\mathbf{Q}$-linear functor
$$
F :
\left\{
\begin{matrix}
\text{smooth projective schemes over }k\\
\text{morphisms are correspondences of degree }0
\end{matrix}
\right\}
\longrightarrow
\mathcal{C}
$$
of symmetric monoidal categories such that the image of $F(c_2)$ on
$F(X)$ is an invertible object, factors uniquely through a functor
$F : M_k \to \mathcal{C}$ of symmetric monoidal categories.

\label{lemma-curves-limits}
The stack $\Curvesstack \to \Sch_{fppf}$ is limit preserving
(Artin's Axioms, Definition \ref{artin-definition-limit-preserving}).

\label{lemma-exactness-pushforward-pullback}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C})
\to (\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$
be a morphism of ringed topoi.
\begin{enumerate}
\item The functor $f_*$ is left exact. In fact it commutes with
all limits.
\item The functor $f^*$ is right exact. In fact it commutes
with all colimits.
\end{enumerate}

\label{lemma-etale-formally-etale}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is \'etale, and
\item the morphism $f$ is locally of finite presentation and
formally \'etale.
\end{enumerate}

\label{lemma-projective-covers-local}
Let $(R, \mathfrak m, \kappa)$ be a local ring. Any finite $R$-module has
a projective cover.

\label{lemma-finite-birational-over-normal}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic
spaces over $S$. Assume
\begin{enumerate}
\item $X$ and $Y$ are decent and have finitely many irreducible components,
\item $f$ is integral and birational,
\item $Y$ is normal, and
\item $X$ is reduced.
\end{enumerate}
Then $f$ is an isomorphism.

\label{lemma-local-annihilator}
\begin{reference}
This is a special case of
\cite[Satz 1]{Faltings-annulators}.
\end{reference}
Let $A$ be a Gorenstein Noetherian local ring. Let $I \subset A$
be an ideal and set $Z = V(I) \subset \Spec(A)$.
Let $M$ be a finite $A$-module. Let $s = s_{A, I}(M)$ as in
(\ref{equation-cutoff}). Then $H^i_Z(M)$ is finite for $i < s$,
but $H^s_Z(M)$ is not finite.

\label{lemma-Noetherian-h-covering}
Let $X$ be a Noetherian scheme. Let $\{X_i \to X\}_{i \in I}$
be a finite family of finite type morphisms. The following are equivalent
\begin{enumerate}
\item $\coprod_{i \in I} X_i \to X$ is universally submersive
(Morphisms, Definition
\ref{morphisms-definition-submersive}), and
\item $\{X_i \to X\}_{i \in I}$ is an h covering.
\end{enumerate}

\label{lemma-mono-towards-locally-quasi-finite-over-field}
Let $k$ be a field. Let $f : X \to Y$ be a monomorphism of algebraic spaces
over $k$. If $Y$ is locally quasi-finite over $k$ so is $X$.

\label{lemma-proj-separated}
Let $S$ be a graded ring.
The scheme $\text{Proj}(S)$ is separated.

\label{lemma-2}
\begin{reference}
See \cite{Lech-inequalities} and \cite[Lemma 2 page 300]{MatCA}.
\end{reference}
Let $A$ be a ring. If $f_1, \ldots, f_{r - 1}, f_rg_r$
are independent and if the $A$-module
$A/(f_1, \ldots, f_{r - 1}, f_rg_r)$ has finite length, then
\begin{align*}
& \text{length}_A(A/(f_1, \ldots, f_{r - 1}, f_rg_r)) \\
& =
\text{length}_A(A/(f_1, \ldots, f_{r - 1}, f_r)) +
\text{length}_A(A/(f_1, \ldots, f_{r - 1}, g_r))
\end{align*}

\label{lemma-base-change-etale}
The base change of an \'etale morphism of algebraic spaces
by any morphism of algebraic spaces is \'etale.

\label{lemma-proper-pure}
In Situation \ref{situation-pre-pure}.
\begin{enumerate}
\item If the support of $\mathcal{F}$ is proper over $Y$, then
$\mathcal{F}$ is universally pure relative to $Y$.
\item If $f$ is proper, then
$\mathcal{F}$ is universally pure relative to $Y$.
\item If $f$ is proper, then $X$ is universally pure relative to $Y$.
\end{enumerate}

\label{lemma-scheme-over-algebraic-closure-enough-affines}
Let $k$ be a field with algebraic closure $\overline{k}$. Let $X$
be an algebraic space over $k$ such that
\begin{enumerate}
\item $X$ is decent and locally of finite type over $k$,
\item $X_{\overline{k}}$ is a scheme, and
\item any finite set of $\overline{k}$-rational points of $X_{\overline{k}}$
is contained in an affine.
\end{enumerate}
Then $X$ is a scheme.

\label{lemma-approximate-principal}
\begin{reference}
The rig-\'etale case of \cite[III Theorem 7]{Elkik}
\end{reference}
Let $A$ be a Noetherian ring and $I = (a)$ a principal ideal.
Let $B$ be an object of (\ref{equation-C-prime}) which is
rig-\'etale over $(A, I)$.
Then there exists a finite type $A$-algebra $C$ and an
isomorphism $B \cong C^\wedge$.

\label{lemma-pic-qs-lfp}
The morphism $\Picardstack_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{lemma-blowup-finite-nr-irreducibles}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$. Let
$b : X' \to X$ be the blowup of $X$ in a closed subspace. If
$X$ satisfies the equivalent conditions of
Morphisms of Spaces, Lemma \ref{spaces-morphisms-lemma-prepare-normalization}
then so does $X'$.

\label{lemma-completion-taut}
Let $A$ be a linearly topologized ring. The map $A \to A^\wedge$
from $A$ to its completion is taut.

\label{lemma-find-affine-codimension-1}
Let $(U, R, s, t, c)$ be a groupoid scheme. Let $u \in U$. Assume
\begin{enumerate}
\item $s, t$ are finite morphisms,
\item $U$ is separated and locally Noetherian,
\item $\dim(\mathcal{O}_{U, u'}) \leq 1$ for every point $u'$
in the orbit of $u$.
\end{enumerate}
Then $u$ is contained in an $R$-invariant affine open of $U$.

\label{lemma-augmentation-site}
In Situation \ref{situation-simplicial-site} let $a_0$ be an
augmentation towards a site $\mathcal{D}$ as in
Remark \ref{remark-augmentation-site}. Then $a_0$ induces
\begin{enumerate}
\item a morphism of topoi $a_n : \Sh(\mathcal{C}_n) \to \Sh(\mathcal{D})$
for all $n \geq 0$,
\item a morphism of topoi $a : \Sh(\mathcal{C}_{total}) \to \Sh(\mathcal{D})$
\end{enumerate}
such that
\begin{enumerate}
\item for all $\varphi : [m] \to [n]$ we have $a_m \circ f_\varphi = a_n$,
\item if $g_n : \Sh(\mathcal{C}_n) \to \Sh(\mathcal{C}_{total})$
is as in Lemma \ref{lemma-restriction-to-components-site}, then
$a \circ g_n = a_n$, and
\item $a_*\mathcal{F}$ for $\mathcal{F} \in \Sh(\mathcal{C}_{total})$
is the equalizer of the two maps
$a_{0, *}\mathcal{F}_0 \to a_{1, *}\mathcal{F}_1$.
\end{enumerate}

\label{lemma-scheme-CM-iff-all-Sk}
Let $X$ be a locally Noetherian scheme.
Then $X$ is Cohen-Macaulay if and only if $X$ has $(S_k)$ for all $k \geq 0$.

\label{lemma-olsson-laszlo}
\begin{reference}
This is \cite[Proposition 2.1.4]{six-I} with slightly changed
hypotheses; it is the analogue of \cite[Proposition 3.13]{Spaltenstein}
for sites.
\end{reference}
In Situation \ref{situation-olsson-laszlo} for any
$E \in D_\mathcal{A}(\mathcal{O})$ the map
$E \to R\lim \tau_{\geq -n} E$ of
Derived Categories, Remark
\ref{derived-remark-map-into-derived-limit-truncations}
is an isomorphism in $D(\mathcal{O})$.

\label{lemma-complexes-diagonal-affine-fp}
The diagonal of $\Complexesstack_{X/B}$ over $B$ is affine
and of finite presentation.

\label{lemma-curves-diagonal-separated-fp}
The diagonal of $\Curvesstack$ is separated
and of finite presentation.

\label{lemma-zariski-etale-smooth-syntomic-fppf-fpqc}
Any fppf covering is an fpqc covering, and a fortiori,
any syntomic, smooth, \'etale or Zariski covering is an fpqc covering.

\label{lemma-complexes-qs-lfp}
The morphism $\Complexesstack_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{lemma-composition-finite-type}
The composition of finite type morphisms is of finite type.
The same holds for locally of finite type.

\label{lemma-proper-push-pull-ph-etale}
In Lemma \ref{lemma-push-pull-ph-etale} if $f$ is proper, then we have
\begin{enumerate}
\item $a_Y^{-1} \circ f_{small, *} = f_{big, ph, *} \circ a_X^{-1}$, and
\item
$a_Y^{-1}(Rf_{small, *}K) = Rf_{big, ph, *}(a_X^{-1}K)$
for $K$ in $D^+(X_\etale)$ with torsion cohomology sheaves.
\end{enumerate}

\label{lemma-separated-implies-morphism-separated}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item If $X$ is separated then $X$ is separated over $S$.
\item If $X$ is locally separated then $X$ is locally separated over $S$.
\item If $X$ is quasi-separated then $X$ is quasi-separated over $S$.
\end{enumerate}
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
\begin{enumerate}
\item[(4)] If $X$ is separated over $S$ then $f$ is separated.
\item[(5)] If $X$ is locally separated over $S$ then $f$ is locally separated.
\item[(6)] If $X$ is quasi-separated over $S$ then $f$ is quasi-separated.
\end{enumerate}

\label{lemma-check-lci-agrees}
Let $S$ be a finite type algebra over a field $k$.
\begin{enumerate}
\item for a prime $\mathfrak q \subset S$ the local ring $S_\mathfrak q$
is a complete intersection in the sense of
Algebra, Definition \ref{algebra-definition-lci-local-ring}
if and only if $S_\mathfrak q$ is a complete
intersection in the sense of Definition \ref{definition-lci}, and
\item $S$ is a local complete intersection in the sense of
Algebra, Definition \ref{algebra-definition-lci-field}
if and only if $S$ is a local complete
intersection in the sense of Definition \ref{definition-lci}.
\end{enumerate}

\label{lemma-adic-taut}
Let $\varphi : A \to B$ be a continuous homomorphism between
pre-adic topological rings. If $\varphi$ is adic, then $\varphi$ is taut.

\label{lemma-finite-disjoint-quasi-compact}
A finite disjoint union of quasi-compact algebraic stacks is
a quasi-compact algebraic stack.

\label{lemma-locally-Noetherian-dimension-0}
A locally Noetherian scheme of dimension $0$ is a disjoint
union of spectra of Artinian local rings.

\label{lemma-descending-property-closed-immersion}
The property $\mathcal{P}(f) =$``$f$ is a closed immersion''
is fpqc local on the base.

\label{lemma-representable-separated-diagonal-closed}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
representable by algebraic spaces. Then the following are equivalent
\begin{enumerate}
\item $f$ is separated,
\item $\Delta_f$ is a closed immersion,
\item $\Delta_f$ is proper, or
\item $\Delta_f$ is universally closed.
\end{enumerate}

\label{lemma-finite-fibre}
Let $f : X \to S$ be a morphism of schemes.
Let $s \in S$. Assume that
\begin{enumerate}
\item $f$ is locally of finite type, and
\item $f^{-1}(\{s\})$ is a finite set.
\end{enumerate}
Then $X_s$ is a finite discrete topological space, and
$f$ is quasi-finite at each point of $X$ lying over $s$.

\label{lemma-base-change-universally-open}
The base change of a universally open morphism of algebraic spaces
by any morphism of algebraic spaces is universally open.

\label{lemma-purity-one-divisor-general}
Let $X$ be a locally Noetherian scheme. Let $U \subset X$ be open and dense.
Let $Y \to U$ be a finite \'etale morphism. Assume
\begin{enumerate}
\item $Y$ is unramified over $X$ in codimension $1$, and
\item $\mathcal{O}_{X, x}$ is regular for all $x \in X \setminus U$.
\end{enumerate}
Then there exists a finite \'etale morphism $Y' \to X$
whose restriction to $U$ is $Y$.

\label{lemma-twisted-inverse-image}
\begin{reference}
This is almost the same as \cite[Example 4.2]{Neeman-Grothendieck}.
\end{reference}
Let $f : X \to Y$ be a morphism between quasi-separated and quasi-compact
schemes. The functor $Rf_* : D_\QCoh(\mathcal{O}_X) \to D_\QCoh(\mathcal{O}_Y)$
has a right adjoint.

\label{lemma-construction-opens}
If $U \subset X$ and $V \subset Y$ are open and $f(U) \subset V$, then
$(\alpha \circ \beta)|_U$ is equal to $\alpha|_U \circ \beta|_V$.

\label{lemma-flat-tor-zero}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $\mathcal{F}$ be an $\mathcal{O}$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a flat $\mathcal{O}$-module, and
\item $\text{Tor}_1^\mathcal{O}(\mathcal{F}, \mathcal{G}) = 0$
for every $\mathcal{O}$-module $\mathcal{G}$.
\end{enumerate}

\label{lemma-rs}
In Situation \ref{situation-contractions} the functor $F$ satisfies
the Rim-Schlessinger condition (RS).

\label{lemma-derived-products}
Let $(A, \text{d})$ be a differential graded algebra. Then
\begin{enumerate}
\item $D(A, \text{d})$ has both direct sums and products,
\item direct sums are obtained by taking direct sums of differential graded
modules,
\item products are obtained by taking products of differential
graded modules.
\end{enumerate}

\label{lemma-quasi-compact-existence-universally-closed}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
Assume
\begin{enumerate}
\item $f$ is quasi-compact, and
\item $f$ satisfies the existence part of the valuative criterion.
\end{enumerate}
Then $f$ is universally closed.

\label{lemma-tor-amplitude}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $E$ be an object of
$D(\mathcal{O})$. Let $a, b \in \mathbf{Z}$ with $a \leq b$. The following
are equivalent
\begin{enumerate}
\item $E$ has tor-amplitude in $[a, b]$.
\item $E$ is represented by a complex
$\mathcal{E}^\bullet$ of flat $\mathcal{O}$-modules with
$\mathcal{E}^i = 0$ for $i \not \in [a, b]$.
\end{enumerate}

\label{lemma-decompose-section-formulae}
In the situation of Lemma \ref{lemma-decompose-section}
assume $Y$ is locally of finite type over $(S, \delta)$ as in
Situation \ref{situation-setup}. Then we have
$i_1^*p^*\alpha = p_1^*i^*\alpha$
in $\CH_k(D_1)$ for all $\alpha \in \CH_k(Y)$.

\label{lemma-affine-compare-bounded}
Let $X = \Spec(A)$ be an affine scheme. All the functors in the diagram
$$
\xymatrix{
D(\QCoh(\mathcal{O}_X)) \ar[rr]_{(\ref{equation-compare})}
& &
D_\QCoh(\mathcal{O}_X) \ar[ld]^{R\Gamma(X, -)} \\
& D(A) \ar[lu]^{\widetilde{\ \ }}
}
$$
are equivalences of triangulated categories. Moreover, for $E$ in
$D_\QCoh(\mathcal{O}_X)$ we have $H^0(X, E) = H^0(X, H^0(E))$.

\label{lemma-immersion-locally-finite-type}
A closed immersion is of finite type.
An immersion is locally of finite type.

\label{lemma-slice-smooth}
Let $f : X \to S$ be a morphism of schemes.
Let $x \in X$ be a point with image $s \in S$.
Assume
\begin{enumerate}
\item $f$ is smooth at $x$, and
\item $x$ is a closed point of $X_s$ and $\kappa(s) \subset \kappa(x)$
is separable.
\end{enumerate}
Then there exists an immersion $Z \to X$ containing $x$ such that
\begin{enumerate}
\item $Z \to S$ is \'etale, and
\item $Z_s = \{x\}$ set theoretically.
\end{enumerate}

\label{lemma-spec}
In Situation \ref{situation-relative-spec}.
The functor $F$ is representable by a scheme.

\label{lemma-zariski-etale-smooth-syntomic-fppf}
Any syntomic covering is an fppf covering, and a fortiori,
any smooth, \'etale, or Zariski covering is an fppf covering.

\label{lemma-deform}
Let $S$ be a scheme. Let $(f, f') : (X \subset X') \to (Y \subset Y')$ be a
morphism of first order thickenings of algebraic spaces over $S$. Assume that
$f$ is flat. Then the following are equivalent
\begin{enumerate}
\item $f'$ is flat and $X = Y \times_{Y'} X'$, and
\item the canonical map $f^*\mathcal{C}_{Y/Y'} \to \mathcal{C}_{X/X'}$
is an isomorphism.
\end{enumerate}

\label{lemma-functor-quasi-coherent-from-affine}
Let $R$ be a ring. Let $X$ and $Y$ be schemes over $R$ with $X$ affine.
There is an equivalence of categories between
\begin{enumerate}
\item the category of $R$-linear functors
$F : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Y)$
which are right exact and commute with arbitrary direct sums, and
\item the category $\QCoh(\mathcal{O}_{X \times_R Y})$
\end{enumerate}
given by sending $\mathcal{K}$ to the functor $F$ in (\ref{equation-FM-QCoh}).

\label{lemma-when-field}
Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
\begin{enumerate}
\item If $|X|$ is a singleton then $X$ is a scheme.
\item If $|X|$ is a singleton and $X$ is reduced, then
$X \cong \Spec(k)$ for some field $k$.
\end{enumerate}

\label{lemma-pullback-effective-Cartier-defined}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
Let $D \subset Y$ be an effective Cartier divisor.
The pullback of $D$ by $f$ is defined in each of the following cases:
\begin{enumerate}
\item $f(x) \not \in |D|$ for any weakly associated point $x$ of $X$,
\item $f$ is flat, and
\item add more here as needed.
\end{enumerate}

\label{lemma-fpqc-quotient-topology}
\begin{reference}
\cite[Expose VIII, Corollaire 4.3]{SGA1} and
\cite[IV, Corollaire 2.3.12]{EGA}
\end{reference}
Let $f : X \to Y$ be a quasi-compact, surjective, flat morphism.
A subset $T \subset Y$ is open (resp.\ closed) if and only
$f^{-1}(T)$ is open (resp.\ closed). In other words, $f$ is
a submersive morphism.

\label{lemma-split-universally-exact-sequence}
Let $A$ be a ring.
\begin{enumerate}
\item Let $L \to M \to N$ be a universally exact sequence
of $A$-modules. Let $K = \Im(M \to N)$.
Then $K \to N$ is universally injective.
\item Any universally exact complex
can be split into universally exact short exact sequences.
\end{enumerate}

\label{lemma-refine-by-standard-ph}
Let $T$ be an affine scheme. Each of the following types of families
of maps with target $T$ has a refinement by a standard ph covering:
\begin{enumerate}
\item any Zariski open covering of $T$,
\item $\{W_{ji} \to T\}_{j = 1, \ldots, m, i = 1, \ldots n_j}$
where $\{W_{ji} \to U_j\}_{i = 1, \ldots, n_j}$
and $\{U_j \to T\}_{j = 1, \ldots, m}$ are standard ph coverings.
\end{enumerate}

\label{lemma-taut-descent-countable}
In the situation above, if $B$ has a countable fundamental system of
open ideals, then $A$ has a countable fundamental system of open ideals.

\label{lemma-thickening}
Let $i : \mathcal{X} \to \mathcal{X}'$ be a morphism of algebraic stacks.
The following are equivalent
\begin{enumerate}
\item $i$ is a thickening of algebraic stacks (abuse of language as above), and
\item $i$ is representable by algebraic spaces and
is a thickening in the sense of Properties of Stacks, Section
\ref{stacks-properties-section-properties-morphisms}.
\end{enumerate}
In this case $i$ is a closed immersion and a universal homeomorphism.

\label{lemma-surjective}
Let $A \to B$ be a ring map in $\mathcal{C}_\Lambda$.
The following are equivalent
\begin{enumerate}
\item $f$ is surjective,
\item $\mathfrak m_A/\mathfrak m_A^2 \to \mathfrak m_B/\mathfrak m_B^2$
is surjective, and
\item $\mathfrak m_A/(\mathfrak m_\Lambda A + \mathfrak m_A^2)
\to \mathfrak m_B/(\mathfrak m_\Lambda B + \mathfrak m_B^2)$ is surjective.
\end{enumerate}

\label{lemma-flat-surjective-monomorphism}
A quasi-compact flat surjective monomorphism of algebraic spaces
is an isomorphism.

\label{lemma-representable-by-spaces-surjective}
Let $p : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$. If $p$ is
representable by algebraic spaces, then the following are equivalent:
\begin{enumerate}
\item $p$ is surjective on objects, and
\item $p$ is surjective (see
Algebraic Stacks,
Definition \ref{algebraic-definition-relative-representable-property}).
\end{enumerate}

\label{lemma-generic-point}
Let $X$ be a scheme. Let $x \in X$. Then $x$ is a generic point of
an irreducible component of $X$ if and only if $\dim(\mathcal{O}_{X, x}) = 0$.

\label{lemma-flat-is-flat-at-all-points}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Then $f$ is flat if and only if $f$ is flat at all points of $|X|$.

\label{lemma-category-of-spaces-over-smaller-base-scheme}
Let $\Sch_{fppf}$ be a big fppf site.
Let $S \to S'$ be a morphism of this site.
The constructions A and B of
Stacks, Section \ref{stacks-section-localize}
above give isomorphisms of $2$-categories
$$
\left\{
\begin{matrix}
2\text{-category of algebraic}\\
\text{stacks }\mathcal{X}\text{ over }S
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
2\text{-category of pairs }(\mathcal{X}', f)\text{ consisting of an}\\
\text{algebraic stack }\mathcal{X}'\text{ over }S'\text{ and a morphism}\\
f : \mathcal{X}' \to (\Sch/S)_{fppf}\text{ of algebraic stacks over }S'
\end{matrix}
\right\}
$$

\label{lemma-map-completions-finite-type}
In the situation above. If $f$ is locally of finite type, then
$f_{/T}$ is locally of finite type.

\label{lemma-ind-etale-permanence}
Let $A$ be a ring. Let $B \to C$ be an $A$-algebra map of ind-\'etale
$A$-algebras. Then $C$ is an ind-\'etale $B$-algebra.

\label{lemma-syntomic-smooth-etale-permanence}
Let $S$ be a scheme. Let
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& B
}
$$
be a commutative diagram of morphisms of algebraic spaces over $S$.
Assume that
\begin{enumerate}
\item $f$ is surjective, and syntomic (resp.\ smooth, resp.\ \'etale),
\item $p$ is syntomic (resp.\ smooth, resp.\ \'etale).
\end{enumerate}
Then $q$ is syntomic (resp.\ smooth, resp.\ \'etale).

\label{proposition-sheaf-fpqc}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$. Then
$X$ satisfies the sheaf property for the fpqc topology.

\label{lemma-composition-separated}
All of the separation axioms listed in
Definition \ref{definition-separated}
are stable under composition of morphisms.

\label{lemma-cd-local}
Let $I \subset A$ be a finitely generated ideal of a ring $A$.
Then $\text{cd}(A, I) = \max \text{cd}(A_\mathfrak p, I_\mathfrak p)$.

\label{lemma-base-change-finite-type}
A base change of a finite type morphism is finite type.
The same holds for locally of finite type.

\label{lemma-regular-gorenstein}
A regular local ring is Gorenstein.
A regular ring is Gorenstein.

\label{lemma-limit-from-good-diagram}
In Situation \ref{situation-limit-noetherian}.
Let $X \to B$ be a quasi-separated and finite type morphism
of algebraic spaces. Given $i \in I$ and a diagram
$$
\vcenter{
\xymatrix{
X \ar[r] \ar[d] & W \ar[d] \\
B \ar[r] & B_i
}
}
$$
as in (\ref{equation-good-diagram}) for $i' \geq i$ let
$X_{i'}$ be the scheme theoretic image of $X \to B_{i'} \times_{B_i} W$.
Then $X = \lim_{i' \geq i} X_{i'}$.

\label{lemma-prepare-leray}
Let $f: X \to Y$ be a morphism and $\mathcal{I}$ an injective object of
$\textit{Ab}(X_\etale)$. Let $V \in \Ob(Y_\etale)$. Then
\begin{enumerate}
\item for any covering $\mathcal{V} = \{V_j\to V\}_{j \in J}$ we have
$\check H^p(\mathcal{V}, f_*\mathcal{I}) = 0$ for all $p > 0$,
\item $f_*\mathcal{I}$ is acyclic for the functor $\Gamma(V, -)$, and
\item if $g : Y \to Z$, then $f_*\mathcal{I}$ is acyclic for $g_*$.
\end{enumerate}

\label{lemma-no-nonconstant-morphism-from-P1-to-group}
\begin{slogan}
No complete rational curves on groups.
\end{slogan}
Let $k$ be a field. Let $G$ be a separated group algebraic space locally
of finite type over $k$. There does not exist a nonconstant
morphism $f : \mathbf{P}^1_k \to G$ over $\Spec(k)$.

\label{lemma-special-locally-free}
Any of the properties (1) -- (8) of Definition \ref{definition-site-local}
is intrinsic (see discussion in Section \ref{section-intrinsic}).

\label{lemma-descending-property-etale}
The property $\mathcal{P}(f) =$``$f$ is \'etale''
is fpqc local on the base.

\label{lemma-locally-closed-where-H0-locally-free}
Let $X$ be a scheme. Let $E \in D(\mathcal{O}_X)$ be perfect
of tor-amplitude in $[a, b]$ for some $a, b \in \mathbf{Z}$.
Let $r \geq 0$.
Then there exists a locally closed subscheme $j : Z \to X$
characterized by the following
\begin{enumerate}
\item $H^a(Lj^*E)$ is a locally free $\mathcal{O}_Z$-module of rank $r$, and
\item a morphism $f : Y \to X$ factors through $Z$
if and only if for all morphisms $g : Y' \to Y$ the
$\mathcal{O}_{Y'}$-module $H^a(L(f \circ g)^*E)$ is locally free
of rank $r$.
\end{enumerate}
Moreover, $j : Z \to X$ is of finite presentation and we have
\begin{enumerate}
\item[(3)] if $f : Y \to X$ factors as $Y \xrightarrow{g} Z \to X$, then
$H^a(Lf^*E) = g^*H^a(Lj^*E)$,
\item[(4)] if $\beta_a(x) \leq r$ for all $x \in X$, then
$j$ is a closed immersion and given $f : Y \to X$ the following
are equivalent
\begin{enumerate}
\item $f : Y \to X$ factors through $Z$,
\item $H^a(Lf^*E)$ is a locally free $\mathcal{O}_Y$-module of rank $r$,
\end{enumerate}
and if $r = 1$ these are also equivalent to
\begin{enumerate}
\item[(c)] $\mathcal{O}_Y \to \SheafHom_{\mathcal{O}_Y}(H^a(Lf^*E), H^a(Lf^*E))$
is injective.
\end{enumerate}
\end{enumerate}

\label{lemma-fibre-product-deformation-categories}
Let $S$ be a locally Noetherian scheme. Let
$$
\xymatrix{
\mathcal{W} \ar[d] \ar[r] & \mathcal{Z} \ar[d] \\
\mathcal{X} \ar[r] & \mathcal{Y}
}
$$
be a $2$-fibre product of categories fibred in groupoids over
$(\Sch/S)_{fppf}$. Let $k$ be a finite type field over $S$ and
$w_0$ an object of $\mathcal{W}$ over $k$. Let $x_0, z_0, y_0$ be
the images of $w_0$ under the morphisms in the diagram. Then
$$
\xymatrix{
\mathcal{F}_{\mathcal{W}, k, w_0} \ar[d] \ar[r] &
\mathcal{F}_{\mathcal{Z}, k, z_0} \ar[d] \\
\mathcal{F}_{\mathcal{X}, k, x_0} \ar[r] & \mathcal{F}_{\mathcal{Y}, k, y_0}
}
$$
is a fibre product of predeformation categories.

\label{lemma-pseudo-coherent-hocolim}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $K \in D(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item $K$ is pseudo-coherent, and
\item $K = \text{hocolim} K_n$ where
$K_n$ is perfect and $\tau_{\geq -n}K_n \to \tau_{\geq -n}K$
is an isomorphism for all $n$.
\end{enumerate}

\label{lemma-existence-lci}
If $A \to B$ is a local complete intersection ring map, then
there exists a solution to (\ref{equation-to-solve}).

\label{lemma-countable}
Let $(A, \text{d})$ be a differential graded algebra with
$H^i(A)$ countable for each $i$. Let $M$ be an object of $D(A, \text{d})$.
Then the following are equivalent
\begin{enumerate}
\item $M = \text{hocolim} E_n$ with $E_n$ compact in $D(A, \text{d})$, and
\item $H^i(M)$ is countable for each $i$.
\end{enumerate}

\label{theorem-K-injective-embedding-grothendieck}
\begin{slogan}
Existence of K-injective complexes for Grothendieck abelian categories.
\end{slogan}
Let $\mathcal{A}$ be a Grothendieck abelian category.
For every complex $M^\bullet$ there exists a quasi-isomorphism
$M^\bullet \to I^\bullet$ such that $M^n \to I^n$ is injective and $I^n$
is an injective object of $\mathcal{A}$ for all $n$ and $I^\bullet$
is a K-injective complex. Moreover, the construction is functorial in
$M^\bullet$.

\label{lemma-gorenstein-shriek}
Let $\varphi : R \to A$ be a flat finite type homomorphism of Noetherian rings.
The following are equivalent
\begin{enumerate}
\item the fibres $A \otimes_R \kappa(\mathfrak p)$ are Gorenstein
for all primes $\mathfrak p \subset R$, and
\item $\omega_{A/R}^\bullet$ is an invertible object of $D(A)$, see
More on Algebra, Lemma \ref{more-algebra-lemma-invertible-derived}.
\end{enumerate}

\label{lemma-descend-monomorphism}
Notation and assumptions as in Situation \ref{situation-descent-property}. If
\begin{enumerate}
\item $f$ is a monomorphism,
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is a monomorphism for some $i \geq 0$.

\label{lemma-shriek-boundedness}
Let $\varphi : R \to A$ be a finite type homomorphism of Noetherian rings.
\begin{enumerate}
\item $\varphi^!$ maps $D^+(R)$ into $D^+(A)$ and
$D^+_{\textit{Coh}}(R)$ into $D^+_{\textit{Coh}}(A)$.
\item if $\varphi$ is perfect, then $\varphi^!$ maps
$D^-(R)$ into $D^-(A)$,
$D^-_{\textit{Coh}}(R)$ into $D^-_{\textit{Coh}}(A)$, and
$D^b_{\textit{Coh}}(R)$ into $D^b_{\textit{Coh}}(A)$.
\end{enumerate}

\label{lemma-formally-etale-nontrivial-cotangent-complex}
There exists a formally \'etale surjective ring map $A \to B$
with $L_{B/A}$ not equal to zero.

\label{lemma-smooth-smooth-local-source}
The property $\mathcal{P}(f)=$``$f$ is smooth''
is smooth local on the source.

\label{lemma-universally-catenary}
Let $A$ be a Noetherian ring which has a dualizing
complex. Then $A$ is universally catenary of finite dimension.

\label{lemma-when-scheme-after-base-change}
Let $k$ be a field with algebraic closure $\overline{k}$.
Let $X$ be a quasi-separated algebraic space over $k$.
\begin{enumerate}
\item If there exists a field extension $K/k$ such that
$X_K$ is a scheme, then $X_{\overline{k}}$ is a scheme.
\item If $X$ is quasi-compact and there exists a field extension
$K/k$ such that $X_K$ is a scheme, then $X_{k'}$
is a scheme for some finite separable extension $k'$ of $k$.
\end{enumerate}

\label{lemma-quasi-compact-quasi-separated-permanence}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
\begin{enumerate}
\item If $\mathcal{X}$ is quasi-compact and $\mathcal{Y}$ is
quasi-separated, then $f$ is quasi-compact.
\item If $\mathcal{X}$ is quasi-compact and quasi-separated and $\mathcal{Y}$
is quasi-separated, then $f$ is quasi-compact and quasi-separated.
\item A fibre product of quasi-compact and quasi-separated algebraic stacks
is quasi-compact and quasi-separated.
\end{enumerate}

\label{lemma-trace-product}
Assume given data (D0), (D1), and (D2') satisfying axioms (A1) -- (A7).
Then axiom (B) of Section \ref{section-axioms} holds.

\label{theorem-injective-embedding-grothendieck}
Let $\mathcal{A}$ be a Grothendieck abelian category.
Then $\mathcal{A}$ has functorial injective embeddings.

\label{lemma-monomorphism-separated}
A monomorphism of algebraic stacks is separated and DM.
The same is true for immersions of algebraic stacks.

\label{lemma-equality-genus-reduction-bigger-than}
If equality holds in Lemma \ref{lemma-genus-reduction-bigger-than}
then
\begin{enumerate}
\item the unique irreducible component of $X_k$ containing
$x$ is a smooth projective geometrically irreducible curve
over $k$,
\item if $C \subset X_k$ is another irreducible component, then
$\kappa = H^0(C, \mathcal{O}_C)$ is a finite separable extension
of $k$, $C$ has a $\kappa$-rational point, and $C$ is smooth over $\kappa$
\end{enumerate}

\label{lemma-criterion-reduced}
Let $X$ be a locally Noetherian scheme.
Then $X$ is reduced if and only if $X$ has properties $(S_1)$ and $(R_0)$.

\label{lemma-composition-rig-surjective}
\begin{slogan}
Rig-surjectivity of locally finite type morphisms is preserved under
composition
\end{slogan}
Let $S$ be a scheme. Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of formal
algebraic spaces over $S$. Assume $X$, $Y$, $Z$ are locally Noetherian and
$f$ and $g$ locally of finite type. Then if $f$ and $g$ are rig-surjective,
so is $g \circ f$.

\label{proposition-separated-closed-in-finite-presentation}
Let $S$ be a scheme. $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Assume
\begin{enumerate}
\item $f$ is of finite type and separated, and
\item $Y$ is quasi-compact and quasi-separated.
\end{enumerate}
Then there exists a separated morphism of finite presentation
$f' : X' \to Y$ and a closed immersion $X \to X'$ over $Y$.

\label{theorem-nagata}
\begin{reference}
See \cite{Lutkebohmert}, \cite{Conrad-Nagata}, \cite{Nagata-1},
\cite{Nagata-2}, \cite{Nagata-3}, and \cite{Nagata-4}
\end{reference}
Let $S$ be a quasi-compact and quasi-separated scheme. Let
$X \to S$ be a separated, finite type morphism.
Then $X$ has a compactification over $S$.

\label{lemma-injective-module-divide}
Let $R$ be a Noetherian ring. Let $I$ be an injective $R$-module.
\begin{enumerate}
\item Let $f \in R$. Then $E = \bigcup I[f^n] = I[f^\infty]$
is an injective submodule of $I$.
\item Let $J \subset R$ be an ideal. Then the $J$-power torsion
submodule $I[J^\infty]$ is an injective submodule of $I$.
\end{enumerate}

\label{lemma-groupoid-in-functors-prorep-equivalences}
Let $(U, R, s, t, c)$ be a groupoid in functors on $\mathcal{C}_\Lambda$.
\begin{enumerate}
\item $(U, R, s, t, c)$ is prorepresentable if and only if its completion is
representable as a groupoid in functors on $\widehat{\mathcal{C}}_\Lambda$.
\item $(U, R, s, t, c)$ is prorepresentable if and only if $U$ and $R$ are
prorepresentable.
\end{enumerate}

\label{lemma-CLambdahat-coproducts}
The category $\widehat{\mathcal{C}}_\Lambda$ admits coproducts
of pairs of objects.

\label{lemma-cartesian-square-inertia}
Let $\pi : \mathcal{X} \to \mathcal{Y}$ and
$f : \mathcal{Y}' \to \mathcal{Y}$ be morphisms of algebraic stacks.
Set $\mathcal{X}' = \mathcal{X} \times_\mathcal{Y} \mathcal{Y}'$.
Then both squares in the diagram
$$
\xymatrix{
\mathcal{I}_{\mathcal{X}'/\mathcal{Y}'} \ar[r]
\ar[d]_{
\text{Categories, Equation}\ (\ref{categories-equation-functorial})
} &
\mathcal{X}' \ar[r]_{\pi'} \ar[d] & \mathcal{Y}' \ar[d]^f \\
\mathcal{I}_{\mathcal{X}/\mathcal{Y}} \ar[r] &
\mathcal{X} \ar[r]^\pi & \mathcal{Y}
}
$$
are fibre product squares.

\label{lemma-flat-finite-presentation-CM-open}
\begin{reference}
\cite[IV Corollary 12.1.7(iii)]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes which is flat and locally
of finite presentation. Let
$$
W = \{x \in X \mid f\text{ is Cohen-Macaulay at }x\}
$$
Then
\begin{enumerate}
\item $W = \{x \in X \mid \mathcal{O}_{X_{f(x)}, x}\text{ is Cohen-Macaulay}\}$,
\item $W$ is open in $X$,
\item $W$ is dense in every fibre of $X \to S$,
\item the formation of $W$ commutes with arbitrary base change of $f$:
For any morphism $g : S' \to S$, consider
the base change $f' : X' \to S'$ of $f$ and the
projection $g' : X' \to X$. Then the corresponding
set $W'$ for the morphism $f'$ is equal to $W' = (g')^{-1}(W)$.
\end{enumerate}

\label{lemma-quasi-regular-immersion}
Let $S$ be a scheme. Let $i : Z \to X$ be an immersion of algebraic spaces
over $S$. Then $i$ is a quasi-regular immersion if and only if the following
conditions are satisfied
\begin{enumerate}
\item $i$ is locally of finite presentation,
\item the conormal sheaf $\mathcal{C}_{Z/X}$ is finite locally free, and
\item the map (\ref{equation-conormal-algebra-quotient}) is an isomorphism.
\end{enumerate}

\label{lemma-free-at-generic-points}
In Situation \ref{situation-free-at-generic-points}.
\begin{enumerate}
\item The functor $H_p$ satisfies the sheaf property for the fpqc topology.
\item If $\mathcal{F}$ is of finite presentation, then functor $H_p$ is
limit preserving.
\end{enumerate}

\label{lemma-crystal-quasi-coherent-modules}
With notation $X/S, \mathcal{I}, \gamma, \mathcal{C}, \mathcal{F}$
as in Definition \ref{definition-modules}. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is quasi-coherent, and
\item $\mathcal{F}$ is locally quasi-coherent and a crystal in
$\mathcal{O}_{X/S}$-modules.
\end{enumerate}

\label{lemma-exterior-product-well-defined-dim-1}
The map $\times : \CH_n(X) \otimes_{\mathbf{Z}} \CH_m(Y) \to
\CH_{n + m - 1}(X \times_S Y)$ is well defined.

\label{lemma-family-associated-module-specialization}
In the situation of Example \ref{example-family-associated-module}
assume $S$ is locally Noetherian and
$\mathcal{F}$ is flat over $S$ in dimensions $\geq r$
(More on Flatness, Definition \ref{flat-definition-flat-dimension-n}).
Then $[\mathcal{F}/X/S]_r$ is a relative $r$-cycle on $X/S$.

\label{lemma-strict-transform-flat}
In the situation of Definition \ref{definition-strict-transform}.
\begin{enumerate}
\item If $X$ is flat over $B$ at all points lying over $Z$, then
the strict transform of $X$ is equal to the base change $X \times_B B'$.
\item Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
If $\mathcal{F}$ is flat over $B$ at all points lying over $Z$, then
the strict transform $\mathcal{F}'$ of $\mathcal{F}$ is equal to the
pullback $\text{pr}_X^*\mathcal{F}$.
\end{enumerate}

\label{lemma-comparison-fppf-etale}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item For $\mathcal{F} \in \Sh(X_\etale)$ we have
$\epsilon_{X, *}a_X^{-1}\mathcal{F} = \pi_X^{-1}\mathcal{F}$
and $a_{X, *}a_X^{-1}\mathcal{F} = \mathcal{F}$.
\item For $\mathcal{F} \in \textit{Ab}(X_\etale)$ we have
$R^i\epsilon_{X, *}(a_X^{-1}\mathcal{F}) = 0$ for $i > 0$.
\end{enumerate}

\label{lemma-descend-surjective}
With notation and assumptions as in
Situation \ref{situation-descent-property}. If
\begin{enumerate}
\item $f$ is surjective,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is surjective for some $i \geq 0$.

\label{lemma-bounded-truncation}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $P \in D_{perf}(\mathcal{O}_X)$ and $E \in D_{\QCoh}(\mathcal{O}_X)$. 
Let $a \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], E) = 0$ for $i \gg 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], \tau_{\geq a} E) = 0$ for $i \gg 0$.
\end{enumerate}

\label{lemma-injective-flat}
Let $R \to S$ be a flat ring map. If $E$ is an injective $S$-module,
then $E$ is injective as an $R$-module.

\label{lemma-normal-locally-finite-nr-irreducibles}
Let $X$ be a scheme such that any quasi-compact open has a finite number
of irreducible components. The following are equivalent:
\begin{enumerate}
\item $X$ is normal, and
\item $X$ is a disjoint union of normal integral schemes.
\end{enumerate}

\label{lemma-Noetherian-approximation}
Let $f : X \to S$ be a morphism of affine schemes, which is of finite
presentation. Then there exists a cartesian diagram
$$
\xymatrix{
X_0 \ar[d]_{f_0} & X \ar[l]^g \ar[d]^f \\
S_0 & S \ar[l]
}
$$
such that
\begin{enumerate}
\item $X_0$, $S_0$ are affine schemes,
\item $S_0$ is of finite type over $\mathbf{Z}$,
\item $f_0$ is of finite type.
\end{enumerate}

\label{lemma-flat-under-gorenstein}
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
The following are equivalent
\begin{enumerate}
\item $B$ is Gorenstein, and
\item $A$ and $B/\mathfrak m_A B$ are Gorenstein.
\end{enumerate}

\label{lemma-algebraic-morphism-to-algebraic}
Let $S$ be a scheme.
Let $F : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of
stacks in groupoids over $(\Sch/S)_{fppf}$. If
\begin{enumerate}
\item $\mathcal{Y}$ is an algebraic stack, and
\item $F$ is algebraic (see above),
\end{enumerate}
then $\mathcal{X}$ is an algebraic stack.

\label{lemma-finite-flat-non-projective}
Strange flat modules.
\begin{enumerate}
\item There exists a ring $R$ and a finite flat $R$-module $M$ which is
not projective.
\item There exists a closed immersion which is flat but not open.
\end{enumerate}

\label{lemma-product-is-tensor-product}
Let $S$ be a scheme. Let $f_i : U_i \to X$ be \'etale morphisms
of algebraic spaces over $S$. Then there are isomorphisms
$$
f_{1, !}\underline{\mathbf{Z}} \otimes_{\mathbf{Z}}
f_{2, !}\underline{\mathbf{Z}}
\longrightarrow
f_{12, !}\underline{\mathbf{Z}}
$$
where $f_{12} : U_1 \times_X U_2 \to X$ is the structure morphism
and
$$
(f_1 \amalg f_2)_! \underline{\mathbf{Z}}
\longrightarrow
f_{1, !}\underline{\mathbf{Z}} \oplus
f_{2, !}\underline{\mathbf{Z}}
$$

\label{lemma-colimit-cotangent-complex}
Let $A_i \to B_i$ be a system of ring maps over a directed index
set $I$. Then $\colim L_{B_i/A_i} = L_{\colim B_i/\colim A_i}$.

\label{lemma-derived-products}
Let $\mathcal{A}$ be a Grothendieck abelian category.
Then
\begin{enumerate}
\item $D(\mathcal{A})$ has both direct sums and products,
\item direct sums are obtained by taking termwise direct sums of
any complexes,
\item products are obtained by taking termwise products of
K-injective complexes.
\end{enumerate}

\label{lemma-hom-injective}
Let $R \to S$ be a ring map. If $E$ is an injective $R$-module,
then $\Hom_R(S, E)$ is an injective $S$-module.

\label{lemma-affine-equivalence-modules}
Let $S$ be a scheme.
Let $f : Y \to X$ be an affine morphism of algebraic spaces over $S$.
Let $\mathcal{A} = f_*\mathcal{O}_Y$.
The functor $\mathcal{F} \mapsto f_*\mathcal{F}$ induces
an equivalence of categories
$$
\left\{
\begin{matrix}
\text{category of quasi-coherent}\\
\mathcal{O}_Y\text{-modules}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{category of quasi-coherent}\\
\mathcal{A}\text{-modules}
\end{matrix}
\right\}
$$
Moreover, an $\mathcal{A}$-module is
quasi-coherent as an $\mathcal{O}_X$-module if and only if
it is quasi-coherent as an $\mathcal{A}$-module.

\label{lemma-big-abelian-category}
There exists a ``big'' abelian category $\mathcal{A}$ whose
$\Ext$-groups are proper classes.

\label{lemma-diagonal-regular-immersion}
Let $X$ be a nonsingular variety. Then the diagonal
$\Delta : X \to X \times X$ is a regular immersion of codimension $\dim(X)$.

\label{lemma-graded-algebras-RS}
Example \ref{example-graded-algebras}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_P$ is a deformation category
for any graded $k$-algebra $P$.

\label{lemma-factor-through-residual-space-Noetherian}
Let $S$ be a scheme. Let $f : Y \to X$ be a morphism of algebraic
spaces over $S$. Let $x \in |X|$ be a point. Assume
\begin{enumerate}
\item $|f|(|Y|)$ is contained in $\{x\} \subset |X|$,
\item $Y$ is reduced, and
\item $X$ is locally Noetherian.
\end{enumerate}
Then $f$ factors through the residual space $Z_x$ of $X$ at $x$.
